import crypto from 'crypto';
import { CircuitBreaker, CircuitBreakerRegistry } from '@edgecloud/circuit-breaker';
import { EventBus, TOPICS } from '@edgecloud/event-bus';
import { MultiObjectiveScorer, SchedulingPredictor } from '@edgecloud/ml-scheduler';
import { RaftNode, StateMachine } from '@edgecloud/raft-consensus';
import { EdgeNode, SchedulingDecisionEvent,Task, TaskScheduledEvent } from '@edgecloud/shared-kernel';
import cors from '@fastify/cors';
import rateLimit from '@fastify/rate-limit';
import axios from 'axios';
import Fastify from 'fastify';

const app = Fastify({ logger: true, trustProxy: true });

// Configuration
const NODE_ID = process.env.NODE_ID || 'scheduler-1';
const RAFT_PEERS = (process.env.RAFT_PEERS || '').split(',').filter(Boolean).map((p) => {
  const [id, host, port] = p.split(':');
  return { id, host, port: parseInt(port) };
});

const TASK_SERVICE_URL = process.env.TASK_SERVICE_URL || 'http://task-service:80';
const NODE_SERVICE_URL = process.env.NODE_SERVICE_URL || 'http://node-service:80';

// Event bus
const eventBus = new EventBus({
  clientId: `scheduler-${NODE_ID}`,
  brokers: (process.env.KAFKA_BROKERS || 'localhost:9092').split(','),
});

// ML Predictor
const predictor = new SchedulingPredictor();

// Scorer
const scorer = new MultiObjectiveScorer(predictor);

// Circuit breaker registry
const circuitBreakerRegistry = new CircuitBreakerRegistry();

// Circuit breakers for external services
const taskServiceBreaker = circuitBreakerRegistry.getOrCreate('task-service', {
  failureThreshold: 3,
  resetTimeout: 15000,
});

const nodeServiceBreaker = circuitBreakerRegistry.getOrCreate('node-service', {
  failureThreshold: 3,
  resetTimeout: 15000,
});

// Helper to call with circuit breaker
async function callWithCircuitBreaker<T>(
  breaker: CircuitBreaker,
  operation: () => Promise<T>
): Promise<T> {
  return breaker.execute(operation);
}

// Retry with exponential backoff
async function retryWithBackoff<T>(
  operation: () => Promise<T>,
  options: {
    maxRetries?: number;
    baseDelay?: number;
    maxDelay?: number;
    retryableErrors?: string[];
  } = {}
): Promise<T> {
  const {
    maxRetries = 3,
    baseDelay = 100,
    maxDelay = 10000,
    retryableErrors = ['ECONNREFUSED', 'ETIMEDOUT', 'ECONNRESET', '503', '502', '504'],
  } = options;

  let lastError: any;

  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    try {
      return await operation();
    } catch (error: any) {
      lastError = error;

      if (attempt === maxRetries) {break;}

      const errorCode = error.code || error.response?.status?.toString();
      if (!retryableErrors.includes(errorCode)) {
        throw error;
      }

      const delay = Math.min(
        baseDelay * Math.pow(2, attempt) + Math.random() * 100,
        maxDelay
      );

      console.warn(`Retry ${attempt + 1}/${maxRetries} after ${Math.round(delay)}ms: ${error.message}`);
      await new Promise((resolve) => setTimeout(resolve, delay));
    }
  }

  throw lastError;
}

// State machine for scheduling decisions
class SchedulingStateMachine implements StateMachine {
  private decisions: Map<string, any> = new Map();

  apply(command: unknown): void {
    const cmd = command as any;
    if (cmd.type === 'ASSIGN_TASK') {
      this.decisions.set(cmd.taskId, {
        nodeId: cmd.nodeId,
        score: cmd.score,
        timestamp: cmd.timestamp,
      });
    }
  }

  snapshot(): Buffer {
    return Buffer.from(JSON.stringify(Object.fromEntries(this.decisions)));
  }

  restore(snapshot: Buffer): void {
    this.decisions = new Map(Object.entries(JSON.parse(snapshot.toString())));
  }
}

// RAFT node
const stateMachine = new SchedulingStateMachine();
const raftNode = new RaftNode({
  id: NODE_ID,
  host: process.env.HOST || '0.0.0.0',
  port: parseInt(process.env.RAFT_PORT || '7001'),
  peers: RAFT_PEERS,
  electionTimeoutMin: 150,
  electionTimeoutMax: 300,
  heartbeatInterval: 50,
  maxLogEntriesPerRequest: 100,
}, stateMachine);

// Subscribe to task events
async function subscribeToEvents() {
  await eventBus.subscribe(TOPICS.TASK_EVENTS, `scheduler-${NODE_ID}`, async (event) => {
    if (event.eventType === 'TaskCreated' && 'taskId' in event) {
      // Only leader schedules tasks
      if (raftNode.isLeader()) {
        await scheduleTask(event.taskId as string);
      }
    }
  });
}

// Schedule a task
async function scheduleTask(taskId: string): Promise<void> {
  try {
    // Fetch task details with circuit breaker and retry
    const taskRes = await retryWithBackoff(
      () => callWithCircuitBreaker(taskServiceBreaker, () =>
        axios.get(`${TASK_SERVICE_URL}/tasks/${taskId}`)
      ),
      { maxRetries: 3, baseDelay: 100 }
    );
    const task: Task = taskRes.data;

    if (task.status !== 'PENDING') {
      return; // Task already scheduled or cancelled
    }

    // Fetch healthy nodes with circuit breaker and retry
    const nodesRes = await retryWithBackoff(
      () => callWithCircuitBreaker(nodeServiceBreaker, () =>
        axios.get(`${NODE_SERVICE_URL}/internal/nodes/healthy`)
      ),
      { maxRetries: 3, baseDelay: 100 }
    );
    const nodes: EdgeNode[] = nodesRes.data;

    if (nodes.length === 0) {
      app.log.warn(`No healthy nodes available for task ${taskId}`);
      return;
    }

    // Score and rank nodes
    const ranked = scorer.rankNodes(task, nodes);
    const best = ranked[0];

    app.log.info(`Scheduling task ${taskId} to node ${best.nodeId} with score ${best.score}`);

    // Replicate through RAFT
    const command = {
      type: 'ASSIGN_TASK',
      taskId,
      nodeId: best.nodeId,
      score: best.score,
      timestamp: Date.now(),
    };

    const replicated = await raftNode.replicateCommand(command);
    
    if (!replicated) {
      app.log.error(`Failed to replicate scheduling decision for task ${taskId}`);
      return;
    }

    // Update task in task service with circuit breaker and retry
    await retryWithBackoff(
      () => callWithCircuitBreaker(taskServiceBreaker, () =>
        axios.post(`${TASK_SERVICE_URL}/internal/tasks/${taskId}/schedule`, {
          nodeId: best.nodeId,
          score: best.score,
        })
      ),
      { maxRetries: 3, baseDelay: 100 }
    );

    // Publish scheduling decision event
    const decisionEvent: SchedulingDecisionEvent = {
      eventId: crypto.randomUUID(),
      eventType: 'SchedulingDecision',
      aggregateId: taskId,
      timestamp: new Date(),
      version: 1,
      taskId,
      nodeId: best.nodeId,
      score: best.score,
      scoreComponents: best.components,
      algorithm: 'multi-objective-ml',
    };

    await eventBus.publish(TOPICS.SCHEDULER_DECISIONS, decisionEvent);

  } catch (error) {
    app.log.error(`Error scheduling task ${taskId}: ${error}`);
  }
}

// API Routes
// CORS configuration with whitelist - restricted origins for security
const corsOrigins = process.env.CORS_ORIGINS 
  ? process.env.CORS_ORIGINS.split(',').map((o) => o.trim())
  : ['http://localhost:5173', 'http://localhost:3000'];

app.register(cors, { 
  origin: corsOrigins,
  credentials: true 
});

// Rate limiting
app.register(rateLimit, {
  max: 100,
  timeWindow: '1 minute',
  allowList: ['127.0.0.1'],
});

app.get('/health', async () => {
  const circuitBreakerMetrics = circuitBreakerRegistry.getAllMetrics();
  const allHealthy = Object.values(circuitBreakerMetrics).every((m: any) => m.state !== 'OPEN');
  
  return {
    status: allHealthy ? 'healthy' : 'degraded',
    service: 'scheduler-service',
    nodeId: NODE_ID,
    isLeader: raftNode.isLeader(),
    raftState: raftNode.getState(),
    timestamp: new Date().toISOString(),
    circuitBreakers: circuitBreakerMetrics,
  };
});

app.get('/metrics', async () => ({
  raft: raftNode.getMetrics(),
}));

// Trigger scheduling (for manual/ad-hoc scheduling)
app.post('/schedule/:taskId', async (request, reply) => {
  if (!raftNode.isLeader()) {
    reply.status(503).send({ 
      error: 'Not leader', 
      leaderId: raftNode.getLeaderId() 
    });
    return;
  }

  const { taskId } = request.params as any;
  await scheduleTask(taskId);
  reply.send({ scheduled: true });
});

// Start server
async function start() {
  await eventBus.connect();
  await subscribeToEvents();
  
  const port = parseInt(process.env.PORT || '3003');
  await app.listen({ port, host: '0.0.0.0' });
  
  app.log.info(`Scheduler Service (${NODE_ID}) running on port ${port}`);
  
  // Log leader changes
  raftNode.on('becameLeader', () => {
    app.log.info(`Became leader for term ${raftNode.getCurrentTerm()}`);
  });
  
  raftNode.on('stateChanged', (state) => {
    app.log.info(`RAFT state changed to ${state}`);
  });
}

// Graceful shutdown
let isShuttingDown = false;

process.on('SIGTERM', async () => {
  if (isShuttingDown) {return;}
  isShuttingDown = true;
  
  console.log('Shutting down gracefully...');
  
  // Step down as leader if applicable
  raftNode.shutdown();
  
  // Stop accepting new connections
  await app.close();
  
  // Disconnect from event bus
  await eventBus.disconnect();
  
  console.log('Shutdown complete');
  process.exit(0);
});

process.on('SIGINT', async () => {
  if (isShuttingDown) {return;}
  isShuttingDown = true;
  
  raftNode.shutdown();
  await app.close();
  await eventBus.disconnect();
  process.exit(0);
});

start();

import { CircuitBreaker, CircuitBreakerRegistry } from '@edgecloud/circuit-breaker';
import { DEFAULT_TOPIC_CONFIG,EventBus } from '@edgecloud/event-bus';
import {
  CancelTaskBodySchema,
  CompleteTaskBodySchema,
  createAuthMiddleware,
  CreateTaskSchema,
  FailTaskBodySchema,
  requirePermission,
  requireRole,
  ScheduleTaskBodySchema,
  TaskIdParamsSchema,
  TaskListQuerySchema,
  VERSION,
} from '@edgecloud/shared-kernel';
import cors from '@fastify/cors';
import rateLimit from '@fastify/rate-limit';
import Fastify, { type FastifyReply,type FastifyRequest } from 'fastify';
import { Pool } from 'pg';

import { metricsEndpoint,registerMetrics } from './metrics';
import { PostgresTaskRepository } from './repository';
import { TaskService } from './service';

const app = Fastify({
  logger: true,
  trustProxy: true,
});

// Configuration - JWT_SECRET validation
const jwtSecret = process.env.JWT_SECRET
if (!jwtSecret) {
  throw new Error('FATAL: JWT_SECRET environment variable is required')
}
if (jwtSecret.length < 32) {
  throw new Error('FATAL: JWT_SECRET must be at least 32 characters')
}

const config = {
  jwtSecret,
  serviceToken: process.env.SERVICE_TOKEN || 'dev-service-token',
  database: {
    host: process.env.DATABASE_HOST || 'localhost',
    port: parseInt(process.env.DATABASE_PORT || '26257'),
    database: process.env.DATABASE_NAME || 'edgecloud',
    user: process.env.DATABASE_USER || 'root',
    password: process.env.DATABASE_PASSWORD || '',
    ssl: process.env.DATABASE_SSL === 'true' ? { rejectUnauthorized: false } : false,
  },
  kafka: {
    brokers: (process.env.KAFKA_BROKERS || 'localhost:9092').split(','),
  },
};

// Database connection
const pool = new Pool(config.database);

// Event bus
const eventBus = new EventBus({
  clientId: 'task-service',
  brokers: config.kafka.brokers,
});

// Repository and service
const repository = new PostgresTaskRepository(pool);
const taskService = new TaskService(repository, eventBus);

// Circuit breaker registry
const circuitBreakerRegistry = new CircuitBreakerRegistry();

// Circuit breakers for external dependencies
const dbCircuitBreaker = circuitBreakerRegistry.getOrCreate('database', {
  failureThreshold: 5,
  resetTimeout: 30000,
  halfOpenMaxCalls: 3,
});

const kafkaCircuitBreaker = circuitBreakerRegistry.getOrCreate('kafka', {
  failureThreshold: 3,
  resetTimeout: 15000,
  halfOpenMaxCalls: 2,
});

// Register plugins
async function registerPlugins() {
  // CORS
  await app.register(cors, {
    origin: process.env.CORS_ORIGINS?.split(',') || true,
    credentials: true,
  });

  // Rate limiting
  await app.register(rateLimit, {
    max: 100,
    timeWindow: '1 minute',
    cache: 10000,
    allowList: ['127.0.0.1'],
    redis: process.env.REDIS_URL ? { url: process.env.REDIS_URL } : undefined,
  });

  // Authentication middleware
  const authMiddleware = createAuthMiddleware({
    jwtSecret: config.jwtSecret,
    serviceToken: config.serviceToken,
    skipPaths: ['/health', '/metrics', '/ready'],
  });

  app.addHook('preHandler', authMiddleware);
}

// Health check (no auth)
app.get('/health', async () => {
  const circuitBreakerMetrics = circuitBreakerRegistry.getAllMetrics();
  const allHealthy = Object.values(circuitBreakerMetrics).every((m: any) => m.state !== 'OPEN');
  
  return {
    status: allHealthy ? 'healthy' : 'degraded',
    service: 'task-service',
    timestamp: new Date().toISOString(),
    version: VERSION,
    circuitBreakers: circuitBreakerMetrics,
  };
});

// Readiness check
app.get('/ready', async () => {
  try {
    await pool.query('SELECT 1');
    return { status: 'ready', timestamp: new Date().toISOString() };
  } catch (error) {
    return { status: 'not ready', error: (error as Error).message };
  }
});

// Metrics endpoint (no auth)
app.get('/metrics', metricsEndpoint);

// Circuit breaker status endpoint
app.get('/internal/circuit-breakers', async () => {
  return circuitBreakerRegistry.getAllMetrics();
});

// API Routes with validation and auth
app.post('/tasks', {
  preHandler: requirePermission('tasks:create'),
}, async (request: FastifyRequest, reply: FastifyReply) => {
  const input = CreateTaskSchema.parse(request.body);
  const task = await taskService.createTask(input);
  reply.status(201).send(task);
});

app.get('/tasks', {
  preHandler: requirePermission('tasks:read'),
}, async (request: FastifyRequest, reply: FastifyReply) => {
  const query = TaskListQuerySchema.parse(request.query);
  const tasks = await taskService.listTasks(query);
  reply.send(tasks);
});

app.get('/tasks/stats', {
  preHandler: requirePermission('tasks:read'),
}, async () => {
  return taskService.getTaskStats();
});

app.get('/tasks/:id', {
  preHandler: requirePermission('tasks:read'),
}, async (request: FastifyRequest, reply: FastifyReply) => {
  const { id } = TaskIdParamsSchema.parse(request.params);
  const task = await taskService.getTask(id);
  
  if (!task) {
    reply.status(404).send({ error: 'Task not found', code: 'NOT_FOUND' });
    return;
  }
  
  reply.send(task);
});

app.post('/tasks/:id/cancel', {
  preHandler: requirePermission('tasks:update'),
