import { CreateTaskCommand, Task, TaskStatus } from '@edgecloud/shared-kernel';
import { Pool, QueryResult } from 'pg';

export interface TaskRepository {
  create(command: CreateTaskCommand): Promise<Task>;
  findById(id: string): Promise<Task | null>;
  findAll(options: { status?: TaskStatus; limit: number; offset: number }): Promise<Task[]>;
  updateStatus(id: string, status: TaskStatus, updates?: Partial<Task>): Promise<Task | null>;
  countByStatus(status: TaskStatus): Promise<number>;
  countAll(): Promise<number>;
}

export class PostgresTaskRepository implements TaskRepository {
  constructor(private pool: Pool) {}

  async create(command: CreateTaskCommand): Promise<Task> {
    const query = `
      INSERT INTO tasks (
        id, name, type, status, priority, target, node_id, policy, reason,
        input, metadata, max_retries, retry_count, region, submitted_at, created_at, updated_at
      ) VALUES (
        gen_random_uuid(), $1, $2, 'PENDING', $3, $4, $5, 'auto', 'Task created',
        $6, $7, $8, 0, $9, NOW(), NOW(), NOW()
      ) RETURNING *
    `;

    const values = [
      command.name,
      command.type,
      command.priority,
      command.target || 'EDGE',
      command.nodeId || null,
      JSON.stringify(command.input || {}),
      JSON.stringify(command.metadata || {}),
      command.maxRetries || 3,
      'us-east', // Default region
    ];

    const result = await this.pool.query(query, values);
    return this.mapRowToTask(result.rows[0]);
  }

  async findById(id: string): Promise<Task | null> {
    const result = await this.pool.query('SELECT * FROM tasks WHERE id = $1', [id]);
    if (result.rows.length === 0) {return null;}
    return this.mapRowToTask(result.rows[0]);
  }

  async findAll(options: { status?: TaskStatus; limit: number; offset: number }): Promise<Task[]> {
    let query = 'SELECT * FROM tasks';
    const values: any[] = [];

    if (options.status) {
      query += ' WHERE status = $1';
      values.push(options.status);
    }

    query += ` ORDER BY created_at DESC LIMIT $${  values.length + 1  } OFFSET $${  values.length + 2}`;
    values.push(options.limit, options.offset);

    const result = await this.pool.query(query, values);
    return result.rows.map((row) => this.mapRowToTask(row));
  }

  async updateStatus(
    id: string,
    status: TaskStatus,
    updates?: Partial<Task>
  ): Promise<Task | null> {
    const setClauses: string[] = ['status = $1', 'updated_at = NOW()'];
    const values: any[] = [status];

    if (updates?.nodeId) {
      setClauses.push(`node_id = $${values.length + 1}`);
      values.push(updates.nodeId);
    }

    if (updates?.executionTimeMs) {
      setClauses.push(`execution_time_ms = $${values.length + 1}`);
      values.push(updates.executionTimeMs);
    }

    if (updates?.cost) {
      setClauses.push(`cost = $${values.length + 1}`);
      values.push(updates.cost);
    }

    // Add timestamp based on status
    switch (status) {
      case 'SCHEDULED':
        setClauses.push('scheduled_at = NOW()');
        break;
      case 'RUNNING':
        setClauses.push('started_at = NOW()');
        break;
      case 'COMPLETED':
        setClauses.push('completed_at = NOW()');
        break;
      case 'FAILED':
        setClauses.push('failed_at = NOW()');
        break;
      case 'CANCELLED':
        setClauses.push('cancelled_at = NOW()');
        break;
    }

    values.push(id);
    const query = `UPDATE tasks SET ${setClauses.join(', ')} WHERE id = $${values.length} RETURNING *`;

    const result = await this.pool.query(query, values);
    if (result.rows.length === 0) {return null;}
    return this.mapRowToTask(result.rows[0]);
  }

  async countByStatus(status: TaskStatus): Promise<number> {
    const result = await this.pool.query('SELECT COUNT(*) FROM tasks WHERE status = $1', [status]);
    return parseInt(result.rows[0].count, 10);
  }

  async countAll(): Promise<number> {
    const result = await this.pool.query('SELECT COUNT(*) FROM tasks');
    return parseInt(result.rows[0].count, 10);
  }

  private mapRowToTask(row: any): Task {
    return {
      id: row.id,
      name: row.name,
      type: row.type,
      status: row.status,
      priority: row.priority,
      target: row.target,
      nodeId: row.node_id,
      policy: row.policy,
      reason: row.reason,
      input: row.input,
      output: row.output,
      metadata: row.metadata,
      maxRetries: row.max_retries,
      retryCount: row.retry_count,
      submittedAt: row.submitted_at,
      scheduledAt: row.scheduled_at,
      startedAt: row.started_at,
      completedAt: row.completed_at,
      failedAt: row.failed_at,
      cancelledAt: row.cancelled_at,
      executionTimeMs: row.execution_time_ms,
      cost: row.cost,
      region: row.region,
      createdAt: row.created_at,
      updatedAt: row.updated_at,
    };
  }
}

import { EventBus, TOPICS } from '@edgecloud/event-bus';
import {
  CreateTaskCommand,
  generateCorrelationId,
  Task,
  TaskCancelledEvent,
  TaskCompletedEvent,
  TaskCreatedEvent,
  TaskFailedEvent,
  TaskScheduledEvent,
  TaskStatus,
} from '@edgecloud/shared-kernel';

import { TaskRepository } from './repository';

export class TaskService {
  constructor(
    private repository: TaskRepository,
    private eventBus: EventBus
  ) {}

  async createTask(command: CreateTaskCommand): Promise<Task> {
    // Create task in database
    const task = await this.repository.create(command);

    // Publish TaskCreated event
    const event: TaskCreatedEvent = {
      eventId: '',
      eventType: 'TaskCreated',
      aggregateId: task.id,
      timestamp: new Date(),
      version: 1,
      taskId: task.id,
      name: task.name,
      type: task.type,
      priority: task.priority,
      target: task.target,
      region: task.region,
    };

    await this.eventBus.publish(TOPICS.TASK_EVENTS, event);

    return task;
  }

  async getTask(id: string): Promise<Task | null> {
    return this.repository.findById(id);
  }

  async listTasks(options: {
    status?: TaskStatus;
    limit: number;
    offset: number;
  }): Promise<{ tasks: Task[]; total: number }> {
    const [tasks, total] = await Promise.all([
      this.repository.findAll(options),
      options.status
        ? this.repository.countByStatus(options.status)
        : this.repository.countAll(),
    ]);

    return { tasks, total };
  }

  async scheduleTask(
    taskId: string,
    nodeId: string,
    score: number
  ): Promise<Task | null> {
    const task = await this.repository.updateStatus(taskId, 'SCHEDULED', {
      nodeId,
    });

    if (!task) {return null;}

    // Publish TaskScheduled event
    const event: TaskScheduledEvent = {
      eventId: '',
      eventType: 'TaskScheduled',
      aggregateId: task.id,
      timestamp: new Date(),
      version: 1,
      taskId: task.id,
      nodeId,
      score,
      scheduledAt: new Date(),
    };

    await this.eventBus.publish(TOPICS.TASK_EVENTS, event);

    return task;
  }

  async startTask(taskId: string): Promise<Task | null> {
    return this.repository.updateStatus(taskId, 'RUNNING');
  }

  async completeTask(
    taskId: string,
    executionTimeMs: number,
    cost: number,
    output?: Record<string, unknown>
  ): Promise<Task | null> {
    const task = await this.repository.updateStatus(taskId, 'COMPLETED', {
      executionTimeMs,
      cost,
    });

    if (!task) {return null;}

    // Publish TaskCompleted event
    const event: TaskCompletedEvent = {
      eventId: '',
      eventType: 'TaskCompleted',
      aggregateId: task.id,
      timestamp: new Date(),
      version: 1,
      taskId: task.id,
      nodeId: task.nodeId!,
      executionTimeMs,
      cost,
      output,
      completedAt: new Date(),
    };

    await this.eventBus.publish(TOPICS.TASK_EVENTS, event);

    return task;
  }

  async failTask(
    taskId: string,
    error: string,
    retryCount: number,
    willRetry: boolean
  ): Promise<Task | null> {
    const task = await this.repository.findById(taskId);
    if (!task) {return null;}

    let newStatus: TaskStatus = 'FAILED';
    
    // Check if we should retry
    if (willRetry && retryCount < task.maxRetries) {
      newStatus = 'PENDING'; // Reset to pending for retry
    }

    const updatedTask = await this.repository.updateStatus(taskId, newStatus);

    if (!updatedTask) {return null;}

    // Publish TaskFailed event
    const event: TaskFailedEvent = {
      eventId: '',
      eventType: 'TaskFailed',
      aggregateId: task.id,
      timestamp: new Date(),
      version: 1,
      taskId: task.id,
      nodeId: task.nodeId!,
      error,
      retryCount,
      willRetry,
      failedAt: new Date(),
    };

    await this.eventBus.publish(TOPICS.TASK_EVENTS, event);

    return updatedTask;
  }

  async cancelTask(taskId: string, reason: string): Promise<Task | null> {
    const task = await this.repository.updateStatus(taskId, 'CANCELLED');

    if (!task) {return null;}

    // Publish TaskCancelled event
    const event: TaskCancelledEvent = {
      eventId: '',
      eventType: 'TaskCancelled',
      aggregateId: task.id,
      timestamp: new Date(),
      version: 1,
      taskId: task.id,
      reason,
      cancelledAt: new Date(),
    };

    await this.eventBus.publish(TOPICS.TASK_EVENTS, event);

    return task;
  }

  async getTaskStats(): Promise<{
    total: number;
    pending: number;
    scheduled: number;
    running: number;
    completed: number;
    failed: number;
    cancelled: number;
  }> {
    const [
      pending,
      scheduled,
      running,
      completed,
      failed,
      cancelled,
    ] = await Promise.all([
      this.repository.countByStatus('PENDING'),
      this.repository.countByStatus('SCHEDULED'),
      this.repository.countByStatus('RUNNING'),
      this.repository.countByStatus('COMPLETED'),
      this.repository.countByStatus('FAILED'),
      this.repository.countByStatus('CANCELLED'),
    ]);

    return {
      total: pending + scheduled + running + completed + failed + cancelled,
      pending,
      scheduled,
      running,
      completed,
      failed,
      cancelled,
    };
  }
}

