// ============================================================================
// Environment Configuration Validator
// ============================================================================
// 
// Enforces mandatory environment variables at startup
// Prevents insecure default configurations
// Blocks application from running without required secrets
// ============================================================================

import { z } from 'zod';

import { createLogger } from '../lib/logger';

const logger = createLogger('env-validator');

// ============================================================================
// Constants
// ============================================================================

const REQUIRED_ENV_VARS = [
  'DATABASE_URL',
  'JWT_SECRET',
  'PORT',
  'NODE_ENV',
  'REDIS_URL',
  'KAFKA_BROKERS',
  'ENCRYPTION_KEY',
] as const;

const OPTIONAL_ENV_VARS = [
  'LOG_LEVEL',
  'METRICS_ENABLED',
  'RATE_LIMIT_MAX',
  'CORS_ORIGIN',
  'SSL_CERT_PATH',
  'SSL_KEY_PATH',
  'WEBHOOK_URL',
  'BACKUP_DIR',
] as const;

type RequiredEnvVar = typeof REQUIRED_ENV_VARS[number];
type OptionalEnvVar = typeof OPTIONAL_ENV_VARS[number];

// ============================================================================
// Zod Schemas
// ============================================================================

const envSchema = z.object({
  // Required
  DATABASE_URL: z.string().url(),
  JWT_SECRET: z.string().min(32),
  PORT: z.string().regex(/^\d+$/).transform(Number),
  NODE_ENV: z.enum(['development', 'production', 'test']),
  REDIS_URL: z.string().url(),
  KAFKA_BROKERS: z.string(),
  ENCRYPTION_KEY: z.string().length(64), // AES-256 key
  
  // Optional with defaults
  LOG_LEVEL: z.string().default('info'),
  METRICS_ENABLED: z.string().optional().default('true'),
  RATE_LIMIT_MAX: z.string().optional().default('100'),
  CORS_ORIGIN: z.string().optional().default('*'),
  SSL_CERT_PATH: z.string().optional(),
  SSL_KEY_PATH: z.string().optional(),
  WEBHOOK_URL: z.string().url().optional(),
  BACKUP_DIR: z.string().optional(),
});

// ============================================================================
// Validation Functions
// ============================================================================

/**
 * Check if a required environment variable is missing
 */
function isMissing(envVar: string): boolean {
  return !process.env[envVar] || process.env[envVar] === '';
}

/**
 * Validate that all required environment variables are present
 * Throws error if any are missing - blocks startup
 */
export function validateRequiredEnvVars(): void {
  const missing = REQUIRED_ENV_VARS.filter(isMissing);
  
  if (missing.length > 0) {
    const errorMsg = [
      '❌ FATAL: Missing required environment variables:',
      ...missing.map((name) => `   - ${name}`),
      '',
      'These must be set before the application can start.',
      'This prevents insecure default configurations.',
    ].join('\n');
    
    throw new Error(errorMsg);
  }
  
  logger.info('✅ All required environment variables present');
}

/**
 * Validate environment variable values using Zod schema
 * Provides detailed error messages for invalid formats
 */
export function validateEnvValues(): z.infer<typeof envSchema> {
  try {
    const validated = envSchema.parse(process.env);
    logger.info('✅ Environment variable values validated');
    return validated;
  } catch (error) {
    if (error instanceof z.ZodError) {
      const errors = error.errors.map((err) => {
        const path = err.path.join('.');
        const {message} = err;
        return `   - ${path}: ${message}`;
      });
      
      const errorMsg = [
        '❌ FATAL: Invalid environment variable values:',
        ...errors,
        '',
        'Fix these values before starting the application.',
      ].join('\n');
      
      throw new Error(errorMsg);
    }
    throw error;
  }
}

/**
 * Security check: Ensure we're not running as root in production
 */
export function checkNotRunningAsRoot(): void {
  if (process.getuid && process.getuid() === 0) {
    const errorMsg = [
      '❌ FATAL: Refusing to run as root user',
      '',
      'For security reasons, this application cannot run with elevated privileges.',
      'Please use Docker with non-root user or configure proper user permissions.',
      '',
      'Example Dockerfile:',
      '  RUN addgroup -g 1001 nodejs && adduser -S nodejs -u 1001',
      '  USER nodejs',
    ].join('\n');
    
    throw new Error(errorMsg);
  }
  
  logger.info('✅ Not running as root user');
}

/**
 * Production-specific security checks
 */
export function validateProductionSecurity(): void {
  if (process.env.NODE_ENV !== 'production') {
    return;
  }
  
  const warnings: string[] = [];
  
  // Check for demo/test credentials
  if (process.env.JWT_SECRET?.includes('demo') || 
      process.env.JWT_SECRET?.includes('test')) {
    warnings.push('JWT_SECRET contains "demo" or "test" - weak secret detected');
  }
  
  // Check encryption key strength
  const encryptionKey = process.env.ENCRYPTION_KEY;
  if (!encryptionKey || encryptionKey.length < 64) {
    warnings.push('ENCRYPTION_KEY should be 64 characters (AES-256)');
  }
  
  // Warn about HTTP vs HTTPS
  if (!process.env.SSL_CERT_PATH || !process.env.SSL_KEY_PATH) {
    warnings.push('SSL certificates not configured - consider enabling HTTPS');
  }
  
  if (warnings.length > 0) {
    logger.warn('⚠️  Production Security Warnings:');
    warnings.forEach((w) => logger.warn(`   - ${w}`));
    logger.warn('   These do not block startup but should be addressed.\n');
  }
}

/**
 * Comprehensive environment validation
 * Call this at application startup
 */
export function validateEnvironment(): void {
  logger.info('\n🔒 Validating environment configuration...\n');
  
  // Step 1: Check required vars exist
  validateRequiredEnvVars();
  
  // Step 2: Validate value formats
  validateEnvValues();
  
  // Step 3: Security checks
  checkNotRunningAsRoot();
  validateProductionSecurity();
  
  logger.info('✅ Environment validation complete\n');
}

/**
 * Get validated configuration object
 * Use this instead of process.env directly
 */
export function getConfig<T extends z.ZodType>(schema: T): z.infer<T> {
  try {
    return schema.parse(process.env);
  } catch (error) {
    if (error instanceof z.ZodError) {
      throw new Error(
        `Invalid configuration: ${error.errors.map((e) => e.message).join(', ')}`
      );
    }
    throw error;
  }
}

/**
 * Centralized configuration validation
 * Validates all required environment variables at startup
 * Fails fast if any critical configuration is missing
 */

import { Logger } from 'pino';

export interface ConfigValidation {
  name: string;
  value: string | undefined;
  required: boolean;
  minLength?: number;
  pattern?: RegExp;
  message?: string;
}

/**
 * Validate a single configuration value
 */
function validateConfigItem(item: ConfigValidation): string | null {
  // Check if required
  if (item.required && !item.value) {
    return `${item.name} is required${item.message ? `: ${item.message}` : ''}`;
  }

  // Skip further validation if not required and not set
  if (!item.required && !item.value) {
    return null;
  }

  const value = item.value || '';

  // Check minimum length
  if (item.minLength && value.length < item.minLength) {
    return `${item.name} must be at least ${item.minLength} characters`;
  }

  // Check pattern
  if (item.pattern && !item.pattern.test(value)) {
    return `${item.name} format is invalid${item.message ? `: ${item.message}` : ''}`;
  }

  return null;
}

/**
 * Validate all critical configuration
 * Throws error if any validation fails
 */
export function validateConfiguration(logger: Logger): void {
  const isDevelopment = process.env.NODE_ENV !== 'production';
  const isProduction = !isDevelopment;

  const validations: ConfigValidation[] = [
    // Critical security configs - always required
    {
      name: 'JWT_SECRET',
      value: process.env.JWT_SECRET,
      required: true,
      minLength: 32,
      message: 'Must be at least 32 characters for security',
    },
    {
      name: 'ENCRYPTION_KEY',
      value: process.env.ENCRYPTION_KEY,
      required: true,
      minLength: 32,
      message: 'Must be at least 32 characters for AES-256 encryption',
    },

    // Production-only requirements
    {
      name: 'DATABASE_URL',
      value: process.env.DATABASE_URL,
      required: isProduction,
      pattern: /^postgresql:\/\//,
      message: 'Must be a valid PostgreSQL connection string',
    },

    // Certificate paths - required if mTLS enabled
    {
      name: 'MTLS_CA_CERT',
      value: process.env.MTLS_CA_CERT,
      required: process.env.MTLS_ENABLED === 'true' && isProduction,
      message: 'Required when MTLS_ENABLED is true',
    },
    {
      name: 'MTLS_SERVER_CERT',
      value: process.env.MTLS_SERVER_CERT,
      required: process.env.MTLS_ENABLED === 'true' && isProduction,
      message: 'Required when MTLS_ENABLED is true',
    },
    {
      name: 'MTLS_SERVER_KEY',
      value: process.env.MTLS_SERVER_KEY,
      required: process.env.MTLS_ENABLED === 'true' && isProduction,
      message: 'Required when MTLS_ENABLED is true',
    },
  ];

  const errors: string[] = [];

  for (const item of validations) {
    const error = validateConfigItem(item);
    if (error) {
      errors.push(error);
    }
  }

  // Additional production checks
  if (isProduction) {
    if (process.env.FORCE_MOCK_DB === 'true') {
      errors.push('FORCE_MOCK_DB cannot be true in production');
    }

    if (process.env.ENABLE_DEMO_CREDENTIALS === 'true') {
      errors.push('ENABLE_DEMO_CREDENTIALS cannot be true in production');
    }

    // Check for default/placeholder values
    const placeholderValues = ['your-32-character', 'change-me', 'default', 'example'];
    for (const key of ['JWT_SECRET', 'ENCRYPTION_KEY', 'DATABASE_URL']) {
      const value = process.env[key] || '';
      for (const placeholder of placeholderValues) {
        if (value.toLowerCase().includes(placeholder)) {
          errors.push(`${key} appears to contain a placeholder value`);
          break;
        }
      }
    }
  }

  // Log and throw if errors found
  if (errors.length > 0) {
    for (const error of errors) {
      logger.fatal(`FATAL CONFIG ERROR: ${error}`);
    }
    throw new Error(`Configuration validation failed with ${errors.length} error(s)`);
  }

  logger.info('✅ Configuration validation passed');
}

/**
 * Get configuration with type safety
 */
export function getConfig<T extends string>(key: string, defaultValue?: T): T {
  const value = process.env[key] as T | undefined;
  if (value === undefined && defaultValue === undefined) {
    throw new Error(`Configuration ${key} is not set`);
  }
  return (value ?? defaultValue)!;
}

/**
 * Check if running in production
 */
export function isProduction(): boolean {
  return process.env.NODE_ENV === 'production';
}

/**
 * Check if running in development
 */
export function isDevelopment(): boolean {
  return process.env.NODE_ENV !== 'production';
}

import { PrismaClient } from '@prisma/client'

// Read replica URL for scaling read operations
const readReplicaUrl = process.env.DATABASE_READ_URL || process.env.DATABASE_URL

// Primary database URL for writes
const primaryUrl = process.env.DATABASE_URL

// Extended Prisma client with read replica support
class PrismaClientWithReplicas {
  private primary: PrismaClient
  private readReplica: PrismaClient | null = null
  private useReadReplica: boolean

  constructor() {
    this.primary = new PrismaClient({
      log: process.env.NODE_ENV === 'development' 
        ? ['query', 'error', 'warn'] 
        : ['error'],
    })

    // Only create read replica client if URL is different from primary
    this.useReadReplica = readReplicaUrl !== primaryUrl && !!readReplicaUrl
    
    if (this.useReadReplica) {
      this.readReplica = new PrismaClient({
        datasources: {
          db: {
            url: readReplicaUrl,
          },
        },
        log: process.env.NODE_ENV === 'development' 
          ? ['query', 'error', 'warn'] 
          : ['error'],
      })
    }
  }

  /**
   * Get client for write operations (always uses primary)
   */
  get write(): PrismaClient {
    return this.primary
  }

  /**
   * Get client for read operations (uses replica if available)
   */
  get read(): PrismaClient {
    return this.readReplica || this.primary
  }

  /**
   * Get primary client for transactions
   */
  get $transaction() {
    return this.primary.$transaction.bind(this.primary)
  }

  /**
   * Connect both clients
   */
  async $connect() {
    await this.primary.$connect()
    if (this.readReplica) {
      await this.readReplica.$connect()
    }
  }

  /**
   * Disconnect both clients
   */
  async $disconnect() {
    await this.primary.$disconnect()
    if (this.readReplica) {
      await this.readReplica.$disconnect()
    }
  }

  /**
   * Health check for both connections
   */
  async healthCheck(): Promise<{ primary: boolean; replica: boolean }> {
    const results = { primary: false, replica: false }
    
    try {
      await this.primary.$queryRaw`SELECT 1`
      results.primary = true
    } catch {
      results.primary = false
    }

    if (this.readReplica) {
      try {
        await this.readReplica.$queryRaw`SELECT 1`
        results.replica = true
      } catch {
        results.replica = false
      }
    } else {
      results.replica = results.primary // Same as primary if no replica
    }

    return results
  }
}

