  const mockAdminUser = {
    id: 'dev-admin-001',
    email: 'admin@edgecloud.io',
    passwordHash: '$2a$10$VC1weBSLr6S4BE2fw4JkDukXyUbhtR96iF62bEgRUrCvInfmg1fYC', // admin123
    name: 'Development Admin',
    role: 'ADMIN',
    isActive: true,
