    createdAt: new Date(),
    updatedAt: new Date(),
    lastLoginAt: null,
  }
  mockUsers.set(mockAdminUser.email, mockAdminUser)
  mockUsers.set(mockAdminUser.id, mockAdminUser)
}

const mockPrisma = {
  user: {
    findUnique: async ({ where }: any) => {
      if (where.email) {return mockUsers.get(where.email) || null}
      if (where.id) {return mockUsers.get(where.id) || null}
      return null
    },
    findFirst: async ({ where }: any) => {
      for (const user of mockUsers.values()) {
        if (where?.apiKey && user.apiKey === where.apiKey) {return user}
      }
      return null
    },
    create: async ({ data }: any) => {
      const id = data.id || `dev-user-${Date.now()}`
      const user = { ...data, id, createdAt: new Date(), updatedAt: new Date() }
      mockUsers.set(user.email, user)
      mockUsers.set(user.id, user)
      return user
    },
    update: async ({ where, data }: any) => {
      const user = mockUsers.get(where.id) || mockUsers.get(where.email)
      if (!user) {throw new Error('User not found')}
      const updated = { ...user, ...data, updatedAt: new Date() }
      mockUsers.set(updated.email, updated)
      mockUsers.set(updated.id, updated)
      return updated
    },
    count: async () => mockUsers.size / 2, // Divide by 2 because we store by both email and id
  },
  session: {
    create: async ({ data }: any) => {
      const session = { ...data, id: `dev-session-${Date.now()}`, createdAt: new Date() }
      mockSessions.set(data.refreshToken || data.token, session)
      return session
    },
    findUnique: async ({ where }: any) => {
      return mockSessions.get(where.token) || null
    },
    findFirst: async ({ where }: any) => {
      for (const session of mockSessions.values()) {
        if (where?.refreshToken && session.refreshToken === where.refreshToken) {return session}
        if (where?.token && session.token === where.token) {return session}
      }
      return null
    },
    delete: async ({ where }: any) => {
      for (const [key, session] of mockSessions.entries()) {
        if (session.id === where.id) {
          mockSessions.delete(key)
          return session
        }
      }
      return null
    },
    deleteMany: async ({ where }: any) => {
      if (where?.userId) {
        for (const [key, session] of mockSessions.entries()) {
          if (session.userId === where.userId) {mockSessions.delete(key)}
        }
      }
      return { count: 1 }
    },
  },
  auditLog: {
    create: async ({ data }: any) => ({ id: `dev-audit-${Date.now()}`, ...data }),
  },
  task: {
    findMany: async ({ where, orderBy, skip, take, include }: any) => {
      let tasks = Array.from(mockTasks.values())
      if (where?.status) {tasks = tasks.filter((t) => t.status === where.status)}
      if (where?.type) {tasks = tasks.filter((t) => t.type === where.type)}
      if (where?.nodeId) {tasks = tasks.filter((t) => t.nodeId === where.nodeId)}
      if (where?.priority) {tasks = tasks.filter((t) => t.priority === where.priority)}
      return tasks
    },
    findUnique: async ({ where }: any) => {
      return mockTasks.get(where.id) || null
    },
    findFirst: async ({ where }: any) => {
      for (const task of mockTasks.values()) {
        if (where?.id && task.id === where.id) {return task}
      }
      return null
    },
    create: async ({ data, include }: any) => {
      const id = data.id || `dev-task-${Date.now()}`
      const task = { 
        ...data, 
        id, 
        status: 'pending',
        submittedAt: new Date(),
        startedAt: null,
        completedAt: null,
        duration: 0,
        cost: 0,
        latencyMs: 0,
        retryCount: 0,
        reason: data.reason || 'Manually submitted',
        policy: data.policy || 'manual',
      }
      mockTasks.set(id, task)
      // Handle include parameter
      if (include?.node) {
        return {
          ...task, 
          node: task.nodeId ? { id: true, name: true, region: true, ...mockNodes.get(task.nodeId) } : null
        }
      }
      return task
    },
    update: async ({ where, data }: any) => {
      const task = mockTasks.get(where.id)
      if (!task) {throw new Error('Task not found')}
      const updated = { ...task, ...data, updatedAt: new Date() }
      mockTasks.set(where.id, updated)
      return updated
    },
    count: async (args?: any) => {
      let count = mockTasks.size
      if (args?.where?.status) {count = Array.from(mockTasks.values()).filter((t: any) => t.status === args.where.status).length}
      return count
    },
  },
  edgeNode: {
    findMany: async ({ where, orderBy, include, skip, take }: any) => {
      let nodes = Array.from(mockNodes.values())
      if (where?.status) {nodes = nodes.filter((n) => n.status === where.status)}
      if (where?.region) {nodes = nodes.filter((n) => n.region === where.region)}
      if (skip) {nodes = nodes.slice(skip)}
      if (take) {nodes = nodes.slice(0, take)}
      return nodes
    },
    findUnique: async ({ where }: any) => {
      if (where.id) {return mockNodes.get(where.id) || null}
      if (where.name) {return Array.from(mockNodes.values()).find((n: any) => n.name === where.name) || null}
      return null
    },
    create: async ({ data }: any) => {
      const id = data.id || `dev-node-${Date.now()}`
      const node = { 
        ...data, 
        id, 
        status: 'online',
        tasksRunning: 0,
        lastHeartbeat: new Date(),
        createdAt: new Date(),
        updatedAt: new Date(),
        healthHistory: data.healthHistory || []
      }
      mockNodes.set(id, node)
      return node
    },
    update: async ({ where, data }: any) => {
      const node = mockNodes.get(where.id)
      if (!node) {throw new Error('Node not found')}
      const updated = { ...node, ...data, updatedAt: new Date() }
      mockNodes.set(where.id, updated)
      return updated
    },
    delete: async ({ where }: any) => {
      const node = mockNodes.get(where.id)
      mockNodes.delete(where.id)
      return node
    },
    count: async (args?: any) => {
      let count = mockNodes.size
      if (args?.where?.status) {count = Array.from(mockNodes.values()).filter((n: any) => n.status === args.where.status).length}
      return count
    },
    aggregate: async (args?: any) => {
      let nodes = Array.from(mockNodes.values())
      if (args?.where?.status) {nodes = nodes.filter((n: any) => n.status === args.where.status)}
      const result: any = {}
      if (args?._avg) {
        result._avg = {}
        for (const field of Object.keys(args._avg)) {
          const vals = nodes.map((n: any) => n[field] || 0)
          result._avg[field] = vals.length ? vals.reduce((a: number, b: number) => a + b, 0) / vals.length : 0
        }
      }
      return result
    },
  },
  costRecord: {
    aggregate: async () => ({ _sum: { cost: 0 } }),
    findMany: async () => [],
    create: async ({ data }: any) => ({ id: `cost-${Date.now()}`, ...data }),
  },
  carbonMetric: {
    aggregate: async () => ({ _sum: { carbonKg: 0, energyKwh: 0 } }),
  },
  sagaInstance: {
    findMany: async ({ where }: any) => {
      // Return empty array for saga recovery (no incomplete sagas in mock mode)
      return []
    },
    findUnique: async ({ where }: any) => null,
    create: async ({ data }: any) => ({
      id: `saga-${Date.now()}`,
      ...data,
      createdAt: new Date(),
      updatedAt: new Date(),
    }),
    update: async ({ where, data }: any) => ({
      id: where.id,
      ...data,
      updatedAt: new Date(),
    }),
    count: async () => 0,
  },
  $queryRaw: async () => [{ 1: 1 }],
  $disconnect: async () => {},
} as any

// Enforce DATABASE_URL in production
if (!isDevelopment && !process.env.DATABASE_URL) {
