// Register plugins
async function registerPlugins() {
  // Security
  await app.register(helmet, {
    contentSecurityPolicy: {
      directives: {
        defaultSrc: ["'self'"],
        styleSrc: ["'self'", "'unsafe-inline'"],
        imgSrc: ["'self'", 'data:', 'https:'],
        scriptSrc: ["'self'"],
      },
    },
  })

  // CORS configuration with whitelist
  const corsOrigins = process.env.CORS_ORIGINS 
    ? process.env.CORS_ORIGINS.split(',').map((o) => o.trim())
    : isDevelopment 
      ? ['http://localhost:5173', 'http://localhost:5174', 'http://localhost:3000']
      : []

  if (!isDevelopment && corsOrigins.length === 0) {
    logger.warn('CORS_ORIGINS not set in production - CORS will block all cross-origin requests')
  }

  await app.register(cors, {
    origin: corsOrigins,
    credentials: true,
    methods: ['GET', 'POST', 'PUT', 'DELETE', 'PATCH', 'OPTIONS'],
  })

  // Validate critical security configuration
  if (!process.env.JWT_SECRET) {
    logger.fatal('FATAL: JWT_SECRET environment variable is required')
    throw new Error('JWT_SECRET is required')
  }
  
  if (process.env.JWT_SECRET.length < 32) {
    logger.fatal('FATAL: JWT_SECRET must be at least 32 characters')
    throw new Error('JWT_SECRET must be at least 32 characters')
  }

  await app.register(cookie, {
    secret: process.env.JWT_SECRET,
  })

  await app.register(jwt, {
    secret: process.env.JWT_SECRET,
    sign: {
      expiresIn: process.env.JWT_EXPIRES_IN || '15m',
    },
  })

  await app.register(rateLimit, {
    max: parseInt(process.env.RATE_LIMIT_MAX || '100', 10),
    timeWindow: parseInt(process.env.RATE_LIMIT_WINDOW_MS || '60000', 10),
    cache: 10000,
    allowList: ['127.0.0.1'],
    redis: redis,
  })

  // WebSocket
  await app.register(websocket)

  // Multipart file upload with size limits
  await app.register(require('@fastify/multipart'), {
    limits: {
      fileSize: 10 * 1024 * 1024, // 10MB max file size
      files: 1, // Max 1 file per request
      fields: 10, // Max 10 non-file fields
    },
  })

  // Swagger/OpenAPI
  await app.register(swagger, {
    openapi: {
      openapi: '3.0.0',
      info: {
        title: 'Edge-Cloud Orchestrator API',
        description: 'Production API for distributed edge-cloud compute orchestration',
        version: '1.0.0',
      },
      servers: [
        { url: 'http://localhost:3000', description: 'Development' },
      ],
      components: {
        securitySchemes: {
          bearerAuth: {
            type: 'http',
            scheme: 'bearer',
            bearerFormat: 'JWT',
          },
        },
      },
    },
  })

  await app.register(swaggerUi, {
    routePrefix: '/docs',
    uiConfig: {
      docExpansion: 'list',
      deepLinking: true,
    },
  })

  // HTTP request metrics hook
  app.addHook('onResponse', async (request, reply) => {
    const { httpRequestsTotal, httpRequestDuration, httpErrorsTotal } = await import('./services/metrics-service.js')
    const route = request.routerPath || request.url
    const {method} = request
    const {statusCode} = reply
    
    httpRequestsTotal.inc({ method, route, status: statusCode.toString() })
    httpRequestDuration.observe(
      { method, route, status: statusCode.toString() },
      reply.elapsedTime / 1000 // Convert to seconds
    )
    
    // Track errors (4xx and 5xx)
    if (statusCode >= 400) {
      const errorType = statusCode >= 500 ? 'server_error' : 'client_error'
      httpErrorsTotal.inc({ 
        method, 
        route, 
        status_code: statusCode.toString(), 
        error_type: errorType 
      })
    }
  })

  // Custom plugins
  await app.register(prismaPlugin, { prisma })
  await app.register(redisPlugin, { redis })
  await app.register(authPlugin)
  await app.register(errorHandler)
  await app.register(requestLogger)

  // Global request ID middleware for tracing
  app.addHook('onRequest', createRequestIdMiddleware(logger))

  // Decorate services on fastify instance
  app.decorate('wsManager', wsManager)
  app.decorate('heartbeatMonitor', heartbeatMonitor)
  app.decorate('taskScheduler', taskScheduler)
  app.decorate('idempotencyService', idempotencyService)
  app.decorate('priorityScheduler', priorityScheduler)
  app.decorate('backpressureController', backpressureController)
  app.decorate('gracefulDegradation', gracefulDegradation)
}

// Register routes
async function registerRoutes() {
  // Serve static frontend files from dist folder
  const frontendDist = path.resolve(process.cwd(), '..', 'dist')
  
  await app.register(staticPlugin, {
    root: frontendDist,
    prefix: '/',
    wildcard: false, // Don't register wildcard route, we'll handle SPA fallback manually
  })

  // SPA fallback - serve index.html for non-API routes
  app.get('/*', async (request, reply) => {
    const {url} = request
    if (url.startsWith('/api/') || url.startsWith('/docs') || url.startsWith('/ws') || url.startsWith('/assets/')) {
      return reply.callNotFound()
    }
    return reply.sendFile('index.html')
  })

  await app.register(authRoutes, { prefix: '/api/auth' })
  await app.register(nodeRoutes, { prefix: '/api/nodes' })
  await app.register(taskRoutes, { prefix: '/api/tasks' })
  await app.register(workflowRoutes, { prefix: '/api/workflows' })
  await app.register(webhookRoutes, { prefix: '/api/webhooks' })
  await app.register(metricsRoutes, { prefix: '/api/metrics' })
  await app.register(flRoutes, { prefix: '/api/fl' })
  await app.register(costRoutes, { prefix: '/api/cost' })
  await app.register(carbonRoutes, { prefix: '/api/carbon' })
  await app.register(adminRoutes, { prefix: '/api/admin' })
  await app.register(alertRoutes, { prefix: '/api/alerts' })

  // Health check
  app.get('/health', async () => ({
    status: 'healthy',
    timestamp: new Date().toISOString(),
    version: '1.0.0',
  }))

  // Comprehensive health check with all services
  app.get('/health/detailed', async () => {
    const [dbHealth, redisHealth, schedulerHealth] = await Promise.all([
      prisma.$queryRaw`SELECT 1`.then(() => true).catch(() => false),
      redis.ping().then(() => true).catch(() => false),
      Promise.resolve(taskScheduler.isCurrentlyLeader()),
    ])

    const degradationLevel = gracefulDegradation.getCurrentLevel()
    const backpressureStatus = backpressureController.getStats()

    return {
      status: dbHealth && redisHealth ? 'healthy' : 'degraded',
      timestamp: new Date().toISOString(),
      services: {
        database: dbHealth ? 'healthy' : 'unhealthy',
        redis: redisHealth ? 'healthy' : 'unhealthy',
        scheduler: {
          isLeader: schedulerHealth,
          queueLength: await taskScheduler.getQueueLength(),
        },
        gracefulDegradation: {
          level: degradationLevel,
          features: gracefulDegradation.getFeatureStates().filter((f) => !f.enabled).map((f) => f.name),
        },
        backpressure: backpressureStatus,
      },
    }
  })

  // WebSocket endpoint
  app.register(async function (fastify) {
    fastify.get('/ws', { websocket: true }, (connection: any, req: any) => {
      // fastify-websocket passes connection object, actual socket is connection.socket
      wsManager.handleConnection(connection.socket, req)
    })
  })
}

// Start server
async function start() {
  try {
    await registerPlugins()
    await registerRoutes()

    // Start services
    await heartbeatMonitor.start()
    priorityScheduler.start()
    gracefulDegradation.start()
    await taskScheduler.start()

    // Initialize advanced services (lazy-loaded, safe to fail)
    await initializeServices(app, prisma, redis, logger)

    const port = parseInt(process.env.PORT || '3000', 10)
    const host = process.env.HOST || '0.0.0.0'

    await app.listen({ port, host })
    
    logger.info(`🚀 Edge-Cloud Orchestrator API running on http://${host}:${port}`)
    logger.info(`📚 API Documentation: http://${host}:${port}/docs`)
    logger.info(`🔌 WebSocket: ws://${host}:${port}/ws`)

    // Task lifecycle simulation (dev mode only)
    if (useMockDb) {
      // Progress tasks: pending → running → completed
      setInterval(async () => {
        const tasks = Array.from(mockTasks.values())
        for (const task of tasks) {
          if (task.status === 'pending') {
            // Move to running after ~3s
            const age = Date.now() - new Date(task.submittedAt).getTime()
            if (age > 3000) {
              task.status = 'running'
              task.startedAt = new Date()
              mockTasks.set(task.id, task)
              logger.info({ taskId: task.id }, 'Task transitioned to running')
            }
          } else if (task.status === 'running') {
            // Complete after ~5s of running
            const startedAt = task.startedAt ? new Date(task.startedAt).getTime() : (Date.now() - 6000)
            const runAge = Date.now() - startedAt
            if (runAge > 5000) {
              task.status = Math.random() > 0.1 ? 'completed' : 'failed'
              task.completedAt = new Date()
              task.duration = runAge
              task.cost = parseFloat((Math.random() * 0.01).toFixed(4))
              task.latencyMs = Math.floor(Math.random() * 200) + 20
              mockTasks.set(task.id, task)
              logger.info({ taskId: task.id, status: task.status }, 'Task completed')
            }
          }
        }
      }, 2000)

      // Node heartbeat simulation - keep nodes online with realistic metrics
      setInterval(() => {
        for (const [id, node] of mockNodes.entries()) {
          const updated = {
            ...node,
            status: 'online',
            lastHeartbeat: new Date(),
            cpuUsage: parseFloat((Math.random() * 60 + 10).toFixed(1)),
            memoryUsage: parseFloat((Math.random() * 50 + 20).toFixed(1)),
            latency: Math.floor(Math.random() * 80) + 5,
            tasksRunning: Array.from(mockTasks.values()).filter((t: any) => t.nodeId === id && t.status === 'running').length,
          }
          mockNodes.set(id, updated)
        }
      }, 5000)

      logger.info('Task lifecycle & node heartbeat simulation started')
    }
  } catch (err) {
    logger.error(err, 'Failed to start server')
    process.exit(1)
  }
}

// Graceful shutdown
async function shutdown(signal: string) {
  logger.info(`Received ${signal}, shutting down gracefully...`)
  
  // Shutdown advanced services
  await shutdownServices(logger)
  
  // Stop all services in reverse order
  gracefulDegradation.stop()
  priorityScheduler.stop()
  heartbeatMonitor.stop()
  taskScheduler.stop()
  wsManager.close()
  
  await app.close()
  await prisma.$disconnect()
  redis.disconnect()
  
  logger.info('Server shutdown complete')
  process.exit(0)
}

process.on('SIGTERM', () => shutdown('SIGTERM'))
process.on('SIGINT', () => shutdown('SIGINT'))

start()

export { app, prisma, redis, wsManager }

/**
 * Service Initializer Module
 * 
 * Safely initializes advanced services without breaking existing functionality.
 * All services are lazily loaded to avoid TypeScript compilation issues.
 */

import type { PrismaClient } from '@prisma/client'
import type { FastifyInstance } from 'fastify'
import type Redis from 'ioredis'
import type { Logger } from 'pino'

// Service instances
let autoHealer: any = null
let healthMonitor: any = null
let slaMonitor: any = null
let costOptimizer: any = null
let sagaOrchestrator: any = null
let k8sOperator: any = null

/**
 * Initialize all advanced services
 */
export async function initializeServices(
  app: FastifyInstance,
  prisma: PrismaClient,
  redis: Redis,
  logger: Logger
) {
  logger.info('Initializing advanced services...')

  // 0. Alerting Service - Basic alerting (log-based + optional webhook)
  try {
    const { initializeAlerting } = await import('../services/alerting-service.js')
    const alerting = initializeAlerting(logger, {
      logAlerts: true,
      webhookUrl: process.env.ALERT_WEBHOOK_URL,
      throttleMs: parseInt(process.env.ALERT_THROTTLE_MS || '60000', 10),
    })
    app.decorate('alerting', alerting)
    logger.info('✅ Alerting Service initialized')
  } catch (error: any) {
    logger.warn({ err: error.message }, '⚠️ Alerting Service not initialized')
  }

  // 1. Auto-Healer - Automatic node recovery
  try {
    const { AutoHealer } = await import('../services/auto-healer.js')
    autoHealer = new AutoHealer(prisma, redis, logger)
    autoHealer.start()
    app.decorate('autoHealer', autoHealer)
    logger.info('✅ Auto-Healer initialized')
  } catch (error: any) {
    logger.warn({ err: error.message }, '⚠️ Auto-Healer not initialized')
  }

  // 2. Health Monitor - Comprehensive health checks
  try {
    const { HealthMonitor } = await import('../services/health-monitor.js')
    healthMonitor = new HealthMonitor(prisma, redis, logger)
    healthMonitor.start()
    app.decorate('healthMonitor', healthMonitor)
    logger.info('✅ Health Monitor initialized')
  } catch (error: any) {
    logger.warn({ err: error.message }, '⚠️ Health Monitor not initialized')
  }

  // 3. SLA Monitor - Service level tracking
  try {
    const { SLAMonitor } = await import('../services/sla-monitor.js')
    slaMonitor = new SLAMonitor(prisma, redis, logger)
    app.decorate('slaMonitor', slaMonitor)
    logger.info('✅ SLA Monitor initialized')
  } catch (error: any) {
    logger.warn({ err: error.message }, '⚠️ SLA Monitor not initialized')
  }

  // 4. Cost Optimizer - Cost-aware scheduling
  try {
    const { CostOptimizer } = await import('../services/cost-optimizer.js')
    costOptimizer = new CostOptimizer()
    app.decorate('costOptimizer', costOptimizer)
    logger.info('✅ Cost Optimizer initialized')
  } catch (error: any) {
    logger.warn({ err: error.message }, '⚠️ Cost Optimizer not initialized')
  }

  // 5. Saga Orchestrator - Distributed transactions
  try {
    const { SagaOrchestrator } = await import('@edgecloud/saga')
    const { createTaskLifecycleSaga } = await import('../sagas/task-lifecycle-saga.js')
    
    sagaOrchestrator = new SagaOrchestrator(prisma)
    
    // Register task lifecycle saga
    const taskSaga = createTaskLifecycleSaga(prisma, logger)
    sagaOrchestrator.registerSaga(taskSaga)
    
    // Start saga recovery
    sagaOrchestrator.startRecovery()
    
    app.decorate('sagaOrchestrator', sagaOrchestrator)
    logger.info('✅ Saga Orchestrator initialized')
  } catch (error: any) {
    logger.warn({ err: error.message }, '⚠️ Saga Orchestrator not initialized')
  }

  // 6. Kubernetes Operator - K8s integration (only if KUBECONFIG exists)
  if (process.env.KUBECONFIG) {
    try {
      const { EdgeCloudOperator } = await import('../services/kubernetes-operator.js')
      k8sOperator = new EdgeCloudOperator('edge-cloud-orchestrator')
      app.decorate('k8sOperator', k8sOperator)
      logger.info('✅ Kubernetes Operator initialized')
    } catch (error: any) {
      logger.warn({ err: error.message }, '⚠️ Kubernetes Operator not initialized')
    }
  }

  logger.info('Service initialization complete')
}

/**
 * Get status of all services
 */
export function getServiceStatus() {
  return {
    autoHealer: autoHealer !== null,
    healthMonitor: healthMonitor !== null,
    slaMonitor: slaMonitor !== null,
    costOptimizer: costOptimizer !== null,
    sagaOrchestrator: sagaOrchestrator !== null,
    kubernetesOperator: k8sOperator !== null,
  }
}

/**
 * Graceful shutdown of services
 */
export async function shutdownServices(logger: Logger) {
  logger.info('Shutting down services...')
  
  if (autoHealer) {
    try { autoHealer.stop() } catch (e) {}
  }
  if (healthMonitor) {
    try { healthMonitor.stop() } catch (e) {}
  }
  if (sagaOrchestrator) {
    try { sagaOrchestrator.stopRecovery() } catch (e) {}
  }
  
  logger.info('Services shutdown complete')
}

/**
 * Structured Logging with Pino
 * 
 * This module configures structured logging for the application,
 * compatible with log aggregation systems like ELK/Loki.
 */

import pino from 'pino'

// Configure log level based on environment
const logLevel = process.env.LOG_LEVEL || 'info'
const logFormat = process.env.LOG_FORMAT || 'pretty'

// Create logger instance
export const logger = pino({
  level: logLevel,
  // Pretty print in development, JSON in production
  transport: logFormat === 'pretty' && process.env.NODE_ENV !== 'production'
    ? {
        target: 'pino-pretty',
        options: {
          colorize: true,
          translateTime: 'HH:MM:ss Z',
          ignore: 'pid,hostname',
        },
      }
    : undefined,
  // Add standard fields for log aggregation
  base: {
    service: 'edge-cloud-orchestrator',
    version: '1.0.0',
    environment: process.env.NODE_ENV || 'development',
  },
  // Redact sensitive fields
  redact: {
    paths: [
      'password',
      'passwordHash',
      'token',
      'refreshToken',
      'apiKey',
      'secret',
      'headers.authorization',
      'headers.cookie',
    ],
    remove: true,
  },
})

// Child loggers for specific components
export function createLogger(component: string) {
  return logger.child({ component })
}

// Request logging helper
export function logRequest(
  requestId: string,
  method: string,
  url: string,
  statusCode: number,
  duration: number,
  userId?: string
) {
  const logData = {
    requestId,
    method,
    url,
    statusCode,
    duration,
    ...(userId && { userId }),
  }

  if (statusCode >= 500) {
    logger.error(logData, 'Request failed')
  } else if (statusCode >= 400) {
    logger.warn(logData, 'Request error')
  } else {
    logger.info(logData, 'Request completed')
  }
}

// Error logging helper
export function logError(
  error: Error,
  context: Record<string, unknown> = {},
  requestId?: string
) {
  logger.error({
    error: {
      name: error.name,
      message: error.message,
      stack: error.stack,
    },
    ...context,
    ...(requestId && { requestId }),
  }, error.message)
}

// Audit logging helper
export function logAudit(
  userId: string,
  action: string,
  resource: string,
  resourceId?: string,
  details?: Record<string, unknown>
) {
  logger.info({
    audit: true,
    userId,
    action,
    resource,
    resourceId,
    details,
    timestamp: new Date().toISOString(),
  }, `Audit: ${action} on ${resource}`)
}

// Performance logging helper
export function logPerformance(
  operation: string,
  duration: number,
  metadata?: Record<string, unknown>
) {
  logger.info({
    performance: true,
    operation,
    duration,
    ...metadata,
  }, `Performance: ${operation} took ${duration}ms`)
}

// Seed script logger (runs outside main app context)
export const seedLogger = pino({
  level: 'info',
  transport: {
    target: 'pino-pretty',
    options: {
      colorize: true,
      translateTime: 'HH:MM:ss Z',
      ignore: 'pid,hostname,service,version,environment',
    },
  },
})

/**
 * OpenTelemetry Distributed Tracing Setup
 * 
 * This module configures distributed tracing for the application,
 * allowing request flows to be tracked across services.
 */

import { getNodeAutoInstrumentations } from '@opentelemetry/auto-instrumentations-node'
import { OTLPTraceExporter } from '@opentelemetry/exporter-trace-otlp-grpc'
import { FastifyInstrumentation } from '@opentelemetry/instrumentation-fastify'
import { HttpInstrumentation } from '@opentelemetry/instrumentation-http'
import { PgInstrumentation } from '@opentelemetry/instrumentation-pg'
import { RedisInstrumentation } from '@opentelemetry/instrumentation-redis'
import { NodeSDK } from '@opentelemetry/sdk-node'

import { createLogger } from './logger'
import type { FastifyInstance } from 'fastify'






const logger = createLogger('tracing')

let sdk: NodeSDK | null = null

export function initTracing(): void {
  const enabled = process.env.OTEL_ENABLED === 'true'
  
  if (!enabled) {
    logger.info('OpenTelemetry tracing disabled')
    return
  }

  const serviceName = process.env.OTEL_SERVICE_NAME || 'edge-cloud-orchestrator'
  const endpoint = process.env.OTEL_EXPORTER_OTLP_ENDPOINT || 'http://localhost:4317'

  const traceExporter = new OTLPTraceExporter({
    url: endpoint,
  })

  sdk = new NodeSDK({
    traceExporter,
    instrumentations: [
      getNodeAutoInstrumentations(),
      new FastifyInstrumentation(),
      new HttpInstrumentation(),
      new PgInstrumentation(),
      new RedisInstrumentation(),
    ],
    resource: {
      'service.name': serviceName,
      'service.version': '1.0.0',
      'deployment.environment': process.env.NODE_ENV || 'development',
    } as any,
  })

  sdk.start()
  logger.info({ serviceName, endpoint }, 'OpenTelemetry tracing enabled')
}

export function shutdownTracing(): Promise<void> {
  if (sdk) {
    return sdk.shutdown()
  }
  return Promise.resolve()
}

// Middleware to add trace context to requests
export function tracingMiddleware(fastify: FastifyInstance): void {
  fastify.addHook('onRequest', async (request, reply) => {
    // Add trace ID to response headers for debugging
    const {span} = (request as any)
    if (span) {
      reply.header('X-Trace-Id', span.spanContext().traceId)
      reply.header('X-Span-Id', span.spanContext().spanId)
    }
  })
}

// Helper to create custom spans
export async function withSpan<T>(
  name: string,
  operation: () => Promise<T>,
  attributes?: Record<string, string | number | boolean>
): Promise<T> {
  const { trace } = await import('@opentelemetry/api')
  const tracer = trace.getTracer('edge-cloud-orchestrator')
  
  return tracer.startActiveSpan(name, async (span) => {
    try {
      if (attributes) {
        Object.entries(attributes).forEach(([key, value]) => {
          span.setAttribute(key, value)
        })
      }
      
      const result = await operation()
      span.setStatus({ code: 1 }) // OK
      return result
    } catch (error) {
      span.setStatus({
        code: 2, // ERROR
        message: error instanceof Error ? error.message : 'Unknown error',
      })
      span.recordException(error as Error)
      throw error
    } finally {
      span.end()
    }
  })
}

// ============================================================================
// Authorization Middleware - RBAC Enforcement
// ============================================================================
// 
// Provides role-based access control that MUST be applied to all protected routes.
// This middleware enforces authorization at the route level.
// ============================================================================

import { FastifyReply,FastifyRequest } from 'fastify';

import type { UserRole } from '../types/fastify';

export class AuthorizationError extends Error {
  constructor(
    message: string,
    public requiredRoles: string[],
    public userRole?: string
  ) {
    super(message);
    this.name = 'AuthorizationError';
  }
}

/**
 * Require specific roles for route access
 * 
 * @param roles - Allowed roles for this route
 * @returns Fastify preHandler function
 * 
 * @example
 * ```typescript
 * // Admin-only route
 * fastify.post('/api/admin/users', {
 *   preHandler: [authorize('admin')]
 * }, handler);
 * 
 * // Multiple roles allowed
 * fastify.get('/api/tasks', {
 *   preHandler: [authorize('admin', 'operator', 'user')]
 * }, handler);
 * ```
 */
export function authorize(...roles: UserRole[]) {
  return async function (request: FastifyRequest, reply: FastifyReply) {
    // Check if user is authenticated
    if (!request.user) {
      return reply.status(401).send({
        error: 'Authentication required',
        code: 'AUTH_REQUIRED'
      });
    }

    // Admin can access everything (super user)
    if (request.user.role === 'admin') {
      return;
    }

    // Check if user has required role
    if (!roles.includes(request.user.role)) {
      throw new AuthorizationError(
        `Access denied. Required roles: ${roles.join(', ')}. Your role: ${request.user.role}`,
        roles,
        request.user.role
      );
    }
  };
}

/**
 * Require specific permissions for route access
 * More granular than role-based checks
 * 
 * @param permissions - Required permissions
 * @returns Fastify preHandler function
 */
export function requirePermissions(...permissions: string[]) {
  return async function (request: FastifyRequest, reply: FastifyReply) {
    if (!request.user) {
      return reply.status(401).send({
        error: 'Authentication required',
        code: 'AUTH_REQUIRED'
      });
    }

    // Admin bypasses permission checks
    if (request.user.role === 'admin') {
      return;
    }

    const ROLE_PERMISSIONS: Record<UserRole, string[]> = {
      ADMIN: ['*'],
      OPERATOR: ['task:create', 'task:read', 'task:update', 'node:read', 'node:update', 'node:manage', 'workflow:read', 'webhook:read'],
      VIEWER: ['task:read', 'node:read', 'workflow:read', 'webhook:read']
    };

    const userPermissions = ROLE_PERMISSIONS[request.user.role] || [];
    
    const hasPermission = permissions.every((perm) => 
      userPermissions.includes('*') || userPermissions.includes(perm)
    );

    if (!hasPermission) {
      throw new AuthorizationError(
        `Missing required permissions: ${permissions.join(', ')}`,
        [],
        request.user.role
      );
    }
  };
}

/**
 * Resource ownership check
 * Ensures user can only access their own resources
 * 
 * @param resourceIdParam - Name of URL parameter containing resource ID
 * @param getUserFromResource - Function to get owner ID from resource
 * @returns Fastify preHandler function
 */
export function requireOwnership<T>(
  resourceIdParam: string,
  getUserFromResource: (resourceId: string) => Promise<string | null>
) {
  return async function (request: FastifyRequest, reply: FastifyReply) {
    if (!request.user) {
      return reply.status(401).send({
        error: 'Authentication required',
        code: 'AUTH_REQUIRED'
      });
    }

    const resourceId = (request.params as Record<string, string>)[resourceIdParam];
    
    if (!resourceId) {
      return reply.status(400).send({
        error: 'Resource ID required',
        code: 'INVALID_PARAM'
      });
    }

    const ownerId = await getUserFromResource(resourceId);
    
    if (!ownerId) {
      return reply.status(404).send({
        error: 'Resource not found',
        code: 'NOT_FOUND'
      });
    }

    // Admin can access any resource
    if (request.user.role === 'admin') {
      return;
    }

    // Check if user owns the resource
    if (request.user.id !== ownerId) {
      throw new AuthorizationError(
        'You can only access your own resources',
        ['owner'],
        request.user.role
      );
    }
  };
}

