/**
 * Global Request ID Middleware
 * 
 * Tracing backbone for distributed requests.
 * Flows through: API → Kafka → DB → WebSocket
 */

import { AsyncLocalStorage } from 'async_hooks';
import type { FastifyReply,FastifyRequest } from 'fastify';
import type { Logger } from 'pino';
import { v4 as uuidv4 } from 'uuid';

// ============================================================================
// Types
// ============================================================================

export interface RequestContext {
  requestId: string;
  traceId: string;
  spanId: string;
  parentId?: string;
  userId?: string;
  tenantId?: string;
  source: string;
  startTime: number;
  metadata: Record<string, unknown>;
}

export interface TracingHeaders {
  'x-request-id': string;
  'x-trace-id': string;
  'x-span-id': string;
  'x-parent-id'?: string;
  'x-user-id'?: string;
  'x-tenant-id'?: string;
  'x-source': string;
}

// ============================================================================
// Constants
// ============================================================================

export const TRACING_HEADERS: (keyof TracingHeaders)[] = [
  'x-request-id',
  'x-trace-id',
  'x-span-id',
  'x-parent-id',
  'x-user-id',
  'x-tenant-id',
  'x-source',
];

// Async local storage for request context
const asyncLocalStorage = new AsyncLocalStorage<RequestContext>();

// ============================================================================
// Request ID Middleware
// ============================================================================

export function createRequestIdMiddleware(logger: Logger) {
  return async (request: FastifyRequest, reply: FastifyReply): Promise<void> => {
    const startTime = Date.now();

    // Extract or generate IDs
    const requestId = request.headers['x-request-id'] as string || generateId('req');
    const traceId = request.headers['x-trace-id'] as string || generateId('trace');
    const spanId = generateId('span');
    const parentId = request.headers['x-span-id'] as string;
    const userId = request.headers['x-user-id'] as string;
    const tenantId = request.headers['x-tenant-id'] as string;
    const source = request.headers['x-source'] as string || 'api-gateway';

    const context: RequestContext = {
      requestId,
      traceId,
      spanId,
      parentId,
      userId,
      tenantId,
      source,
      startTime,
      metadata: {},
    };

    // Store in async local storage
    asyncLocalStorage.run(context, () => {});

    // Set response headers
    reply.header('x-request-id', requestId);
    reply.header('x-trace-id', traceId);
    reply.header('x-span-id', spanId);
    reply.header('x-source', source);

    // Add to request object for easy access
    request.requestContext = context;

    // Log request start
    logger.info({
      requestId,
      traceId,
      method: request.method,
      url: request.url,
      userId,
      tenantId,
    }, 'Request started');

    // Hook to log request completion
    request.raw.on('end', () => {
      const duration = Date.now() - startTime;
      logger.info({
        requestId,
        traceId,
        method: request.method,
        url: request.url,
        statusCode: reply.statusCode,
        duration,
      }, 'Request completed');
    });
  };
}

// ============================================================================
// Helper Functions
// ============================================================================

function generateId(prefix: string): string {
  return `${prefix}-${uuidv4().split('-')[0]}${Date.now().toString(36)}`;
}

/**
 * Get current request context from async storage
 */
export function getRequestContext(): RequestContext | undefined {
  return asyncLocalStorage.getStore();
}

/**
 * Get request ID for current context
 */
export function getRequestId(): string {
  return asyncLocalStorage.getStore()?.requestId || 'unknown';
}

/**
 * Get trace ID for current context
 */
export function getTraceId(): string {
  return asyncLocalStorage.getStore()?.traceId || 'unknown';
}

/**
 * Create a child span for tracing
 */
export function createChildSpan(name: string): RequestContext {
  const parent = asyncLocalStorage.getStore();
  
  const child: RequestContext = {
    requestId: parent?.requestId || generateId('req'),
    traceId: parent?.traceId || generateId('trace'),
    spanId: generateId('span'),
    parentId: parent?.spanId,
    userId: parent?.userId,
    tenantId: parent?.tenantId,
    source: parent?.source || 'unknown',
    startTime: Date.now(),
    metadata: { spanName: name, ...parent?.metadata },
  };

  return child;
}

/**
 * Run code with a specific context
 */
export function runWithContext<T>(context: RequestContext, fn: () => T): T {
  return asyncLocalStorage.run(context, fn);
}

/**
 * Inject tracing headers into outgoing requests
 */
export function injectTracingHeaders(headers: Record<string, string> = {}): TracingHeaders {
  const context = asyncLocalStorage.getStore();
  
  return {
    'x-request-id': context?.requestId || generateId('req'),
    'x-trace-id': context?.traceId || generateId('trace'),
    'x-span-id': generateId('span'),
    'x-parent-id': context?.spanId,
    'x-user-id': context?.userId,
    'x-tenant-id': context?.tenantId,
    'x-source': context?.source || 'service',
    ...headers,
  };
}

/**
 * Extract tracing headers from incoming message/event
 */
export function extractTracingHeaders(headers: Record<string, string | undefined>): Partial<RequestContext> {
  return {
    requestId: headers['x-request-id'],
    traceId: headers['x-trace-id'],
    spanId: headers['x-span-id'],
    parentId: headers['x-parent-id'],
    userId: headers['x-user-id'],
    tenantId: headers['x-tenant-id'],
    source: headers['x-source'],
  };
}

/**
 * Create Kafka message headers with tracing
 */
export function createKafkaTracingHeaders(): Record<string, string> {
  const context = asyncLocalStorage.getStore();
  
  return {
    'x-request-id': context?.requestId || generateId('req'),
    'x-trace-id': context?.traceId || generateId('trace'),
    'x-span-id': generateId('span'),
    'x-parent-id': context?.spanId || '',
    'x-source': context?.source || 'kafka-producer',
    'timestamp': Date.now().toString(),
  };
}

/**
 * Create WebSocket message with tracing
 */
export function createWebSocketTracingMetadata(): Record<string, unknown> {
  const context = asyncLocalStorage.getStore();
  
  return {
    requestId: context?.requestId,
    traceId: context?.traceId,
    spanId: generateId('span'),
    parentId: context?.spanId,
    source: 'websocket',
    timestamp: Date.now(),
  };
}

/**
 * Add metadata to current context
 */
export function addContextMetadata(key: string, value: unknown): void {
  const context = asyncLocalStorage.getStore();
  if (context) {
    context.metadata[key] = value;
  }
}

// ============================================================================
// Type Augmentation
// ============================================================================

declare module 'fastify' {
  interface FastifyRequest {
    requestContext?: RequestContext;
  }
}

// ============================================================================
// Authentication Plugin
// ============================================================================
// 
// Provides JWT and API key authentication for Fastify routes.
// Uses types from src/types/fastify.d.ts
// ============================================================================

import { FastifyInstance, FastifyReply,FastifyRequest } from 'fastify'
import fp from 'fastify-plugin'
import jwt from 'jsonwebtoken'

import type { UserPayload,UserRole } from '../types/fastify'

const {JWT_SECRET} = process.env
if (!JWT_SECRET) {
  throw new Error('FATAL: JWT_SECRET environment variable is required')
}
if (JWT_SECRET.length < 32) {
  throw new Error('FATAL: JWT_SECRET must be at least 32 characters')
}

export const authPlugin = fp(async (fastify: FastifyInstance) => {
  // ==========================================================================
  // Authentication Middleware
  // ==========================================================================
  
  fastify.decorate('authenticate', async function (
    request: FastifyRequest,
    reply: FastifyReply
  ): Promise<void> {
    try {
      // Check for API key first (service-to-service auth)
      const apiKey = request.headers['x-api-key']
      if (apiKey && typeof apiKey === 'string') {
        const key = await fastify.prisma.apiKey.findUnique({
          where: { key: apiKey },
          include: { user: true },
        })
        
        if (!key || (key.expiresAt && key.expiresAt < new Date())) {
          return reply.status(401).send({ error: 'Invalid or expired API key' })
        }
        
        // Update last used timestamp
        await fastify.prisma.apiKey.update({
          where: { id: key.id },
          data: { lastUsedAt: new Date() },
        })
        
        // Set user payload (typed via FastifyRequest extension)
        request.user = {
          id: key.user.id,
          email: key.user.email,
          role: key.user.role as UserRole,
        }
        return
      }
      
      // Check for Bearer token (user auth)
      const authHeader = request.headers.authorization
      if (!authHeader?.startsWith('Bearer ')) {
        return reply.status(401).send({ error: 'No authentication token provided' })
      }
      
      const token = authHeader.replace('Bearer ', '')
      
      // Validate JWT token
      try {
        const decoded = jwt.verify(token, JWT_SECRET) as UserPayload & { permissions?: string[] }
        request.user = {
          id: decoded.id,
          email: decoded.email,
          role: decoded.role as UserRole,
        }
      } catch (jwtError) {
        return reply.status(401).send({ error: 'Invalid or expired token' })
      }
    } catch (error) {
      request.log.error({ error }, 'Authentication failed')
      return reply.status(401).send({ error: 'Authentication failed' })
    }
  })
  
  // ==========================================================================
  // Role-Based Authorization Middleware
  // ==========================================================================
  
  fastify.decorate('requireRole', function (
    this: FastifyInstance,
    ...roles: UserRole[]
  ) {
    return async function (
      request: FastifyRequest,
      reply: FastifyReply
    ): Promise<void> {
      // request.user is guaranteed by authenticate preHandler
      if (!request.user) {
        return reply.status(401).send({ error: 'Not authenticated' })
      }
      
      if (!roles.includes(request.user.role)) {
        return reply.status(403).send({
          error: 'Insufficient permissions',
          required: roles,
          current: request.user.role,
        })
      }
    }
  })
})

// ============================================================================
// Type Exports
// ============================================================================

export type { UserPayload,UserRole }

// ============================================================================
// Cost Optimization Plugin
// ============================================================================
// 
// Provides cost-aware scheduling and spend tracking for the orchestrator.
// This is an OPTIONAL plugin - the core orchestration works without it.
// ============================================================================

import { FastifyInstance } from 'fastify'

import type { OrchestratorPlugin, PluginContext } from '../architecture/core-vs-plugins'

// ============================================================================
// Plugin Models (would go in plugins/cost-optimization/models.prisma)
// ============================================================================

/**
 * Prisma models for this plugin:
 * 
 * model NodePricing {
 *   id                  String   @id @default(uuid())
 *   nodeId              String   @unique
 *   baseHourlyRate      Float    @default(0.05)
 *   cpuCoreRate         Float    @default(0.02)
 *   memoryGBRate        Float    @default(0.005)
 *   gpuHourlyRate       Float?
 *   ingressRate         Float    @default(0)
 *   egressRate          Float    @default(0.09)
 *   crossRegionMultiplier Float  @default(2.0)
 *   spotDiscount        Float    @default(0)
 *   updatedAt           DateTime @updatedAt
 *   
 *   @@map("node_pricing")
 * }
 * 
 * model TaskCostEstimate {
 *   id              String   @id @default(uuid())
 *   taskId          String   @unique
 *   estimatedCost   Float
 *   estimatedDurationMs Int
 *   confidence      Float    // 0-1
 *   breakdown       Json
 *   createdAt       DateTime @default(now())
 *   
 *   @@map("task_cost_estimates")
 * }
 * 
 * model CostHistory {
 *   id          String   @id @default(uuid())
 *   nodeId      String
 *   taskId      String?
 *   timestamp   DateTime @default(now())
 *   costUSD     Float
 *   resourceType String
 *   quantity    Float
 *   
 *   @@index([nodeId, timestamp])
 *   @@map("cost_history")
 * }
 */

// ============================================================================
// Plugin Service
// ============================================================================

interface CostOptimizerConfig {
  pricingUpdateInterval: number
  defaultPricing: {
    cpuCoreRate: number
    memoryGBRate: number
    egressRate: number
  }
}

class CostOptimizerService {
  private context: PluginContext
  private config: CostOptimizerConfig
  
  constructor(context: PluginContext, config: CostOptimizerConfig) {
    this.context = context
    this.config = config
  }
  
  /**
   * Estimate cost for a task
   */
  async estimateCost(
    cpuCores: number,
    memoryGB: number,
    durationMs: number,
    egressBytes: number = 0
  ): Promise<{
    estimatedCost: number
    breakdown: {
      compute: number
      memory: number
      egress: number
    }
  }> {
    const hours = durationMs / (1000 * 60 * 60)
    
    const compute = cpuCores * this.config.defaultPricing.cpuCoreRate * hours
    const memory = memoryGB * this.config.defaultPricing.memoryGBRate * hours
    const egress = (egressBytes / (1024 * 1024 * 1024)) * this.config.defaultPricing.egressRate
    
    return {
      estimatedCost: compute + memory + egress,
      breakdown: { compute, memory, egress },
    }
  }
  
  /**
   * Get cost score for scheduling (0-1, lower is cheaper)
   */
  getCostScore(nodeId: string, estimatedCost: number): number {
    // Implementation would compare against other nodes
    return 0.5 // Placeholder
  }
  
  /**
   * Record actual cost after execution
   */
  async recordActualCost(
    taskId: string,
    nodeId: string,
    actualCost: number,
    breakdown: Record<string, number>
  ): Promise<void> {
    // Would insert into CostHistory table
    this.context.logger.info({ taskId, nodeId, actualCost }, 'Recorded actual cost')
  }
}

// ============================================================================
// Plugin Routes
// ============================================================================

async function registerCostRoutes(
  fastify: FastifyInstance,
  service: CostOptimizerService
): Promise<void> {
  // GET /api/v1/cost/estimate - Estimate task cost
  fastify.post('/estimate', async (request, reply) => {
    const { cpuCores, memoryGB, durationMs, egressBytes } = request.body as any
    
    const estimate = await service.estimateCost(
      cpuCores,
      memoryGB,
      durationMs,
      egressBytes
    )
    
    return estimate
  })
  
  // GET /api/v1/cost/history - Get cost history
  fastify.get('/history', async (request, reply) => {
    const { nodeId, from, to } = request.query as any
    
    // Would query CostHistory table
    return {
      totalCost: 0,
      byNode: {},
      byResource: {},
    }
  })
  
  // GET /api/v1/cost/nodes - Get cost per node
  fastify.get('/nodes', async (request, reply) => {
    // Would aggregate costs by node
    return {
      nodes: [],
    }
  })
}

// ============================================================================
// Plugin Definition
// ============================================================================

export const costOptimizationPlugin: OrchestratorPlugin = {
  name: 'cost-optimization',
  version: '1.0.0',
  description: 'Cost-aware scheduling and spend tracking',
  
  dependencies: [],
  loadOrder: 10,
  
  async onLoad(context) {
    context.logger.info('Loading cost optimization plugin')
  },
  
  async onEnable() {
    // Run migrations for plugin models
  },
  
  async onDisable() {
    // Cleanup
  },
  
  models: [
    {
      name: 'NodePricing',
      schema: 'model NodePricing { ... }',
      relations: ['EdgeNode'],
    },
    {
      name: 'TaskCostEstimate',
      schema: 'model TaskCostEstimate { ... }',
      relations: ['Task'],
    },
    {
      name: 'CostHistory',
      schema: 'model CostHistory { ... }',
      relations: ['EdgeNode', 'Task'],
    },
  ],
  
  services: [
    {
      name: 'costOptimizer',
      factory: (context) => {
        const config = context.config as unknown as CostOptimizerConfig
        return new CostOptimizerService(context, config)
      },
    },
  ],
  
  routes: [
    {
      prefix: '/api/v1/cost',
      factory: async (context) => {
        const service = (context.fastify as any).costOptimizer as CostOptimizerService
        await registerCostRoutes(context.fastify, service)
      },
    },
  ],
  
  configSchema: {
    enabled: {
      type: 'boolean',
      default: false,
      description: 'Enable cost optimization features',
    },
    pricingUpdateInterval: {
      type: 'number',
      default: 3600000,
      description: 'How often to refresh pricing data (ms)',
    },
    defaultPricing: {
      type: 'string', // JSON string
      default: JSON.stringify({
        cpuCoreRate: 0.02,
        memoryGBRate: 0.005,
        egressRate: 0.09,
      }),
      description: 'Default pricing rates',
    },
  },
}

export default costOptimizationPlugin

import { Prisma } from '@prisma/client'
import { FastifyError, FastifyInstance, FastifyReply,FastifyRequest } from 'fastify'
import fp from 'fastify-plugin'
import { ZodError } from 'zod'

interface AppError extends Error {
  statusCode?: number
  code?: string
}

export const errorHandler = fp(async (fastify: FastifyInstance) => {
  fastify.setErrorHandler((error: FastifyError | AppError, request: FastifyRequest, reply: FastifyReply) => {
    // Log error
    request.log.error({
      error: {
        message: error.message,
        stack: error.stack,
        statusCode: error.statusCode,
      },
      request: {
        method: request.method,
        url: request.url,
        headers: request.headers,
      },
    })
    
    // Zod validation errors
    if (error instanceof ZodError) {
      return reply.status(400).send({
        error: 'Validation Error',
        details: error.errors.map((e) => ({
          path: e.path.join('.'),
          message: e.message,
          code: e.code,
        })),
      })
    }
    
    // Prisma errors
    if (error instanceof Prisma.PrismaClientKnownRequestError) {
      switch (error.code) {
        case 'P2002':
          return reply.status(409).send({
            error: 'Conflict',
            message: 'A record with this value already exists',
            field: error.meta?.target,
          })
        case 'P2025':
          return reply.status(404).send({
            error: 'Not Found',
            message: 'Record not found',
          })
        default:
          return reply.status(500).send({
            error: 'Database Error',
            code: error.code,
          })
      }
    }
    
    // JWT errors
    if (error.message?.includes('jwt') || error.message?.includes('token')) {
      return reply.status(401).send({
        error: 'Authentication Error',
        message: 'Invalid or expired token',
      })
    }
    
    // Rate limit errors
    if (error.statusCode === 429) {
      return reply.status(429).send({
        error: 'Too Many Requests',
        message: 'Rate limit exceeded. Please try again later.',
      })
    }
    
    // Default error
    const statusCode = error.statusCode || 500
    return reply.status(statusCode).send({
      error: error.name || 'Internal Server Error',
      message: statusCode === 500 ? 'An unexpected error occurred' : error.message,
      ...(process.env.NODE_ENV === 'development' && { stack: error.stack }),
    })
  })
})

