    'VIDEO_PROCESSING',
    'LOG_ANALYSIS',
    'ANOMALY_DETECTION',
    'DATA_PROCESSING',
    'ETL_PIPELINE',
    'ML_TRAINING',
    'NLP',
    'COMPUTER_VISION',
    'SPEECH_RECOGNITION',
    'RECOMMENDATION_ENGINE',
    'FRAUD_DETECTION',
    'IOT_DATA_INGESTION',
    'REALTIME_ANALYTICS',
    'BATCH_PROCESSING',
    'CONTAINER_BUILD',
    'CICD_PIPELINE',
    'CUSTOM',
  ]),
