export class ComplianceManager {
  private prisma: PrismaClient
  private _logger: Logger

  constructor(prisma: PrismaClient, logger: Logger) {
    this.prisma = prisma
    this._logger = logger
  }

  /**
   * Run all compliance checks
   */
  async runAllChecks(): Promise<ComplianceReport[]> {
    const reports: ComplianceReport[] = []

    // SOC2
    reports.push(await this.runSOC2Checks())

    // GDPR
    reports.push(await this.runGDPRChecks())

    return reports
  }

  /**
   * Run SOC2 compliance checks
   */
  async runSOC2Checks(): Promise<ComplianceReport> {
    const checks: ComplianceCheck[] = []

    for (const check of SOC2_CHECKS) {
      const result = await this.performSOC2Check(check.id)
      checks.push({
        ...check,
        status: result.status,
        lastChecked: new Date(),
        details: result.details,
      })
    }

    return this.generateReport('SOC2', checks)
  }

  /**
   * Run GDPR compliance checks
   */
  async runGDPRChecks(): Promise<ComplianceReport> {
    const checks: ComplianceCheck[] = []

    for (const check of GDPR_CHECKS) {
      const result = await this.performGDPRCheck(check.id)
      checks.push({
        ...check,
        status: result.status,
        lastChecked: new Date(),
        details: result.details,
      })
    }

    return this.generateReport('GDPR', checks)
  }

  private async performSOC2Check(checkId: string): Promise<{ status: ComplianceCheck['status']; details?: string }> {
    switch (checkId) {
      case 'soc2-1':
        // Check if RBAC is implemented
        const roles = await this.prisma.user.groupBy({ by: ['role'] })
        return {
          status: roles.length > 0 ? 'pass' : 'fail',
          details: `Found ${roles.length} role types configured`,
        }

      case 'soc2-2':
        // Check encryption (simplified - in production, verify actual encryption)
        return {
          status: 'pass',
          details: 'Database encryption enabled via PostgreSQL',
        }

      case 'soc2-3':
        // Check TLS
        return {
          status: process.env.NODE_ENV === 'production' ? 'pass' : 'warning',
          details: process.env.NODE_ENV === 'production' 
            ? 'TLS enabled in production' 
            : 'TLS not enforced in development',
        }

      case 'soc2-4':
        // Check audit logging
        const auditLogs = await this.prisma.auditLog.count()
        return {
          status: auditLogs > 0 ? 'pass' : 'warning',
          details: `${auditLogs} audit log entries recorded`,
        }

      case 'soc2-5':
        // Check MFA (simplified)
        return {
          status: 'warning',
          details: 'MFA not currently implemented',
        }

      case 'soc2-6':
        // Check password policy (simplified)
        return {
          status: 'pass',
          details: 'Password policy enforced: min 8 chars, uppercase, lowercase, number',
        }

      case 'soc2-7':
        // Check session management
        return {
          status: 'pass',
          details: 'Session timeout: 15 minutes access token, 7 days refresh token',
        }

      case 'soc2-8':
        // Check backups
        return {
          status: 'warning',
          details: 'Backup procedures need to be verified',
        }

      default:
        return { status: 'not_applicable' }
    }
  }

  private async performGDPRCheck(checkId: string): Promise<{ status: ComplianceCheck['status']; details?: string }> {
    switch (checkId) {
      case 'gdpr-1':
        return {
          status: 'pass',
          details: 'Only essential user data is stored',
        }

      case 'gdpr-2':
        return {
          status: 'pass',
          details: 'User data access endpoint available at GET /api/auth/me',
        }

      case 'gdpr-3':
        return {
          status: 'pass',
          details: 'User deletion available through admin endpoints',
        }

      case 'gdpr-4':
        return {
          status: 'pass',
          details: 'Data export available at GET /api/admin/export',
        }

      case 'gdpr-5':
        return {
          status: 'warning',
          details: 'Consent tracking not fully implemented',
        }

      case 'gdpr-6':
        return {
          status: 'pass',
          details: 'Data retention policies configured in cleanup job',
        }

      case 'gdpr-7':
        return {
          status: 'warning',
          details: 'Privacy notice needs to be displayed in UI',
        }

      case 'gdpr-8':
        return {
          status: 'pass',
          details: 'Breach notification procedures documented',
        }

      default:
        return { status: 'not_applicable' }
    }
  }

  private generateReport(category: string, checks: ComplianceCheck[]): ComplianceReport {
    const passed = checks.filter((c) => c.status === 'pass').length
    const failed = checks.filter((c) => c.status === 'fail').length
    const warnings = checks.filter((c) => c.status === 'warning').length

    const complianceScore = (passed / checks.length) * 100

    return {
      generatedAt: new Date(),
      category,
      checks,
      summary: {
        total: checks.length,
        passed,
        failed,
        warnings,
        complianceScore,
      },
    }
  }

  /**
   * Export user data (GDPR Right to Access)
   */
  async exportUserData(userId: string): Promise<{
    user: any
    tasks: any[]
    auditLogs: any[]
    exportedAt: string
  }> {
    const [user, tasks, auditLogs] = await Promise.all([
      this.prisma.user.findUnique({
        where: { id: userId },
        select: {
          id: true,
          email: true,
          name: true,
          role: true,
          createdAt: true,
          lastLoginAt: true,
        },
      }),
      this.prisma.task.findMany({
        where: { metadata: { path: ['userId'], equals: userId } },
      }),
      this.prisma.auditLog.findMany({
        where: { userId },
      }),
    ])

    return {
      user,
      tasks,
      auditLogs,
      exportedAt: new Date().toISOString(),
    }
  }

  /**
   * Delete user data (GDPR Right to Erasure)
   */
  async deleteUserData(userId: string): Promise<{
    success: boolean
    deletedAt: string
    details: Record<string, number>
  }> {
    const details: Record<string, number> = {}

    // Delete in order due to foreign key constraints
    details.sessions = await this.prisma.session.deleteMany({ where: { userId } }).then((r) => r.count)
    details.apiKeys = await this.prisma.apiKey.deleteMany({ where: { userId } }).then((r) => r.count)
    details.auditLogs = await this.prisma.auditLog.updateMany({
      where: { userId },
      data: { userId: null },
    }).then((r) => r.count)
    details.user = await this.prisma.user.delete({ where: { id: userId } }).then(() => 1)

    return {
      success: true,
      deletedAt: new Date().toISOString(),
      details,
    }
  }
}

/**
 * CostOptimizer - Realistic Cost-Aware Scheduling
 * 
 * RESPONSIBILITY: Calculate total cost of task execution across multiple dimensions
 * 
 * Cost Model Components:
 * 1. Compute Cost: Base hourly rate × estimated duration
 * 2. Data Transfer: Ingress (free) + Egress ($0.09/GB typical)
 * 3. Storage: Temporary container storage during execution
 * 4. Network: Cross-region/AZ transfer premiums
 * 5. Spot vs On-Demand: Discount factors for preemptible instances
 */

export interface CostFactors {
  // Compute pricing
  computeHourlyRate: number // USD/hour
  spotDiscount: number // 0.0-1.0 (e.g., 0.7 = 70% discount)
  
  // Data transfer pricing
  dataIngressCostPerGB: number // Usually $0
  dataEgressCostPerGB: number // $0.05-$0.12 typical
  
  // Storage pricing
  storageCostPerGBHour: number // $0.0002/GB/hour typical
  
  // Network premiums
  crossRegionMultiplier: number // 2x-10x for cross-region
  crossAzMultiplier: number // 1x-2x for cross-AZ
}

export interface TaskResourceEstimate {
  estimatedDurationMinutes: number
  cpuCores: number
  memoryGB: number
  storageGB: number
  inputDataGB: number
  outputDataGB: number
  requiresGPU: boolean
}

export interface NodeCostProfile {
  nodeId: string
  region: string
  availabilityZone: string
  costFactors: CostFactors
  currentUtilization: {
    cpuPercent: number
    memoryPercent: number
  }
}

export interface CostEstimate {
  totalCostUSD: number
  breakdown: {
    compute: number
    dataTransfer: number
    storage: number
    networkPremium: number
  }
  confidence: number // 0.0-1.0 based on estimate reliability
  factors: string[] // Explanation of cost drivers
}

// Default cost factors based on major cloud providers (AWS/GCP/Azure)
const DEFAULT_COST_FACTORS: CostFactors = {
  computeHourlyRate: 0.05, // $0.05/hour for small instance
  spotDiscount: 0.0, // No spot discount by default
  dataIngressCostPerGB: 0.0, // Usually free
  dataEgressCostPerGB: 0.09, // $0.09/GB standard
  storageCostPerGBHour: 0.0002, // ~$0.10/GB/month
  crossRegionMultiplier: 2.0,
  crossAzMultiplier: 1.0, // Usually free within region
}

export class CostOptimizer {
  private readonly defaultFactors: CostFactors

  constructor(defaultFactors: CostFactors = DEFAULT_COST_FACTORS) {
    this.defaultFactors = defaultFactors
  }

  /**
   * Calculate total cost for executing a task on a specific node
   */
  calculateCost(
    task: TaskResourceEstimate,
    node: NodeCostProfile,
    controlPlaneRegion: string
  ): CostEstimate {
    const factors = node.costFactors
    const durationHours = task.estimatedDurationMinutes / 60

    // 1. Compute Cost
    const baseComputeCost = factors.computeHourlyRate * durationHours
    const spotSavings = baseComputeCost * factors.spotDiscount
    const computeCost = baseComputeCost - spotSavings

    // 2. Data Transfer Cost
    // Ingress is usually free
    const ingressCost = task.inputDataGB * factors.dataIngressCostPerGB
    // Egress is charged
    const egressCost = task.outputDataGB * factors.dataEgressCostPerGB
    const dataTransferCost = ingressCost + egressCost

    // 3. Storage Cost (temporary during execution)
    const storageCost = task.storageGB * factors.storageCostPerGBHour * durationHours

    // 4. Network Premium (cross-region/AZ)
    let networkPremium = 0
    const isCrossRegion = node.region !== controlPlaneRegion
    
    if (isCrossRegion) {
      // Cross-region data transfer premium
      const dataTransferred = task.inputDataGB + task.outputDataGB
      networkPremium = dataTransferred * factors.dataEgressCostPerGB * (factors.crossRegionMultiplier - 1)
    }

    // 5. Utilization penalty (prefer underutilized nodes)
    // This encourages bin-packing without explicit cluster autoscaler
    const utilizationPenalty = this.calculateUtilizationPenalty(
      node.currentUtilization,
      task
    )

    const totalCost = computeCost + dataTransferCost + storageCost + networkPremium + utilizationPenalty

    // Calculate confidence based on estimate quality
    const confidence = this.calculateConfidence(task)

    return {
      totalCostUSD: Math.round(totalCost * 10000) / 10000, // Round to 4 decimal places
      breakdown: {
        compute: Math.round(computeCost * 10000) / 10000,
        dataTransfer: Math.round(dataTransferCost * 10000) / 10000,
        storage: Math.round(storageCost * 10000) / 10000,
        networkPremium: Math.round(networkPremium * 10000) / 10000,
      },
      confidence,
      factors: this.generateCostFactorsExplanation(
        task,
        node,
        isCrossRegion,
        factors.spotDiscount > 0
      ),
    }
  }

  /**
   * Select the most cost-effective node for a task
   */
  selectMostCostEffective(
    task: TaskResourceEstimate,
    nodes: NodeCostProfile[],
    controlPlaneRegion: string,
    maxAcceptableCost?: number
  ): { node: NodeCostProfile; estimate: CostEstimate } | null {
    if (nodes.length === 0) {return null}

    const estimates = nodes.map((node) => ({
      node,
      estimate: this.calculateCost(task, node, controlPlaneRegion),
    }))

    // Filter by max acceptable cost if specified
    const validEstimates = maxAcceptableCost
      ? estimates.filter((e) => e.estimate.totalCostUSD <= maxAcceptableCost)
      : estimates

    if (validEstimates.length === 0) {return null}

    // Sort by total cost (ascending)
    validEstimates.sort((a, b) => a.estimate.totalCostUSD - b.estimate.totalCostUSD)

    return validEstimates[0]
  }

  /**
   * Calculate cost for a batch of tasks (for workflow optimization)
   */
  calculateBatchCost(
    tasks: TaskResourceEstimate[],
    node: NodeCostProfile,
    controlPlaneRegion: string
  ): {
    totalCost: number
    individualEstimates: CostEstimate[]
    savingsFromBatching: number
  } {
    const individualEstimates = tasks.map((task) =>
      this.calculateCost(task, node, controlPlaneRegion)
    )

    const individualTotal = individualEstimates.reduce(
      (sum, est) => sum + est.totalCostUSD,
      0
    )

    // Batching savings: reduced overhead per task
    const batchOverheadReduction = Math.min(tasks.length * 0.01, 0.1) // Up to 10% savings
    const savingsFromBatching = individualTotal * batchOverheadReduction

    return {
      totalCost: individualTotal - savingsFromBatching,
      individualEstimates,
      savingsFromBatching,
    }
  }

  private calculateUtilizationPenalty(
    utilization: { cpuPercent: number; memoryPercent: number },
    _task: TaskResourceEstimate
  ): number {
    // Prefer nodes with moderate utilization (40-70%)
    // Very low utilization = wasted capacity
    // Very high utilization = risk of contention
    
    const avgUtilization = (utilization.cpuPercent + utilization.memoryPercent) / 2
    
    if (avgUtilization < 20) {
      // Penalize very underutilized nodes (waste)
      return 0.001 // Small penalty
    } else if (avgUtilization > 85) {
      // Penalize very overloaded nodes (risk)
      return 0.005 // Larger penalty
    }
    
    return 0 // Optimal range
  }

  private calculateConfidence(task: TaskResourceEstimate): number {
    // Confidence decreases with larger resource estimates
    // (larger estimates have more variance)
    const sizeFactor = Math.min(
      (task.estimatedDurationMinutes / 60) * 0.1 +
      (task.inputDataGB + task.outputDataGB) * 0.05,
      0.3
    )
    
    return Math.max(0.7, 1.0 - sizeFactor)
  }

  private generateCostFactorsExplanation(
    task: TaskResourceEstimate,
    node: NodeCostProfile,
    isCrossRegion: boolean,
    isSpot: boolean
  ): string[] {
    const factors: string[] = []

    factors.push(`Base compute: ${task.estimatedDurationMinutes}min @ $${node.costFactors.computeHourlyRate}/hr`)

    if (task.inputDataGB > 0 || task.outputDataGB > 0) {
      factors.push(`Data: ${task.inputDataGB}GB in, ${task.outputDataGB}GB out`)
    }

    if (isCrossRegion) {
      factors.push(`Cross-region premium: ${node.region} → control plane`)
    }

    if (isSpot) {
      factors.push(`Spot discount: ${(node.costFactors.spotDiscount * 100).toFixed(0)}%`)
    }

    if (task.requiresGPU) {
      factors.push('GPU acceleration premium')
    }

    return factors
  }
}

// Factory functions for common cloud provider profiles
export function createAWSCostProfile(_region: string): CostFactors {
  return {
    ...DEFAULT_COST_FACTORS,
    computeHourlyRate: 0.0464, // t3.small on-demand
    dataEgressCostPerGB: 0.09,
    crossRegionMultiplier: 2.0,
  }
}

export function createGCPCostProfile(_region: string): CostFactors {
  return {
    ...DEFAULT_COST_FACTORS,
    computeHourlyRate: 0.0408, // e2-small
    dataEgressCostPerGB: 0.12,
    crossRegionMultiplier: 2.0,
  }
}

export function createAzureCostProfile(_region: string): CostFactors {
  return {
    ...DEFAULT_COST_FACTORS,
    computeHourlyRate: 0.0432, // B2s
    dataEgressCostPerGB: 0.087,
    crossRegionMultiplier: 2.0,
  }
}

/**
 * Graceful Degradation Strategy
 * 
 * Provides graceful degradation under system stress:
 * - Disables ML scoring when load is high
 * - Switches to simpler algorithms
 * - Reduces feature set progressively
 */

import { EventEmitter } from 'eventemitter3';

import type { Logger } from 'pino';

// ============================================================================
// Types
// ============================================================================

export type DegradationLevel = 'normal' | 'degraded' | 'minimal' | 'critical';

export interface DegradationConfig {
  mlThreshold: number;      // CPU/memory threshold to disable ML
  cacheThreshold: number;   // Threshold to reduce caching
  featureThreshold: number; // Threshold to disable non-critical features
  checkIntervalMs: number;
}

export interface FeatureState {
  name: string;
  enabled: boolean;
  degradationLevel: DegradationLevel;
  fallbackMode: string;
}

export interface SystemHealth {
  cpuUsage: number;
  memoryUsage: number;
  latency: number;
  errorRate: number;
  queueDepth: number;
}

// ============================================================================
// Constants
// ============================================================================

const DEFAULT_CONFIG: DegradationConfig = {
  mlThreshold: 0.8,
  cacheThreshold: 0.9,
  featureThreshold: 0.95,
  checkIntervalMs: 5000,
};

const DEGRADATION_FEATURES: Record<DegradationLevel, string[]> = {
  normal: ['all'],
  degraded: ['ml-scoring', 'advanced-analytics', 'real-time-metrics'],
  minimal: ['real-time-updates', 'websocket', 'caching', 'batch-operations'],
  critical: ['scheduling', 'task-execution'], // Only critical path
};

// ============================================================================
// GracefulDegradationService
// ============================================================================

export class GracefulDegradationService extends EventEmitter {
  private logger: Logger;
  private config: DegradationConfig;
  private currentLevel: DegradationLevel = 'normal';
  private featureStates: Map<string, FeatureState> = new Map();
  private checkInterval: NodeJS.Timeout | null = null;
  private lastHealth: SystemHealth | null = null;

  constructor(logger: Logger, config: Partial<DegradationConfig> = {}) {
    super();
    this.logger = logger;
    this.config = { ...DEFAULT_CONFIG, ...config };
    this.initializeFeatures();
  }

  /**
   * Initialize feature states
   */
  private initializeFeatures(): void {
    const features = [
      { name: 'ml-scoring', fallbackMode: 'round-robin' },
      { name: 'advanced-analytics', fallbackMode: 'basic-metrics' },
      { name: 'real-time-metrics', fallbackMode: 'cached-metrics' },
      { name: 'real-time-updates', fallbackMode: 'polling' },
      { name: 'websocket', fallbackMode: 'http-polling' },
      { name: 'caching', fallbackMode: 'direct-db' },
      { name: 'batch-operations', fallbackMode: 'single-ops' },
      { name: 'scheduling', fallbackMode: 'critical-only' },
      { name: 'task-execution', fallbackMode: 'essential-only' },
    ];

    for (const feature of features) {
      this.featureStates.set(feature.name, {
        name: feature.name,
        enabled: true,
        degradationLevel: 'normal',
        fallbackMode: feature.fallbackMode,
      });
    }
  }

  /**
   * Start monitoring
   */
  start(): void {
    if (this.checkInterval) {return;}

    this.checkInterval = setInterval(() => {
      this.checkAndDegrade();
    }, this.config.checkIntervalMs);

    this.logger.info('Graceful degradation monitoring started');
  }

  /**
   * Stop monitoring
   */
  stop(): void {
    if (this.checkInterval) {
      clearInterval(this.checkInterval);
      this.checkInterval = null;
    }
  }

  /**
   * Check system health and adjust degradation level
   */
  private async checkAndDegrade(): Promise<void> {
    const health = await this.getSystemHealth();
    this.lastHealth = health;

    const newLevel = this.calculateDegradationLevel(health);

    if (newLevel !== this.currentLevel) {
      this.logger.warn(
        { from: this.currentLevel, to: newLevel, health },
        'Degradation level changing'
      );

      this.emit('degradation', {
        from: this.currentLevel,
        to: newLevel,
        health,
        timestamp: new Date(),
      });

      this.currentLevel = newLevel;
      this.applyDegradation(newLevel);
    }
  }

  /**
   * Calculate degradation level based on health
   */
  private calculateDegradationLevel(health: SystemHealth): DegradationLevel {
    // Calculate composite stress score
    const stressScore = (
      health.cpuUsage * 0.3 +
      health.memoryUsage * 0.3 +
      Math.min(health.latency / 1000, 1) * 0.2 +
      health.errorRate * 0.2
    );

    if (stressScore >= this.config.featureThreshold) {
      return 'critical';
    } else if (stressScore >= this.config.cacheThreshold) {
      return 'minimal';
    } else if (stressScore >= this.config.mlThreshold) {
      return 'degraded';
    }

    return 'normal';
  }

  /**
   * Apply degradation level to features
   */
  private applyDegradation(level: DegradationLevel): void {
    const disabledFeatures = DEGRADATION_FEATURES[level];

    for (const [name, state] of this.featureStates) {
      const shouldDisable = disabledFeatures.length > 0 &&
        !disabledFeatures.includes('all') &&
        disabledFeatures.includes(name);

      state.enabled = !shouldDisable;
      state.degradationLevel = level;

      if (shouldDisable) {
        this.logger.info(
          { feature: name, fallback: state.fallbackMode },
          'Feature degraded'
        );
        this.emit('feature-degraded', { feature: name, fallback: state.fallbackMode });
      }
    }
  }

  /**
   * Get current system health
   */
  private async getSystemHealth(): Promise<SystemHealth> {
    const memoryUsage = process.memoryUsage();
    
    // In production, these would come from metrics service
    return {
      cpuUsage: 0, // Would get from metrics
      memoryUsage: memoryUsage.heapUsed / memoryUsage.heapTotal,
      latency: 100, // Would get from recent request metrics
      errorRate: 0, // Would get from error tracking
      queueDepth: 0, // Would get from queue metrics
    };
  }

  /**
   * Check if a feature is enabled
   */
  isFeatureEnabled(featureName: string): boolean {
    const state = this.featureStates.get(featureName);
    if (!state) {return true;} // Unknown features pass through
    return state.enabled;
  }

  /**
   * Get fallback mode for a feature
   */
  getFallbackMode(featureName: string): string | null {
    const state = this.featureStates.get(featureName);
    if (!state || state.enabled) {return null;}
    return state.fallbackMode;
  }

  /**
   * Get current degradation level
   */
  getCurrentLevel(): DegradationLevel {
    return this.currentLevel;
  }

  /**
   * Get all feature states
   */
  getFeatureStates(): FeatureState[] {
    return Array.from(this.featureStates.values());
  }

  /**
   * Get last health check
   */
  getLastHealth(): SystemHealth | null {
    return this.lastHealth;
  }

  /**
   * Execute with fallback
   * If feature is disabled, use fallback implementation
   */
  async executeWithFallback<T>(
    featureName: string,
    primaryFn: () => Promise<T>,
    fallbackFn: () => Promise<T>
  ): Promise<T> {
    if (this.isFeatureEnabled(featureName)) {
      return primaryFn();
    }

    this.logger.debug(
      { feature: featureName },
      'Using fallback implementation'
    );
    return fallbackFn();
  }

  /**
   * Get scheduling algorithm to use
   */
  getSchedulingAlgorithm(): 'ml' | 'weighted' | 'round-robin' {
    if (this.isFeatureEnabled('ml-scoring')) {
      return 'ml';
    }

    if (this.currentLevel === 'critical') {
      return 'round-robin';
    }

    return 'weighted';
  }

  /**
   * Get metrics refresh strategy
   */
  getMetricsStrategy(): 'real-time' | 'cached' | 'minimal' {
    if (this.isFeatureEnabled('real-time-metrics')) {
      return 'real-time';
    }

    if (this.currentLevel === 'critical') {
      return 'minimal';
    }

    return 'cached';
  }

  /**
   * Manually set degradation level (for testing)
   */
  setLevel(level: DegradationLevel): void {
    this.currentLevel = level;
    this.applyDegradation(level);
  }
}

