/**
 * Priority-Based Task Scheduler
 * 
 * Implements weighted priority execution:
 * - HIGH priority: 60% of capacity
 * - MEDIUM priority: 30% of capacity
 * - LOW priority: 10% of capacity (best effort)
 * 
 * Prevents starvation through priority aging
 */

import { EventEmitter } from 'eventemitter3';
import Redis from 'ioredis';

import type { Logger } from 'pino';

// ============================================================================
// Types
// ============================================================================

export type TaskPriority = 'CRITICAL' | 'HIGH' | 'MEDIUM' | 'LOW';

export interface PriorityTask {
  id: string;
  priority: TaskPriority;
  payload: Record<string, unknown>;
  createdAt: Date;
  deadline?: Date;
  estimatedDuration?: number; // seconds
  nodeId?: string;
  userId: string;
  agingBoost: number; // Increases over time to prevent starvation
}

export interface PriorityQueue {
  name: TaskPriority;
  weight: number; // Percentage of capacity (0-1)
  maxWaitTimeMs: number;
  agingRate: number; // Boost per second waiting
}

export interface ScheduleResult {
  taskId: string;
  priority: TaskPriority;
  scheduledAt: Date;
  estimatedStart: Date;
  position: number;
}

export interface PriorityStats {
  queueDepths: Record<TaskPriority, number>;
  avgWaitTimes: Record<TaskPriority, number>;
  processedCounts: Record<TaskPriority, number>;
  starvedTasks: number;
}

// ============================================================================
// Constants
// ============================================================================

const PRIORITY_QUEUES: Record<TaskPriority, PriorityQueue> = {
  CRITICAL: {
    name: 'CRITICAL',
    weight: 0.5, // 50% of capacity (bypasses normal scheduling)
    maxWaitTimeMs: 0, // Immediate
    agingRate: 0,
  },
  HIGH: {
    name: 'HIGH',
    weight: 0.35, // 35% of normal capacity
    maxWaitTimeMs: 30000, // 30s max wait
    agingRate: 0.1, // 10% boost per second
  },
  MEDIUM: {
    name: 'MEDIUM',
    weight: 0.12, // 12% of normal capacity
    maxWaitTimeMs: 120000, // 2min max wait
    agingRate: 0.05, // 5% boost per second
  },
  LOW: {
    name: 'LOW',
    weight: 0.03, // 3% of normal capacity (best effort)
    maxWaitTimeMs: 600000, // 10min max wait
    agingRate: 0.02, // 2% boost per second
  },
};

const REDIS_KEYS = {
  queue: (priority: TaskPriority) => `priority:queue:${priority}`,
  task: (taskId: string) => `priority:task:${taskId}`,
  stats: (priority: TaskPriority) => `priority:stats:${priority}`,
  aging: 'priority:aging',
};

// ============================================================================
// PriorityScheduler
// ============================================================================

export class PriorityScheduler extends EventEmitter {
  private redis: Redis;
  private logger: Logger;
  private isRunning: boolean = false;
  private processingInterval: NodeJS.Timeout | null = null;
  private agingInterval: NodeJS.Timeout | null = null;

  constructor(redis: Redis, logger: Logger) {
    super();
    this.redis = redis;
    this.logger = logger;
  }

  /**
   * Start the priority scheduler
   */
  start(): void {
    if (this.isRunning) {return;}

    this.isRunning = true;

    // Start aging process (every 5 seconds)
    this.agingInterval = setInterval(() => {
      this.applyAging();
    }, 5000);

    this.logger.info('Priority scheduler started');
  }

  /**
   * Stop the scheduler
   */
  stop(): void {
    this.isRunning = false;

    if (this.processingInterval) {
      clearInterval(this.processingInterval);
      this.processingInterval = null;
    }

    if (this.agingInterval) {
      clearInterval(this.agingInterval);
      this.agingInterval = null;
    }

    this.logger.info('Priority scheduler stopped');
  }

  /**
   * Submit a task to the priority queue
   */
  async submitTask(task: Omit<PriorityTask, 'agingBoost'>): Promise<ScheduleResult> {
    const {priority} = task;
    const fullTask: PriorityTask = {
      ...task,
      agingBoost: 0,
    };

    // Calculate effective priority score
    const score = this.calculatePriorityScore(fullTask);

    // Add to priority queue (sorted set)
    await this.redis.zadd(
      REDIS_KEYS.queue(priority),
      score,
      JSON.stringify(fullTask)
    );

    // Store task details
    await this.redis.setex(
      REDIS_KEYS.task(task.id),
      86400,
      JSON.stringify(fullTask)
    );

    // Update stats
    await this.redis.hincrby(REDIS_KEYS.stats(priority), 'submitted', 1);

    // Get position in queue
    const position = await this.redis.zrank(
      REDIS_KEYS.queue(priority),
      JSON.stringify(fullTask)
    );

    this.logger.debug(
      { taskId: task.id, priority, score, position },
      'Task submitted to priority queue'
    );

    // Emit event for immediate processing if CRITICAL
    if (priority === 'CRITICAL') {
      this.emit('critical-task', fullTask);
    }

    return {
      taskId: task.id,
      priority,
      scheduledAt: new Date(),
      estimatedStart: this.estimateStartTime(priority, position || 0),
      position: (position || 0) + 1,
    };
  }

  /**
   * Get next batch of tasks to execute
   * Respects priority weights to prevent starvation
   */
  async getNextBatch(batchSize: number = 10): Promise<PriorityTask[]> {
    const tasks: PriorityTask[] = [];

    // 1. Always process CRITICAL first (bypasses weights)
    const criticalTasks = await this.redis.zrange(
      REDIS_KEYS.queue('CRITICAL'),
      0,
      batchSize - 1
    );

    for (const taskJson of criticalTasks) {
      const task: PriorityTask = JSON.parse(taskJson);
      tasks.push(task);
      await this.redis.zrem(REDIS_KEYS.queue('CRITICAL'), taskJson);
    }

    const remainingAfterCritical = batchSize - tasks.length;
    if (remainingAfterCritical <= 0) {return tasks;}

    // 2. Calculate slots per priority based on weights
    const slots = {
      HIGH: Math.floor(remainingAfterCritical * PRIORITY_QUEUES.HIGH.weight),
      MEDIUM: Math.floor(remainingAfterCritical * PRIORITY_QUEUES.MEDIUM.weight),
      LOW: Math.max(1, Math.floor(remainingAfterCritical * PRIORITY_QUEUES.LOW.weight)),
    };

    // 3. Process HIGH priority
    const highTasks = await this.redis.zrange(
      REDIS_KEYS.queue('HIGH'),
      0,
      slots.HIGH - 1
    );

    for (const taskJson of highTasks) {
      const task: PriorityTask = JSON.parse(taskJson);
      tasks.push(task);
      await this.redis.zrem(REDIS_KEYS.queue('HIGH'), taskJson);
    }

    // 4. Process MEDIUM priority
    const mediumTasks = await this.redis.zrange(
      REDIS_KEYS.queue('MEDIUM'),
      0,
      slots.MEDIUM - 1
    );

    for (const taskJson of mediumTasks) {
      const task: PriorityTask = JSON.parse(taskJson);
      tasks.push(task);
      await this.redis.zrem(REDIS_KEYS.queue('MEDIUM'), taskJson);
    }

    // 5. Process LOW priority (fill remaining slots)
    const remainingSlots2 = batchSize - tasks.length;
    if (remainingSlots2 > 0) {
      const lowTasks = await this.redis.zrange(
        REDIS_KEYS.queue('LOW'),
        0,
        remainingSlots2 - 1
      );

      for (const taskJson of lowTasks) {
        const task: PriorityTask = JSON.parse(taskJson);
        tasks.push(task);
        await this.redis.zrem(REDIS_KEYS.queue('LOW'), taskJson);
      }
    }

    // Update stats
    for (const task of tasks) {
      await this.redis.hincrby(REDIS_KEYS.stats(task.priority), 'processed', 1);
    }

    return tasks;
  }

  /**
   * Apply aging to prevent starvation
   * Increases priority score of waiting tasks
   */
  private async applyAging(): Promise<void> {
    const priorities: TaskPriority[] = ['HIGH', 'MEDIUM', 'LOW'];

    for (const priority of priorities) {
      const queue = PRIORITY_QUEUES[priority];
      const tasks = await this.redis.zrange(
        REDIS_KEYS.queue(priority),
        0,
        -1,
        'WITHSCORES'
      );

      for (let i = 0; i < tasks.length; i += 2) {
        const taskJson = tasks[i];
        if (!taskJson) {continue;}
        const task: PriorityTask = JSON.parse(taskJson);

        // Calculate aging boost
        const waitTimeMs = Date.now() - new Date(task.createdAt).getTime();
        const waitTimeSeconds = waitTimeMs / 1000;
        const agingBoost = waitTimeSeconds * queue.agingRate;

        // Update task with new boost
        task.agingBoost = agingBoost;
        const newScore = this.calculatePriorityScore(task);

        // Update in queue
        await this.redis.zadd(
          REDIS_KEYS.queue(priority),
          newScore,
          JSON.stringify(task)
        );

        // Check for starvation
        if (waitTimeMs > queue.maxWaitTimeMs) {
          this.emit('starvation-warning', {
            taskId: task.id,
            priority,
            waitTimeMs,
          });
        }
      }
    }
  }

  /**
   * Calculate priority score (lower = higher priority)
   */
  private calculatePriorityScore(task: PriorityTask): number {
    const baseScores: Record<TaskPriority, number> = {
      CRITICAL: 0,
      HIGH: 100,
      MEDIUM: 200,
      LOW: 300,
    };

    const baseScore = baseScores[task.priority];
    const agingPenalty = -task.agingBoost * 10; // Negative to increase priority
    const deadlinePenalty = this.calculateDeadlinePenalty(task);

    return baseScore + agingPenalty + deadlinePenalty;
  }

  /**
   * Calculate deadline penalty (negative = higher priority)
   */
  private calculateDeadlinePenalty(task: PriorityTask): number {
    if (!task.deadline) {return 0;}

    const now = Date.now();
    const deadline = new Date(task.deadline).getTime();
    const timeUntilDeadline = deadline - now;

    if (timeUntilDeadline < 0) {
      return -1000; // Overdue - maximum priority
    }

    if (timeUntilDeadline < 60000) {
      return -500; // Less than 1 minute
    }

    if (timeUntilDeadline < 300000) {
      return -200; // Less than 5 minutes
    }

    return 0;
  }

  /**
   * Estimate start time for a task
   */
  private estimateStartTime(_priority: TaskPriority, position: number): Date {
    const avgProcessingTime = 5000; // 5 seconds per task
    const estimatedWaitMs = position * avgProcessingTime;
    return new Date(Date.now() + estimatedWaitMs);
  }

  /**
   * Get queue statistics
   */
  async getStats(): Promise<PriorityStats> {
    const priorities: TaskPriority[] = ['CRITICAL', 'HIGH', 'MEDIUM', 'LOW'];
    const queueDepths: Record<TaskPriority, number> = {} as Record<TaskPriority, number>;
    const processedCounts: Record<TaskPriority, number> = {} as Record<TaskPriority, number>;

    for (const priority of priorities) {
      const depth = await this.redis.zcard(REDIS_KEYS.queue(priority));
      queueDepths[priority] = depth;

      const stats = await this.redis.hgetall(REDIS_KEYS.stats(priority));
      processedCounts[priority] = parseInt(stats.processed || '0', 10);
    }

    // Calculate average wait times
    const avgWaitTimes: Record<TaskPriority, number> = {} as Record<TaskPriority, number>;
    for (const priority of priorities) {
      const tasks = await this.redis.zrange(
        REDIS_KEYS.queue(priority),
        0,
        -1
      );

      if (tasks.length === 0) {
        avgWaitTimes[priority] = 0;
        continue;
      }

      let totalWait = 0;
      for (const taskJson of tasks) {
        const task: PriorityTask = JSON.parse(taskJson);
        totalWait += Date.now() - new Date(task.createdAt).getTime();
      }

      avgWaitTimes[priority] = totalWait / tasks.length;
    }

    // Count starved tasks
    let starvedTasks = 0;
    for (const priority of priorities) {
      const queue = PRIORITY_QUEUES[priority];
      const tasks = await this.redis.zrange(
        REDIS_KEYS.queue(priority),
        0,
        -1
      );

      for (const taskJson of tasks) {
        const task: PriorityTask = JSON.parse(taskJson);
        const waitTime = Date.now() - new Date(task.createdAt).getTime();
        if (waitTime > queue.maxWaitTimeMs) {
          starvedTasks++;
        }
      }
    }

    return {
      queueDepths,
      avgWaitTimes,
      processedCounts,
      starvedTasks,
    };
  }

  /**
   * Promote a task to higher priority
   */
  async promoteTask(taskId: string, newPriority: TaskPriority): Promise<boolean> {
    const taskJson = await this.redis.get(REDIS_KEYS.task(taskId));
    if (!taskJson) {return false;}

    const task: PriorityTask = JSON.parse(taskJson);
    const oldPriority = task.priority;

    // Remove from old queue
    await this.redis.zrem(REDIS_KEYS.queue(oldPriority), taskJson);

    // Update priority
    task.priority = newPriority;
    task.agingBoost = 0;

    // Add to new queue
    const score = this.calculatePriorityScore(task);
    await this.redis.zadd(
      REDIS_KEYS.queue(newPriority),
      score,
      JSON.stringify(task)
    );

    // Update stored task
    await this.redis.setex(
      REDIS_KEYS.task(taskId),
      86400,
      JSON.stringify(task)
    );

    this.logger.info(
      { taskId, from: oldPriority, to: newPriority },
      'Task priority promoted'
    );

    return true;
  }

  /**
   * Cancel a task
   */
  async cancelTask(taskId: string): Promise<boolean> {
    const taskJson = await this.redis.get(REDIS_KEYS.task(taskId));
    if (!taskJson) {return false;}

    const task: PriorityTask = JSON.parse(taskJson);

    // Remove from queue
    await this.redis.zrem(REDIS_KEYS.queue(task.priority), taskJson);

    // Delete task record
    await this.redis.del(REDIS_KEYS.task(taskId));

    this.logger.info({ taskId }, 'Task cancelled');

    return true;
  }
}

/**
 * RecoveryCoordinator - Orchestrates recovery procedures
 * 
 * Coordinates recovery actions across the system, maintains recovery state,
 * and prevents recovery storms with cooldown periods.
 */

import { PrismaClient } from '@prisma/client';
import { EventEmitter } from 'eventemitter3';
import Redis from 'ioredis';
import type { Logger } from 'pino';

// ============================================================================
// Types
// ============================================================================

export interface RecoveryPlan {
  id: string;
  incidentId: string;
  type: 'node-failure' | 'service-failure' | 'data-corruption' | 'network-partition' | 'cascade-failure';
  status: 'pending' | 'executing' | 'completed' | 'failed';
  steps: RecoveryStep[];
  startedAt: Date;
  completedAt?: Date;
  error?: string;
}

export interface RecoveryStep {
  name: string;
  action: string;
  status: 'pending' | 'in-progress' | 'completed' | 'failed' | 'skipped';
  startedAt?: Date;
  completedAt?: Date;
  error?: string;
}

export interface RecoveryConfig {
  cooldownMs: number;
  maxConcurrentRecoveries: number;
  stepTimeoutMs: number;
  enableAutoRecovery: boolean;
}

// ============================================================================
// Constants
// ============================================================================

const DEFAULT_CONFIG: RecoveryConfig = {
  cooldownMs: 300000, // 5 minutes
  maxConcurrentRecoveries: 3,
  stepTimeoutMs: 60000, // 1 minute per step
  enableAutoRecovery: true,
};

const RECOVERY_KEY_PREFIX = 'recovery:';
const COOLDOWN_KEY_PREFIX = 'recovery:cooldown:';

// ============================================================================
// RecoveryCoordinator Service
// ============================================================================

export class RecoveryCoordinator extends EventEmitter {
  private prisma: PrismaClient;
  private redis: Redis;
  private logger: Logger;
  private config: RecoveryConfig;
  private activeRecoveries: Map<string, RecoveryPlan> = new Map();
  private recoveryHistory: RecoveryPlan[] = [];
  private recoveryLock: Map<string, boolean> = new Map();

  constructor(
    prisma: PrismaClient,
    redis: Redis,
    logger: Logger,
    config: Partial<RecoveryConfig> = {}
  ) {
    super();
    this.prisma = prisma;
    this.redis = redis;
    this.logger = logger;
    this.config = { ...DEFAULT_CONFIG, ...config };
  }

  /**
   * Initiate a recovery plan
   */
  async initiateRecovery(
    incidentId: string,
    type: RecoveryPlan['type'],
    affectedEntities: string[]
  ): Promise<RecoveryPlan | null> {
    const recoveryId = `recovery-${Date.now()}-${Math.random().toString(36).substring(2, 7)}`;

    // Check cooldown
    if (await this.isOnCooldown(type)) {
      this.logger.info({ type, incidentId }, 'Recovery on cooldown');
      return null;
    }

    // Check concurrent limit
    if (this.activeRecoveries.size >= this.config.maxConcurrentRecoveries) {
      this.logger.warn('Max concurrent recoveries reached');
      return null;
    }

    // Check for duplicate recovery
    const lockKey = `${type}:${affectedEntities.join(',')}`;
    if (this.recoveryLock.has(lockKey)) {
      this.logger.info({ lockKey }, 'Recovery already in progress for these entities');
      return null;
    }

    // Create recovery plan
    const plan = this.createRecoveryPlan(recoveryId, incidentId, type, affectedEntities);
    this.activeRecoveries.set(recoveryId, plan);
    this.recoveryLock.set(lockKey, true);

    // Set cooldown
    await this.setCooldown(type);

    this.logger.info({ recoveryId, type, incidentId }, 'Initiating recovery');
    this.emit('recovery_started', plan);

    // Execute recovery
    try {
      await this.executeRecovery(plan);
      plan.status = 'completed';
      plan.completedAt = new Date();
      this.emit('recovery_completed', plan);
    } catch (error) {
      plan.status = 'failed';
      plan.error = (error as Error).message;
      plan.completedAt = new Date();
      this.emit('recovery_failed', plan);
    } finally {
      this.activeRecoveries.delete(recoveryId);
      this.recoveryLock.delete(lockKey);
      this.recoveryHistory.push(plan);
      // Keep only last 50 recoveries
      if (this.recoveryHistory.length > 50) {
        this.recoveryHistory.shift();
      }
    }

    return plan;
  }

  /**
   * Create a recovery plan based on incident type
   */
  private createRecoveryPlan(
    recoveryId: string,
    incidentId: string,
    type: RecoveryPlan['type'],
    affectedEntities: string[]
  ): RecoveryPlan {
    const steps = this.getRecoverySteps(type, affectedEntities);

    return {
      id: recoveryId,
      incidentId,
      type,
      status: 'pending',
      steps,
      startedAt: new Date(),
    };
  }

  /**
   * Get recovery steps for incident type
   */
  private getRecoverySteps(
    type: RecoveryPlan['type'],
    _affectedEntities: string[]
  ): RecoveryStep[] {
    switch (type) {
      case 'node-failure':
        return [
          { name: 'Isolate failed node', action: 'isolate-node', status: 'pending' },
          { name: 'Reschedule tasks', action: 'reschedule-tasks', status: 'pending' },
          { name: 'Update node status', action: 'update-status', status: 'pending' },
          { name: 'Notify monitoring', action: 'notify', status: 'pending' },
        ];

      case 'service-failure':
        return [
          { name: 'Check service health', action: 'health-check', status: 'pending' },
          { name: 'Restart service', action: 'restart-service', status: 'pending' },
          { name: 'Verify recovery', action: 'verify', status: 'pending' },
        ];

      case 'data-corruption':
        return [
          { name: 'Stop affected services', action: 'stop-services', status: 'pending' },
          { name: 'Restore from backup', action: 'restore-backup', status: 'pending' },
          { name: 'Verify data integrity', action: 'verify-integrity', status: 'pending' },
          { name: 'Restart services', action: 'restart-services', status: 'pending' },
        ];

      case 'network-partition':
        return [
          { name: 'Identify partition', action: 'identify-partition', status: 'pending' },
          { name: 'Isolate affected nodes', action: 'isolate-nodes', status: 'pending' },
          { name: 'Wait for network recovery', action: 'wait', status: 'pending' },
          { name: 'Reintegrate nodes', action: 'reintegrate', status: 'pending' },
        ];

      case 'cascade-failure':
        return [
          { name: 'Stop cascade', action: 'stop-cascade', status: 'pending' },
          { name: 'Assess damage', action: 'assess', status: 'pending' },
          { name: 'Prioritize recovery', action: 'prioritize', status: 'pending' },
          { name: 'Execute recovery', action: 'execute', status: 'pending' },
          { name: 'Verify system stability', action: 'verify', status: 'pending' },
        ];

      default:
        return [{ name: 'Generic recovery', action: 'generic', status: 'pending' }];
    }
  }

  /**
   * Execute recovery plan
   */
  private async executeRecovery(plan: RecoveryPlan): Promise<void> {
    plan.status = 'executing';

    for (const step of plan.steps) {
      step.status = 'in-progress';
      step.startedAt = new Date();

      this.logger.info({ recoveryId: plan.id, step: step.name }, 'Executing recovery step');
      this.emit('step_started', { planId: plan.id, step });

      try {
        await this.executeStep(step, plan);
        step.status = 'completed';
        step.completedAt = new Date();
        this.emit('step_completed', { planId: plan.id, step });
      } catch (error) {
        step.status = 'failed';
        step.error = (error as Error).message;
        step.completedAt = new Date();
        this.emit('step_failed', { planId: plan.id, step, error });

        // Decide whether to continue or abort
        if (this.isCriticalStep(step)) {
          throw new Error(`Critical step failed: ${step.name}`);
        }
      }
    }
  }

  /**
   * Execute a recovery step
   */
  private async executeStep(step: RecoveryStep, plan: RecoveryPlan): Promise<void> {
    switch (step.action) {
      case 'isolate-node':
        await this.isolateNode(plan);
        break;
      case 'reschedule-tasks':
        await this.rescheduleTasks(plan);
        break;
      case 'update-status':
        await this.updateNodeStatus(plan);
        break;
      case 'restart-service':
        await this.restartService(plan);
        break;
      case 'health-check':
        await this.healthCheck(plan);
        break;
      case 'verify':
        await this.verifyRecovery(plan);
        break;
      case 'notify':
        await this.notify(plan);
        break;
      default:
        this.logger.warn({ action: step.action }, 'Unknown recovery action');
    }
  }

  /**
   * Check if a step is critical
   */
  private isCriticalStep(step: RecoveryStep): boolean {
    const criticalSteps = ['isolate-node', 'stop-cascade', 'restore-backup'];
    return criticalSteps.includes(step.action);
  }

  // Recovery step implementations

  private async isolateNode(plan: RecoveryPlan): Promise<void> {
    // Mark node as isolated in Redis
    const key = `${RECOVERY_KEY_PREFIX}isolated:${plan.incidentId}`;
    await this.redis.setex(key, 3600, 'true');
  }

  private async rescheduleTasks(plan: RecoveryPlan): Promise<void> {
    // Find tasks on failed node and reschedule
    const tasks = await this.prisma.task.findMany({
      where: {
        status: { in: ['SCHEDULED', 'RUNNING'] },
      },
      take: 100,
    });

    for (const task of tasks) {
      await this.prisma.task.update({
        where: { id: task.id },
        data: {
          nodeId: null,
          status: 'PENDING',
          reason: `Rescheduled by recovery ${plan.id}`,
        },
      });

      await this.redis.zadd('task:queue', Date.now(), task.id);
    }
  }

  private async updateNodeStatus(plan: RecoveryPlan): Promise<void> {
    // Update node status in database
    this.logger.info({ incidentId: plan.incidentId }, 'Updating node status');
  }

  private async restartService(_plan: RecoveryPlan): Promise<void> {
    // Kubernetes restart implementation
    this.logger.info('Restarting service via Kubernetes');
  }

  private async healthCheck(_plan: RecoveryPlan): Promise<void> {
    // Run health checks
    await new Promise((resolve) => setTimeout(resolve, 1000));
  }

  private async verifyRecovery(_plan: RecoveryPlan): Promise<void> {
    // Verify system has recovered
    await new Promise((resolve) => setTimeout(resolve, 2000));
  }

  private async notify(plan: RecoveryPlan): Promise<void> {
    // Notify monitoring system
    this.emit('notification', {
      type: 'recovery',
      planId: plan.id,
      status: plan.status,
    });
  }

  // Cooldown management

  private async isOnCooldown(type: string): Promise<boolean> {
    const key = `${COOLDOWN_KEY_PREFIX}${type}`;
    const cooldown = await this.redis.get(key);
    return cooldown !== null;
  }

  private async setCooldown(type: string): Promise<void> {
    const key = `${COOLDOWN_KEY_PREFIX}${type}`;
    await this.redis.setex(key, Math.floor(this.config.cooldownMs / 1000), 'true');
  }

  // Status methods

  getActiveRecoveries(): RecoveryPlan[] {
    return Array.from(this.activeRecoveries.values());
  }

  getRecoveryHistory(limit: number = 20): RecoveryPlan[] {
    return this.recoveryHistory.slice(-limit);
  }

  getStats(): {
    activeRecoveries: number;
    totalRecoveries: number;
    byType: Record<string, number>;
    successRate: number;
  } {
    const byType: Record<string, number> = {};
    let successful = 0;

    for (const plan of this.recoveryHistory) {
      byType[plan.type] = (byType[plan.type] || 0) + 1;
      if (plan.status === 'completed') {successful++;}
    }

    return {
      activeRecoveries: this.activeRecoveries.size,
      totalRecoveries: this.recoveryHistory.length,
      byType,
      successRate: this.recoveryHistory.length > 0 
        ? successful / this.recoveryHistory.length 
        : 1,
    };
  }
}

