/**
 * Scheduler Rate Limiter
 * 
 * Enforces rate limits at scheduler level:
 * - Tasks per node
 * - Tasks per user
 * - Global task rate
 */

import { EventEmitter } from 'eventemitter3';
import Redis from 'ioredis';

import type { Logger } from 'pino';

// ============================================================================
// Types
// ============================================================================

export interface SchedulerRateLimitConfig {
  maxTasksPerNodePerMinute: number;
  maxTasksPerUserPerHour: number;
  maxGlobalTasksPerMinute: number;
  maxPendingTasksPerNode: number;
  maxPendingTasksGlobal: number;
  burstAllowance: number;
}

export interface RateLimitCheck {
  allowed: boolean;
  reason?: string;
  retryAfterMs?: number;
  currentUsage?: RateLimitUsage;
}

export interface RateLimitUsage {
  globalTasksPerMinute: number;
  userTasksPerHour: number;
  nodeTasksPerMinute: number;
  pendingGlobal: number;
  pendingPerNode: Record<string, number>;
}

export interface RateLimitViolation {
  type: string;
  identifier: string;
  current: number;
  limit: number;
  timestamp: Date;
}

// ============================================================================
// Constants
// ============================================================================

const DEFAULT_CONFIG: SchedulerRateLimitConfig = {
  maxTasksPerNodePerMinute: 60,
  maxTasksPerUserPerHour: 1000,
  maxGlobalTasksPerMinute: 10000,
  maxPendingTasksPerNode: 100,
  maxPendingTasksGlobal: 5000,
  burstAllowance: 10, // Allow 10% burst over limit
};

const REDIS_KEYS = {
  globalTasksPerMinute: 'scheduler:rate:global:minute',
  userTasksPerHour: (userId: string) => `scheduler:rate:user:${userId}:hour`,
  nodeTasksPerMinute: (nodeId: string) => `scheduler:rate:node:${nodeId}:minute`,
  pendingGlobal: 'scheduler:pending:global',
  pendingNode: (nodeId: string) => `scheduler:pending:node:${nodeId}`,
};

// ============================================================================
// SchedulerRateLimiter
// ============================================================================

export class SchedulerRateLimiter extends EventEmitter {
  private redis: Redis;
  private logger: Logger;
  private config: SchedulerRateLimitConfig;

  constructor(redis: Redis, logger: Logger, config: Partial<SchedulerRateLimitConfig> = {}) {
    super();
    this.redis = redis;
    this.logger = logger;
    this.config = { ...DEFAULT_CONFIG, ...config };
  }

  /**
   * Check if a task scheduling request is allowed
   */
  async checkRateLimit(
    _taskId: string,
    userId: string,
    nodeId: string
  ): Promise<RateLimitCheck> {
    const usage = await this.getCurrentUsage(userId, nodeId);

    // Check global rate limit
    const globalLimit = this.config.maxGlobalTasksPerMinute * (1 + this.config.burstAllowance);
    if (usage.globalTasksPerMinute >= globalLimit) {
      this.emit('violation', {
        type: 'global_rate',
        identifier: 'global',
        current: usage.globalTasksPerMinute,
        limit: globalLimit,
        timestamp: new Date(),
      } as RateLimitViolation);

      return {
        allowed: false,
        reason: 'Global rate limit exceeded',
        retryAfterMs: 60000 - (Date.now() % 60000),
        currentUsage: usage,
      };
    }

    // Check per-user rate limit
    const userLimit = this.config.maxTasksPerUserPerHour * (1 + this.config.burstAllowance);
    if (usage.userTasksPerHour >= userLimit) {
      this.emit('violation', {
        type: 'user_rate',
        identifier: userId,
        current: usage.userTasksPerHour,
        limit: userLimit,
        timestamp: new Date(),
      } as RateLimitViolation);

      return {
        allowed: false,
        reason: `User ${userId} rate limit exceeded`,
        retryAfterMs: 3600000 - (Date.now() % 3600000),
        currentUsage: usage,
      };
    }

    // Check per-node rate limit
    const nodeLimit = this.config.maxTasksPerNodePerMinute * (1 + this.config.burstAllowance);
    if (usage.nodeTasksPerMinute >= nodeLimit) {
      this.emit('violation', {
        type: 'node_rate',
        identifier: nodeId,
        current: usage.nodeTasksPerMinute,
        limit: nodeLimit,
        timestamp: new Date(),
      } as RateLimitViolation);

      return {
        allowed: false,
        reason: `Node ${nodeId} rate limit exceeded`,
        retryAfterMs: 60000 - (Date.now() % 60000),
        currentUsage: usage,
      };
    }

    // Check pending tasks limits
    if (usage.pendingGlobal >= this.config.maxPendingTasksGlobal) {
      return {
        allowed: false,
        reason: 'Global pending task limit exceeded',
        currentUsage: usage,
      };
    }

    const nodePending = usage.pendingPerNode[nodeId] || 0;
    if (nodePending >= this.config.maxPendingTasksPerNode) {
      return {
        allowed: false,
        reason: `Node ${nodeId} pending task limit exceeded`,
        currentUsage: usage,
      };
    }

    return {
      allowed: true,
      currentUsage: usage,
    };
  }

  /**
   * Record a task scheduling event
   */
  async recordTaskScheduled(userId: string, nodeId: string): Promise<void> {
    const now = Date.now();
    const minuteKey = Math.floor(now / 60000);
    const hourKey = Math.floor(now / 3600000);

    // Increment counters with TTL
    const pipeline = this.redis.pipeline();

    // Global per-minute counter
    pipeline.incr(`${REDIS_KEYS.globalTasksPerMinute}:${minuteKey}`);
    pipeline.expire(`${REDIS_KEYS.globalTasksPerMinute}:${minuteKey}`, 120);

    // User per-hour counter
    pipeline.incr(`${REDIS_KEYS.userTasksPerHour(userId)}:${hourKey}`);
    pipeline.expire(`${REDIS_KEYS.userTasksPerHour(userId)}:${hourKey}`, 7200);

    // Node per-minute counter
    pipeline.incr(`${REDIS_KEYS.nodeTasksPerMinute(nodeId)}:${minuteKey}`);
    pipeline.expire(`${REDIS_KEYS.nodeTasksPerMinute(nodeId)}:${minuteKey}`, 120);

    // Pending task counters
    pipeline.incr(REDIS_KEYS.pendingGlobal);
    pipeline.incr(REDIS_KEYS.pendingNode(nodeId));

    await pipeline.exec();

    this.logger.debug({ userId, nodeId }, 'Recorded task scheduling');
  }

  /**
   * Record task completion (decrement pending)
   */
  async recordTaskCompleted(nodeId: string): Promise<void> {
    const pipeline = this.redis.pipeline();

    pipeline.decr(REDIS_KEYS.pendingGlobal);
    pipeline.decr(REDIS_KEYS.pendingNode(nodeId));

    await pipeline.exec();
  }

  /**
   * Get current rate limit usage
   */
  async getCurrentUsage(userId: string, nodeId: string): Promise<RateLimitUsage> {
    const now = Date.now();
    const minuteKey = Math.floor(now / 60000);
    const hourKey = Math.floor(now / 3600000);

    const [globalMinute, userHour, nodeMinute, pendingGlobal, pendingNode] = await Promise.all([
      this.redis.get(`${REDIS_KEYS.globalTasksPerMinute}:${minuteKey}`),
      this.redis.get(`${REDIS_KEYS.userTasksPerHour(userId)}:${hourKey}`),
      this.redis.get(`${REDIS_KEYS.nodeTasksPerMinute(nodeId)}:${minuteKey}`),
      this.redis.get(REDIS_KEYS.pendingGlobal),
      this.redis.get(REDIS_KEYS.pendingNode(nodeId)),
    ]);

    return {
      globalTasksPerMinute: globalMinute ? parseInt(globalMinute, 10) : 0,
      userTasksPerHour: userHour ? parseInt(userHour, 10) : 0,
      nodeTasksPerMinute: nodeMinute ? parseInt(nodeMinute, 10) : 0,
      pendingGlobal: pendingGlobal ? parseInt(pendingGlobal, 10) : 0,
      pendingPerNode: nodeId && pendingNode ? { [nodeId]: parseInt(pendingNode, 10) } : {},
    };
  }

  /**
   * Get rate limit status for all nodes
   */
  async getNodeRateLimits(): Promise<Record<string, number>> {
    const keys = await this.redis.keys('scheduler:rate:node:*:minute:*');
    const result: Record<string, number> = {};

    for (const key of keys) {
      const match = key.match(/scheduler:rate:node:([^:]+):minute:/);
      if (match && match[1]) {
        const nodeId = match[1];
        const count = await this.redis.get(key);
        if (count) {
          result[nodeId] = parseInt(count, 10);
        }
      }
    }

    return result;
  }

  /**
   * Reset rate limits (for testing)
   */
  async reset(): Promise<void> {
    const keys = await this.redis.keys('scheduler:rate:*');
    if (keys.length > 0) {
      await this.redis.del(...keys);
    }
  }

  /**
   * Get current configuration
   */
  getConfig(): SchedulerRateLimitConfig {
    return { ...this.config };
  }

  /**
   * Update configuration
   */
  updateConfig(newConfig: Partial<SchedulerRateLimitConfig>): void {
    this.config = { ...this.config, ...newConfig };
    this.logger.info({ config: this.config }, 'Rate limit config updated');
  }
}

import { PrismaClient } from '@prisma/client'
import Redis from 'ioredis'
import type { Logger } from 'pino'

export interface SLATarget {
  id: string
  name: string
  metric: string
  target: number
  unit: string
  window: number // in seconds
  severity: 'critical' | 'high' | 'medium'
}

export interface SLAMetric {
  timestamp: number
  value: number
  labels: Record<string, string>
}

export interface SLAStatus {
  target: SLATarget
  current: number
  status: 'healthy' | 'warning' | 'breach'
  percentage: number
  trend: 'improving' | 'stable' | 'degrading'
}

const DEFAULT_SLA_TARGETS: SLATarget[] = [
  {
    id: 'availability',
    name: 'System Availability',
    metric: 'uptime',
    target: 99.9,
    unit: 'percent',
    window: 2592000, // 30 days
    severity: 'critical',
  },
  {
    id: 'api-latency-p99',
    name: 'API Latency (P99)',
    metric: 'latency',
    target: 500,
    unit: 'ms',
    window: 300, // 5 minutes
    severity: 'high',
  },
  {
    id: 'api-latency-p95',
    name: 'API Latency (P95)',
    metric: 'latency',
    target: 200,
    unit: 'ms',
    window: 300,
    severity: 'medium',
  },
  {
    id: 'task-success-rate',
    name: 'Task Success Rate',
    metric: 'task_success',
    target: 95,
    unit: 'percent',
    window: 3600, // 1 hour
    severity: 'high',
  },
  {
    id: 'node-availability',
    name: 'Node Availability',
    metric: 'node_uptime',
    target: 99.5,
    unit: 'percent',
    window: 86400, // 1 day
    severity: 'high',
  },
  {
    id: 'error-rate',
    name: 'Error Rate',
    metric: 'error_rate',
    target: 1,
    unit: 'percent',
    window: 300,
    severity: 'critical',
  },
]

export class SLAMonitor {
  private prisma: PrismaClient
  private redis: Redis
  private _logger: Logger
  private targets: SLATarget[]

  constructor(prisma: PrismaClient, redis: Redis, logger: Logger, targets?: SLATarget[]) {
    this.prisma = prisma
    this.redis = redis
    this._logger = logger
    this.targets = targets || DEFAULT_SLA_TARGETS
  }

  /**
   * Record a metric for SLA calculation
   */
  async recordMetric(metric: string, value: number, labels: Record<string, string> = {}): Promise<void> {
    const timestamp = Date.now()
    const key = `sla:metrics:${metric}`

    // Store in Redis sorted set for time-series data
    await this.redis.zadd(key, timestamp, JSON.stringify({ value, labels, timestamp }))

    // Trim old data (keep last 30 days)
    const cutoff = timestamp - 30 * 24 * 60 * 60 * 1000
    await this.redis.zremrangebyscore(key, '-inf', cutoff)
  }

  /**
   * Get current SLA status for all targets
   */
  async getStatus(): Promise<SLAStatus[]> {
    const statuses: SLAStatus[] = []

    for (const target of this.targets) {
      const status = await this.getTargetStatus(target)
      statuses.push(status)
    }

    return statuses
  }

  /**
   * Get status for a specific SLA target
   */
  private async getTargetStatus(target: SLATarget): Promise<SLAStatus> {
    const now = Date.now()
    const windowStart = now - target.window * 1000

    let current: number
    let trend: 'improving' | 'stable' | 'degrading' = 'stable'

    switch (target.metric) {
      case 'uptime':
        current = await this.calculateUptime(windowStart, now)
        break
      case 'latency':
        current = await this.calculateLatency(windowStart, now, target.id.includes('p99') ? 99 : 95)
        break
      case 'task_success':
        current = await this.calculateTaskSuccessRate(windowStart, now)
        break
      case 'node_uptime':
        current = await this.calculateNodeUptime(windowStart, now)
        break
      case 'error_rate':
        current = await this.calculateErrorRate(windowStart, now)
        break
      default:
        current = 0
    }

    // Calculate trend (compare with previous window)
    const previousStart = windowStart - target.window * 1000
    let previous: number

    switch (target.metric) {
      case 'uptime':
        previous = await this.calculateUptime(previousStart, windowStart)
        break
      case 'latency':
        previous = await this.calculateLatency(previousStart, windowStart, target.id.includes('p99') ? 99 : 95)
        break
      default:
        previous = current
    }

    if (target.unit === 'percent') {
      trend = current > previous ? 'improving' : current < previous ? 'degrading' : 'stable'
    } else {
      // For latency and error rate, lower is better
      trend = current < previous ? 'improving' : current > previous ? 'degrading' : 'stable'
    }

    // Determine status
    let status: 'healthy' | 'warning' | 'breach'
    const percentage = target.unit === 'percent'
      ? (current / target.target) * 100
      : (target.target / current) * 100

    if (target.unit === 'percent') {
      if (current >= target.target) {
        status = 'healthy'
      } else if (current >= target.target * 0.95) {
        status = 'warning'
      } else {
        status = 'breach'
      }
    } else {
      // For latency/error rate, lower is better
      if (current <= target.target) {
        status = 'healthy'
      } else if (current <= target.target * 1.5) {
        status = 'warning'
      } else {
        status = 'breach'
      }
    }

    return {
      target,
      current,
      status,
      percentage,
      trend,
    }
  }

  private async calculateUptime(start: number, end: number): Promise<number> {
    // Get total time and downtime from metrics
    const totalTime = (end - start) / 1000
    const downtime = await this.getDowntimeSeconds(start, end)
    return ((totalTime - downtime) / totalTime) * 100
  }

  private async getDowntimeSeconds(start: number, end: number): Promise<number> {
    // Query from Redis or database
    const key = 'sla:downtime'
    const entries = await this.redis.zrangebyscore(key, start, end, 'WITHSCORES')
    // Sum downtime
    return entries.length * 10 // Simplified
  }

  private async calculateLatency(start: number, end: number, percentile: number): Promise<number> {
    const key = 'sla:metrics:latency'
    const entries = await this.redis.zrangebyscore(key, start, end)
    
    if (entries.length === 0) {return 0}

    const latencies = entries
      .map((e) => JSON.parse(e).value)
      .sort((a, b) => a - b)

    const index = Math.ceil((percentile / 100) * latencies.length) - 1
    return latencies[index] || 0
  }

  private async calculateTaskSuccessRate(_start: number, _end: number): Promise<number> {
    const completed = await this.prisma.task.count({
      where: {
        status: 'COMPLETED',
      },
    })

    const failed = await this.prisma.task.count({
      where: {
        status: 'FAILED',
      },
    })

    const total = completed + failed
    return total > 0 ? (completed / total) * 100 : 100
  }

  private async calculateNodeUptime(_start: number, _end: number): Promise<number> {
    const onlineNodes = await this.prisma.edgeNode.count({
      where: { status: 'ONLINE' },
    })

    const totalNodes = await this.prisma.edgeNode.count()
    return totalNodes > 0 ? (onlineNodes / totalNodes) * 100 : 100
  }

  private async calculateErrorRate(start: number, end: number): Promise<number> {
    const key = 'sla:metrics:error_rate'
    const entries = await this.redis.zrangebyscore(key, start, end)

    if (entries.length === 0) {return 0}

    const sum = entries.reduce((acc, e) => acc + JSON.parse(e).value, 0)
    return sum / entries.length
  }

  /**
   * Generate SLA report
   */
  async generateReport(period: 'daily' | 'weekly' | 'monthly'): Promise<{
    period: string
    generatedAt: string
    targets: SLAStatus[]
    summary: {
      healthy: number
      warning: number
      breach: number
      overallScore: number
    }
  }> {
    const statuses = await this.getStatus()
    
    const healthy = statuses.filter((s) => s.status === 'healthy').length
    const warning = statuses.filter((s) => s.status === 'warning').length
    const breach = statuses.filter((s) => s.status === 'breach').length

    const overallScore = statuses.reduce((sum, s) => {
      const weight = s.target.severity === 'critical' ? 3 : s.target.severity === 'high' ? 2 : 1
      const score = s.status === 'healthy' ? 100 : s.status === 'warning' ? 70 : 30
      return sum + score * weight
    }, 0) / statuses.reduce((sum, s) => {
      const weight = s.target.severity === 'critical' ? 3 : s.target.severity === 'high' ? 2 : 1
      return sum + weight
    }, 0)

    return {
      period,
      generatedAt: new Date().toISOString(),
      targets: statuses,
      summary: {
        healthy,
        warning,
        breach,
        overallScore,
      },
    }
  }
}

/**
 * TaskScheduler - CONTROL PLANE COMPONENT
 * 
 * RESPONSIBILITY: Makes scheduling decisions only
 * DOES NOT: Execute tasks, manage containers, or collect metrics
 * 
 * This service operates purely in the control plane, making decisions about
 * which node should execute a task based on policies and node state.
 * Actual task execution is delegated to the data plane (Edge Agents).
 */

import { CircuitBreakerRegistry } from '@edgecloud/circuit-breaker'
import { SchedulingPredictor, type ScoreWeights } from '@edgecloud/ml-scheduler'
import { PrismaClient } from '@prisma/client'
import axios, { AxiosError } from 'axios'
import Redis from 'ioredis'
import type { Logger } from 'pino'

import type { WebSocketManager } from './websocket-manager'





const SCHEDULING_INTERVAL = 5000 // 5 seconds
const TASK_TIMEOUT = 300000 // 5 minutes
const REDIS_KEY_TTL = 86400 // 24 hours
const REQUEST_TIMEOUT = 30000 // 30 seconds
const CIRCUIT_BREAKER_THRESHOLD = 5 // failures before opening
const CIRCUIT_BREAKER_RESET_TIME = 60000 // 1 minute
const LEADER_LOCK_TTL = 10000 // 10 seconds leader lock TTL
const LEADER_LOCK_KEY = 'scheduler:leader:lock'

// Local type definitions to avoid Prisma import issues
type TaskStatusType = 'PENDING' | 'SCHEDULED' | 'RUNNING' | 'COMPLETED' | 'FAILED' | 'CANCELLED'

interface Task {
  id: string
  name: string
  type: string
  status: TaskStatusType
  priority: string
  target: string
  nodeId: string | null
  policy: string
  reason: string
  submittedAt: Date
  maxRetries: number
  input: unknown
  metadata: unknown
}

// Scheduling decision - pure control plane output
export interface SchedulingDecision {
  taskId: string
  nodeId: string
  nodeUrl: string
  policy: string
  reason: string
  estimatedCost?: number
  estimatedLatency?: number
}

export class TaskScheduler {
  private prisma: PrismaClient
  private redis: Redis
  private wsManager: WebSocketManager
  private logger: Logger
  private interval: ReturnType<typeof setInterval> | null = null
  private leaderInterval: ReturnType<typeof setInterval> | null = null
  private queueKey = 'task:queue'
  private circuitBreakerRegistry: CircuitBreakerRegistry
  private predictor: SchedulingPredictor
  private schedulerWeights: ScoreWeights
  private instanceId: string
  private isLeader = false
  private leaderLockRenewalInterval: ReturnType<typeof setInterval> | null = null
  
  // Integration services
  private priorityScheduler?: any
  private backpressureController?: any
  private gracefulDegradation?: any
  private schedulerRateLimiter?: any

  constructor(prisma: PrismaClient, redis: Redis, wsManager: WebSocketManager, logger: Logger) {
    this.prisma = prisma
    this.redis = redis
    this.wsManager = wsManager
    this.logger = logger
    this.circuitBreakerRegistry = new CircuitBreakerRegistry()
    
    // Initialize ML scheduler components
    this.predictor = new SchedulingPredictor()
    
    // Default weights - can be updated via API
    this.schedulerWeights = {
      latency: 0.2,
      cpu: 0.15,
      memory: 0.15,
      cost: 0.2,
      network: 0.1,
      ml: 0.1,
      health: 0.1,
    }
    
    // Generate unique instance ID for this scheduler instance
    this.instanceId = `scheduler-${Date.now()}-${Math.random().toString(36).substring(2, 9)}`
  }

  // Setter methods for integration
  setPriorityScheduler(scheduler: any) {
    this.priorityScheduler = scheduler
  }

  setBackpressureController(controller: any) {
    this.backpressureController = controller
  }

  setGracefulDegradation(service: any) {
    this.gracefulDegradation = service
  }

  setSchedulerRateLimiter(limiter: any) {
    this.schedulerRateLimiter = limiter
  }

  setColdStartHandler(_handler: any) {
    // Cold start handler stored for future use
  }

  async start() {
    // Attempt to become leader before starting scheduling
    await this.tryBecomeLeader()
    
    // Start leader election heartbeat
    this.leaderInterval = setInterval(() => this.maintainLeadership(), LEADER_LOCK_TTL / 2)
    
    // Only process queue if we are the leader
    this.interval = setInterval(() => {
      if (this.isLeader) {
        this.processQueue()
      }
    }, SCHEDULING_INTERVAL)
    
    // Start reconciliation job (every 5 minutes) to fix drift
    setInterval(() => {
      if (this.isLeader) {
        this.reconcileTaskCounts()
      }
    }, 300000)
    
    this.logger.info({ instanceId: this.instanceId, isLeader: this.isLeader }, 'Task scheduler started')
  }

  /**
   * Reconcile task counts to fix drift between actual and recorded
   */
  private async reconcileTaskCounts(): Promise<void> {
    try {
      const nodes = await this.prisma.edgeNode.findMany({
        select: { id: true, tasksRunning: true }
      })

      for (const node of nodes) {
        // Count actual running tasks for this node
        const actualCount = await this.prisma.task.count({
          where: {
            nodeId: node.id,
            status: { in: ['RUNNING', 'SCHEDULED'] }
          }
        })

        // Update if drift detected
        if (node.tasksRunning !== actualCount) {
          this.logger.warn(
            { nodeId: node.id, recorded: node.tasksRunning, actual: actualCount },
            'Task count drift detected, reconciling'
          )
          
          await this.prisma.edgeNode.update({
            where: { id: node.id },
            data: { tasksRunning: actualCount }
          })
        }
      }
    } catch (error) {
      this.logger.error({ error }, 'Task count reconciliation failed')
    }
  }

  stop() {
    if (this.interval) {
      clearInterval(this.interval)
      this.interval = null
    }
    if (this.leaderInterval) {
      clearInterval(this.leaderInterval)
      this.leaderInterval = null
    }
    if (this.leaderLockRenewalInterval) {
      clearInterval(this.leaderLockRenewalInterval)
      this.leaderLockRenewalInterval = null
    }
    
    // Release leadership on graceful shutdown
    if (this.isLeader) {
      this.releaseLeadership()
    }
    
    this.logger.info({ instanceId: this.instanceId }, 'Task scheduler stopped')
  }

  /**
   * Attempt to acquire leader lock using Redis Redlock pattern
   */
  private async tryBecomeLeader(): Promise<boolean> {
    try {
      // Use SET NX EX for atomic lock acquisition
      const acquired = await this.redis.set(
        LEADER_LOCK_KEY,
        this.instanceId,
        'PX',
        LEADER_LOCK_TTL,
        'NX'
      )
      
      if (acquired === 'OK') {
        this.isLeader = true
        this.logger.info({ instanceId: this.instanceId }, 'Became scheduler leader')
        return true
      }
      
      // Check if current leader is still alive
      const currentLeader = await this.redis.get(LEADER_LOCK_KEY)
      this.logger.debug({ currentLeader, myId: this.instanceId }, 'Leader lock held by another instance')
      return false
    } catch (error) {
      this.logger.error({ error, instanceId: this.instanceId }, 'Failed to acquire leader lock')
      return false
    }
  }

  /**
   * Maintain leadership by renewing the lock
   */
  private async maintainLeadership(): Promise<void> {
    if (!this.isLeader) {
      // Try to become leader if we're not currently
      await this.tryBecomeLeader()
      return
    }

    try {
      // Use Lua script for atomic check-and-renew
      const renewScript = `
        if redis.call("get", KEYS[1]) == ARGV[1] then
          return redis.call("expire", KEYS[1], ARGV[2])
        else
          return 0
        end
      `
      
      const renewed = await this.redis.eval(
        renewScript,
        1,
        LEADER_LOCK_KEY,
        this.instanceId,
        Math.floor(LEADER_LOCK_TTL / 1000)
      )
      
      if (!renewed) {
        // Lost leadership
        this.isLeader = false
        this.logger.warn({ instanceId: this.instanceId }, 'Lost scheduler leadership')
      }
    } catch (error) {
      this.logger.error({ error, instanceId: this.instanceId }, 'Failed to renew leader lock')
      this.isLeader = false
    }
  }

  /**
   * Release leadership lock on shutdown
   */
  private async releaseLeadership(): Promise<void> {
    try {
      const releaseScript = `
        if redis.call("get", KEYS[1]) == ARGV[1] then
          return redis.call("del", KEYS[1])
        else
          return 0
        end
      `
      
      await this.redis.eval(releaseScript, 1, LEADER_LOCK_KEY, this.instanceId)
      this.isLeader = false
      this.logger.info({ instanceId: this.instanceId }, 'Released scheduler leadership')
    } catch (error) {
      this.logger.error({ error, instanceId: this.instanceId }, 'Failed to release leadership')
    }
  }

  /**
   * Check if this scheduler instance is currently the leader
   */
  isCurrentlyLeader(): boolean {
    return this.isLeader
  }

  async enqueue(task: Task) {
    // Add to Redis queue with priority
    const priority = this.getPriorityScore(task)
    await this.redis.zadd(this.queueKey, priority, task.id)
    // Set TTL on the queue key
    await this.redis.expire(this.queueKey, REDIS_KEY_TTL)
    this.logger.info({ taskId: task.id, priority }, 'Task enqueued')
  }

  async dequeue(taskId: string) {
    // Remove task from queue
    await this.redis.zrem(this.queueKey, taskId)
    this.logger.info({ taskId }, 'Task dequeued')
  }

  private getPriorityScore(task: Task): number {
    const now = Date.now()
    const age = now - task.submittedAt.getTime()
    const ageScore = Math.min(age / 60000, 10) // Max 10 points for age

    const priorityScores: Record<string, number> = {
      CRITICAL: 100,
      HIGH: 75,
      MEDIUM: 50,
      LOW: 25,
    }

    return (priorityScores[task.priority] || 0) + ageScore
  }

  // Circuit breaker methods using CircuitBreakerRegistry with Redis sync
  private async isCircuitOpen(nodeId: string): Promise<boolean> {
    // Check distributed state first (Redis)
    const distributedState = await this.redis.get(`circuit:${nodeId}:state`);
    if (distributedState === 'OPEN') {
      return true;
    }

    const breaker = this.circuitBreakerRegistry.getOrCreate(nodeId, {
      failureThreshold: CIRCUIT_BREAKER_THRESHOLD,
      resetTimeout: CIRCUIT_BREAKER_RESET_TIME,
      name: nodeId,
    });
    
    const isOpen = breaker.getState() === 'OPEN';
    
    // Sync to Redis if open
    if (isOpen) {
      await this.redis.setex(`circuit:${nodeId}:state`, 60, 'OPEN');
    }
    
    return isOpen;
  }

  private async recordSuccess(nodeId: string) {
    const breaker = this.circuitBreakerRegistry.get(nodeId);
    if (breaker) {
      breaker.forceClose();
    }
    // Clear distributed state
    await this.redis.del(`circuit:${nodeId}:state`);
  }

  /**
   * Get circuit breaker health for all nodes
   */
  getCircuitBreakerHealth() {
    return this.circuitBreakerRegistry.healthCheck();
  }

  private async processQueue() {
    try {
      // Check backpressure before processing
      if (this.backpressureController) {
        const decision = await this.backpressureController.shouldAcceptTask('MEDIUM')
        if (decision.shouldThrottle) {
          this.logger.debug({ reason: decision.reason }, 'Backpressure throttling task processing')
          return
        }
      }

      // Get highest priority task (from priority scheduler if available)
      let taskId: string | null = null
      
      if (this.priorityScheduler) {
        const batch = await this.priorityScheduler.getNextBatch(1)
        if (batch.length > 0) {
          taskId = batch[0].id
        }
      } else {
        // Fallback to legacy queue
        const taskIds = await this.redis.zrevrange(this.queueKey, 0, 0)
        taskId = taskIds[0] || null
      }

      if (!taskId) {return}

      // Get task from database
      const task = await this.prisma.task.findUnique({ where: { id: taskId } })

      if (!task || task.status !== 'PENDING') {
        // Remove from queue if not pending
        await this.redis.zrem(this.queueKey, taskId)
        return
      }

      // Check rate limiting
      if (this.schedulerRateLimiter) {
        const userId = (task as any).userId || 'system'
        const rateLimitCheck = await this.schedulerRateLimiter.checkRateLimit(taskId, userId, 'pending')
        if (!rateLimitCheck.allowed) {
          this.logger.debug({ taskId, reason: rateLimitCheck.reason }, 'Rate limit exceeded, deferring task')
          return
        }
      }

      // Find suitable node
      const node = await this.findNode(task)

      if (!node) {
        this.logger.debug({ taskId }, 'No suitable node found, task remains in queue')
        return
      }

      // Check circuit breaker
      if (await this.isCircuitOpen(node.id)) {
        this.logger.debug({ taskId, nodeId: node.id }, 'Circuit breaker open, skipping node')
        return
      }

      // Remove from queue
      await this.redis.zrem(this.queueKey, taskId)

      // Record rate limit usage
      if (this.schedulerRateLimiter) {
        const userId = (task as any).userId || 'system'
        await this.schedulerRateLimiter.recordTaskScheduled(userId, node.id)
      }

      // Assign task to node
      await this.assignTask(task, node)

    } catch (error) {
      this.logger.error({ error }, 'Error processing task queue')
    }
  }

  private async findNode(task: Task): Promise<{ id: string; url: string } | null> {
    const nodes = await this.prisma.edgeNode.findMany({
      where: {
        status: 'ONLINE',
        isMaintenanceMode: false,
        tasksRunning: { lt: 10 }, // Max tasks per node
      },
      orderBy: [
        { tasksRunning: 'asc' }, // Prefer least loaded
        { latency: 'asc' }, // Then lowest latency
      ],
    })

    if (nodes.length === 0) {return null}

    // Filter out nodes with open circuit breakers
    const circuitStates = await Promise.all(
      nodes.map(async (n: { id: string }) => ({ id: n.id, isOpen: await this.isCircuitOpen(n.id) }))
    )
    const openCircuits = new Set(circuitStates.filter((s) => s.isOpen).map((s) => s.id))
    const availableNodes = nodes.filter((n: { id: string }) => !openCircuits.has(n.id))
    if (availableNodes.length === 0) {
      this.logger.warn('All nodes have open circuit breakers')
      return null
    }

    // Apply scheduling policy
    switch (task.policy) {
      case 'latency-aware':
        return this.selectByLatency(availableNodes)
      case 'cost-aware':
        return await this.selectByCost(availableNodes, task)
      case 'round-robin':
        return await this.selectRoundRobin(availableNodes)
      case 'ml-optimized':
        return await this.selectByMLScore(availableNodes, task)
      case 'load-balanced':
      default:
        return availableNodes[0] ?? null
    }
  }

  private selectByLatency(nodes: { id: string; url: string; latency: number }[]): { id: string; url: string } | null {
    const sorted = [...nodes].sort((a, b) => a.latency - b.latency)
    return sorted[0] || null
  }

  /**
   * Cost-aware node selection using realistic multi-factor cost model
   * 
   * Factors considered:
   * - Compute cost (hourly rate × estimated duration)
   * - Data transfer costs (ingress/egress)
   * - Cross-region network premiums
   * - Spot instance discounts
   * - Node utilization (bin-packing optimization)
   */
  private async selectByCost(
    nodes: { id: string; url: string; costPerHour: number; region: string; availabilityZone?: string }[],
    _task?: Task
  ): Promise<{ id: string; url: string } | null> {
    // Lazy import to avoid circular dependencies
    const { CostOptimizer, createAWSCostProfile } = await import('./cost-optimizer.js')
    
    const optimizer = new CostOptimizer()
    const controlPlaneRegion = process.env.CONTROL_PLANE_REGION || 'us-east-1'
    
    // Build node cost profiles
    const nodeProfiles = nodes.map((node) => ({
      nodeId: node.id,
      region: node.region,
      availabilityZone: node.availabilityZone || `${node.region}a`,
      costFactors: createAWSCostProfile(node.region),
      currentUtilization: { cpuPercent: 50, memoryPercent: 50 }, // Would come from metrics
    }))

    // Estimate task resources (would be based on task type/history)
    const taskEstimate = {
      estimatedDurationMinutes: 5, // Default estimate
      cpuCores: 1,
      memoryGB: 2,
      storageGB: 10,
      inputDataGB: 0.1,
      outputDataGB: 0.1,
      requiresGPU: false,
    }

    // Find most cost-effective node
    const result = optimizer.selectMostCostEffective(
      taskEstimate,
      nodeProfiles,
      controlPlaneRegion
    )

    if (result) {
      const selectedNode = nodes.find((n) => n.id === result.node.nodeId)
      if (selectedNode) {
        this.logger.info(
          { 
            nodeId: selectedNode.id, 
            totalCost: result.estimate.totalCostUSD,
            breakdown: result.estimate.breakdown,
            confidence: result.estimate.confidence,
          },
          'Selected node using cost-aware optimizer'
        )
        return selectedNode
      }
    }

    // Fallback to simple sorting if cost optimization fails
    const sorted = [...nodes].sort((a, b) => a.costPerHour - b.costPerHour)
    return sorted[0] || null
  }

  private async selectRoundRobin(nodes: { id: string; url: string }[]): Promise<{ id: string; url: string } | null> {
    const lastIndex = parseInt(await this.redis.get('scheduler:round-robin:index') || '0', 10)
    const nextIndex = (lastIndex + 1) % nodes.length
    await this.redis.setex('scheduler:round-robin:index', REDIS_KEY_TTL, nextIndex.toString())
    return nodes[nextIndex] || null
  }

  /**
   * ML-optimized node selection using multi-objective scoring
   * 
   * Factors: latency, cpu, memory, cost, network, ML prediction, health
   * Respects graceful degradation settings
   */
  private async selectByMLScore(
    nodes: { id: string; url: string; latency?: number; cpuUsage?: number; memoryUsage?: number; costPerHour?: number; bandwidthInMbps?: number }[],
    task: Task
  ): Promise<{ id: string; url: string } | null> {
    if (nodes.length === 0) {return null}

    // Check graceful degradation for ML scoring
    if (this.gracefulDegradation && !this.gracefulDegradation.isFeatureEnabled('ml-scoring')) {
      this.logger.debug('ML scoring disabled by graceful degradation, using weighted fallback')
      // Use weighted scoring without ML
      const algorithm = this.gracefulDegradation.getSchedulingAlgorithm()
      if (algorithm === 'round-robin') {
        return await this.selectRoundRobin(nodes)
      }
      // Fall through to weighted calculation
    }

    // Convert nodes to scorer format
    const scoredNodes = nodes.map((node) => {
      const score = this.calculateNodeScore(node, task)
      return { ...node, score }
    })

    // Sort by score descending
    scoredNodes.sort((a, b) => b.score - a.score)

    const selectedNode = scoredNodes[0]
    
    if (!selectedNode) {
      return null
    }

    this.logger.info(
      {
        nodeId: selectedNode.id,
        score: selectedNode.score,
        taskId: task.id,
        algorithm: this.gracefulDegradation?.getSchedulingAlgorithm() || 'ml',
      },
      'Selected node using ML-optimized scorer'
    )

    return { id: selectedNode.id, url: selectedNode.url }
  }

  /**
   * Calculate node score based on weighted factors
   */
  private calculateNodeScore(
    node: { id: string; latency?: number; cpuUsage?: number; memoryUsage?: number; costPerHour?: number; bandwidthInMbps?: number },
    _task: Task
  ): number {
    const weights = this.schedulerWeights

    // Normalize each factor to 0-1 scale
    const latencyScore = node.latency ? 1 - Math.min(node.latency / 500, 1) : 0.5
    const cpuScore = node.cpuUsage !== undefined ? 1 - node.cpuUsage / 100 : 0.5
    const memoryScore = node.memoryUsage !== undefined ? 1 - node.memoryUsage / 100 : 0.5
    const costScore = node.costPerHour ? 1 - Math.min(node.costPerHour, 1) : 0.5
    const networkScore = node.bandwidthInMbps ? Math.min(node.bandwidthInMbps / 1000, 1) : 0.5

    // ML prediction score (would use predictor in production)
    const mlPredictionScore = 0.5 // Default prediction

    // Health score (would come from health monitor)
    const healthScore = 0.9 // Default health

    // Weighted sum
    return (
      weights.latency * latencyScore +
      weights.cpu * cpuScore +
      weights.memory * memoryScore +
      weights.cost * costScore +
      weights.network * networkScore +
      weights.ml * mlPredictionScore +
      weights.health * healthScore
    )
  }

  /**
   * Update scheduler weights (via API)
   */
  setSchedulerWeights(weights: Partial<ScoreWeights>): void {
    this.schedulerWeights = { ...this.schedulerWeights, ...weights }
    this.logger.info({ weights: this.schedulerWeights }, 'Updated scheduler weights')
  }

  /**
   * Get current scheduler weights
   */
  getSchedulerWeights(): ScoreWeights {
    return { ...this.schedulerWeights }
  }

  private async assignTask(task: Task, node: { id: string; url: string }) {
    this.logger.info({ taskId: task.id, nodeId: node.id }, 'Assigning task to node')

    // Update task status
    await this.prisma.task.update({
      where: { id: task.id },
      data: {
        nodeId: node.id,
        status: 'SCHEDULED',
        reason: `Scheduled on node ${node.id}`,
      },
    })

    // Send to edge agent with circuit breaker protection
    try {
      const controller = new AbortController()
      const timeoutId = setTimeout(() => controller.abort(), REQUEST_TIMEOUT)

      const requestId = `${task.id}-${Date.now()}`
      
      // Get or create circuit breaker for this node
      const breaker = this.circuitBreakerRegistry.getOrCreate(node.id, {
        failureThreshold: CIRCUIT_BREAKER_THRESHOLD,
        resetTimeout: CIRCUIT_BREAKER_RESET_TIME,
        name: node.id,
      })

      // Execute HTTP call with circuit breaker protection
      await breaker.execute(async () => {
        await axios.post(`${node.url}/run-task`, {
          taskId: task.id,
          taskName: task.name,
          type: task.type,
          input: task.input,
          timeout: TASK_TIMEOUT,
        }, {
          timeout: REQUEST_TIMEOUT,
          signal: controller.signal,
          headers: {
            'X-Request-ID': requestId,
            'X-Trace-ID': requestId,
            'X-Source': 'task-scheduler',
          },
        })
      })

      clearTimeout(timeoutId)

      // Clear distributed state on success
      await this.redis.del(`circuit:${node.id}:state`)

      // Mark as running
      await this.prisma.task.update({
        where: { id: task.id },
        data: {
          status: 'RUNNING',
        },
      })

      // Update node task count
      await this.prisma.edgeNode.update({
        where: { id: node.id },
        data: { tasksRunning: { increment: 1 } },
      })

      this.wsManager.broadcast('task:started', {
        taskId: task.id,
        nodeId: node.id,
        timestamp: new Date().toISOString(),
      })

    } catch (error) {
      // Circuit breaker automatically records failure
      // Sync to Redis if circuit is now open
      const breaker = this.circuitBreakerRegistry.get(node.id)
      if (breaker?.getState() === 'OPEN') {
        await this.redis.setex(`circuit:${node.id}:state`, 60, 'OPEN')
      }

      const errorMessage = error instanceof AxiosError 
        ? `HTTP ${error.response?.status || 'unknown'}: ${error.message}`
        : error instanceof Error 
          ? error.message 
          : 'Unknown error'

      this.logger.error({ taskId: task.id, nodeId: node.id, error: errorMessage }, 'Failed to assign task to node')

      // Mark as failed and potentially retry
      await this.prisma.task.update({
        where: { id: task.id },
        data: {
          status: 'FAILED',
        },
      })

      // Re-enqueue if retries available
      const executionCount = await this.prisma.taskExecution.count({ where: { taskId: task.id } })
      if (executionCount < task.maxRetries) {
        const retryTask = await this.prisma.task.create({
          data: {
            name: task.name,
            type: task.type,
            priority: task.priority,
            target: task.target,
            policy: task.policy,
            reason: `Retry after: ${errorMessage}`,
            input: task.input,
            metadata: { ...task.metadata as object, retryOf: task.id },
            maxRetries: task.maxRetries,
          } as any,
        })
        
        // Enqueue retry task
        await this.enqueue(retryTask as any)
      }
    }
  }

  async handleTaskCompletion(taskId: string, nodeId: string, result: {
    status: 'completed' | 'failed'
    output?: unknown
    error?: string
    duration: number
  }) {
    const task = await this.prisma.task.findUnique({ where: { id: taskId } })

    if (!task) {
      this.logger.warn({ taskId }, 'Task not found for completion')
      return
    }

    // Record success for circuit breaker
    await this.recordSuccess(nodeId)

    await this.prisma.task.update({
      where: { id: taskId },
      data: {
        status: result.status === 'completed' ? 'COMPLETED' : 'FAILED',
      },
    })

    // Update node task count (with check to prevent negative)
    const node = await this.prisma.edgeNode.findUnique({
      where: { id: nodeId },
      select: { tasksRunning: true }
    })
    
    if (node && node.tasksRunning > 0) {
      await this.prisma.edgeNode.update({
        where: { id: nodeId },
        data: { tasksRunning: { decrement: 1 } },
      })
    }

    this.wsManager.broadcast(`task:${result.status}`, {
      taskId,
      nodeId,
      duration: result.duration,
      timestamp: new Date().toISOString(),
    })
  }

  getQueueLength(): Promise<number> {
    return this.redis.zcard(this.queueKey)
  }

  async getQueuePosition(taskId: string): Promise<number> {
    const rank = await this.redis.zrevrank(this.queueKey, taskId)
    return rank !== null ? rank + 1 : -1
  }
}

