/**
 * Unified DLQ Service
 * 
 * Kafka DLQ is PRIMARY for:
 * - Persistent failed messages
 * - Long-term storage
 * - Replay capability
 * - Audit trail
 * 
 * Redis is SECONDARY for:
 * - Retry scheduling (delayed execution)
 * - Temporary caching
 * - Rate-limited retry coordination
 */

import type { PrismaClient } from '@prisma/client';
import Redis from 'ioredis';
import { Kafka, Producer } from 'kafkajs';
import type { Logger } from 'pino';

// ============================================================================
// Types
// ============================================================================

export interface DLQMessage {
  id: string;
  originalTopic: string;
  originalPartition: number;
  originalOffset: string;
  key: string | null;
  value: Record<string, unknown>;
  headers: Record<string, string>;
  errorMessage: string;
  errorStack?: string;
  retryCount: number;
  maxRetries: number;
  createdAt: Date;
  nextRetryAt?: Date;
  status: 'pending' | 'processing' | 'resolved' | 'exhausted';
}

export interface RetrySchedule {
  messageId: string;
  scheduledAt: Date;
  delayMs: number;
  priority: 'low' | 'normal' | 'high';
}

export interface DLQStats {
  pending: number;
  processing: number;
  resolved: number;
  exhausted: number;
  totalRetries: number;
}

// ============================================================================
// Constants
// ============================================================================

const DLQ_TOPIC_PREFIX = 'dlq-';
const REDIS_RETRY_QUEUE = 'dlq:retry:queue';
const REDIS_RETRY_SCHEDULE = 'dlq:retry:schedule';

const DEFAULT_RETRY_DELAYS = [1000, 5000, 30000, 60000, 300000, 900000]; // Exponential backoff

// ============================================================================
// UnifiedDLQService
// ============================================================================

export class UnifiedDLQService {
  private kafka: Kafka;
  private kafkaProducer: Producer;
  private redis: Redis;
  private prisma: PrismaClient;
  private logger: Logger;

  constructor(
    kafka: Kafka,
    redis: Redis,
    prisma: PrismaClient,
    logger: Logger
  ) {
    this.kafka = kafka;
    this.redis = redis;
    this.prisma = prisma;
    this.logger = logger;

    this.kafkaProducer = this.kafka.producer();
  }

  async initialize(): Promise<void> {
    await this.kafkaProducer.connect();
    this.logger.info('Unified DLQ Service initialized');
  }

  /**
   * Send failed message to DLQ (Kafka - PRIMARY)
   * This provides durability and replay capability
   */
  async sendToDLQ(
    originalTopic: string,
    partition: number,
    offset: string,
    message: { key: string | null; value: Record<string, unknown>; headers: Record<string, string> },
    error: Error,
    retryCount: number = 0
  ): Promise<string> {
    const dlqTopic = `${DLQ_TOPIC_PREFIX}${originalTopic}`;
    const messageId = `dlq-${Date.now()}-${Math.random().toString(36).substring(2, 9)}`;

    const dlqMessage: DLQMessage = {
      id: messageId,
      originalTopic,
      originalPartition: partition,
      originalOffset: offset,
      key: message.key,
      value: message.value,
      headers: message.headers,
      errorMessage: error.message,
      errorStack: error.stack,
      retryCount,
      maxRetries: 5,
      createdAt: new Date(),
      status: 'pending',
    };

    // 1. Send to Kafka DLQ (persistent storage)
    await this.kafkaProducer.send({
      topic: dlqTopic,
      messages: [
        {
          key: messageId,
          value: JSON.stringify(dlqMessage),
          headers: {
            'original-topic': originalTopic,
            'error-message': error.message.substring(0, 255),
            'retry-count': retryCount.toString(),
            'created-at': new Date().toISOString(),
          },
        },
      ],
    });

    // 2. Store in database for queryability
    await this.prisma.dLQMessage.create({
      data: {
        id: messageId,
        originalTopic,
        originalPartition: partition,
        originalOffset: offset,
        messageKey: message.key,
        messageValue: message.value as any,
        headers: message.headers as any,
        errorMessage: error.message,
        errorStack: error.stack,
        retryCount,
        maxRetries: 5,
        status: 'pending',
      },
    });

    this.logger.info({
      messageId,
      originalTopic,
      retryCount,
    }, 'Message sent to DLQ');

    return messageId;
  }

  /**
   * Schedule a retry (Redis - SECONDARY)
   * Used for delayed retry execution
   */
  async scheduleRetry(
    messageId: string,
    delayMs?: number
  ): Promise<void> {
    // Get message from DB
    const message = await this.prisma.dLQMessage.findUnique({
      where: { id: messageId },
    });

    if (!message || message.status !== 'pending') {
      throw new Error(`Message ${messageId} not found or not pending`);
    }

    // Calculate delay with exponential backoff
    const defaultDelay = DEFAULT_RETRY_DELAYS[Math.min(message.retryCount, DEFAULT_RETRY_DELAYS.length - 1)] ?? 1000;
    const delay = delayMs ?? defaultDelay;
    const scheduledAt = new Date(Date.now() + delay);

    // Store in Redis sorted set for scheduling
    await this.redis.zadd(
      REDIS_RETRY_SCHEDULE,
      scheduledAt.getTime(),
      messageId
    );

    // Update message with next retry time
    await this.prisma.dLQMessage.update({
      where: { id: messageId },
      data: { nextRetryAt: scheduledAt },
    });

    this.logger.debug({
      messageId,
      scheduledAt,
      delay,
    }, 'Retry scheduled');
  }

  /**
   * Get messages ready for retry
   */
  async getRetryCandidates(limit: number = 100): Promise<DLQMessage[]> {
    const now = Date.now();

    // Get from Redis sorted set (scheduled retries)
    const messageIds = await this.redis.zrangebyscore(
      REDIS_RETRY_SCHEDULE,
      0,
      now,
      'LIMIT',
      0,
      limit
    );

    if (messageIds.length === 0) {
      return [];
    }

    // Get full messages from DB
    const messages = await this.prisma.dLQMessage.findMany({
      where: {
        id: { in: messageIds },
        status: 'pending',
      },
    });

    // Remove from schedule queue
    await this.redis.zrem(REDIS_RETRY_SCHEDULE, ...messageIds);

    return messages.map((m) => ({
      id: m.id,
      originalTopic: m.originalTopic,
      originalPartition: m.originalPartition,
      originalOffset: m.originalOffset,
      key: m.messageKey,
      value: m.messageValue as Record<string, unknown>,
      headers: m.headers as Record<string, string>,
      errorMessage: m.errorMessage,
      errorStack: m.errorStack || undefined,
      retryCount: m.retryCount,
      maxRetries: m.maxRetries,
      createdAt: m.createdAt,
      nextRetryAt: m.nextRetryAt || undefined,
      status: m.status as 'pending' | 'processing' | 'resolved' | 'exhausted',
    }));
  }

  /**
   * Mark message as processing
   */
  async markProcessing(messageId: string): Promise<void> {
    await this.prisma.dLQMessage.update({
      where: { id: messageId },
      data: { status: 'processing' },
    });
  }

  /**
   * Mark message as resolved
   */
  async markResolved(messageId: string): Promise<void> {
    await this.prisma.dLQMessage.update({
      where: { id: messageId },
      data: {
        status: 'resolved',
        resolvedAt: new Date(),
      },
    });

    // Remove from any Redis queues
    await this.redis.zrem(REDIS_RETRY_SCHEDULE, messageId);
    await this.redis.lrem(REDIS_RETRY_QUEUE, 0, messageId);

    this.logger.info({ messageId }, 'DLQ message resolved');
  }

  /**
   * Mark message as exhausted (max retries reached)
   */
  async markExhausted(messageId: string): Promise<void> {
    await this.prisma.dLQMessage.update({
      where: { id: messageId },
      data: { status: 'exhausted' },
    });

    // Remove from Redis queues
    await this.redis.zrem(REDIS_RETRY_SCHEDULE, messageId);
    await this.redis.lrem(REDIS_RETRY_QUEUE, 0, messageId);

    this.logger.warn({ messageId }, 'DLQ message exhausted');
  }

  /**
   * Get DLQ statistics
   */
  async getStats(): Promise<DLQStats> {
    const stats = await this.prisma.dLQMessage.groupBy({
      by: ['status'],
      _count: true,
    });

    const result: DLQStats = {
      pending: 0,
      processing: 0,
      resolved: 0,
      exhausted: 0,
      totalRetries: 0,
    };

    for (const stat of stats) {
      result[stat.status as keyof DLQStats] = stat._count;
    }

    // Get total retry count
    const agg = await this.prisma.dLQMessage.aggregate({
      _sum: { retryCount: true },
    });
    result.totalRetries = agg._sum.retryCount || 0;

    return result;
  }

  /**
   * Get messages from DLQ (for admin review)
   */
  async getMessages(
    status?: 'pending' | 'processing' | 'resolved' | 'exhausted',
    limit: number = 100,
    offset: number = 0
  ): Promise<DLQMessage[]> {
    const messages = await this.prisma.dLQMessage.findMany({
      where: status ? { status } : undefined,
      orderBy: { createdAt: 'desc' },
      take: limit,
      skip: offset,
    });

    return messages.map((m) => ({
      id: m.id,
      originalTopic: m.originalTopic,
      originalPartition: m.originalPartition,
      originalOffset: m.originalOffset,
      key: m.messageKey,
      value: m.messageValue as Record<string, unknown>,
      headers: m.headers as Record<string, string>,
      errorMessage: m.errorMessage,
      errorStack: m.errorStack || undefined,
      retryCount: m.retryCount,
      maxRetries: m.maxRetries,
      createdAt: m.createdAt,
      nextRetryAt: m.nextRetryAt || undefined,
      status: m.status as 'pending' | 'processing' | 'resolved' | 'exhausted',
    }));
  }

  /**
   * Replay a message back to original topic
   */
  async replayMessage(messageId: string): Promise<void> {
    const message = await this.prisma.dLQMessage.findUnique({
      where: { id: messageId },
    });

    if (!message) {
      throw new Error(`Message ${messageId} not found`);
    }

    // Increment retry count
    const newRetryCount = message.retryCount + 1;

    // Check if max retries exceeded
    if (newRetryCount > message.maxRetries) {
      await this.markExhausted(messageId);
      throw new Error('Max retries exceeded');
    }

    // Send back to original topic
    await this.kafkaProducer.send({
      topic: message.originalTopic,
      messages: [
        {
          key: message.messageKey,
          value: JSON.stringify(message.messageValue),
          headers: {
            ...message.headers as Record<string, string>,
            'x-dlq-retry-count': newRetryCount.toString(),
            'x-dlq-message-id': messageId,
          },
        },
      ],
    });

    // Update retry count
    await this.prisma.dLQMessage.update({
      where: { id: messageId },
      data: {
        retryCount: newRetryCount,
        status: 'pending',
      },
    });

    this.logger.info({
      messageId,
      originalTopic: message.originalTopic,
      retryCount: newRetryCount,
    }, 'Message replayed');
  }
}

import { IncomingMessage } from 'http'

import Redis from 'ioredis'
import jwt from 'jsonwebtoken'

import { v4 as uuidv4 } from 'uuid'
import { WebSocket } from 'ws'
import type { Logger } from 'pino'

// JWT_SECRET must be set - validated in index.ts
const JWT_SECRET = process.env.JWT_SECRET!

// WebSocket authentication timeout
const AUTH_TIMEOUT = 10000 // 10 seconds to authenticate

const HEARTBEAT_INTERVAL = 30000 // 30 seconds
const HEARTBEAT_TIMEOUT = 60000 // 60 seconds - close if no response
const REDIS_PUBSUB_CHANNEL = 'ws:broadcast'

interface Client {
  id: string
  ws: WebSocket
  subscriptions: Set<string>
  isAuthenticated: boolean
  userId?: string
  connectedAt: Date
  lastPing: Date
  isAlive: boolean
}

interface Message {
  type: string
  payload: unknown
  timestamp: string
}

interface ClusterMessage {
  instanceId: string
  channel: string
  payload: unknown
  excludeSender?: string
}

export class WebSocketManager {
  private clients: Map<string, Client> = new Map()
  private logger: Logger
  private heartbeatInterval: ReturnType<typeof setInterval> | null = null
  private redis?: Redis
  private redisSubscriber?: Redis
  private instanceId: string

  constructor(logger: Logger, redis?: Redis) {
    this.logger = logger
    this.redis = redis
    this.instanceId = `ws-${Date.now()}-${Math.random().toString(36).substring(2, 7)}`
    
    if (redis) {
      this.setupRedisClustering()
    }
    
    this.startHeartbeatCheck()
  }

  /**
   * Setup Redis Pub/Sub for cross-instance messaging
   */
  private async setupRedisClustering(): Promise<void> {
    if (!this.redis) {return}

    // Create a dedicated subscriber connection
    this.redisSubscriber = this.redis.duplicate()
    
    await this.redisSubscriber.subscribe(REDIS_PUBSUB_CHANNEL)
    
    this.redisSubscriber.on('message', (channel: string, message: string) => {
      if (channel !== REDIS_PUBSUB_CHANNEL) {return}
      
      try {
        const clusterMsg: ClusterMessage = JSON.parse(message)
        
        // Don't process messages from this instance
        if (clusterMsg.instanceId === this.instanceId) {return}
        
        // Don't broadcast to excluded client
        if (clusterMsg.excludeSender) {
          this.broadcastLocally(clusterMsg.channel, clusterMsg.payload, clusterMsg.excludeSender)
        } else {
          this.broadcastLocally(clusterMsg.channel, clusterMsg.payload)
        }
      } catch (error) {
        this.logger.error({ error }, 'Failed to parse cluster message')
      }
    })

    this.logger.info({ instanceId: this.instanceId }, 'WebSocket clustering enabled')
  }

  private startHeartbeatCheck() {
    this.heartbeatInterval = setInterval(() => {
      const now = Date.now()
      const staleClients: string[] = []

      for (const [clientId, client] of this.clients.entries()) {
        // Check if client is still alive
        if (!client.isAlive) {
          staleClients.push(clientId)
          continue
        }

        // Check for timeout
        const timeSinceLastPing = now - client.lastPing.getTime()
        if (timeSinceLastPing > HEARTBEAT_TIMEOUT) {
          this.logger.warn({ clientId, timeSinceLastPing }, 'Client heartbeat timeout')
          staleClients.push(clientId)
          continue
        }

        // Send ping and mark as not alive (expecting pong)
        client.isAlive = false
        try {
          if (client.ws.readyState === WebSocket.OPEN) {
            client.ws.ping()
          }
        } catch (error) {
          // Socket may be closing
          staleClients.push(clientId)
        }
      }

      // Terminate stale connections
      for (const clientId of staleClients) {
        const client = this.clients.get(clientId)
        if (client) {
          this.logger.info({ clientId }, 'Terminating stale WebSocket connection')
          try {
            client.ws.close(1001, 'Heartbeat timeout')
          } catch (error) {
            // Socket may already be closed
          }
          this.clients.delete(clientId)
        }
      }

      if (staleClients.length > 0) {
        this.logger.info({ count: staleClients.length, remaining: this.clients.size }, 'Cleaned up stale connections')
      }
    }, HEARTBEAT_INTERVAL)
  }

  handleConnection(ws: WebSocket, _req: IncomingMessage) {
    const clientId = uuidv4()
    const client: Client = {
      id: clientId,
      ws,
      subscriptions: new Set(),
      isAuthenticated: false,
      connectedAt: new Date(),
      lastPing: new Date(),
      isAlive: true,
    }

    this.clients.set(clientId, client)
    this.logger.info({ clientId, totalClients: this.clients.size }, 'WebSocket client connected')

    // Send welcome message with auth requirement
    this.sendToClient(client, 'connected', { 
      clientId, 
      message: 'Please authenticate within 10 seconds using { type: "authenticate", payload: { token: "your-jwt" } }'
    })

    // Set authentication timeout
    const authTimeout = setTimeout(() => {
      if (!client.isAuthenticated) {
        this.logger.warn({ clientId }, 'WebSocket client failed to authenticate in time')
        try {
          // Send error message before closing
          if (ws.readyState === WebSocket.OPEN) {
            ws.send(JSON.stringify({ type: 'error', payload: { message: 'Authentication timeout' }, timestamp: new Date().toISOString() }))
            // Use code 1008 (policy violation) for auth failure
            ws.close(1008)
          }
        } catch (error) {
          // Socket may already be closed
        }
        this.clients.delete(clientId)
      }
    }, AUTH_TIMEOUT)

    // Handle pong responses
    ws.on('pong', () => {
      client.isAlive = true
      client.lastPing = new Date()
    })

    ws.on('message', (data: Buffer) => {
      // Mark as alive on any message
      client.isAlive = true
      client.lastPing = new Date()

      try {
        const message = JSON.parse(data.toString())
        this.handleMessage(client, message, authTimeout)
      } catch (error) {
        this.logger.warn({ clientId, error }, 'Failed to parse WebSocket message')
        this.sendToClient(client, 'error', { message: 'Invalid message format' })
      }
    })

    ws.on('close', () => {
      clearTimeout(authTimeout)
      this.clients.delete(clientId)
      this.logger.info({ clientId, totalClients: this.clients.size }, 'WebSocket client disconnected')
    })

    ws.on('error', (error) => {
      this.logger.error({ clientId, error }, 'WebSocket error')
      this.clients.delete(clientId)
    })
  }

  private handleMessage(client: Client, message: { type: string; payload?: unknown }, authTimeout: ReturnType<typeof setTimeout>) {
    // Require authentication for all messages except 'authenticate'
    if (message.type !== 'authenticate' && !client.isAuthenticated) {
      this.sendToClient(client, 'error', { message: 'Authentication required' })
      return
    }

    switch (message.type) {
      case 'subscribe':
        this.handleSubscribe(client, message.payload as { channels: string[] })
        break
      case 'unsubscribe':
        this.handleUnsubscribe(client, message.payload as { channels: string[] })
        break
      case 'authenticate':
        this.handleAuthenticate(client, message.payload as { token: string }, authTimeout)
        break
      case 'ping':
        this.sendToClient(client, 'pong', { timestamp: new Date().toISOString() })
        break
      default:
        this.logger.warn({ clientId: client.id, type: message.type }, 'Unknown WebSocket message type')
    }
  }

  private handleSubscribe(client: Client, payload: { channels: string[] }) {
    if (!payload?.channels || !Array.isArray(payload.channels)) {
      return this.sendToClient(client, 'error', { message: 'Invalid subscribe payload' })
    }

    for (const channel of payload.channels) {
      client.subscriptions.add(channel)
    }

    this.sendToClient(client, 'subscribed', { channels: payload.channels })
    this.logger.debug({ clientId: client.id, channels: payload.channels }, 'Client subscribed to channels')
  }

  private handleUnsubscribe(client: Client, payload: { channels: string[] }) {
    if (!payload?.channels || !Array.isArray(payload.channels)) {
      return this.sendToClient(client, 'error', { message: 'Invalid unsubscribe payload' })
    }

    for (const channel of payload.channels) {
      client.subscriptions.delete(channel)
    }

    this.sendToClient(client, 'unsubscribed', { channels: payload.channels })
  }

  private async handleAuthenticate(client: Client, payload: { token: string }, authTimeout: ReturnType<typeof setTimeout>) {
    try {
      if (!payload.token) {
        this.sendToClient(client, 'error', { message: 'Token required' })
        client.ws.close(4001, 'Authentication required')
        return
      }

      const decoded = jwt.verify(payload.token, JWT_SECRET) as { userId: string; role?: string }
      client.isAuthenticated = true
      client.userId = decoded.userId
      
      // Clear auth timeout on successful authentication
      clearTimeout(authTimeout)
      
      this.sendToClient(client, 'authenticated', { 
        success: true, 
        userId: decoded.userId,
        role: decoded.role 
      })
      
      this.logger.info({ clientId: client.id, userId: decoded.userId }, 'WebSocket client authenticated')
    } catch (error) {
      this.logger.warn({ clientId: client.id, error: (error as Error).message }, 'WebSocket authentication failed')
      this.sendToClient(client, 'error', { message: 'Authentication failed' })
      client.ws.close(4001, 'Invalid token')
    }
  }

  private sendToClient(client: Client, type: string, payload: unknown) {
    if (client.ws.readyState === WebSocket.OPEN) {
      const message: Message = {
        type,
        payload,
        timestamp: new Date().toISOString(),
      }
      client.ws.send(JSON.stringify(message))
    }
  }

  /**
   * Broadcast to local clients only
   */
  broadcastLocally(channel: string, payload: unknown, excludeClientId?: string) {
    const message: Message = {
      type: channel,
      payload,
      timestamp: new Date().toISOString(),
    }

    const messageStr = JSON.stringify(message)
    let sent = 0

    for (const client of this.clients.values()) {
      if (excludeClientId && client.id === excludeClientId) {continue}
      
      if (client.subscriptions.has(channel) || client.subscriptions.has('*')) {
        if (client.ws.readyState === WebSocket.OPEN) {
          client.ws.send(messageStr)
          sent++
        }
      }
    }

    this.logger.debug({ channel, clients: sent }, 'Local broadcast')
  }

  /**
   * Broadcast to all instances via Redis Pub/Sub
   */
  broadcast(channel: string, payload: unknown, excludeClientId?: string) {
    // First, broadcast locally
    this.broadcastLocally(channel, payload, excludeClientId)

    // Then, broadcast to other instances via Redis
    if (this.redis) {
      const clusterMsg: ClusterMessage = {
        instanceId: this.instanceId,
        channel,
        payload,
        excludeSender: excludeClientId,
      }
      
      this.redis.publish(REDIS_PUBSUB_CHANNEL, JSON.stringify(clusterMsg)).catch((error) => {
        this.logger.error({ error }, 'Failed to publish cluster message')
      })
    }
  }

  broadcastToUser(userId: string, type: string, payload: unknown) {
    for (const client of this.clients.values()) {
      if (client.userId === userId && client.ws.readyState === WebSocket.OPEN) {
        this.sendToClient(client, type, payload)
      }
    }
  }

  getStats() {
    return {
      totalClients: this.clients.size,
      authenticatedClients: Array.from(this.clients.values()).filter((c) => c.isAuthenticated).length,
      subscriptions: Array.from(this.clients.values()).reduce((acc, c) => {
        for (const sub of c.subscriptions) {
          acc[sub] = (acc[sub] || 0) + 1
        }
        return acc
      }, {} as Record<string, number>),
    }
  }

  close() {
    // Stop heartbeat check
    if (this.heartbeatInterval) {
      clearInterval(this.heartbeatInterval)
      this.heartbeatInterval = null
    }
    
    // Close all connections
    for (const client of this.clients.values()) {
      client.ws.close()
    }
    this.clients.clear()
    this.logger.info('WebSocket manager closed')
  }
}

/**
 * Circuit breaker configurations for external dependencies
 * Applied to: DB calls, Redis calls, External APIs
 */

import { CircuitBreaker, CircuitBreakerConfig } from '@edgecloud/circuit-breaker';

import { createLogger } from '../lib/logger';

const logger = createLogger('circuit-breaker');

// Circuit breaker configurations for different service types
export const circuitBreakerConfigs = {
  // Database circuit breaker - conservative due to criticality
  database: {
    name: 'database',
    failureThreshold: 5,
    resetTimeout: 30000, // 30 seconds
    halfOpenMaxCalls: 3,
    successThreshold: 2,
  } as CircuitBreakerConfig,

  // Redis circuit breaker - more aggressive recovery
  redis: {
    name: 'redis',
    failureThreshold: 3,
    resetTimeout: 10000, // 10 seconds
    halfOpenMaxCalls: 2,
    successThreshold: 1,
  } as CircuitBreakerConfig,

  // External API circuit breaker - conservative
  externalApi: {
    name: 'external-api',
    failureThreshold: 5,
    resetTimeout: 60000, // 60 seconds
    halfOpenMaxCalls: 3,
    successThreshold: 2,
  } as CircuitBreakerConfig,

  // Node agent circuit breaker
  nodeAgent: {
    name: 'node-agent',
    failureThreshold: 3,
    resetTimeout: 30000, // 30 seconds
    halfOpenMaxCalls: 2,
    successThreshold: 1,
  } as CircuitBreakerConfig,
};

// Singleton circuit breaker instances
const circuitBreakers = new Map<string, CircuitBreaker>();

/**
 * Get or create a circuit breaker for a service
 */
export function getCircuitBreaker(config: CircuitBreakerConfig): CircuitBreaker {
  if (!circuitBreakers.has(config.name)) {
    const cb = new CircuitBreaker(config);
    
    // Add logging for state changes
    cb.on('open', () => {
      logger.warn({ breaker: config.name }, 'Circuit breaker opened');
    });
    
    cb.on('close', () => {
      logger.info({ breaker: config.name }, 'Circuit breaker closed (healthy)');
    });
    
    cb.on('halfOpen', () => {
      logger.info({ breaker: config.name }, 'Circuit breaker half-open (testing)');
    });
    
    circuitBreakers.set(config.name, cb);
  }
  
  return circuitBreakers.get(config.name)!;
}

/**
 * Execute function with circuit breaker protection
 */
export async function withCircuitBreaker<T>(
  config: CircuitBreakerConfig,
  fn: () => Promise<T>,
  fallback?: () => T
): Promise<T> {
  const cb = getCircuitBreaker(config);
  return cb.execute(fn, fallback);
}

/**
 * Get metrics for all circuit breakers
 */
export function getAllCircuitBreakerMetrics() {
  const metrics: Record<string, ReturnType<CircuitBreaker['getMetrics']>> = {};
  
  for (const [name, cb] of circuitBreakers.entries()) {
    metrics[name] = cb.getMetrics();
  }
  
  return metrics;
}

/**
 * Force close all circuit breakers (useful for testing or manual recovery)
 */
export function forceCloseAllCircuitBreakers(): void {
  for (const cb of circuitBreakers.values()) {
    cb.forceClose();
  }
}

/**
 * Simple encryption utility for sensitive database fields
 * Uses AES-256-GCM for authenticated encryption
 * 
 * NOTE: For production, consider using a KMS (AWS KMS, Azure Key Vault, HashiCorp Vault)
 * This implementation provides a practical middle-ground for immediate security improvement
 */

import { createCipheriv, createDecipheriv, randomBytes, scryptSync } from 'crypto';

const ALGORITHM = 'aes-256-gcm';
const IV_LENGTH = 16;
const AUTH_TAG_LENGTH = 16;
const SALT_LENGTH = 32;

/**
 * Derive encryption key from environment variable
 * Uses scrypt for key derivation
 */
function getEncryptionKey(): Buffer {
  const encryptionKey = process.env.ENCRYPTION_KEY;
  
  if (!encryptionKey) {
    throw new Error('ENCRYPTION_KEY environment variable is required for field encryption');
  }
  
  if (encryptionKey.length < 32) {
    throw new Error('ENCRYPTION_KEY must be at least 32 characters');
  }
  
  // Use scrypt to derive a proper 256-bit key
  return scryptSync(encryptionKey, 'edgecloud-salt', 32);
}

/**
 * Encrypt sensitive data
 * @param plaintext - Data to encrypt
 * @returns Encrypted string in format: salt:iv:authTag:ciphertext (base64)
 */
export function encrypt(plaintext: string): string {
  if (!plaintext) {return plaintext;}
  
  try {
    const key = getEncryptionKey();
    const salt = randomBytes(SALT_LENGTH);
    const iv = randomBytes(IV_LENGTH);
    
    const cipher = createCipheriv(ALGORITHM, key, iv);
    
    let encrypted = cipher.update(plaintext, 'utf8', 'base64');
    encrypted += cipher.final('base64');
    
    const authTag = cipher.getAuthTag();
    
    // Combine salt + iv + authTag + ciphertext
    const result = Buffer.concat([
      salt,
      iv,
      authTag,
      Buffer.from(encrypted, 'base64')
    ]).toString('base64');
    
    return result;
  } catch (error) {
    throw new Error(`Encryption failed: ${(error as Error).message}`);
  }
}

/**
 * Decrypt sensitive data
 * @param ciphertext - Encrypted string in format: salt:iv:authTag:ciphertext (base64)
 * @returns Decrypted plaintext
 */
export function decrypt(ciphertext: string): string {
  if (!ciphertext) {return ciphertext;}
  
  try {
    const key = getEncryptionKey();
    const buffer = Buffer.from(ciphertext, 'base64');
    
    // Extract components
    const _salt = buffer.subarray(0, SALT_LENGTH);
    const iv = buffer.subarray(SALT_LENGTH, SALT_LENGTH + IV_LENGTH);
    const authTag = buffer.subarray(SALT_LENGTH + IV_LENGTH, SALT_LENGTH + IV_LENGTH + AUTH_TAG_LENGTH);
    const encrypted = buffer.subarray(SALT_LENGTH + IV_LENGTH + AUTH_TAG_LENGTH);
    
    const decipher = createDecipheriv(ALGORITHM, key, iv);
    decipher.setAuthTag(authTag);
    
    let decrypted = decipher.update(encrypted.toString('base64'), 'base64', 'utf8');
    decrypted += decipher.final('utf8');
    
    return decrypted;
  } catch (error) {
    throw new Error(`Decryption failed: ${(error as Error).message}`);
  }
}

/**
 * Check if a string appears to be encrypted (basic heuristic)
 * @param value - String to check
 * @returns true if likely encrypted
 */
export function isEncrypted(value: string): boolean {
  if (!value || typeof value !== 'string') {return false;}
  
  try {
    const buffer = Buffer.from(value, 'base64');
    // Check if length matches expected encrypted format
    return buffer.length >= SALT_LENGTH + IV_LENGTH + AUTH_TAG_LENGTH + 1;
  } catch {
    return false;
  }
}

/**
 * Hash sensitive data for comparison (one-way)
 * Use for fields that don't need decryption (e.g., API key hashes)
 * @param data - Data to hash
 * @returns SHA-256 hash
 */
export function hashSensitive(data: string): string {
  const { createHash } = require('crypto');
  return createHash('sha256').update(data).digest('hex');
}

// ============================================================================
// Global Error Handler
// ============================================================================
// 
// Catches all unhandled errors in the application
// Prevents silent failures and enables graceful degradation
// ============================================================================

import { createLogger } from '../lib/logger';

const logger = createLogger('global-error-handler');

let hasUnhandledErrors = false;
let unhandledErrorCount = 0;

/**
 * Register global error handlers
 * Should be called once at application startup
 */
export function registerGlobalErrorHandlers(): void {
  // Unhandled promise rejections
  process.on('unhandledRejection', (reason, promise) => {
    unhandledErrorCount++;
    hasUnhandledErrors = true;
    
    logger.error({
      reason,
      promise: promise.toString(),
      count: unhandledErrorCount,
    }, 'UNHANDLED REJECTION');
    
    // Don't exit - allow application to continue
    // But log severity for monitoring
  });

  // Uncaught exceptions
  process.on('uncaughtException', (error) => {
    logger.fatal({ error }, 'UNCAUGHT EXCEPTION');
    
    // Log but don't exit immediately
    // Allow cleanup and graceful shutdown
    setTimeout(() => {
      logger.warn('Process continuing after uncaught exception');
    }, 1000);
  });

  // Warning before exit (for cleanup)
  process.on('exit', (code) => {
    if (hasUnhandledErrors) {
      logger.warn({ code, unhandledErrorCount }, 'Process exiting with unhandled errors');
    } else {
      logger.info({ code }, 'Process exiting normally');
    }
  });

  logger.info('✅ Global error handlers registered');
}

/**
 * Get unhandled error statistics
 */
export function getUnhandledErrorStats(): { hasErrors: boolean; count: number } {
  return {
    hasErrors: hasUnhandledErrors,
    count: unhandledErrorCount,
  };
}

/**
 * Reset error state (for testing only)
 */
export function resetErrorState(): void {
  hasUnhandledErrors = false;
  unhandledErrorCount = 0;
}

