// ============================================================================
// Reliable Service Call Layer
// ============================================================================
// 
// Combines retry, circuit breaker, timeout, and safe execution
// for all external service calls.
// 
// Usage:
//   const result = await reliableCall(() => axios.get(url));
// ============================================================================

import { RetryPolicy } from '@edgecloud/circuit-breaker';
import axios, { AxiosError, AxiosResponse } from 'axios';
import type { CircuitBreaker } from '@edgecloud/circuit-breaker';

export interface ReliableCallConfig {
  retries?: number;
  timeoutMs?: number;
  circuitBreaker?: CircuitBreaker | undefined;
  retryableStatusCodes?: number[];
  operationName?: string;
}

const DEFAULT_CONFIG: Omit<ReliableCallConfig, 'circuitBreaker'> & { circuitBreaker: undefined } = {
  retries: 3,
  timeoutMs: 5000,
  circuitBreaker: undefined,
  retryableStatusCodes: [408, 429, 500, 502, 503, 504],
  operationName: 'unknown',
};

export class ReliableCallError extends Error {
  constructor(
    message: string,
    public cause?: Error,
    public statusCode?: number,
    public attemptCount?: number
  ) {
    super(message);
    this.name = 'ReliableCallError';
  }
}

export class TimeoutError extends Error {
  constructor(operation: string, timeoutMs: number) {
    super(`${operation} timed out after ${timeoutMs}ms`);
    this.name = 'TimeoutError';
  }
}

/**
 * Execute a function with reliability patterns:
 * - Retry with exponential backoff
 * - Circuit breaker integration
 * - Timeout protection
 * - Error classification
 * 
 * @param fn - Function to execute (should return Promise)
 * @param config - Reliability configuration
 * @returns Result of the function call
 * 
 * @example
 * ```typescript
 * // Basic usage
 * const response = await reliableCall(() => axios.get('/api/tasks'));
 * 
 * // With custom config
 * const response = await reliableCall(
 *   () => axios.post('/api/external', data),
 *   { retries: 5, timeoutMs: 10000, operationName: 'external-api-call' }
 * );
 * 
 * // With circuit breaker
 * const response = await reliableCall(
 *   () => axios.get('/api/service'),
 *   { circuitBreaker: myCircuitBreaker }
 * );
 * ```
 */
export async function reliableCall<T>(
  fn: () => Promise<T>,
  config: ReliableCallConfig = {}
): Promise<T> {
  const settings = { 
    retries: config.retries ?? DEFAULT_CONFIG.retries,
    timeoutMs: config.timeoutMs ?? DEFAULT_CONFIG.timeoutMs,
    circuitBreaker: config.circuitBreaker,
    retryableStatusCodes: config.retryableStatusCodes ?? DEFAULT_CONFIG.retryableStatusCodes,
    operationName: config.operationName ?? DEFAULT_CONFIG.operationName,
  };
  
  // Create retry policy
  const retryPolicy = new RetryPolicy({
    maxAttempts: settings.retries,
    initialDelay: 1000,
    maxDelay: settings.timeoutMs / 2,
    backoffMultiplier: 2,
    jitterType: 'full',
    circuitBreaker: settings.circuitBreaker,
    retryableErrors: settings.retryableStatusCodes.map((code) => `HTTP_${code}`),
  });

  let lastError: Error | undefined;
  let attemptCount = 0;

  try {
    return await retryPolicy.execute(async (context) => {
      attemptCount = context.attempt;
      
      // Execute with timeout
      const result = await Promise.race([
        fn(),
        new Promise<never>((_, reject) =>
          setTimeout(
            () => reject(new TimeoutError(settings.operationName!, settings.timeoutMs)),
            settings.timeoutMs
          )
        ),
      ]);

      return result;
    });
  } catch (error) {
    lastError = error as Error;
    
    // Extract status code if axios error
    let statusCode: number | undefined;
    if (axios.isAxiosError(error)) {
      statusCode = (error as AxiosError).response?.status;
    }

    throw new ReliableCallError(
      `Failed after ${attemptCount} attempts: ${lastError.message}`,
      lastError,
      statusCode,
      attemptCount
    );
  }
}

/**
 * Wrapper for axios calls with built-in reliability
 */
export async function reliableAxios<T>(
  url: string,
  options?: any,
  config?: ReliableCallConfig
): Promise<AxiosResponse<T>> {
  return reliableCall(
    () => axios.get<T>(url, options),
    { ...config, operationName: config?.operationName || `GET ${url}` }
  );
}

/**
 * Wrapper for fetch calls with built-in reliability
 */
export async function reliableFetch<T>(
  url: string,
  options?: RequestInit,
  config?: ReliableCallConfig
): Promise<T> {
  return reliableCall(
    () => fetch(url, options).then((res) => {
      if (!res.ok) {
        throw new Error(`HTTP ${res.status}: ${res.statusText}`);
      }
      return res.json() as Promise<T>;
    }),
    { ...config, operationName: config?.operationName || `FETCH ${url}` }
  );
}

/**
 * Check if an error is retryable
 */
export function isRetryableError(error: unknown): boolean {
  if (!error) {return false;}
  
  const err = error as Error;
  
  // Network errors are retryable
  if (err.message.includes('ECONNRESET') ||
      err.message.includes('ETIMEDOUT') ||
      err.message.includes('ENOTFOUND')) {
    return true;
  }

  // HTTP status codes
  if (axios.isAxiosError(error)) {
    const status = error.response?.status;
    return status === 408 || status === 429 || 
           (!!status && status >= 500 && status <= 599);
  }

  // Timeout errors are NOT retryable (we set the timeout)
  if (error instanceof TimeoutError) {
    return false;
  }

  return false;
}

import { createLogger } from '../lib/logger'

const logger = createLogger('retry')

export async function retry<T>(
  fn: () => Promise<T>,
  retries = 3,
  delay = 500
): Promise<T> {
  let lastError;

  for (let i = 0; i < retries; i++) {
    try {
      return await fn();
    } catch (err) {
      lastError = err;

      const backoff = delay * Math.pow(2, i);
      logger.warn({ attempt: i + 1, retries, backoff }, 'Retry attempt');

      await new Promise((res) => setTimeout(res, backoff));
    }
  }

  throw lastError;
}

// ============================================================================
// Secure Command Execution Layer
// ============================================================================
// 
// Provides safe command execution with:
// - Command whitelisting
// - Argument validation
// - No shell injection possible
// - Timeout protection
// ============================================================================

import { spawn, SpawnOptions } from 'child_process';

// Whitelist of allowed commands and their valid arguments
const ALLOWED_COMMANDS: Record<string, { allowedArgs: string[]; description: string }> = {
  tar: {
    allowedArgs: ['-czf', '-C', '-xzf', '-z', '-cf', '-xf'],
    description: 'Archive utility'
  },
  docker: {
    allowedArgs: ['run', 'stop', 'ps', 'rm', 'logs', 'inspect', 'exec'],
    description: 'Container runtime'
  },
  pg_dump: {
    allowedArgs: ['-F', '-f', '-h', '-U', '-d', '--format', '--file'],
    description: 'Database backup'
  },
  gzip: {
    allowedArgs: ['-c', '-d', '-k'],
    description: 'Compression utility'
  },
  which: {
    allowedArgs: [],
    description: 'Binary location lookup'
  },
  runsc: {
    allowedArgs: ['run', 'kill', 'delete', 'list'],
    description: 'Container runtime (gVisor)'
  }
};

type AllowedCommand = keyof typeof ALLOWED_COMMANDS;

export class CommandExecutionError extends Error {
  constructor(
    message: string,
    public command: string,
    public args: string[],
    public exitCode?: number
  ) {
    super(message);
    this.name = 'CommandExecutionError';
  }
}

export interface SafeExecResult {
  stdout: string;
  stderr: string;
  exitCode: number;
  command: string;
  args: string[];
}

/**
 * Validates that an argument is safe (no shell metacharacters)
 */
function validateArg(arg: string, argIndex: number): void {
  if (typeof arg !== 'string') {
    throw new CommandExecutionError(
      `Argument at index ${argIndex} must be a string`,
      '',
      [arg]
    );
  }

  // Block shell metacharacters that could enable injection
  const dangerousPatterns = [
    ';',   // Command separator
    '|',   // Pipe
    '&',   // Background/AND
    '$',   // Variable expansion
    '`',   // Command substitution
    '(', ')', '{', '}',  // Grouping
    '<', '>',  // Redirection
    '\n', '\r',  // Newlines
    '\\',  // Escape
    '"', '\'',  // Quotes (when unbalanced)
  ];

  for (const pattern of dangerousPatterns) {
    if (arg.includes(pattern)) {
      throw new CommandExecutionError(
        `Argument contains forbidden character '${pattern}'`,
        '',
        [arg]
      );
    }
  }

  // Block path traversal attempts
  if (arg.includes('..') && arg.startsWith('/')) {
    throw new CommandExecutionError(
      'Absolute path traversal is forbidden',
      '',
      [arg]
    );
  }
}

/**
 * Validates command and arguments against whitelist
 */
function validateCommand(command: string, args: string[]): void {
  // Check if command is allowed
  const allowedCommand = ALLOWED_COMMANDS[command];
  
  if (!allowedCommand) {
    throw new CommandExecutionError(
      `Command not allowed: ${command}. Allowed commands: ${Object.keys(ALLOWED_COMMANDS).join(', ')}`,
      command,
      args
    );
  }

  // Validate each argument
  args.forEach((arg, index) => {
    validateArg(arg, index);
    
    // If command has specific allowed args, validate against whitelist
    if (allowedCommand.allowedArgs.length > 0) {
      // Extract base argument (without value)
      const baseArg = arg.split('=').find((a) => a !== '') || arg;
      
      if (!allowedCommand.allowedArgs.includes(baseArg)) {
        // Check if it's a value for a known argument
        const prevArg = args[index - 1];
        const isValue = prevArg && allowedCommand.allowedArgs.includes(prevArg);
        
        if (!isValue && !baseArg.startsWith('/')) {
          throw new CommandExecutionError(
            `Argument '${baseArg}' not allowed for command '${command}'. Allowed: ${allowedCommand.allowedArgs.join(', ')}`,
            command,
            args
          );
        }
      }
    }
  });
}

/**
 * Safely execute a command with validation and timeout protection
 * 
 * @param command - Command to execute (must be whitelisted)
 * @param args - Command arguments (validated)
 * @param options - Spawn options
 * @param timeoutMs - Timeout in milliseconds (default: 30s)
 * @returns Promise with stdout, stderr, and exit code
 * 
 * @example
 * ```typescript
 * // Safe usage
 * const result = await safeExec('tar', ['-czf', 'backup.tar.gz', '-C', '/backups', '.']);
 * 
 * // Will throw error
 * await safeExec('rm', ['-rf', '/']); // ❌ Command not allowed
 * await safeExec('tar', ['-czf', 'file; rm -rf / #']); // ❌ Shell metacharacter
 * ```
 */
export async function safeExec(
  command: string,
  args: string[],
  options: SpawnOptions = {},
  timeoutMs: number = 30000
): Promise<SafeExecResult> {
  // Validate command and arguments BEFORE execution
  validateCommand(command, args);

  return new Promise((resolve, reject) => {
    let stdout = '';
    let stderr = '';
    let settled = false;

    // Set up spawn with shell disabled (CRITICAL SECURITY)
    const proc = spawn(command, args, {
      ...options,
      shell: false,  // NEVER use shell
      stdio: ['ignore', 'pipe', 'pipe']
    });

    // Timeout protection
    const timeout = setTimeout(() => {
      if (!settled) {
        settled = true;
        proc.kill('SIGTERM');
        
        // Force kill after grace period
        setTimeout(() => {
          try {
            proc.kill('SIGKILL');
          } catch (e) {
            // Process already dead
          }
        }, 5000);
        
        reject(new CommandExecutionError(
          `Command timed out after ${timeoutMs}ms`,
          command,
          args
        ));
      }
    }, timeoutMs);

    // Capture output
    proc.stdout?.on('data', (data: Buffer) => {
      stdout += data.toString();
    });

    proc.stderr?.on('data', (data: Buffer) => {
      stderr += data.toString();
    });

    // Handle completion
    proc.on('close', (code: number | null) => {
      if (settled) {return;}
      settled = true;
      clearTimeout(timeout);

      if (code === 0) {
        resolve({
          stdout: stdout.trim(),
          stderr: stderr.trim(),
          exitCode: code,
          command,
          args
        });
      } else {
        reject(new CommandExecutionError(
          `Command failed with exit code ${code}: ${stderr.trim()}`,
          command,
          args,
          code ?? undefined
        ));
      }
    });

    // Handle spawn errors
    proc.on('error', (error: Error) => {
      if (!settled) {
        settled = true;
        clearTimeout(timeout);
        reject(new CommandExecutionError(
          `Failed to spawn command: ${error.message}`,
          command,
          args
        ));
      }
    });
  });
}

/**
 * Execute a command and return only stdout (convenience wrapper)
 */
export async function safeExecOutput(
  command: string,
  args: string[],
  timeoutMs: number = 30000
): Promise<string> {
  const result = await safeExec(command, args, {}, timeoutMs);
  return result.stdout;
}

/**
 * Check if a command exists and is executable
 */
export async function commandExists(command: string): Promise<boolean> {
  try {
    await safeExec('which', [command], {}, 5000);
    return true;
  } catch {
    return false;
  }
}

/**
 * Timeout Utility for HTTP Requests
 * 
 * Prevents hanging requests by enforcing timeouts on all external calls.
 * Works with both fetch and axios.
 */

// ============================================================================
// Types
// ============================================================================

export interface TimeoutOptions {
  /** Timeout in milliseconds */
  timeoutMs: number;
  /** Operation name for error message */
  operationName?: string;
  /** AbortSignal (for fetch) */
  signal?: AbortSignal;
}

export class TimeoutError extends Error {
  constructor(
    public readonly operationName: string,
    public readonly timeoutMs: number
  ) {
    super(`${operationName} timed out after ${timeoutMs}ms`);
    this.name = 'TimeoutError';
  }
}

// ============================================================================
// Timeout Wrapper for Promises
// ============================================================================

/**
 * Wrap any promise with a timeout
 * 
 * @param promise - The promise to wrap
 * @param timeoutMs - Timeout in milliseconds
 * @param operationName - Name of the operation for error messages
 * @returns Promise that rejects with TimeoutError if timeout is exceeded
 */
export async function withTimeout<T>(
  promise: Promise<T>,
  timeoutMs: number,
  operationName: string = 'Operation'
): Promise<T> {
  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), timeoutMs);

  try {
    return await Promise.race([
      promise,
      new Promise<T>((_, reject) => {
        controller.signal.addEventListener('abort', () => {
          clearTimeout(timeoutId);
          reject(new TimeoutError(operationName, timeoutMs));
        });
      })
    ]);
  } finally {
    clearTimeout(timeoutId);
  }
}

// ============================================================================
// Fetch with Timeout
// ============================================================================

/**
 * Fetch wrapper with automatic timeout
 * 
 * @param url - URL to fetch
 * @param options - Fetch options including timeout
 * @returns Response from fetch
 * 
 * @example
 * const response = await fetchWithTimeout('/api/tasks', {
 *   timeoutMs: 5000,
 *   method: 'POST',
 *   body: JSON.stringify(data)
 * });
 */
export async function fetchWithTimeout(
  url: string,
  options: RequestInit & { timeoutMs?: number } = {}
): Promise<Response> {
  const { timeoutMs = 10000, ...fetchOptions } = options;
  
  // Create abort controller
  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), timeoutMs);

  try {
    const response = await fetch(url, {
      ...fetchOptions,
      signal: controller.signal,
    });
    
    return response;
  } catch (error) {
    if ((error as any).name === 'AbortError') {
      throw new TimeoutError(`GET ${url}`, timeoutMs);
    }
    throw error;
  } finally {
    clearTimeout(timeoutId);
  }
}

// ============================================================================
// Axios-like Helper
// ============================================================================

/**
 * Axios request configuration
 */
export interface AxiosRequestConfig {
  url: string;
  method?: 'GET' | 'POST' | 'PUT' | 'DELETE' | 'PATCH';
  data?: any;
  headers?: Record<string, string>;
  timeout?: number;
  signal?: AbortSignal;
}

/**
 * Axios response wrapper
 */
export interface AxiosResponse<T = any> {
  data: T;
  status: number;
  statusText: string;
  headers: any;
}

/**
 * Execute axios-like request with timeout
 * Note: This creates an AbortSignal that can be passed to axios
 * 
 * @param config - Request configuration
 * @param timeoutMs - Timeout in milliseconds
 * @returns Object with signal that should be passed to axios
 * 
 * @example
 * const { signal } = createTimeoutSignal(5000);
 * const response = await axios.get(url, { signal });
 */
export function createTimeoutSignal(timeoutMs: number): { signal: AbortSignal } {
  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), timeoutMs);
  
  // Auto-clear timeout when request completes
  const cleanup = () => clearTimeout(timeoutId);
  controller.signal.addEventListener('abort', cleanup);
  
  return { signal: controller.signal };
}

