// ============================================================================

/**
 * Example route with Zod schema conversion:
 * 
 * ```typescript
 * import { FastifyInstance, FastifyRequest, FastifyReply } from 'fastify'
 * import { z } from 'zod'
 * import { createSchema, zodToFastifySchema } from './zod-schema'
