      }
      return { 
        ok: true, 
        status: 200, 
        json: async () => ({ data: 'success' }) 
      };
    });
    
    const result = await reliableFetch('http://api.example.com/test', undefined, { retries: 3 });
    
    expect((result as any).data).toBe('success');
    expect(global.fetch).toHaveBeenCalledTimes(3);
  });
});

