describe('TaskScheduler', () => {
  let scheduler: TaskScheduler
  let mockPrisma: Partial<PrismaClient>
  let mockRedis: Redis
  let mockWsManager: Partial<WebSocketManager>
  let mockLogger: Logger

  beforeEach(() => {
    mockPrisma = {
      task: {
        findMany: vi.fn(),
        findUnique: vi.fn(),
        update: vi.fn(),
        count: vi.fn(),
      } as unknown as PrismaClient['task'],
      edgeNode: {
