    }
    mockLogger = {
      info: vi.fn(),
      error: vi.fn(),
      warn: vi.fn(),
      debug: vi.fn(),
    } as unknown as Logger

    scheduler = new TaskScheduler(
      mockPrisma as PrismaClient,
