      const fn = vi.fn().mockRejectedValue(new Error('test error'));
      
      try {
        await policy.execute(fn);
        expect.fail('Should have thrown');
      } catch (error) {
        expect(error).toBeInstanceOf(RetryExhaustedError);
        if (error instanceof RetryExhaustedError) {
          expect(error.errors).toHaveLength(2);
          expect(error.errors[0].message).toBe('test error');
        }
      }
    });
  });

  describe('exponential backoff', () => {
    it('should increase delay exponentially', async () => {
      vi.useFakeTimers();
      
      const policy = new RetryPolicy({
        maxAttempts: 3,
        initialDelay: 100,
        backoffMultiplier: 2,
        maxDelay: 1000,
      });
      
      const fn = vi.fn()
        .mockRejectedValueOnce(new Error('fail'))
        .mockRejectedValueOnce(new Error('fail'))
        .mockResolvedValue('success');
      
      const promise = policy.execute(fn);
      
      // First call happens immediately
      expect(fn).toHaveBeenCalledTimes(1);
      
      // Advance 100ms (first backoff)
      await vi.advanceTimersByTimeAsync(100);
      expect(fn).toHaveBeenCalledTimes(2);
      
      // Advance 200ms (second backoff)
      await vi.advanceTimersByTimeAsync(200);
      expect(fn).toHaveBeenCalledTimes(3);
      
      const result = await promise;
      expect(result).toBe('success');
      
      vi.useRealTimers();
    });

    it('should cap delay at maxDelay', async () => {
      vi.useFakeTimers();
      
      const policy = new RetryPolicy({
        maxAttempts: 5,
        initialDelay: 1000,
        backoffMultiplier: 10,
        maxDelay: 5000,
      });
      
      const delays: number[] = [];
      const fn = vi.fn().mockImplementation(async () => {
        throw new Error('fail');
      });
      
      const onRetry = vi.fn((attempt, error, delay) => {
        delays.push(delay);
      });
      
      const policyWithCallback = new RetryPolicy({
        maxAttempts: 5,
        initialDelay: 1000,
        backoffMultiplier: 10,
        maxDelay: 5000,
        onRetry,
      });
      
      try {
        await policyWithCallback.execute(fn);
      } catch (e) {}
      
      // Delays should be capped at maxDelay
      delays.forEach((delay) => {
        expect(delay).toBeLessThanOrEqual(5000);
      });
      
      vi.useRealTimers();
    });
  });

  describe('retryable errors filter', () => {
    it('should only retry specified errors', async () => {
      const policy = new RetryPolicy({
        maxAttempts: 3,
        initialDelay: 10,
        retryableErrors: ['NetworkError', 'TimeoutError'],
      });
      
      class NetworkError extends Error {
        constructor() {
          super('network error');
          this.name = 'NetworkError';
        }
      }
      
      const fn = vi.fn()
        .mockRejectedValueOnce(new NetworkError())
        .mockResolvedValue('success');
      
      const result = await policy.execute(fn);
      expect(result).toBe('success');
      expect(fn).toHaveBeenCalledTimes(2);
    });

    it('should not retry non-retryable errors', async () => {
      const policy = new RetryPolicy({
        maxAttempts: 3,
        initialDelay: 10,
        retryableErrors: ['NetworkError'],
      });
      
      const fn = vi.fn().mockRejectedValue(new Error('OtherError'));
      
      await expect(policy.execute(fn)).rejects.toThrow('OtherError');
      expect(fn).toHaveBeenCalledTimes(1);
    });
  });

  describe('events', () => {
    it('should emit retry events', async () => {
      const policy = new RetryPolicy({ maxAttempts: 3, initialDelay: 10 });
      const retryEvents: any[] = [];
      
      policy.on('retry', (data) => retryEvents.push(data));
      
      const fn = vi.fn()
        .mockRejectedValueOnce(new Error('fail'))
        .mockResolvedValue('success');
      
      await policy.execute(fn);
      
      expect(retryEvents).toHaveLength(1);
      expect(retryEvents[0].attempt).toBe(1);
      expect(retryEvents[0].error.message).toBe('fail');
    });
  });
});

import { EventEmitter } from 'eventemitter3';
import { Consumer, EachMessagePayload,Kafka, Message, Producer } from 'kafkajs';

// ============================================================================
// Types
// ============================================================================

export interface DLQConfig {
  dlqTopicSuffix: string;
  maxRetries: number;
  retryDelayMs: number;
  enabled: boolean;
}

export interface FailedEvent {
  id: string;
  originalTopic: string;
  originalKey: string | null;
  payload: Record<string, unknown>;
  headers: Record<string, string>;
  error: string;
  errorStack?: string;
  attempts: number;
  originalEventId?: string;
  timestamp: Date;
}

export interface DLQStats {
  totalEvents: number;
  pendingRetry: number;
  permanentlyFailed: number;
  reprocessed: number;
  byTopic: Record<string, number>;
}

export const DEFAULT_DLQ_CONFIG: DLQConfig = {
  dlqTopicSuffix: '.dlq',
  maxRetries: 3,
  retryDelayMs: 5000,
  enabled: true,
};

// PrismaClient-like interface for dead letter events
interface PrismaClientLike {
  deadLetterEvent: {
    create: (args: any) => Promise<any>;
    findUnique: (args: any) => Promise<any | null>;
    findMany: (args: any) => Promise<any[]>;
    count: (args: any) => Promise<number>;
    update: (args: any) => Promise<any>;
    updateMany: (args: any) => Promise<any>;
    deleteMany: (args: any) => Promise<any>;
    groupBy: (args: any) => Promise<any[]>;
  };
}

// ============================================================================
// Dead Letter Queue Manager
// ============================================================================

export class DeadLetterQueue extends EventEmitter {
  private kafka: Kafka;
  private producer: Producer;
  private prisma: PrismaClientLike;
  private config: DLQConfig;
  private dlqTopics: Set<string> = new Set();

  constructor(
    kafka: Kafka,
    producer: Producer,
    prisma: PrismaClientLike,
    config: Partial<DLQConfig> = {}
  ) {
    super();
    this.kafka = kafka;
    this.producer = producer;
    this.prisma = prisma;
    this.config = { ...DEFAULT_DLQ_CONFIG, ...config };
  }

  /**
   * Get the DLQ topic name for a given original topic
   */
  getDLQTopic(originalTopic: string): string {
    return `${originalTopic}${this.config.dlqTopicSuffix}`;
  }

  /**
   * Create DLQ topics for existing topics
   */
  async ensureDLQTopics(topics: string[]): Promise<void> {
    const admin = this.kafka.admin();
    await admin.connect();

    try {
      const existingTopics = await admin.listTopics();
      const dlqTopics = topics.map((t) => this.getDLQTopic(t));
      const topicsToCreate = dlqTopics.filter((t) => !existingTopics.includes(t));

      if (topicsToCreate.length > 0) {
        await admin.createTopics({
          topics: topicsToCreate.map((topic) => ({
            topic,
            numPartitions: 6,
            replicationFactor: 3,
            configEntries: [
              { name: 'retention.ms', value: '604800000' }, // 7 days
              { name: 'cleanup.policy', value: 'compact' },
            ],
          })),
        });
      }

      for (const topic of dlqTopics) {
        this.dlqTopics.add(topic);
      }
    } finally {
      await admin.disconnect();
    }
  }

  /**
   * Send a failed event to the DLQ
   */
  async sendToDLQ(
    originalTopic: string,
    message: Message,
    error: Error,
    originalEventId?: string
  ): Promise<void> {
    if (!this.config.enabled) {
      return;
    }

    const dlqTopic = this.getDLQTopic(originalTopic);

    const failedEvent: FailedEvent = {
      id: `dlq-${Date.now()}-${Math.random().toString(36).substring(2, 9)}`,
      originalTopic,
      originalKey: message.key?.toString() || null,
      payload: message.value ? JSON.parse(message.value.toString()) : {},
      headers: this.parseHeaders(message.headers),
      error: error.message,
      errorStack: error.stack,
      attempts: 1,
      originalEventId,
      timestamp: new Date(),
    };

    // Store in database for reprocessing
    await this.prisma.deadLetterEvent.create({
      data: {
        originalTopic,
        originalKey: failedEvent.originalKey,
        payload: failedEvent.payload,
        headers: failedEvent.headers as any,
        error: failedEvent.error,
        errorStack: failedEvent.errorStack,
        originalEventId,
        status: 'PENDING',
      },
    });

    // Also send to Kafka DLQ topic for visibility
    await this.producer.send({
      topic: dlqTopic,
      messages: [{
        key: failedEvent.id,
        value: JSON.stringify(failedEvent),
        headers: {
          'original-topic': originalTopic,
          'error': error.message,
          'failed-at': new Date().toISOString(),
        },
      }],
    });

    this.emit('event_added', { eventId: failedEvent.id, originalTopic, error });
  }

  /**
   * Get failed events from DLQ
   */
  async getFailedEvents(options: {
    topic?: string;
    status?: 'PENDING' | 'RETRYING' | 'REPROCESSED' | 'PERMANENTLY_FAILED';
    limit?: number;
    offset?: number;
  } = {}): Promise<FailedEvent[]> {
    const where: any = {};
    
    if (options.topic) {
      where.originalTopic = options.topic;
    }
    
    if (options.status) {
      where.status = options.status;
    }

    const events = await this.prisma.deadLetterEvent.findMany({
      where,
      orderBy: { createdAt: 'desc' },
      take: options.limit || 50,
      skip: options.offset || 0,
    });

    return events.map((e: { id: string; originalTopic: string; originalKey: string | null; payload: Record<string, unknown>; headers: Record<string, unknown>; error: string; errorStack: string | null; attempts: number; originalEventId: string | null; createdAt: Date }) => ({
      id: e.id,
      originalTopic: e.originalTopic,
      originalKey: e.originalKey,
      payload: e.payload,
      headers: e.headers as Record<string, string>,
      error: e.error,
      errorStack: e.errorStack || undefined,
      attempts: e.attempts,
      originalEventId: e.originalEventId || undefined,
      timestamp: e.createdAt,
    }));
  }

  /**
   * Retry a failed event
   */
  async retryEvent(eventId: string): Promise<boolean> {
    const event = await this.prisma.deadLetterEvent.findUnique({
      where: { id: eventId },
    });

    if (!event) {
      throw new Error(`Event ${eventId} not found`);
    }

    if (event.status === 'REPROCESSED') {
      throw new Error('Event already reprocessed');
    }

    // Update status
    await this.prisma.deadLetterEvent.update({
      where: { id: eventId },
      data: {
        status: 'RETRYING',
        attempts: { increment: 1 },
        lastAttemptAt: new Date(),
      },
    });

    try {
      // Re-publish to original topic
      await this.producer.send({
        topic: event.originalTopic,
        messages: [{
          key: event.originalKey || undefined,
          value: JSON.stringify(event.payload),
          headers: {
            ...event.headers as Record<string, string>,
            'dlq-retry': 'true',
            'dlq-event-id': eventId,
            'dlq-attempt': String(event.attempts + 1),
          },
        }],
      });

      // Mark as reprocessed
      await this.prisma.deadLetterEvent.update({
        where: { id: eventId },
        data: { status: 'REPROCESSED' },
      });

      this.emit('event_reprocessed', { eventId, originalTopic: event.originalTopic });
      return true;
    } catch (error) {
      // Check if max retries exceeded
      if (event.attempts + 1 >= this.config.maxRetries) {
        await this.prisma.deadLetterEvent.update({
          where: { id: eventId },
          data: { status: 'PERMANENTLY_FAILED' },
        });
        this.emit('event_permanently_failed', { eventId, error });
      } else {
        await this.prisma.deadLetterEvent.update({
          where: { id: eventId },
          data: { status: 'PENDING' },
        });
      }
      throw error;
    }
  }

  /**
   * Retry multiple events
   */
  async retryEvents(eventIds: string[]): Promise<{
    succeeded: string[];
    failed: { id: string; error: string }[];
  }> {
    const succeeded: string[] = [];
    const failed: { id: string; error: string }[] = [];

    for (const eventId of eventIds) {
      try {
        await this.retryEvent(eventId);
        succeeded.push(eventId);
      } catch (error) {
        failed.push({ id: eventId, error: (error as Error).message });
      }
    }

    return { succeeded, failed };
  }

  /**
   * Get DLQ statistics
   */
  async getStats(): Promise<DLQStats> {
    const [totalEvents, pendingRetry, permanentlyFailed, reprocessed, byTopic] = await Promise.all([
      this.prisma.deadLetterEvent.count({}),
      this.prisma.deadLetterEvent.count({ where: { status: 'PENDING' } }),
      this.prisma.deadLetterEvent.count({ where: { status: 'PERMANENTLY_FAILED' } }),
      this.prisma.deadLetterEvent.count({ where: { status: 'REPROCESSED' } }),
      this.prisma.deadLetterEvent.groupBy({
        by: ['originalTopic'],
        _count: { id: true },
        where: { status: 'PENDING' },
      }),
    ]);

    return {
      totalEvents,
      pendingRetry,
      permanentlyFailed,
      reprocessed,
      byTopic: byTopic.reduce((acc: Record<string, number>, item: { originalTopic: string; _count: { id: number } }) => {
        acc[item.originalTopic] = item._count.id;
        return acc;
      }, {} as Record<string, number>),
    };
  }

  /**
   * Purge old events
   */
  async purgeOldEvents(olderThanDays: number = 7): Promise<number> {
    const cutoff = new Date(Date.now() - olderThanDays * 24 * 60 * 60 * 1000);
    
    const result = await this.prisma.deadLetterEvent.deleteMany({
      where: {
        status: { in: ['REPROCESSED', 'PERMANENTLY_FAILED'] },
        createdAt: { lt: cutoff },
      },
    });

    this.emit('purged', { count: result.count });
    return result.count;
  }

  /**
   * Parse Kafka headers
   */
  private parseHeaders(headers?: Record<string, any>): Record<string, string> {
    if (!headers) {return {};}
    
    const result: Record<string, string> = {};
    for (const [key, value] of Object.entries(headers)) {
      if (Buffer.isBuffer(value)) {
        result[key] = value.toString();
      } else if (typeof value === 'string') {
        result[key] = value;
      }
    }
    return result;
  }
}

import { DomainEvent, generateCorrelationId,generateEventId } from '@edgecloud/shared-kernel';
import { Consumer, Kafka, Message,Producer } from 'kafkajs';

import { DeadLetterQueue, DLQConfig } from './dead-letter-queue';

export interface EventBusConfig {
  brokers: string[];
  clientId: string;
  retry?: {
    maxRetries: number;
    retries: number;
  };
}

export interface PublishOptions {
  correlationId?: string;
  partition?: number;
  headers?: Record<string, string>;
}

export type EventHandler<T extends DomainEvent> = (event: T) => Promise<void>;

export class EventBus {
  private kafka: Kafka;
  private producer: Producer;
  private consumers: Map<string, Consumer> = new Map();
  private isConnected: boolean = false;
  private dlq: DeadLetterQueue | null = null;

  constructor(private config: EventBusConfig) {
    this.kafka = new Kafka({
      clientId: config.clientId,
      brokers: config.brokers,
      retry: config.retry || { maxRetries: 5, retries: 5 },
    });

    this.producer = this.kafka.producer({
      idempotent: true,
      transactionalId: config.clientId,
    });
  }

  async initializeDLQ(prisma: any, topics: string[], config?: Partial<DLQConfig>): Promise<void> {
    this.dlq = new DeadLetterQueue(this.kafka, this.producer, prisma, config);
    await this.dlq.ensureDLQTopics(topics);
  }

  async retryFailedEvent(eventId: string): Promise<boolean> {
    if (!this.dlq) {
      throw new Error('DLQ not initialized');
    }
    return this.dlq.retryEvent(eventId);
  }

  async connect(): Promise<void> {
    if (this.isConnected) {return;}
    
    await this.producer.connect();
    this.isConnected = true;
  }

  async disconnect(): Promise<void> {
    await this.producer.disconnect();
    
    for (const consumer of this.consumers.values()) {
      await consumer.disconnect();
    }
    
    this.isConnected = false;
  }

  async publish<T extends DomainEvent>(
    topic: string,
    event: Omit<T, 'eventId' | 'timestamp'>,
    options?: PublishOptions
  ): Promise<void> {
    if (!this.isConnected) {
      await this.connect();
    }

    const fullEvent: DomainEvent = {
      ...event,
      eventId: generateEventId(),
      timestamp: new Date(),
    };

    const message: Message = {
      key: fullEvent.aggregateId,
      value: JSON.stringify(fullEvent),
      headers: {
        'event-type': fullEvent.eventType,
        'correlation-id': options?.correlationId || generateCorrelationId(),
        'timestamp': fullEvent.timestamp.toISOString(),
        ...options?.headers,
      },
    };

    await this.producer.send({
      topic,
      messages: [message],
    });
  }

  async subscribe<T extends DomainEvent>(
    topic: string,
    groupId: string,
    handler: EventHandler<T>
  ): Promise<void> {
    const consumerKey = `${topic}:${groupId}`;
    
    if (this.consumers.has(consumerKey)) {
      throw new Error(`Consumer already exists for ${consumerKey}`);
    }

    const consumer = this.kafka.consumer({
      groupId,
      sessionTimeout: 30000,
      heartbeatInterval: 3000,
    });

    await consumer.connect();
    await consumer.subscribe({ topic, fromBeginning: false });

    await consumer.run({
      eachMessage: async ({ message }: { message: Message }) => {
        if (!message.value) {return;}

        try {
          const event = JSON.parse(message.value.toString()) as T;
          await handler(event);
        } catch (error) {
          console.error(`Error handling event from ${topic}:`, error);
          
          // Forward to DLQ if configured
          if (this.dlq) {
            const eventId = message.headers?.['event-id']?.toString() || 
              message.key?.toString() || 
              `evt-${Date.now()}`;
            
            await this.dlq.sendToDLQ(
              topic,
              message,
              error as Error,
              eventId
            );
          }
        }
      },
    });

    this.consumers.set(consumerKey, consumer);
  }

  async createTopics(topics: Array<{ topic: string; partitions: number; replicationFactor: number }>): Promise<void> {
    const admin = this.kafka.admin();
    await admin.connect();

    const existingTopics = await admin.listTopics();
    const topicsToCreate = topics.filter((t) => !existingTopics?.includes(t.topic));
    
    if (topicsToCreate.length > 0) {
      await admin.createTopics({
        topics: topicsToCreate.map((t) => ({
          topic: t.topic,
          numPartitions: t.partitions,
          replicationFactor: t.replicationFactor,
        })),
      });
    }

    await admin.disconnect();
  }
}

// Topic definitions
export const TOPICS = {
  TASK_COMMANDS: 'tasks.commands',
  TASK_EVENTS: 'tasks.events',
  NODE_COMMANDS: 'nodes.commands',
  NODE_EVENTS: 'nodes.events',
  METRICS: 'metrics.raw',
  METRICS_RAW: 'metrics.raw',
  METRICS_AGGREGATED: 'metrics.aggregated',
  SCHEDULER_DECISIONS: 'scheduler.decisions',
  SYSTEM_ALERTS: 'system.alerts',
} as const;

export const DEFAULT_TOPIC_CONFIG = [
  { topic: TOPICS.TASK_COMMANDS, partitions: 12, replicationFactor: 3 },
  { topic: TOPICS.TASK_EVENTS, partitions: 12, replicationFactor: 3 },
  { topic: TOPICS.NODE_COMMANDS, partitions: 6, replicationFactor: 3 },
  { topic: TOPICS.NODE_EVENTS, partitions: 6, replicationFactor: 3 },
  { topic: TOPICS.METRICS_RAW, partitions: 24, replicationFactor: 3 },
  { topic: TOPICS.METRICS_AGGREGATED, partitions: 6, replicationFactor: 3 },
  { topic: TOPICS.SCHEDULER_DECISIONS, partitions: 6, replicationFactor: 3 },
  { topic: TOPICS.SYSTEM_ALERTS, partitions: 3, replicationFactor: 3 },
];

