export class ServiceContainer extends EventEmitter {
  private config: ServiceConfig;
  
  // Core infrastructure
  public eventBus: EventBus;
  public cache: DistributedCache;
  public rateLimiter: DistributedRateLimiter;
  public db: PooledDatabase;
  
  // Security
