      // node-1 has lowest CPU usage (30%)
      const node1Score = results.find((r) => r.nodeId === 'node-1')!;
      const node2Score = results.find((r) => r.nodeId === 'node-2')!;
      
      expect(node1Score.scores.cpu).toBeGreaterThan(node2Score.scores.cpu);
    });

    it('should prefer nodes with lower memory usage', () => {
      const results = scorer.scoreNodes(mockNodes as any);
      
      // node-1 has lowest memory usage (40%)
      const node1Score = results.find((r) => r.nodeId === 'node-1')!;
      const node2Score = results.find((r) => r.nodeId === 'node-2')!;
      
      expect(node1Score.scores.memory).toBeGreaterThan(node2Score.scores.memory);
    });

    it('should prefer nodes with lower latency', () => {
      const results = scorer.scoreNodes(mockNodes as any);
      
      // node-1 has lowest latency (10ms)
      const node1Score = results.find((r) => r.nodeId === 'node-1')!;
      const node3Score = results.find((r) => r.nodeId === 'node-3')!;
      
      expect(node1Score.scores.latency).toBeGreaterThan(node3Score.scores.latency);
    });

    it('should return sorted results by default', () => {
      const results = scorer.scoreNodes(mockNodes as any);
      
      for (let i = 1; i < results.length; i++) {
        expect(results[i-1].totalScore).toBeGreaterThanOrEqual(results[i].totalScore);
      }
    });
  });

  describe('custom weights', () => {
    it('should use custom weights for scoring', () => {
      const customScorer = new MultiObjectiveScorer({
        latency: 0.5,
        cpu: 0.3,
        memory: 0.1,
        cost: 0.1,
        network: 0.0,
      });
      
      const nodes = [
        { id: 'high-latency', cpuUsage: 10, memoryUsage: 10, networkLatency: 100, availableMemory: 8192, totalMemory: 16384, costPerHour: 0.05 },
        { id: 'low-latency', cpuUsage: 90, memoryUsage: 90, networkLatency: 5, availableMemory: 1024, totalMemory: 16384, costPerHour: 0.50 },
      ];
      
      const results = customScorer.scoreNodes(nodes as any);
      
      // With latency weight of 0.5, low-latency node should win despite high CPU
      expect(results[0].nodeId).toBe('low-latency');
    });
  });

  describe('score calculation', () => {
    it('should calculate CPU score correctly', () => {
      const score = scorer.calculateCpuScore(50);
      expect(score).toBeGreaterThanOrEqual(0);
      expect(score).toBeLessThanOrEqual(1);
    });

    it('should give higher score to lower CPU usage', () => {
      const lowCpuScore = scorer.calculateCpuScore(20);
      const highCpuScore = scorer.calculateCpuScore(80);
      
      expect(lowCpuScore).toBeGreaterThan(highCpuScore);
    });

    it('should calculate memory score correctly', () => {
      const score = scorer.calculateMemoryScore(50);
      expect(score).toBeGreaterThanOrEqual(0);
      expect(score).toBeLessThanOrEqual(1);
    });

    it('should calculate latency score correctly', () => {
      const score = scorer.calculateLatencyScore(30);
      expect(score).toBeGreaterThanOrEqual(0);
      expect(score).toBeLessThanOrEqual(1);
    });

    it('should penalize high latency', () => {
      const lowLatencyScore = scorer.calculateLatencyScore(10);
      const highLatencyScore = scorer.calculateLatencyScore(200);
      
      expect(lowLatencyScore).toBeGreaterThan(highLatencyScore);
    });
  });

  describe('edge cases', () => {
    it('should handle empty node list', () => {
      const results = scorer.scoreNodes([]);
      expect(results).toEqual([]);
    });

    it('should handle single node', () => {
      const nodes = [
        { id: 'only-node', cpuUsage: 50, memoryUsage: 50, networkLatency: 20, availableMemory: 4096, totalMemory: 8192, costPerHour: 0.10 },
      ];
      
      const results = scorer.scoreNodes(nodes as any);
      
      expect(results).toHaveLength(1);
      expect(results[0].nodeId).toBe('only-node');
    });

    it('should handle extreme values', () => {
      const nodes = [
        { id: 'extreme', cpuUsage: 100, memoryUsage: 100, networkLatency: 1000, availableMemory: 0, totalMemory: 16384, costPerHour: 10 },
      ];
      
      const results = scorer.scoreNodes(nodes as any);
      
      expect(results[0].totalScore).toBeGreaterThanOrEqual(0);
    });
  });
});

import { EventEmitter } from 'eventemitter3';
import { collectDefaultMetrics,Counter, Gauge, Histogram, Registry } from 'prom-client';

export interface MetricsConfig {
  serviceName: string;
  serviceVersion: string;
  collectDefaults?: boolean;
  prefix?: string;
}

export class MetricsCollector extends EventEmitter {
  public readonly registry: Registry;
  private config: MetricsConfig;

  // Task metrics
  public readonly tasksCreated: Counter;
  public readonly tasksScheduled: Counter;
  public readonly tasksCompleted: Counter;
  public readonly tasksFailed: Counter;
  public readonly tasksCancelled: Counter;
  public readonly taskDuration: Histogram;
  public readonly taskQueueTime: Histogram;

  // Node metrics
  public readonly nodeRegistrations: Counter;
  public readonly nodeHeartbeats: Counter;
  public readonly nodeFailures: Counter;
  public readonly activeNodes: Gauge;
  public readonly nodeCpuUsage: Gauge;
  public readonly nodeMemoryUsage: Gauge;

  // Scheduler metrics
  public readonly schedulingDecisions: Counter;
  public readonly schedulingDuration: Histogram;
  public readonly schedulerLeader: Gauge;

  // RAFT metrics
  public readonly raftStateChanges: Counter;
  public readonly raftElections: Counter;
  public readonly raftLogEntries: Counter;
  public readonly raftCommitIndex: Gauge;

  // API metrics
  public readonly httpRequestsTotal: Counter;
  public readonly httpRequestDuration: Histogram;
  public readonly httpActiveRequests: Gauge;

  // Event bus metrics
  public readonly eventsPublished: Counter;
  public readonly eventsConsumed: Counter;
  public readonly eventProcessingDuration: Histogram;
  public readonly eventLag: Gauge;

  // Database metrics
  public readonly dbQueryDuration: Histogram;
  public readonly dbConnections: Gauge;
  public readonly dbConnectionErrors: Counter;

  constructor(config: MetricsConfig) {
    super();
    this.config = config;
    this.registry = new Registry();

    // Set default labels
    this.registry.setDefaultLabels({
      service: config.serviceName,
      version: config.serviceVersion,
    });

    // Collect default Node.js metrics
    if (config.collectDefaults !== false) {
      collectDefaultMetrics({ register: this.registry });
    }

    const prefix = config.prefix || 'edgecloud';

    // Initialize task metrics
    this.tasksCreated = new Counter({
      name: `${prefix}_tasks_created_total`,
      help: 'Total number of tasks created',
      labelNames: ['type', 'priority', 'region'],
      registers: [this.registry],
    });

    this.tasksScheduled = new Counter({
      name: `${prefix}_tasks_scheduled_total`,
      help: 'Total number of tasks scheduled',
      labelNames: ['node_id', 'algorithm'],
      registers: [this.registry],
    });

    this.tasksCompleted = new Counter({
      name: `${prefix}_tasks_completed_total`,
      help: 'Total number of tasks completed',
      labelNames: ['node_id', 'status'],
      registers: [this.registry],
    });

    this.tasksFailed = new Counter({
      name: `${prefix}_tasks_failed_total`,
      help: 'Total number of tasks failed',
      labelNames: ['node_id', 'error_type', 'retry_count'],
      registers: [this.registry],
    });

    this.tasksCancelled = new Counter({
      name: `${prefix}_tasks_cancelled_total`,
      help: 'Total number of tasks cancelled',
      labelNames: ['reason'],
      registers: [this.registry],
    });

    this.taskDuration = new Histogram({
      name: `${prefix}_task_duration_seconds`,
      help: 'Task execution duration in seconds',
      labelNames: ['type', 'node_id'],
      buckets: [0.1, 0.5, 1, 2, 5, 10, 30, 60, 120, 300],
      registers: [this.registry],
    });

    this.taskQueueTime = new Histogram({
      name: `${prefix}_task_queue_duration_seconds`,
      help: 'Time tasks spend in queue',
      labelNames: ['type', 'priority'],
      buckets: [0.1, 0.5, 1, 2, 5, 10, 30, 60],
      registers: [this.registry],
    });

    // Initialize node metrics
    this.nodeRegistrations = new Counter({
      name: `${prefix}_node_registrations_total`,
      help: 'Total number of node registrations',
      labelNames: ['region'],
      registers: [this.registry],
    });

    this.nodeHeartbeats = new Counter({
      name: `${prefix}_node_heartbeats_total`,
      help: 'Total number of node heartbeats received',
      labelNames: ['node_id', 'region'],
      registers: [this.registry],
    });

    this.nodeFailures = new Counter({
      name: `${prefix}_node_failures_total`,
      help: 'Total number of node failures',
      labelNames: ['node_id', 'reason'],
      registers: [this.registry],
    });

    this.activeNodes = new Gauge({
      name: `${prefix}_active_nodes`,
      help: 'Number of currently active nodes',
      labelNames: ['region', 'status'],
      registers: [this.registry],
    });

    this.nodeCpuUsage = new Gauge({
      name: `${prefix}_node_cpu_usage_percent`,
      help: 'CPU usage percentage per node',
      labelNames: ['node_id', 'region'],
      registers: [this.registry],
    });

    this.nodeMemoryUsage = new Gauge({
      name: `${prefix}_node_memory_usage_percent`,
      help: 'Memory usage percentage per node',
      labelNames: ['node_id', 'region'],
      registers: [this.registry],
    });

    // Initialize scheduler metrics
    this.schedulingDecisions = new Counter({
      name: `${prefix}_scheduling_decisions_total`,
      help: 'Total number of scheduling decisions',
      labelNames: ['algorithm', 'result'],
      registers: [this.registry],
    });

    this.schedulingDuration = new Histogram({
      name: `${prefix}_scheduling_duration_seconds`,
      help: 'Time taken to make scheduling decisions',
      labelNames: ['algorithm'],
      buckets: [0.001, 0.005, 0.01, 0.025, 0.05, 0.1, 0.25, 0.5, 1],
      registers: [this.registry],
    });

    this.schedulerLeader = new Gauge({
      name: `${prefix}_scheduler_leader`,
      help: 'Whether this scheduler instance is the leader (1) or not (0)',
      labelNames: ['node_id'],
      registers: [this.registry],
    });

    // Initialize RAFT metrics
    this.raftStateChanges = new Counter({
      name: `${prefix}_raft_state_changes_total`,
      help: 'Total number of RAFT state changes',
      labelNames: ['from_state', 'to_state'],
      registers: [this.registry],
    });

    this.raftElections = new Counter({
      name: `${prefix}_raft_elections_total`,
      help: 'Total number of RAFT elections',
      labelNames: ['result'],
      registers: [this.registry],
    });

    this.raftLogEntries = new Counter({
      name: `${prefix}_raft_log_entries_total`,
      help: 'Total number of RAFT log entries',
      labelNames: ['operation'],
      registers: [this.registry],
    });

    this.raftCommitIndex = new Gauge({
      name: `${prefix}_raft_commit_index`,
      help: 'Current RAFT commit index',
      labelNames: ['node_id'],
      registers: [this.registry],
    });

    // Initialize API metrics
    this.httpRequestsTotal = new Counter({
      name: `${prefix}_http_requests_total`,
      help: 'Total HTTP requests',
      labelNames: ['method', 'route', 'status_code'],
      registers: [this.registry],
    });

    this.httpRequestDuration = new Histogram({
      name: `${prefix}_http_request_duration_seconds`,
      help: 'HTTP request duration',
      labelNames: ['method', 'route'],
      buckets: [0.001, 0.005, 0.01, 0.025, 0.05, 0.1, 0.25, 0.5, 1, 2.5, 5, 10],
      registers: [this.registry],
    });

    this.httpActiveRequests = new Gauge({
      name: `${prefix}_http_active_requests`,
      help: 'Number of active HTTP requests',
      labelNames: ['method', 'route'],
      registers: [this.registry],
    });

    // Initialize event bus metrics
    this.eventsPublished = new Counter({
      name: `${prefix}_events_published_total`,
      help: 'Total events published',
      labelNames: ['topic', 'event_type'],
      registers: [this.registry],
    });

    this.eventsConsumed = new Counter({
      name: `${prefix}_events_consumed_total`,
      help: 'Total events consumed',
      labelNames: ['topic', 'consumer_group'],
      registers: [this.registry],
    });

    this.eventProcessingDuration = new Histogram({
      name: `${prefix}_event_processing_duration_seconds`,
      help: 'Event processing duration',
      labelNames: ['topic', 'event_type'],
      buckets: [0.001, 0.005, 0.01, 0.025, 0.05, 0.1, 0.25, 0.5, 1],
      registers: [this.registry],
    });

    this.eventLag = new Gauge({
      name: `${prefix}_event_lag_seconds`,
      help: 'Consumer lag in seconds',
      labelNames: ['topic', 'consumer_group', 'partition'],
      registers: [this.registry],
    });

    // Initialize database metrics
    this.dbQueryDuration = new Histogram({
      name: `${prefix}_db_query_duration_seconds`,
      help: 'Database query duration',
      labelNames: ['operation', 'table'],
      buckets: [0.001, 0.005, 0.01, 0.025, 0.05, 0.1, 0.25, 0.5, 1, 2.5],
      registers: [this.registry],
    });

    this.dbConnections = new Gauge({
      name: `${prefix}_db_connections`,
      help: 'Number of database connections',
      labelNames: ['state'],
      registers: [this.registry],
    });

    this.dbConnectionErrors = new Counter({
      name: `${prefix}_db_connection_errors_total`,
      help: 'Total database connection errors',
      labelNames: ['error_type'],
      registers: [this.registry],
    });
  }

  async getMetrics(): Promise<string> {
    return this.registry.metrics();
  }

  getContentType(): string {
    return this.registry.contentType;
  }

  // Helper methods for common metric updates
  recordTaskCreated(type: string, priority: string, region: string): void {
    this.tasksCreated.inc({ type, priority, region });
  }

  recordTaskScheduled(nodeId: string, algorithm: string): void {
    this.tasksScheduled.inc({ node_id: nodeId, algorithm });
  }

  recordTaskCompleted(nodeId: string, status: string, durationSeconds: number, type: string): void {
    this.tasksCompleted.inc({ node_id: nodeId, status });
    this.taskDuration.observe({ type, node_id: nodeId }, durationSeconds);
  }

  recordTaskFailed(nodeId: string, errorType: string, retryCount: number): void {
    this.tasksFailed.inc({ node_id: nodeId, error_type: errorType, retry_count: retryCount.toString() });
  }

  recordNodeHeartbeat(nodeId: string, region: string, cpuUsage: number, memoryUsage: number): void {
    this.nodeHeartbeats.inc({ node_id: nodeId, region });
    this.nodeCpuUsage.set({ node_id: nodeId, region }, cpuUsage);
    this.nodeMemoryUsage.set({ node_id: nodeId, region }, memoryUsage);
  }

  recordSchedulingDecision(algorithm: string, result: string, durationSeconds: number): void {
    this.schedulingDecisions.inc({ algorithm, result });
    this.schedulingDuration.observe({ algorithm }, durationSeconds);
  }

  recordHttpRequest(method: string, route: string, statusCode: number, durationSeconds: number): void {
    this.httpRequestsTotal.inc({ method, route, status_code: statusCode.toString() });
    this.httpRequestDuration.observe({ method, route }, durationSeconds);
  }

  recordEventPublished(topic: string, eventType: string): void {
    this.eventsPublished.inc({ topic, event_type: eventType });
  }

  recordEventConsumed(topic: string, consumerGroup: string, durationSeconds: number): void {
    this.eventsConsumed.inc({ topic, consumer_group: consumerGroup });
    this.eventProcessingDuration.observe({ topic, event_type: 'unknown' }, durationSeconds);
  }

  recordDbQuery(operation: string, table: string, durationSeconds: number): void {
    this.dbQueryDuration.observe({ operation, table }, durationSeconds);
  }

  updateActiveNodes(count: number, region: string, status: string): void {
    this.activeNodes.set({ region, status }, count);
  }

  setSchedulerLeader(nodeId: string, isLeader: boolean): void {
    this.schedulerLeader.set({ node_id: nodeId }, isLeader ? 1 : 0);
  }

  updateRaftCommitIndex(nodeId: string, index: number): void {
    this.raftCommitIndex.set({ node_id: nodeId }, index);
  }
}

import { Context, context as apiContext,Span, SpanStatusCode, trace, Tracer } from '@opentelemetry/api';
import { JaegerExporter } from '@opentelemetry/exporter-jaeger';
import { OTLPTraceExporter } from '@opentelemetry/exporter-trace-otlp-grpc';
import { ZipkinExporter } from '@opentelemetry/exporter-zipkin';
import { ExpressInstrumentation } from '@opentelemetry/instrumentation-express';
import { HttpInstrumentation } from '@opentelemetry/instrumentation-http';
import { KafkaJsInstrumentation } from '@opentelemetry/instrumentation-kafkajs';
import { PgInstrumentation } from '@opentelemetry/instrumentation-pg';
import { Resource } from '@opentelemetry/resources';
import { NodeSDK } from '@opentelemetry/sdk-node';
import { BatchSpanProcessor, SimpleSpanProcessor } from '@opentelemetry/sdk-trace-base';
import { NodeTracerProvider } from '@opentelemetry/sdk-trace-node';
import { SemanticResourceAttributes } from '@opentelemetry/semantic-conventions';

export interface TracingConfig {
  serviceName: string;
  serviceVersion: string;
  environment: string;
  exporter?: 'jaeger' | 'zipkin' | 'otlp';
  jaegerEndpoint?: string;
  zipkinEndpoint?: string;
  otlpEndpoint?: string;
  samplingRate?: number;
}

export class TracingManager {
  private sdk: NodeSDK | null = null;
  private provider: NodeTracerProvider | null = null;
  private config: TracingConfig;
  private tracer: Tracer;

  constructor(config: TracingConfig) {
    this.config = {
      exporter: 'jaeger',
      jaegerEndpoint: 'http://jaeger:14268/api/traces',
      zipkinEndpoint: 'http://zipkin:9411/api/v2/spans',
      otlpEndpoint: 'http://otel-collector:4317',
      samplingRate: 1.0,
      ...config,
    };

    this.tracer = trace.getTracer(config.serviceName, config.serviceVersion);
  }

  async initialize(): Promise<void> {
    const resource = new Resource({
      [SemanticResourceAttributes.SERVICE_NAME]: this.config.serviceName,
      [SemanticResourceAttributes.SERVICE_VERSION]: this.config.serviceVersion,
      [SemanticResourceAttributes.DEPLOYMENT_ENVIRONMENT]: this.config.environment,
    });

    // Configure exporter
    let exporter;
    switch (this.config.exporter) {
      case 'zipkin':
        exporter = new ZipkinExporter({
          url: this.config.zipkinEndpoint,
        });
        break;
      case 'otlp':
        exporter = new OTLPTraceExporter({
          url: this.config.otlpEndpoint,
        });
        break;
      case 'jaeger':
      default:
        exporter = new JaegerExporter({
          endpoint: this.config.jaegerEndpoint,
        });
    }

    // Create span processor
    const spanProcessor = new BatchSpanProcessor(exporter);

    // Initialize SDK with auto-instrumentations
    this.sdk = new NodeSDK({
      resource,
      spanProcessor,
      instrumentations: [
        new HttpInstrumentation({
          requestHook: (span, request) => {
            span.setAttribute('http.request.body.size', request.headers['content-length'] || 0);
          },
          responseHook: (span, response) => {
            span.setAttribute('http.response.body.size', response.headers['content-length'] || 0);
          },
        }),
        new ExpressInstrumentation(),
        new PgInstrumentation({
          enhancedDatabaseReporting: true,
        }),
        new KafkaJsInstrumentation(),
      ],
    });

    await this.sdk.start();
    console.log(`Tracing initialized for ${this.config.serviceName}`);
  }

  async shutdown(): Promise<void> {
    if (this.sdk) {
      await this.sdk.shutdown();
    }
  }

  getTracer(): Tracer {
    return this.tracer;
  }

  // Helper method to create a span
  createSpan(
    name: string,
    options?: {
      parent?: Context;
      attributes?: Record<string, any>;
    }
  ): Span {
    const ctx = options?.parent || apiContext.active();
    return this.tracer.startSpan(name, {
      attributes: options?.attributes,
    }, ctx);
  }

  // Helper method to wrap a function in a span
  async withSpan<T>(
    name: string,
    fn: (span: Span) => Promise<T>,
    options?: {
      parent?: Context;
      attributes?: Record<string, any>;
    }
  ): Promise<T> {
    const span = this.createSpan(name, options);
    const ctx = trace.setSpan(apiContext.active(), span);

    try {
      const result = await apiContext.with(ctx, () => fn(span));
      span.setStatus({ code: SpanStatusCode.OK });
      return result;
    } catch (error) {
      span.setStatus({
        code: SpanStatusCode.ERROR,
        message: error instanceof Error ? error.message : 'Unknown error',
      });
      span.recordException(error as Error);
      throw error;
    } finally {
      span.end();
    }
  }

  // Helper for database operations
  async traceDbOperation<T>(
    operation: string,
    table: string,
    fn: () => Promise<T>
  ): Promise<T> {
    return this.withSpan(
      `db.${operation}`,
      async (span) => {
        span.setAttributes({
          'db.operation': operation,
          'db.table': table,
          'db.system': 'cockroachdb',
        });
        return fn();
      }
    );
  }

  // Helper for task operations
  async traceTaskOperation<T>(
    operation: string,
    taskId: string,
    fn: () => Promise<T>
  ): Promise<T> {
    return this.withSpan(
      `task.${operation}`,
      async (span) => {
        span.setAttributes({
          'task.id': taskId,
          'task.operation': operation,
        });
        return fn();
      }
    );
  }

  // Helper for scheduling operations
  async traceScheduling<T>(
    algorithm: string,
    fn: () => Promise<T>
  ): Promise<T> {
    return this.withSpan(
      'scheduler.decision',
      async (span) => {
        span.setAttributes({
          'scheduler.algorithm': algorithm,
        });
        const startTime = Date.now();
        const result = await fn();
        span.setAttribute('scheduler.duration_ms', Date.now() - startTime);
        return result;
      }
    );
  }

  // Helper for event processing
  async traceEventProcessing<T>(
    topic: string,
    eventType: string,
    fn: () => Promise<T>
  ): Promise<T> {
    return this.withSpan(
      'event.process',
      async (span) => {
        span.setAttributes({
          'messaging.system': 'kafka',
          'messaging.destination': topic,
          'messaging.destination_kind': 'topic',
          'event.type': eventType,
        });
        return fn();
      }
    );
  }

  // Helper for HTTP client calls
  async traceHttpClient<T>(
    method: string,
    url: string,
    fn: () => Promise<T>
  ): Promise<T> {
    return this.withSpan(
      `http.client.${method}`,
      async (span) => {
        span.setAttributes({
          'http.method': method,
          'http.url': url,
        });
        return fn();
      }
    );
  }
}

// Singleton instance for the application
let tracingManager: TracingManager | null = null;

export function initializeTracing(config: TracingConfig): TracingManager {
  if (!tracingManager) {
    tracingManager = new TracingManager(config);
  }
  return tracingManager;
}

export function getTracingManager(): TracingManager | null {
  return tracingManager;
}

export {
  DEFAULT_OUTBOX_CONFIG,
  type OutboxConfig,
  type OutboxEvent,
  type OutboxEventInput,
  OutboxManager,
} from './outbox-manager';

import { EventEmitter } from 'eventemitter3';
import { Message,Producer } from 'kafkajs';

// Define types locally to avoid direct Prisma dependency
export type OutboxStatus = 'PENDING' | 'PROCESSING' | 'PUBLISHED' | 'FAILED';

export interface OutboxConfig {
  pollingIntervalMs: number;
  batchSize: number;
  maxAttempts: number;
  retryBaseDelayMs: number;
  retryMaxDelayMs: number;
  enabled: boolean;
}

export interface OutboxEventInput {
  aggregateId: string;
  eventType: string;
  payload: Record<string, unknown>;
  headers?: Record<string, string>;
}

export interface OutboxEvent {
  id: string;
  aggregateId: string;
  eventType: string;
  payload: Record<string, unknown>;
  headers?: Record<string, string> | null;
  status: OutboxStatus;
  attempts: number;
  maxAttempts: number;
  nextRetryAt: Date | null;
  processedAt: Date | null;
  createdAt: Date;
  updatedAt: Date;
}

// PrismaClient type with outboxEvent methods
interface PrismaClientLike {
  outboxEvent: {
    create: (args: any) => Promise<any>;
    createMany: (args: any) => Promise<any>;
    findMany: (args: any) => Promise<any[]>;
    findFirst: (args: any) => Promise<any | null>;
    count: (args: any) => Promise<number>;
    update: (args: any) => Promise<any>;
    updateMany: (args: any) => Promise<any>;
  };
}

export const DEFAULT_OUTBOX_CONFIG: OutboxConfig = {
  pollingIntervalMs: 1000,
  batchSize: 100,
  maxAttempts: 5,
  retryBaseDelayMs: 1000,
  retryMaxDelayMs: 60000,
  enabled: true,
};

export class OutboxManager extends EventEmitter {
  private prisma: PrismaClientLike;
  private producer: Producer;
  private config: OutboxConfig;
  private pollingInterval: ReturnType<typeof setInterval> | null = null;
  private isProcessing: boolean = false;
  private topicMapping: Map<string, string> = new Map();

  constructor(
    prisma: PrismaClientLike,
    producer: Producer,
    config: Partial<OutboxConfig> = {}
  ) {
    super();
    this.prisma = prisma;
    this.producer = producer;
    this.config = { ...DEFAULT_OUTBOX_CONFIG, ...config };
  }

  /**
   * Register a mapping from event type to Kafka topic
   */
  registerTopicMapping(eventType: string, topic: string): void {
    this.topicMapping.set(eventType, topic);
  }

  /**
   * Store an event in the outbox within an existing transaction
   * This should be called inside a Prisma transaction callback
   */
  async storeEvent(
    tx: PrismaClientLike,
    event: OutboxEventInput
  ): Promise<OutboxEvent> {
    return tx.outboxEvent.create({
      data: {
        aggregateId: event.aggregateId,
        eventType: event.eventType,
        payload: event.payload,
        headers: event.headers || null,
        status: 'PENDING',
        attempts: 0,
        maxAttempts: this.config.maxAttempts,
      },
    }) as Promise<OutboxEvent>;
  }

  /**
   * Store multiple events atomically
   */
  async storeEvents(
    tx: PrismaClientLike,
    events: OutboxEventInput[]
  ): Promise<OutboxEvent[]> {
    return tx.outboxEvent.createMany({
      data: events.map((e) => ({
        aggregateId: e.aggregateId,
        eventType: e.eventType,
        payload: e.payload,
        headers: e.headers || null,
        status: 'PENDING' as OutboxStatus,
        attempts: 0,
        maxAttempts: this.config.maxAttempts,
      })),
    }).then(() => 
      tx.outboxEvent.findMany({
        where: {
          aggregateId: { in: events.map((e) => e.aggregateId) },
          status: 'PENDING',
        },
        orderBy: { createdAt: 'desc' },
        take: events.length,
      })
    ) as Promise<OutboxEvent[]>;
  }

  /**
   * Start the background publisher
   */
  start(): void {
    if (!this.config.enabled) {
      return;
    }

    this.pollingInterval = setInterval(() => {
      this.processPendingEvents();
    }, this.config.pollingIntervalMs);

    this.emit('started');
  }

  /**
   * Stop the background publisher
   */
  async stop(): Promise<void> {
    if (this.pollingInterval) {
      clearInterval(this.pollingInterval);
      this.pollingInterval = null;
    }

    // Wait for current processing to complete
    while (this.isProcessing) {
      await new Promise((resolve) => setTimeout(resolve, 100));
    }

    this.emit('stopped');
  }

  /**
   * Process pending events in batches
   */
  private async processPendingEvents(): Promise<void> {
    if (this.isProcessing) {
      return;
    }

    this.isProcessing = true;

    try {
      const events = await this.fetchPendingEvents();

      if (events.length === 0) {
        return;
      }

      this.emit('processing', { count: events.length });

      for (const event of events) {
        await this.processEvent(event);
      }
    } catch (error) {
      this.emit('error', { error, phase: 'processPendingEvents' });
    } finally {
      this.isProcessing = false;
    }
  }

  /**
   * Fetch pending events that are ready for processing
   */
  private async fetchPendingEvents(): Promise<OutboxEvent[]> {
    return this.prisma.outboxEvent.findMany({
      where: {
        status: 'PENDING',
        OR: [
          { nextRetryAt: null },
          { nextRetryAt: { lte: new Date() } },
        ],
      },
      orderBy: { createdAt: 'asc' },
      take: this.config.batchSize,
    }) as Promise<OutboxEvent[]>;
  }

  /**
   * Process a single event
   */
  private async processEvent(event: OutboxEvent): Promise<void> {
    // Mark as processing
    await this.prisma.outboxEvent.update({
      where: { id: event.id },
      data: { status: 'PROCESSING' as OutboxStatus },
    });

    try {
      const topic = this.topicMapping.get(event.eventType) || this.inferTopic(event.eventType);

      const message: Message = {
        key: event.aggregateId,
        value: JSON.stringify(event.payload),
        headers: {
          'event-type': event.eventType,
          'event-id': event.id,
          'aggregate-id': event.aggregateId,
          'idempotency-key': event.id, // Prevent duplicate processing
          'timestamp': new Date().toISOString(),
          ...(event.headers as Record<string, string> || {}),
        },
      };

      await this.producer.send({
        topic,
        messages: [message],
      });

      // Mark as published
      await this.prisma.outboxEvent.update({
        where: { id: event.id },
        data: {
          status: 'PUBLISHED' as OutboxStatus,
          processedAt: new Date(),
        },
      });

      this.emit('published', { eventId: event.id, eventType: event.eventType });
    } catch (error) {
      await this.handlePublishError(event, error as Error);
    }
  }

  /**
   * Handle publishing errors with retry logic
   */
  private async handlePublishError(event: OutboxEvent, error: Error): Promise<void> {
    const attempts = event.attempts + 1;
    const shouldRetry = attempts < event.maxAttempts;

    if (shouldRetry) {
      const nextRetryDelay = this.calculateBackoff(attempts);
      const nextRetryAt = new Date(Date.now() + nextRetryDelay);

      await this.prisma.outboxEvent.update({
        where: { id: event.id },
        data: {
          status: 'PENDING' as OutboxStatus,
          attempts,
          nextRetryAt,
        },
      });

      this.emit('retry', {
        eventId: event.id,
        attempt: attempts,
        nextRetryAt,
        error,
      });
    } else {
      await this.prisma.outboxEvent.update({
        where: { id: event.id },
        data: {
          status: 'FAILED' as OutboxStatus,
          attempts,
        },
      });

      this.emit('failed', {
        eventId: event.id,
        eventType: event.eventType,
        attempts,
        error,
      });
    }
  }

  /**
   * Calculate exponential backoff with jitter
   */
  private calculateBackoff(attempt: number): number {
    const baseDelay = this.config.retryBaseDelayMs;
    const maxDelay = this.config.retryMaxDelayMs;
    const exponentialDelay = Math.min(baseDelay * Math.pow(2, attempt), maxDelay);
    const jitter = Math.random() * 0.1 * exponentialDelay;
    return Math.floor(exponentialDelay + jitter);
  }

  /**
   * Infer Kafka topic from event type
   */
  private inferTopic(eventType: string): string {
    // Convert event type like "TaskCreated" to "tasks.events"
    const entity = eventType.replace(/^(Created|Updated|Deleted|Failed|Completed)/, '').toLowerCase();
    return `${entity}.events`;
  }

  /**
   * Get statistics about the outbox
   */
  async getStats(): Promise<{
    pending: number;
    processing: number;
    published: number;
    failed: number;
    oldestPending?: Date;
  }> {
    const [pending, processing, published, failed, oldestPending] = await Promise.all([
      this.prisma.outboxEvent.count({ where: { status: 'PENDING' } }),
      this.prisma.outboxEvent.count({ where: { status: 'PROCESSING' } }),
      this.prisma.outboxEvent.count({ where: { status: 'PUBLISHED' } }),
      this.prisma.outboxEvent.count({ where: { status: 'FAILED' } }),
      this.prisma.outboxEvent.findFirst({
        where: { status: 'PENDING' },
        orderBy: { createdAt: 'asc' },
        select: { createdAt: true },
      }),
    ]);

    return {
      pending,
      processing,
      published,
      failed,
      oldestPending: oldestPending?.createdAt,
    };
  }

  /**
   * Manually retry failed events
   */
  async retryFailed(eventIds?: string[]): Promise<number> {
    const where = eventIds
      ? { id: { in: eventIds }, status: 'FAILED' as OutboxStatus }
      : { status: 'FAILED' as OutboxStatus };

    const result = await this.prisma.outboxEvent.updateMany({
      where,
      data: {
        status: 'PENDING' as OutboxStatus,
        attempts: 0,
        nextRetryAt: null,
      },
    });

    this.emit('retry_requested', { count: result.count });
    return result.count;
  }
}

export {
  type CacheConfig,
  CachedQueryExecutor,
  DistributedCache,
  DistributedRateLimiter,
  MultiLayerCache,
  PooledDatabase,
  type PooledDatabaseConfig
} from './optimizations';

import { EventEmitter } from 'eventemitter3';
import Redis from 'ioredis';
import { Pool, PoolClient } from 'pg';

// Phase 14: Performance Optimization - Caching & Connection Pooling

export interface CacheConfig {
  host: string;
  port: number;
  password?: string;
  db?: number;
  maxRetries?: number;
  retryDelay?: number;
}

export class DistributedCache extends EventEmitter {
  private redis: Redis;
  private defaultTTL: number = 300; // 5 minutes

  constructor(config: CacheConfig) {
    super();
    this.redis = new Redis({
      host: config.host,
      port: config.port,
      password: config.password,
      db: config.db || 0,
      maxRetriesPerRequest: config.maxRetries || 3,
      retryStrategy: (times) => {
        const delay = Math.min(times * (config.retryDelay || 50), 2000);
        return delay;
      },
    });

    this.redis.on('connect', () => this.emit('connected'));
    this.redis.on('error', (err) => this.emit('error', err));
  }

  async get<T>(key: string): Promise<T | null> {
    const value = await this.redis.get(key);
    return value ? JSON.parse(value) : null;
  }

  async set(key: string, value: any, ttlSeconds?: number): Promise<void> {
    const serialized = JSON.stringify(value);
    await this.redis.setex(key, ttlSeconds || this.defaultTTL, serialized);
  }

  async getOrSet<T>(
    key: string,
    factory: () => Promise<T>,
    ttlSeconds?: number
  ): Promise<T> {
    const cached = await this.get<T>(key);
    if (cached !== null) {
      return cached;
    }

    const value = await factory();
    await this.set(key, value, ttlSeconds);
    return value;
  }

  async delete(key: string): Promise<void> {
    await this.redis.del(key);
  }

  async deletePattern(pattern: string): Promise<void> {
    const keys = await this.redis.keys(pattern);
    if (keys.length > 0) {
      await this.redis.del(...keys);
    }
  }

  async increment(key: string, amount: number = 1): Promise<number> {
    return this.redis.incrby(key, amount);
  }

  async expire(key: string, seconds: number): Promise<void> {
    await this.redis.expire(key, seconds);
  }

  // Cache-aside pattern with stampede protection
  async getWithLock<T>(
    key: string,
    factory: () => Promise<T>,
    ttlSeconds: number = 300,
    lockTimeout: number = 10
  ): Promise<T> {
    const lockKey = `lock:${key}`;
    const lockValue = `${Date.now()}-${Math.random()}`;

    // Try to get from cache
    const cached = await this.get<T>(key);
    if (cached !== null) {
      return cached;
    }

    // Try to acquire lock
    const acquired = await this.redis.set(lockKey, lockValue, 'EX', lockTimeout, 'NX');
    
    if (acquired) {
      try {
        // We have the lock, fetch and cache
        const value = await factory();
        await this.set(key, value, ttlSeconds);
        return value;
      } finally {
        // Release lock
        await this.redis.del(lockKey);
      }
    } else {
      // Someone else is fetching, wait and retry
      await new Promise((resolve) => setTimeout(resolve, 100));
      return this.getWithLock(key, factory, ttlSeconds, lockTimeout);
    }
  }

  async close(): Promise<void> {
    await this.redis.quit();
  }
}

// Multi-layer caching: L1 (in-memory) + L2 (Redis)
export class MultiLayerCache extends EventEmitter {
  private l1Cache: Map<string, { value: any; expires: number }> = new Map();
  private l2Cache: DistributedCache;
  private l1TTL: number = 60000; // 1 minute in-memory

  constructor(redisConfig: CacheConfig) {
    super();
    this.l2Cache = new DistributedCache(redisConfig);
    
    // Periodic cleanup of expired L1 entries
    setInterval(() => this.cleanupL1(), 60000);
  }

  async get<T>(key: string): Promise<T | null> {
    // Check L1 first
    const l1Entry = this.l1Cache.get(key);
    if (l1Entry && l1Entry.expires > Date.now()) {
      return l1Entry.value;
    }

    // Check L2
    const l2Value = await this.l2Cache.get<T>(key);
    if (l2Value !== null) {
      // Populate L1
      this.l1Cache.set(key, { value: l2Value, expires: Date.now() + this.l1TTL });
      return l2Value;
    }

    return null;
  }

  async set(key: string, value: any, l2TTL: number = 300): Promise<void> {
    // Set in both layers
    this.l1Cache.set(key, { value, expires: Date.now() + this.l1TTL });
    await this.l2Cache.set(key, value, l2TTL);
  }

  async delete(key: string): Promise<void> {
    this.l1Cache.delete(key);
    await this.l2Cache.delete(key);
  }

  async deletePattern(pattern: string): Promise<void> {
    // Delete from L1 cache - iterate and match pattern
    const regex = new RegExp(pattern.replace(/\*/g, '.*'));
    for (const key of this.l1Cache.keys()) {
      if (regex.test(key)) {
        this.l1Cache.delete(key);
      }
    }
    // Delete from L2 cache
    await this.l2Cache.deletePattern(pattern);
  }

  private cleanupL1(): void {
    const now = Date.now();
    for (const [key, entry] of this.l1Cache.entries()) {
      if (entry.expires <= now) {
        this.l1Cache.delete(key);
      }
    }
  }

  async close(): Promise<void> {
    await this.l2Cache.close();
  }
}

// Optimized database connection pooling
export interface PooledDatabaseConfig {
  host: string;
  port: number;
  database: string;
  user: string;
  password: string;
  ssl?: any;
  poolSize?: number;
  statementTimeout?: number;
  queryTimeout?: number;
}

export class PooledDatabase extends EventEmitter {
  private pool: Pool;
  private queryMetrics: Map<string, { count: number; totalTime: number }> = new Map();

  constructor(config: PooledDatabaseConfig) {
    super();
    
    this.pool = new Pool({
      host: config.host,
      port: config.port,
      database: config.database,
      user: config.user,
      password: config.password,
      ssl: config.ssl,
      max: config.poolSize || 20,
      min: 5,
      connectionTimeoutMillis: 5000,
      idleTimeoutMillis: 30000,
      statement_timeout: (config.statementTimeout || 30) * 1000,
      query_timeout: (config.queryTimeout || 30) * 1000,
    });

    this.pool.on('connect', () => this.emit('connect'));
    this.pool.on('error', (err) => this.emit('error', err));
    this.pool.on('acquire', () => this.emit('acquire'));
    this.pool.on('remove', () => this.emit('remove'));
  }

  async query<T = any>(sql: string, params?: any[]): Promise<T[]> {
    const startTime = Date.now();
    const client = await this.pool.connect();
    
    try {
      const result = await client.query(sql, params);
      
      // Track metrics
      const duration = Date.now() - startTime;
      this.trackQuery(sql, duration);
      
      return result.rows;
    } finally {
      client.release();
    }
  }

  async transaction<T>(fn: (client: PoolClient) => Promise<T>): Promise<T> {
    const client = await this.pool.connect();
    
    try {
      await client.query('BEGIN');
      const result = await fn(client);
      await client.query('COMMIT');
      return result;
    } catch (error) {
      await client.query('ROLLBACK');
      throw error;
    } finally {
      client.release();
    }
  }

  async withClient<T>(fn: (client: PoolClient) => Promise<T>): Promise<T> {
    const client = await this.pool.connect();
    try {
      return await fn(client);
    } finally {
      client.release();
    }
  }

  private trackQuery(sql: string, duration: number): void {
    // Extract operation type (simplified)
    const operation = sql.trim().split(' ')[0].toUpperCase();
    
    const metrics = this.queryMetrics.get(operation) || { count: 0, totalTime: 0 };
    metrics.count++;
    metrics.totalTime += duration;
    this.queryMetrics.set(operation, metrics);
  }

  getMetrics() {
    const metrics: Record<string, { count: number; avgTime: number }> = {};
    for (const [op, data] of this.queryMetrics) {
      metrics[op] = {
        count: data.count,
        avgTime: data.totalTime / data.count,
      };
    }
    return {
      totalConnections: this.pool.totalCount,
      idleConnections: this.pool.idleCount,
      waitingClients: this.pool.waitingCount,
      queryMetrics: metrics,
    };
  }

  async close(): Promise<void> {
    await this.pool.end();
  }
}

// Query result caching wrapper
export class CachedQueryExecutor extends EventEmitter {
  private db: PooledDatabase;
  private cache: MultiLayerCache;

  constructor(db: PooledDatabase, cache: MultiLayerCache) {
    super();
    this.db = db;
    this.cache = cache;
  }

  async query<T>(
    sql: string,
    params?: any[],
    options?: {
      cacheKey?: string;
      cacheTTL?: number;
      skipCache?: boolean;
    }
  ): Promise<T[]> {
    const cacheKey = options?.cacheKey || `query:${this.hashQuery(sql, params)}`;

    if (!options?.skipCache) {
      const cached = await this.cache.get<T[]>(cacheKey);
      if (cached !== null) {
        this.emit('cacheHit', { cacheKey, sql });
        return cached;
      }
    }

    const result = await this.db.query<T>(sql, params);

    if (!options?.skipCache) {
      await this.cache.set(cacheKey, result, options?.cacheTTL);
      this.emit('cacheMiss', { cacheKey, sql });
    }

    return result;
  }

  async invalidateQuery(pattern: string): Promise<void> {
    await this.cache.deletePattern(`query:*${pattern}*`);
  }

  private hashQuery(sql: string, params?: any[]): string {
    // Simple hash for demo - use proper hashing in production
    const str = `${sql}:${JSON.stringify(params)}`;
    let hash = 0;
    for (let i = 0; i < str.length; i++) {
      const char = str.charCodeAt(i);
      hash = ((hash << 5) - hash) + char;
      hash = hash & hash;
    }
    return hash.toString(16);
  }
}

// Rate limiter with Redis backend
export class DistributedRateLimiter extends EventEmitter {
  private redis: Redis;

  constructor(redisConfig: CacheConfig) {
    super();
    this.redis = new Redis({
      host: redisConfig.host,
      port: redisConfig.port,
      password: redisConfig.password,
    });
  }

  async isAllowed(key: string, limit: number, windowSeconds: number): Promise<boolean> {
    const windowKey = `ratelimit:${key}:${Math.floor(Date.now() / 1000 / windowSeconds)}`;
    
    const current = await this.redis.incr(windowKey);
    if (current === 1) {
      await this.redis.expire(windowKey, windowSeconds);
    }
    
    return current <= limit;
  }

  async getRemaining(key: string, limit: number, windowSeconds: number): Promise<number> {
    const windowKey = `ratelimit:${key}:${Math.floor(Date.now() / 1000 / windowSeconds)}`;
    const current = await this.redis.get(windowKey);
    return limit - (parseInt(current || '0', 10));
  }

  async close(): Promise<void> {
    await this.redis.quit();
  }
}

export { RaftNode, StateMachine } from './raft-node';
export {
  AppendEntriesRequest,
  AppendEntriesResponse,
  LogEntry,
  PeerConfig,
  RaftMetrics,
  RaftNodeConfig,
  RaftState,
  VoteRequest,
  VoteResponse,
} from './types';

import { generateId } from '@edgecloud/shared-kernel';
import { EventEmitter } from 'eventemitter3';

import {
  AppendEntriesRequest,
  AppendEntriesResponse,
  LogEntry,
  PeerConfig,
  RaftMetrics,
  RaftNodeConfig,
  RaftState,
  VoteRequest,
  VoteResponse,
} from './types';

export interface StateMachine {
  apply(command: unknown): void;
  snapshot(): Buffer;
  restore(snapshot: Buffer): void;
}

export class RaftNode extends EventEmitter {
  // Node identity
  public readonly id: string;
  private config: RaftNodeConfig;
  
  // Persistent state
  private currentTerm: number = 0;
  private votedFor: string | null = null;
  private log: LogEntry[] = [];
  
  // Volatile state
  private state: RaftState = 'FOLLOWER';
  private commitIndex: number = 0;
  private lastApplied: number = 0;
  
  // Leader state (reinitialized after election)
  private nextIndex: Map<string, number> = new Map();
  private matchIndex: Map<string, number> = new Map();
  
  // Timing
  private electionTimer: NodeJS.Timeout | null = null;
  private heartbeatTimer: NodeJS.Timeout | null = null;
  private lastHeartbeat: number = Date.now();
  
  // RPC clients
  private peers: Map<string, PeerClient> = new Map();
  
  // State machine
  private stateMachine: StateMachine;
  
  // Metrics
  private electionCount: number = 0;
  private heartbeatCount: number = 0;
  
  constructor(config: RaftNodeConfig, stateMachine: StateMachine) {
    super();
    this.id = config.id;
    this.config = config;
    this.stateMachine = stateMachine;
    
    // Initialize log with dummy entry at index 0
    this.log.push({
      term: 0,
      index: 0,
      command: null,
      timestamp: Date.now(),
    });
    
    // Initialize peer connections
    for (const peer of config.peers) {
      this.peers.set(peer.id, new PeerClient(peer));
    }
    
    this.resetElectionTimer();
  }
  
  // Public API
  
  public isLeader(): boolean {
    return this.state === 'LEADER';
  }
  
  public getState(): RaftState {
    return this.state;
  }
  
  public getCurrentTerm(): number {
    return this.currentTerm;
  }
  
  public getLeaderId(): string | undefined {
    return this.isLeader() ? this.id : undefined;
  }
  
  public getMetrics(): RaftMetrics {
    return {
      state: this.state,
      currentTerm: this.currentTerm,
      commitIndex: this.commitIndex,
      lastApplied: this.lastApplied,
      logSize: this.log.length,
      leaderId: this.getLeaderId(),
      votedFor: this.votedFor || undefined,
      electionCount: this.electionCount,
      heartbeatCount: this.heartbeatCount,
    };
  }
  
  public async replicateCommand(command: unknown): Promise<boolean> {
    if (!this.isLeader()) {
      throw new Error('Only leader can replicate commands');
    }
    
    // Append to local log
    const entry: LogEntry = {
      term: this.currentTerm,
      index: this.log.length,
      command,
      timestamp: Date.now(),
    };
    
    this.log.push(entry);
    this.persistState();
    
    // Replicate to followers
    await this.replicateLog();
    
    // Wait for commit
    return this.waitForCommit(entry.index);
  }
  
  public shutdown(): void {
    this.clearTimers();
    for (const peer of this.peers.values()) {
      peer.close();
    }
  }
  
  // RPC Handlers
  
  public async handleVoteRequest(request: VoteRequest): Promise<VoteResponse> {
    // Reply false if term < currentTerm
    if (request.term < this.currentTerm) {
      return {
        term: this.currentTerm,
        voteGranted: false,
        voterId: this.id,
      };
    }
    
    // If term > currentTerm, update term and convert to follower
    if (request.term > this.currentTerm) {
      this.currentTerm = request.term;
      this.votedFor = null;
      this.convertToFollower();
    }
    
    // Check if we can vote for this candidate
    const canVote = 
      (this.votedFor === null || this.votedFor === request.candidateId) &&
      this.isLogUpToDate(request.lastLogIndex, request.lastLogTerm);
    
    if (canVote) {
      this.votedFor = request.candidateId;
      this.persistState();
      this.resetElectionTimer();
    }
    
    return {
      term: this.currentTerm,
      voteGranted: canVote,
      voterId: this.id,
    };
  }
  
  public async handleAppendEntries(
    request: AppendEntriesRequest
  ): Promise<AppendEntriesResponse> {
    this.lastHeartbeat = Date.now();
    
    // Reply false if term < currentTerm
    if (request.term < this.currentTerm) {
      return {
        term: this.currentTerm,
        success: false,
        followerId: this.id,
        matchIndex: 0,
      };
    }
    
    // If term >= currentTerm, update term and convert to follower
    if (request.term > this.currentTerm || this.state !== 'FOLLOWER') {
      this.currentTerm = request.term;
      this.votedFor = null;
      this.convertToFollower();
    }
    
    this.resetElectionTimer();
    
    // Check log consistency
    if (request.prevLogIndex > 0) {
      const prevLogEntry = this.log[request.prevLogIndex];
      if (!prevLogEntry || prevLogEntry.term !== request.prevLogTerm) {
        // Find conflict index
        let conflictIndex = request.prevLogIndex;
        let conflictTerm = 0;
        
        if (prevLogEntry) {
          conflictTerm = prevLogEntry.term;
          while (
            conflictIndex > 0 &&
            this.log[conflictIndex]?.term === conflictTerm
          ) {
            conflictIndex--;
          }
        }
        
        return {
          term: this.currentTerm,
          success: false,
          followerId: this.id,
          matchIndex: 0,
          conflictIndex: conflictIndex + 1,
          conflictTerm,
        };
      }
    }
    
    // Append new entries
    for (let i = 0; i < request.entries.length; i++) {
      const entry = request.entries[i];
      const index = request.prevLogIndex + 1 + i;
      
      if (index < this.log.length) {
        // Existing entry conflicts with new entry
        if (this.log[index].term !== entry.term) {
          // Delete existing entry and all that follow it
          this.log = this.log.slice(0, index);
          this.log.push(entry);
        }
        // Otherwise, entry already exists and matches
      } else {
        this.log.push(entry);
      }
    }
    
    // Update commit index
    if (request.leaderCommit > this.commitIndex) {
      this.commitIndex = Math.min(
        request.leaderCommit,
        this.log.length - 1
      );
      this.applyCommittedEntries();
    }
    
    this.persistState();
    
    return {
      term: this.currentTerm,
      success: true,
      followerId: this.id,
      matchIndex: request.prevLogIndex + request.entries.length,
    };
  }
  
  // Private methods
  
  private convertToFollower(): void {
    this.state = 'FOLLOWER';
    this.clearTimers();
    this.resetElectionTimer();
    this.emit('stateChanged', this.state);
  }
  
  private convertToCandidate(): void {
    this.state = 'CANDIDATE';
    this.currentTerm++;
    this.votedFor = this.id;
    this.persistState();
    
    this.electionCount++;
    this.emit('stateChanged', this.state);
    this.emit('electionStarted', this.currentTerm);
    
    // Request votes from all peers
    this.requestVotes();
  }
  
  private convertToLeader(): void {
    this.state = 'LEADER';
    this.clearTimers();
    
    // Initialize leader state
    const lastLogIndex = this.log.length - 1;
    for (const peerId of this.peers.keys()) {
      this.nextIndex.set(peerId, lastLogIndex + 1);
      this.matchIndex.set(peerId, 0);
    }
    
    this.emit('stateChanged', this.state);
    this.emit('becameLeader');
    
    // Start sending heartbeats
    this.sendHeartbeats();
    this.heartbeatTimer = setInterval(
      () => this.sendHeartbeats(),
      this.config.heartbeatInterval
    );
  }
  
  private async requestVotes(): Promise<void> {
    const request: VoteRequest = {
      term: this.currentTerm,
      candidateId: this.id,
      lastLogIndex: this.log.length - 1,
      lastLogTerm: this.log[this.log.length - 1].term,
    };
    
    let votesReceived = 1; // Vote for self
    const majority = Math.floor((this.peers.size + 1) / 2) + 1;
    
    const votePromises = Array.from(this.peers.values()).map(async (peer) => {
      try {
        const response = await peer.requestVote(request);
        if (response.term > this.currentTerm) {
          this.currentTerm = response.term;
          this.votedFor = null;
          this.convertToFollower();
          return;
        }
        
        if (response.voteGranted) {
          votesReceived++;
          if (votesReceived >= majority && this.state === 'CANDIDATE') {
            this.convertToLeader();
          }
        }
      } catch (error) {
        // Peer unreachable, continue
      }
    });
    
    await Promise.all(votePromises);
    
    // If not enough votes and still candidate, restart election
    if (this.state === 'CANDIDATE' && votesReceived < majority) {
      this.resetElectionTimer();
    }
  }
  
  private async sendHeartbeats(): Promise<void> {
    if (!this.isLeader()) {return;}
    
    this.heartbeatCount++;
    
    const promises = Array.from(this.peers.entries()).map(
      async ([peerId, peer]) => {
        const nextIdx = this.nextIndex.get(peerId) || 1;
        const prevLogIndex = nextIdx - 1;
        const prevLogTerm = this.log[prevLogIndex]?.term || 0;
        
        // Get entries to send
        const entries = this.log.slice(
          nextIdx,
          nextIdx + this.config.maxLogEntriesPerRequest
        );
        
        const request: AppendEntriesRequest = {
          term: this.currentTerm,
          leaderId: this.id,
          prevLogIndex,
          prevLogTerm,
          entries,
          leaderCommit: this.commitIndex,
        };
        
        try {
          const response = await peer.appendEntries(request);
          
          if (response.term > this.currentTerm) {
            this.currentTerm = response.term;
            this.votedFor = null;
            this.convertToFollower();
            return;
          }
          
          if (response.success) {
            this.matchIndex.set(peerId, response.matchIndex);
            this.nextIndex.set(peerId, response.matchIndex + 1);
          } else {
            // Decrement nextIndex and retry
            if (response.conflictIndex) {
              this.nextIndex.set(peerId, response.conflictIndex);
            } else {
              this.nextIndex.set(
                peerId,
                Math.max(1, (this.nextIndex.get(peerId) || 1) - 1)
              );
            }
          }
          
          this.updateCommitIndex();
        } catch (error) {
          // Peer unreachable
        }
      }
    );
    
    await Promise.all(promises);
  }
  
  private async replicateLog(): Promise<void> {
    await this.sendHeartbeats();
  }
  
  private updateCommitIndex(): void {
    if (!this.isLeader()) {return;}
    
    // Find the highest index that is replicated on a majority
    const matchIndexes = [
      this.log.length - 1,
      ...Array.from(this.matchIndex.values()),
    ];
    matchIndexes.sort((a, b) => b - a);
    
    const majorityIndex = matchIndexes[Math.floor(matchIndexes.length / 2)];
    
    if (
      majorityIndex > this.commitIndex &&
      this.log[majorityIndex].term === this.currentTerm
    ) {
      this.commitIndex = majorityIndex;
      this.applyCommittedEntries();
    }
  }
  
  private applyCommittedEntries(): void {
    while (this.lastApplied < this.commitIndex) {
      this.lastApplied++;
      const entry = this.log[this.lastApplied];
      if (entry.command) {
        this.stateMachine.apply(entry.command);
        this.emit('commandApplied', entry);
      }
    }
  }
  
  private waitForCommit(index: number): Promise<boolean> {
    return new Promise((resolve) => {
      if (index <= this.commitIndex) {
        resolve(true);
        return;
      }
      
      const checkCommit = () => {
        if (index <= this.commitIndex) {
          resolve(true);
        } else if (!this.isLeader()) {
          resolve(false);
        } else {
          setTimeout(checkCommit, 10);
        }
      };
      
      setTimeout(checkCommit, 10);
      
      // Timeout after 5 seconds
      setTimeout(() => resolve(false), 5000);
    });
  }
  
  private isLogUpToDate(lastLogIndex: number, lastLogTerm: number): boolean {
    const myLastLog = this.log[this.log.length - 1];
    if (myLastLog.term !== lastLogTerm) {
      return lastLogTerm > myLastLog.term;
    }
    return lastLogIndex >= this.log.length - 1;
  }
  
  private resetElectionTimer(): void {
    this.clearElectionTimer();
    
    const timeout =
      this.config.electionTimeoutMin +
      Math.random() *
        (this.config.electionTimeoutMax - this.config.electionTimeoutMin);
    
    this.electionTimer = setTimeout(() => {
      if (this.state !== 'LEADER') {
        this.convertToCandidate();
      }
    }, timeout);
  }
  
  private clearElectionTimer(): void {
    if (this.electionTimer) {
      clearTimeout(this.electionTimer);
      this.electionTimer = null;
    }
  }
  
  private clearHeartbeatTimer(): void {
    if (this.heartbeatTimer) {
      clearInterval(this.heartbeatTimer);
      this.heartbeatTimer = null;
    }
  }
  
  private clearTimers(): void {
    this.clearElectionTimer();
    this.clearHeartbeatTimer();
  }
  
  private persistState(): void {
    // Persist to disk (simplified - in production use proper storage)
    // this.storage.save({ currentTerm: this.currentTerm, votedFor: this.votedFor, log: this.log });
  }
}

