import { ChildProcess,spawn } from 'child_process';

import { mkdir, rm,writeFile } from 'fs/promises';
import { tmpdir } from 'os';
import { join } from 'path';
import { promisify } from 'util';
import { EventEmitter } from 'eventemitter3';

const execAsync = promisify(require('child_process').exec);

export interface SandboxConfig {
  runtime: 'firecracker' | 'gvisor' | 'docker' | 'native';
  memoryLimit: number; // MB
  cpuLimit: number; // percentage
  timeout: number; // seconds
  networkEnabled: boolean;
  diskLimit: number; // MB
}

export interface SandboxResult {
  exitCode: number;
  stdout: string;
  stderr: string;
  duration: number;
  memoryPeak: number;
  oomKilled: boolean;
}

export interface TaskExecutionRequest {
  taskId: string;
  image: string;
  command: string[];
  env: Record<string, string>;
  input?: any;
  artifacts?: string[];
}

export abstract class SandboxRuntime extends EventEmitter {
  protected config: SandboxConfig;

  constructor(config: SandboxConfig) {
    super();
    this.config = config;
  }

  abstract execute(request: TaskExecutionRequest): Promise<SandboxResult>;
  abstract isAvailable(): Promise<boolean>;
  abstract cleanup(taskId: string): Promise<void>;

  protected async createTempDir(taskId: string): Promise<string> {
    const dir = join(tmpdir(), `edgecloud-${taskId}`);
    await mkdir(dir, { recursive: true });
    return dir;
  }

  protected async cleanupTempDir(dir: string): Promise<void> {
    try {
      await rm(dir, { recursive: true, force: true });
    } catch (error) {
      // Ignore cleanup errors
    }
  }
}

// Firecracker MicroVM Runtime
export class FirecrackerRuntime extends SandboxRuntime {
  private firecrackerBinary: string;
  private jailerBinary: string;
  private vms: Map<string, ChildProcess> = new Map();

  constructor(config: SandboxConfig, options?: { firecrackerPath?: string; jailerPath?: string }) {
    super(config);
    this.firecrackerBinary = options?.firecrackerPath || '/usr/bin/firecracker';
    this.jailerBinary = options?.jailerPath || '/usr/bin/jailer';
  }

  async isAvailable(): Promise<boolean> {
    try {
      await execAsync(`which ${this.firecrackerBinary}`);
      await execAsync(`which ${this.jailerBinary}`);
      return true;
    } catch {
      return false;
    }
  }

  async execute(request: TaskExecutionRequest): Promise<SandboxResult> {
    const startTime = Date.now();
    const workDir = await this.createTempDir(request.taskId);

    try {
      // Create Firecracker configuration
      const configPath = await this.createFirecrackerConfig(request, workDir);
      
      // Start Firecracker VM
      const vmProcess = this.startVM(request.taskId, configPath);
      this.vms.set(request.taskId, vmProcess);

      this.emit('vmStarted', { taskId: request.taskId, pid: vmProcess.pid });

      // Wait for completion or timeout
      const result = await this.waitForVM(vmProcess, this.config.timeout);
      
      const duration = Date.now() - startTime;

      return {
        exitCode: result.exitCode,
        stdout: result.stdout,
        stderr: result.stderr,
        duration,
        memoryPeak: result.memoryPeak || this.config.memoryLimit,
        oomKilled: result.oomKilled,
      };
    } finally {
      await this.cleanup(request.taskId);
      await this.cleanupTempDir(workDir);
    }
  }

  private async createFirecrackerConfig(request: TaskExecutionRequest, workDir: string): Promise<string> {
    const config = {
      boot_source: {
        kernel_image_path: '/opt/firecracker/vmlinux',
        boot_args: 'console=ttyS0 noapic reboot=k panic=1 pci=off nomodules',
      },
      drives: [
        {
          drive_id: 'rootfs',
          path_on_host: request.image,
          is_root_device: true,
          is_read_only: false,
        },
      ],
      machine_config: {
        vcpu_count: Math.ceil(this.config.cpuLimit / 100),
        mem_size_mib: this.config.memoryLimit,
      },
      network_interfaces: this.config.networkEnabled ? [
        {
          iface_id: 'eth0',
          guest_mac: 'AA:FC:00:00:00:01',
          host_dev_name: 'tap0',
        },
      ] : [],
    };

    const configPath = join(workDir, 'config.json');
    await writeFile(configPath, JSON.stringify(config, null, 2));
    return configPath;
  }

  private startVM(taskId: string, configPath: string): ChildProcess {
    const socketPath = `/tmp/firecracker-${taskId}.sock`;
    
    return spawn(this.firecrackerBinary, [
      '--api-sock', socketPath,
      '--config-file', configPath,
    ], {
      detached: false,
    });
  }

  private async waitForVM(process: ChildProcess, timeout: number): Promise<any> {
    return new Promise((resolve, reject) => {
      const timeoutId = setTimeout(() => {
        process.kill('SIGTERM');
        reject(new Error('VM execution timeout'));
      }, timeout * 1000);

      let stdout = '';
      let stderr = '';

      process.stdout?.on('data', (data) => {
        stdout += data.toString();
      });

      process.stderr?.on('data', (data) => {
        stderr += data.toString();
      });

      process.on('close', (exitCode) => {
        clearTimeout(timeoutId);
        resolve({
          exitCode: exitCode || 0,
          stdout,
          stderr,
          memoryPeak: 0, // Would need to query Firecracker API
          oomKilled: false,
        });
      });

      process.on('error', (error) => {
        clearTimeout(timeoutId);
        reject(error);
      });
    });
  }

  async cleanup(taskId: string): Promise<void> {
    const vm = this.vms.get(taskId);
    if (vm) {
      vm.kill('SIGTERM');
      this.vms.delete(taskId);
    }

    // Clean up socket
    try {
      await rm(`/tmp/firecracker-${taskId}.sock`, { force: true });
    } catch {
      // Ignore
    }
  }
}

// gVisor Sandbox Runtime
export class GVisorRuntime extends SandboxRuntime {
  private runscBinary: string;
  private containers: Map<string, string> = new Map();

  constructor(config: SandboxConfig, options?: { runscPath?: string }) {
    super(config);
    this.runscBinary = options?.runscPath || '/usr/local/bin/runsc';
  }

  async isAvailable(): Promise<boolean> {
    try {
      await execAsync(`which ${this.runscBinary}`);
      return true;
    } catch {
      return false;
    }
  }

  async execute(request: TaskExecutionRequest): Promise<SandboxResult> {
    const startTime = Date.now();
    const containerName = `edgecloud-${request.taskId}`;
    
    try {
      // Create container
      await this.createContainer(containerName, request);
      this.containers.set(request.taskId, containerName);
      
      this.emit('containerCreated', { taskId: request.taskId, container: containerName });

      // Run container
      const result = await this.runContainer(containerName, request);
      
      const duration = Date.now() - startTime;

      return {
        exitCode: result.exitCode,
        stdout: result.stdout,
        stderr: result.stderr,
        duration,
        memoryPeak: 0, // Would need to query cgroups
        oomKilled: result.exitCode === 137,
      };
    } finally {
      await this.cleanup(request.taskId);
    }
  }

  private async createContainer(name: string, request: TaskExecutionRequest): Promise<void> {
    const envArgs = Object.entries(request.env)
      .map(([k, v]) => `--env=${k}=${v}`)
      .join(' ');

    await execAsync(
      `${this.runscBinary} create --bundle=/var/lib/edgecloud/bundles/${request.image} ${name}`
    );
  }

  private async runContainer(name: string, request: TaskExecutionRequest): Promise<any> {
    return new Promise((resolve, reject) => {
      const timeoutId = setTimeout(async () => {
        try {
          await execAsync(`${this.runscBinary} kill ${name} 9`);
        } catch {
          // Ignore
        }
        reject(new Error('Container execution timeout'));
      }, this.config.timeout * 1000);

      const proc = spawn(this.runscBinary, ['run', name], {
        timeout: this.config.timeout * 1000,
      });

      let stdout = '';
      let stderr = '';

      proc.stdout?.on('data', (data) => {
        stdout += data.toString();
      });

      proc.stderr?.on('data', (data) => {
        stderr += data.toString();
      });

      proc.on('close', (exitCode) => {
        clearTimeout(timeoutId);
        resolve({ exitCode: exitCode || 0, stdout, stderr });
      });

      proc.on('error', (error) => {
        clearTimeout(timeoutId);
        reject(error);
      });
    });
  }

  async cleanup(taskId: string): Promise<void> {
    const containerName = this.containers.get(taskId);
    if (containerName) {
      try {
        await execAsync(`${this.runscBinary} delete ${containerName}`);
      } catch {
        // Ignore cleanup errors
      }
      this.containers.delete(taskId);
    }
  }
}

// Docker Runtime (fallback)
export class DockerRuntime extends SandboxRuntime {
  async isAvailable(): Promise<boolean> {
    try {
      await execAsync('which docker');
      await execAsync('docker ps');
      return true;
    } catch {
      return false;
    }
  }

  async execute(request: TaskExecutionRequest): Promise<SandboxResult> {
    const startTime = Date.now();
    const containerName = `edgecloud-${request.taskId}`;

    try {
      const envArgs = Object.entries(request.env)
        .map(([k, v]) => `-e ${k}=${v}`)
        .join(' ');

      const networkArgs = this.config.networkEnabled ? '' : '--network none';

      const { stdout, stderr } = await execAsync(
        `docker run --rm --name ${containerName} ` +
        `--memory=${this.config.memoryLimit}m ` +
        `--cpus=${this.config.cpuLimit / 100} ` +
        `--storage-opt size=${this.config.diskLimit}M ` +
        `${networkArgs} ${envArgs} ${request.image} ${request.command.join(' ')}`,
        { timeout: this.config.timeout * 1000 }
      );

      return {
        exitCode: 0,
        stdout,
        stderr,
        duration: Date.now() - startTime,
        memoryPeak: 0,
        oomKilled: false,
      };
    } catch (error: any) {
      return {
        exitCode: error.code || 1,
        stdout: error.stdout || '',
        stderr: error.stderr || '',
        duration: Date.now() - startTime,
        memoryPeak: 0,
        oomKilled: error.stderr?.includes('OOM') || false,
      };
    }
  }

  async cleanup(taskId: string): Promise<void> {
    try {
      await execAsync(`docker rm -f edgecloud-${taskId}`);
    } catch {
      // Ignore
    }
  }
}

// Runtime factory
export class SandboxRuntimeFactory {
  static async createPreferredRuntime(config: SandboxConfig): Promise<SandboxRuntime> {
    const runtimes: Array<{ runtime: SandboxRuntime; priority: number }> = [
      { runtime: new FirecrackerRuntime(config), priority: 1 },
      { runtime: new GVisorRuntime(config), priority: 2 },
      { runtime: new DockerRuntime(config), priority: 3 },
    ];

    for (const { runtime } of runtimes.sort((a, b) => a.priority - b.priority)) {
      if (await runtime.isAvailable()) {
        return runtime;
      }
    }

    throw new Error('No sandbox runtime available');
  }
}

import { EdgeNode,Task } from '@edgecloud/shared-kernel';
import { EventEmitter } from 'eventemitter3';

// Phase 11: Advanced Scheduling - Resource Reservations & Gang Scheduling

export interface ResourceReservation {
  id: string;
  taskId: string;
  nodeId: string;
  resources: {
    cpu: number;
    memory: number;
    gpu?: number;
  };
  reservedAt: Date;
  expiresAt: Date;
  status: 'PENDING' | 'CONFIRMED' | 'RELEASED';
}

export interface GangSchedulingRequest {
  id: string;
  name: string;
  tasks: Task[];
  constraints: {
    minNodes: number;
    maxNodes: number;
    requireSameRack?: boolean;
    requireSameRegion?: boolean;
  };
  status: 'PENDING' | 'SCHEDULING' | 'SCHEDULED' | 'FAILED';
}

export interface AffinityConstraint {
  type: 'node-affinity' | 'pod-affinity' | 'pod-anti-affinity';
  weight: number; // 1-100
  expressions: {
    key: string;
    operator: 'In' | 'NotIn' | 'Exists' | 'DoesNotExist';
    values: string[];
  }[];
}

export class ResourceReservationManager extends EventEmitter {
  private reservations: Map<string, ResourceReservation> = new Map();
  private nodeReservations: Map<string, Set<string>> = new Map();

  async createReservation(
    taskId: string,
    nodeId: string,
    resources: { cpu: number; memory: number; gpu?: number },
    ttlSeconds: number = 300
  ): Promise<ResourceReservation> {
    const reservation: ResourceReservation = {
      id: `res-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
      taskId,
      nodeId,
      resources,
      reservedAt: new Date(),
      expiresAt: new Date(Date.now() + ttlSeconds * 1000),
      status: 'PENDING',
    };

    this.reservations.set(reservation.id, reservation);

    // Track reservations per node
    if (!this.nodeReservations.has(nodeId)) {
      this.nodeReservations.set(nodeId, new Set());
    }
    this.nodeReservations.get(nodeId)!.add(reservation.id);

    this.emit('reservationCreated', reservation);

    // Auto-expire reservation
    setTimeout(() => {
      this.releaseReservation(reservation.id);
    }, ttlSeconds * 1000);

    return reservation;
  }

  async confirmReservation(reservationId: string): Promise<void> {
    const reservation = this.reservations.get(reservationId);
    if (!reservation) {
      throw new Error(`Reservation ${reservationId} not found`);
    }

    reservation.status = 'CONFIRMED';
    this.emit('reservationConfirmed', reservation);
  }

  async releaseReservation(reservationId: string): Promise<void> {
    const reservation = this.reservations.get(reservationId);
    if (!reservation) {return;}

    reservation.status = 'RELEASED';

    // Remove from node tracking
    const nodeRes = this.nodeReservations.get(reservation.nodeId);
    if (nodeRes) {
      nodeRes.delete(reservationId);
    }

    this.emit('reservationReleased', reservation);
    this.reservations.delete(reservationId);
  }

  getNodeReservedResources(nodeId: string): { cpu: number; memory: number; gpu: number } {
    const reservationIds = this.nodeReservations.get(nodeId) || new Set();
    let cpu = 0;
    let memory = 0;
    let gpu = 0;

    for (const id of reservationIds) {
      const res = this.reservations.get(id);
      if (res && res.status !== 'RELEASED') {
        cpu += res.resources.cpu;
        memory += res.resources.memory;
        gpu += res.resources.gpu || 0;
      }
    }

    return { cpu, memory, gpu };
  }

  getAvailableResources(node: EdgeNode): { cpu: number; memory: number; gpu: number } {
    const reserved = this.getNodeReservedResources(node.id);
    return {
      cpu: 100 - node.cpuUsage - reserved.cpu,
      memory: 100 - node.memoryUsage - reserved.memory,
      gpu: 100 - reserved.gpu, // Assuming GPU usage tracking
    };
  }
}

export class GangScheduler extends EventEmitter {
  private pendingGangs: Map<string, GangSchedulingRequest> = new Map();
  private reservationManager: ResourceReservationManager;

  constructor(reservationManager: ResourceReservationManager) {
    super();
    this.reservationManager = reservationManager;
  }

  async submitGangRequest(request: GangSchedulingRequest): Promise<string> {
    this.pendingGangs.set(request.id, request);
    this.emit('gangRequestSubmitted', request);

    // Attempt to schedule immediately
    await this.scheduleGang(request.id);

    return request.id;
  }

  private async scheduleGang(gangId: string): Promise<void> {
    const request = this.pendingGangs.get(gangId);
    if (!request || request.status !== 'PENDING') {return;}

    request.status = 'SCHEDULING';
    this.emit('gangSchedulingStarted', request);

    // This is a simplified implementation
    // In production, this would query available nodes and check constraints

    // Simulate finding suitable nodes
    const requiredNodes = Math.min(request.constraints.minNodes, request.tasks.length);

    if (requiredNodes > 0) {
      request.status = 'SCHEDULED';
      this.emit('gangScheduled', request);
    } else {
      request.status = 'FAILED';
      this.emit('gangSchedulingFailed', request);
    }

    this.pendingGangs.delete(gangId);
  }
}

export class AffinityScorer {
  calculateAffinityScore(
    task: Task,
    node: EdgeNode,
    constraints: AffinityConstraint[]
  ): number {
    let totalScore = 0;
    let totalWeight = 0;

    for (const constraint of constraints) {
      totalWeight += constraint.weight;
      const constraintScore = this.evaluateConstraint(task, node, constraint);
      totalScore += constraintScore * (constraint.weight / 100);
    }

    return totalWeight > 0 ? totalScore : 1.0;
  }

  private evaluateConstraint(
    task: Task,
    node: EdgeNode,
    constraint: AffinityConstraint
  ): number {
    let matches = 0;
    const total = constraint.expressions.length;

    for (const expr of constraint.expressions) {
      const nodeValue = this.getNodeLabel(node, expr.key);

      switch (expr.operator) {
        case 'In':
          if (expr.values.includes(nodeValue)) {matches++;}
          break;
        case 'NotIn':
          if (!expr.values.includes(nodeValue)) {matches++;}
          break;
        case 'Exists':
          if (nodeValue !== undefined) {matches++;}
          break;
        case 'DoesNotExist':
          if (nodeValue === undefined) {matches++;}
          break;
      }
    }

    return total > 0 ? matches / total : 1.0;
  }

  private getNodeLabel(node: EdgeNode, key: string): string | undefined {
    const labels = node.labels as Record<string, string> || {};
    return labels[key];
  }
}

// Preemption support for high-priority tasks
export interface PreemptionCandidate {
  taskId: string;
  nodeId: string;
  priority: number;
  resources: { cpu: number; memory: number };
  startTime: Date;
}

export class PreemptionManager extends EventEmitter {
  private runningTasks: Map<string, PreemptionCandidate> = new Map();

  registerRunningTask(candidate: PreemptionCandidate): void {
    this.runningTasks.set(candidate.taskId, candidate);
  }

  unregisterRunningTask(taskId: string): void {
    this.runningTasks.delete(taskId);
  }

  findPreemptionCandidates(
    requiredResources: { cpu: number; memory: number },
    minPriority: number,
    targetNodeId: string
  ): PreemptionCandidate[] {
    const candidates: PreemptionCandidate[] = [];

    for (const task of this.runningTasks.values()) {
      if (task.nodeId === targetNodeId && task.priority < minPriority) {
        candidates.push(task);
      }
    }

    // Sort by priority (lowest first) and start time (oldest first)
    candidates.sort((a, b) => {
      if (a.priority !== b.priority) {
        return a.priority - b.priority;
      }
      return a.startTime.getTime() - b.startTime.getTime();
    });

    // Find minimal set of tasks to preempt
    const toPreempt: PreemptionCandidate[] = [];
    let cpuAvailable = 0;
    let memoryAvailable = 0;

    for (const candidate of candidates) {
      if (cpuAvailable >= requiredResources.cpu && memoryAvailable >= requiredResources.memory) {
        break;
      }
      toPreempt.push(candidate);
      cpuAvailable += candidate.resources.cpu;
      memoryAvailable += candidate.resources.memory;
    }

    return toPreempt;
  }

  async preemptTasks(taskIds: string[]): Promise<void> {
    for (const taskId of taskIds) {
      const task = this.runningTasks.get(taskId);
      if (task) {
        this.emit('taskPreempted', task);
        this.runningTasks.delete(taskId);
      }
    }
  }
}

import { EventEmitter } from 'eventemitter3';

// ABAC - Attribute-Based Access Control

export interface Subject {
  id: string;
  type: 'user' | 'service' | 'agent';
  attributes: Record<string, any>;
  roles: string[];
}

export interface Resource {
  id: string;
  type: string;
  attributes: Record<string, any>;
}

export interface Action {
  name: string;
  attributes: Record<string, any>;
}

export interface Environment {
  time: Date;
  ip?: string;
  region?: string;
  source?: string;
  [key: string]: any;
}

export interface AccessRequest {
  subject: Subject;
  resource: Resource;
  action: Action;
  environment: Environment;
}

export interface Policy {
  id: string;
  name: string;
  description: string;
  effect: 'allow' | 'deny';
  subjects: PolicyCondition[];
  resources: PolicyCondition[];
  actions: PolicyCondition[];
  environments: PolicyCondition[];
  obligations?: Obligation[];
  priority: number;
}

export interface PolicyCondition {
  type: 'equals' | 'notEquals' | 'in' | 'notIn' | 'contains' | 'notContains' | 'greaterThan' | 'lessThan' | 'regex' | 'exists';
  attribute: string;
  value: any;
}

export interface Obligation {
  type: string;
  params: Record<string, any>;
}

export interface AccessDecision {
  allowed: boolean;
  reason: string;
  matchedPolicies: string[];
  obligations: Obligation[];
  evaluatedAt: Date;
}

export class ABACEngine extends EventEmitter {
  private policies: Map<string, Policy> = new Map();
  private attributeResolvers: Map<string, AttributeResolver> = new Map();

  constructor() {
    super();
  }

  addPolicy(policy: Policy): void {
    this.policies.set(policy.id, policy);
    this.emit('policyAdded', { policyId: policy.id, name: policy.name });
  }

  removePolicy(policyId: string): void {
    this.policies.delete(policyId);
    this.emit('policyRemoved', { policyId });
  }

  registerAttributeResolver(name: string, resolver: AttributeResolver): void {
    this.attributeResolvers.set(name, resolver);
  }

  async evaluate(request: AccessRequest): Promise<AccessDecision> {
    const matchedPolicies: string[] = [];
    const obligations: Obligation[] = [];
    let finalDecision: 'allow' | 'deny' | null = null;
    let decisionReason = 'No matching policies';

    // Resolve any dynamic attributes
    await this.resolveAttributes(request);

    // Sort policies by priority (higher priority first)
    const sortedPolicies = Array.from(this.policies.values())
      .sort((a, b) => b.priority - a.priority);

    for (const policy of sortedPolicies) {
      const matches = await this.policyMatches(policy, request);

      if (matches) {
        matchedPolicies.push(policy.id);

        if (policy.obligations) {
          obligations.push(...policy.obligations);
        }

        // First matching policy determines the decision (deny takes precedence)
        if (finalDecision === null || policy.effect === 'deny') {
          finalDecision = policy.effect;
          decisionReason = `Matched policy: ${policy.name}`;
        }

        // If we hit a deny, stop evaluating
        if (policy.effect === 'deny') {
          break;
        }
      }
    }

    const allowed = finalDecision === 'allow';

    this.emit('accessEvaluated', {
      allowed,
      subjectId: request.subject.id,
      resourceType: request.resource.type,
      action: request.action.name,
      matchedPolicies,
    });

    return {
      allowed,
      reason: decisionReason,
      matchedPolicies,
      obligations,
      evaluatedAt: new Date(),
    };
  }

  private async resolveAttributes(request: AccessRequest): Promise<void> {
    for (const [name, resolver] of this.attributeResolvers) {
      try {
        const value = await resolver.resolve(request);
        if (value !== undefined) {
          request.subject.attributes[name] = value;
        }
      } catch (error) {
        this.emit('attributeResolutionError', { name, error });
      }
    }
  }

  private async policyMatches(policy: Policy, request: AccessRequest): Promise<boolean> {
    return (
      this.conditionsMatch(policy.subjects, request.subject.attributes, request) &&
      this.conditionsMatch(policy.resources, request.resource.attributes, request) &&
      this.conditionsMatch(policy.actions, request.action.attributes, request) &&
      this.conditionsMatch(policy.environments, request.environment as Record<string, any>, request)
    );
  }

  private conditionsMatch(
    conditions: PolicyCondition[],
    attributes: Record<string, any>,
    request: AccessRequest
  ): boolean {
    if (conditions.length === 0) {
      return true;
    }

    return conditions.every((condition) => this.conditionMatches(condition, attributes, request));
  }

  private conditionMatches(
    condition: PolicyCondition,
    attributes: Record<string, any>,
    request: AccessRequest
  ): boolean {
    const attributeValue = this.getNestedAttribute(attributes, condition.attribute);

    switch (condition.type) {
      case 'equals':
        return attributeValue === condition.value;

      case 'notEquals':
        return attributeValue !== condition.value;

      case 'in':
        return Array.isArray(condition.value) && condition.value.includes(attributeValue);

      case 'notIn':
        return Array.isArray(condition.value) && !condition.value.includes(attributeValue);

      case 'contains':
        return Array.isArray(attributeValue) && attributeValue.includes(condition.value);

      case 'greaterThan':
        return typeof attributeValue === 'number' && attributeValue > condition.value;

      case 'lessThan':
        return typeof attributeValue === 'number' && attributeValue < condition.value;

      case 'regex':
        return new RegExp(condition.value).test(String(attributeValue));

      case 'exists':
        return attributeValue !== undefined && attributeValue !== null;

      default:
        return false;
    }
  }

  private getNestedAttribute(obj: Record<string, any>, path: string): any {
    return path.split('.').reduce((o, p) => o?.[p], obj);
  }

  getPolicies(): Policy[] {
    return Array.from(this.policies.values());
  }
}

export interface AttributeResolver {
  resolve(request: AccessRequest): Promise<any>;
}

// Common attribute resolvers
export class TimeBasedAttributeResolver implements AttributeResolver {
  async resolve(request: AccessRequest): Promise<any> {
    const hour = request.environment.time.getHours();
    const dayOfWeek = request.environment.time.getDay();

    return {
      isBusinessHours: hour >= 9 && hour < 17 && dayOfWeek > 0 && dayOfWeek < 6,
      isWeekend: dayOfWeek === 0 || dayOfWeek === 6,
      hourOfDay: hour,
      dayOfWeek,
    };
  }
}

export class RoleHierarchyResolver implements AttributeResolver {
  private roleHierarchy: Map<string, string[]> = new Map([
    ['admin', ['user', 'viewer', 'operator']],
    ['operator', ['user', 'viewer']],
    ['user', ['viewer']],
    ['viewer', []],
  ]);

  async resolve(request: AccessRequest): Promise<any> {
    const roles = request.subject.roles || [];
    const effectiveRoles = new Set<string>();

    for (const role of roles) {
      effectiveRoles.add(role);
      const inherited = this.roleHierarchy.get(role) || [];
      inherited.forEach((r) => effectiveRoles.add(r));
    }

    return {
      effectiveRoles: Array.from(effectiveRoles),
      hasAdminRole: effectiveRoles.has('admin'),
      hasOperatorRole: effectiveRoles.has('operator'),
    };
  }
}

// Policy builder for easy policy creation
export class PolicyBuilder {
  private policy: Partial<Policy> = {
    subjects: [],
    resources: [],
    actions: [],
    environments: [],
    obligations: [],
    priority: 100,
  };

  id(id: string): this {
    this.policy.id = id;
    return this;
  }

  name(name: string): this {
    this.policy.name = name;
    return this;
  }

  description(description: string): this {
    this.policy.description = description;
    return this;
  }

  effect(effect: 'allow' | 'deny'): this {
    this.policy.effect = effect;
    return this;
  }

  allow(): this {
    return this.effect('allow');
  }

  deny(): this {
    return this.effect('deny');
  }

  subject(attribute: string, type: PolicyCondition['type'], value: any): this {
    this.policy.subjects!.push({ type, attribute, value });
    return this;
  }

  resource(attribute: string, type: PolicyCondition['type'], value: any): this {
    this.policy.resources!.push({ type, attribute, value });
    return this;
  }

  action(attribute: string, type: PolicyCondition['type'], value: any): this {
    this.policy.actions!.push({ type, attribute, value });
    return this;
  }

  environment(attribute: string, type: PolicyCondition['type'], value: any): this {
    this.policy.environments!.push({ type, attribute, value });
    return this;
  }

  obligation(type: string, params: Record<string, any> = {}): this {
    this.policy.obligations!.push({ type, params });
    return this;
  }

  priority(priority: number): this {
    this.policy.priority = priority;
    return this;
  }

  build(): Policy {
    if (!this.policy.id || !this.policy.name || !this.policy.effect) {
      throw new Error('Policy must have id, name, and effect');
    }
    return this.policy as Policy;
  }
}

// Pre-defined policies for EdgeCloud
export const DEFAULT_POLICIES: Policy[] = [
  // Admin has full access
  new PolicyBuilder()
    .id('admin-full-access')
    .name('Admin Full Access')
    .description('Administrators have full access to all resources')
    .allow()
    .subject('roles', 'contains', 'admin')
    .priority(1000)
    .build(),

  // Operators can manage tasks and nodes
  new PolicyBuilder()
    .id('operator-manage')
    .name('Operator Management Access')
    .description('Operators can manage tasks and nodes')
    .allow()
    .subject('roles', 'contains', 'operator')
    .resource('type', 'in', ['task', 'node'])
    .action('name', 'in', ['create', 'read', 'update', 'delete', 'schedule'])
    .priority(500)
    .build(),

  // Users can read and create tasks
  new PolicyBuilder()
    .id('user-task-access')
    .name('User Task Access')
    .description('Users can create and read tasks')
    .allow()
    .subject('roles', 'contains', 'user')
    .resource('type', 'equals', 'task')
    .action('name', 'in', ['create', 'read'])
    .priority(200)
    .build(),

  // Users can only access their own tasks
  new PolicyBuilder()
    .id('user-own-tasks')
    .name('User Own Tasks Only')
    .description('Users can only modify their own tasks')
    .allow()
    .subject('roles', 'contains', 'user')
    .resource('type', 'equals', 'task')
    .resource('ownerId', 'equals', '${subject.id}')
    .action('name', 'in', ['update', 'delete'])
    .priority(300)
    .build(),

  // Deny access outside business hours for non-admins
  new PolicyBuilder()
    .id('business-hours-only')
    .name('Business Hours Restriction')
    .description('Non-admins cannot access outside business hours')
    .deny()
    .subject('roles', 'notContains', 'admin')
    .environment('isBusinessHours', 'equals', false)
    .action('name', 'notEquals', 'read')
    .priority(100)
    .build(),

  // Region-based access
  new PolicyBuilder()
    .id('region-access')
    .name('Region-Based Access')
    .description('Users can only access resources in their region')
    .allow()
    .subject('roles', 'notContains', 'admin')
    .resource('region', 'equals', '${subject.attributes.region}')
    .priority(150)
    .build(),
];

