import { createHash, createSign, createVerify, generateKeyPairSync, randomBytes } from 'crypto';
import { EventEmitter } from 'eventemitter3';
import { existsSync, mkdirSync,readFileSync, writeFileSync } from 'fs';
import * as forge from 'node-forge';
import { join } from 'path';

export interface CertificateAuthority {
  id: string;
  name: string;
  privateKey: string;
  publicKey: string;
  certificate: string;
  createdAt: Date;
  expiresAt: Date;
}

export interface CertificateRequest {
  id: string;
  subject: {
    commonName: string;
    organization?: string;
    organizationalUnit?: string;
    country?: string;
    region?: string;
  };
  publicKey: string;
  csr: string;
  requestedAt: Date;
  status: 'pending' | 'approved' | 'rejected' | 'issued';
}

export interface IssuedCertificate {
  id: string;
  serialNumber: string;
  subject: {
    commonName: string;
    organization?: string;
    organizationalUnit?: string;
    country?: string;
    region?: string;
  };
  issuer: string;
  publicKey: string;
  certificate: string;
  issuedAt: Date;
  expiresAt: Date;
  revokedAt?: Date;
  revoked?: boolean;
  revocationReason?: string;
}

export interface MTLSConfig {
  caCertPath: string;
  caKeyPath: string;
  certValidityDays: number;
  keySize: number;
  allowedOrganizations: string[];
}

export class MTLSManager extends EventEmitter {
  private config: MTLSConfig;
  private ca: CertificateAuthority | null = null;
  private certificates: Map<string, IssuedCertificate> = new Map();
  private pendingRequests: Map<string, CertificateRequest> = new Map();
  private crl: string[] = []; // Certificate Revocation List

  constructor(config: Partial<MTLSConfig> = {}) {
    super();
    this.config = {
      caCertPath: '/etc/edgecloud/ca.crt',
      caKeyPath: '/etc/edgecloud/ca.key',
      certValidityDays: 90,
      keySize: 4096,
      allowedOrganizations: ['EdgeCloud', 'EdgeCloud-Node', 'EdgeCloud-Agent'],
      ...config,
    };
  }

  async initialize(): Promise<void> {
    if (existsSync(this.config.caCertPath) && existsSync(this.config.caKeyPath)) {
      await this.loadCA();
    } else {
      await this.generateCA();
    }
    this.emit('initialized');
  }

  private async generateCA(): Promise<void> {
    const { publicKey, privateKey } = generateKeyPairSync('rsa', {
      modulusLength: this.config.keySize,
      publicKeyEncoding: { type: 'spki', format: 'pem' },
      privateKeyEncoding: { type: 'pkcs8', format: 'pem' },
    });

    const selfSignedCert = this.createSelfSignedCertificate(publicKey, privateKey);

    this.ca = {
      id: `ca-${Date.now()}`,
      name: 'EdgeCloud Root CA',
      privateKey,
      publicKey,
      certificate: selfSignedCert,
      createdAt: new Date(),
      expiresAt: new Date(Date.now() + 365 * 24 * 60 * 60 * 1000 * 10), // 10 years
    };

    // Ensure directory exists
    const caDir = join(this.config.caCertPath, '..');
    if (!existsSync(caDir)) {
      mkdirSync(caDir, { recursive: true });
    }

    writeFileSync(this.config.caCertPath, this.ca.certificate);
    writeFileSync(this.config.caKeyPath, this.ca.privateKey);

    this.emit('caGenerated', { caId: this.ca.id });
  }

  private async loadCA(): Promise<void> {
    const certificate = readFileSync(this.config.caCertPath, 'utf-8');
    const privateKey = readFileSync(this.config.caKeyPath, 'utf-8');

    this.ca = {
      id: `ca-loaded-${Date.now()}`,
      name: 'EdgeCloud Root CA',
      privateKey,
      publicKey: this.extractPublicKeyFromCert(certificate),
      certificate,
      createdAt: new Date(),
      expiresAt: new Date(Date.now() + 365 * 24 * 60 * 60 * 1000 * 10),
    };

    this.emit('caLoaded', { caId: this.ca.id });
  }

  async generateKeyPair(): Promise<{ publicKey: string; privateKey: string }> {
    const { publicKey, privateKey } = generateKeyPairSync('rsa', {
      modulusLength: this.config.keySize,
      publicKeyEncoding: { type: 'spki', format: 'pem' },
      privateKeyEncoding: { type: 'pkcs8', format: 'pem' },
    });

    return { publicKey, privateKey };
  }

  async createCertificateRequest(
    commonName: string,
    publicKey: string,
    options?: {
      organization?: string;
      organizationalUnit?: string;
      country?: string;
      region?: string;
    }
  ): Promise<CertificateRequest> {
    const request: CertificateRequest = {
      id: `csr-${randomBytes(16).toString('hex')}`,
      subject: {
        commonName,
        organization: options?.organization,
        organizationalUnit: options?.organizationalUnit,
        country: options?.country,
        region: options?.region,
      },
      publicKey,
      csr: this.createCSR(commonName, publicKey, options),
      requestedAt: new Date(),
      status: 'pending',
    };

    this.pendingRequests.set(request.id, request);
    this.emit('certificateRequested', { requestId: request.id, commonName });

    return request;
  }

  async approveCertificate(requestId: string): Promise<IssuedCertificate> {
    const request = this.pendingRequests.get(requestId);
    if (!request) {
      throw new Error(`Certificate request ${requestId} not found`);
    }

    if (request.status !== 'pending') {
      throw new Error(`Certificate request ${requestId} is not pending`);
    }

    if (!this.ca) {
      throw new Error('CA not initialized');
    }

    request.status = 'approved';

    const certificate = this.signCertificate(request);
    request.status = 'issued';

    this.certificates.set(certificate.id, certificate);
    this.pendingRequests.delete(requestId);

    this.emit('certificateIssued', { 
      certificateId: certificate.id, 
      serialNumber: certificate.serialNumber,
      commonName: certificate.subject.commonName 
    });

    return certificate;
  }

  async rejectCertificate(requestId: string, reason: string): Promise<void> {
    const request = this.pendingRequests.get(requestId);
    if (!request) {
      throw new Error(`Certificate request ${requestId} not found`);
    }

    request.status = 'rejected';
    this.emit('certificateRejected', { requestId, reason });
    this.pendingRequests.delete(requestId);
  }

  async revokeCertificate(serialNumber: string, reason: string): Promise<void> {
    for (const [id, cert] of this.certificates) {
      if (cert.serialNumber === serialNumber) {
        cert.revoked = true;
        cert.revokedAt = new Date();
        cert.revocationReason = reason;
        this.crl.push(serialNumber);
        this.emit('certificateRevoked', { serialNumber, reason });
        return;
      }
    }
    throw new Error(`Certificate with serial ${serialNumber} not found`);
  }

  validateCertificate(certificate: string): { valid: boolean; reason?: string; subject?: any } {
    try {
      // Parse certificate
      const parsed = this.parseCertificate(certificate);

      // Check if revoked
      if (this.crl.includes(parsed.serialNumber)) {
        return { valid: false, reason: 'Certificate has been revoked' };
      }

      // Check expiration
      if (new Date() > parsed.expiresAt) {
        return { valid: false, reason: 'Certificate has expired' };
      }

      // Verify signature
      if (!this.verifyCertificateSignature(certificate)) {
        return { valid: false, reason: 'Invalid certificate signature' };
      }

      return { valid: true, subject: parsed.subject };
    } catch (error) {
      return { valid: false, reason: (error as Error).message };
    }
  }

  getCertificate(serialNumber: string): IssuedCertificate | undefined {
    for (const cert of this.certificates.values()) {
      if (cert.serialNumber === serialNumber) {
        return cert;
      }
    }
    return undefined;
  }

  getRevocationList(): string[] {
    return [...this.crl];
  }

  private createSelfSignedCertificate(publicKeyPem: string, privateKeyPem: string): string {
    // Use node-forge for proper X.509 certificate generation
    const keys = {
      privateKey: forge.pki.privateKeyFromPem(privateKeyPem),
      publicKey: forge.pki.publicKeyFromPem(publicKeyPem),
    };
    
    const cert = forge.pki.createCertificate();
    cert.publicKey = keys.publicKey;
    cert.serialNumber = randomBytes(16).toString('hex');
    
    const now = new Date();
    cert.validity.notBefore = now;
    cert.validity.notAfter = new Date(now.getTime() + 365 * 24 * 60 * 60 * 1000 * 10); // 10 years
    
    const attrs = [
      { name: 'commonName', value: 'EdgeCloud Root CA' },
      { name: 'organizationName', value: 'EdgeCloud' },
      { name: 'countryName', value: 'US' },
    ];
    
    cert.setSubject(attrs);
    cert.setIssuer(attrs);
    
    // Add CA extensions
    cert.setExtensions([
      { name: 'basicConstraints', cA: true, critical: true },
      { name: 'keyUsage', keyCertSign: true, cRLSign: true, critical: true },
    ]);
    
    // Self-sign with SHA-384
    cert.sign(keys.privateKey, forge.md.sha384.create());
    
    return forge.pki.certificateToPem(cert);
  }

  private createCSR(commonName: string, publicKey: string, options?: any): string {
    const subject = `CN=${commonName}${options?.organization ? `,O=${options.organization}` : ''}`;
    return Buffer.from(JSON.stringify({
      subject,
      publicKey,
      timestamp: new Date().toISOString(),
    })).toString('base64');
  }

  private signCertificate(request: CertificateRequest): IssuedCertificate {
    if (!this.ca) {throw new Error('CA not initialized');}

    const serialNumber = randomBytes(16).toString('hex');
    const validityDays = this.config.certValidityDays;
    const issuedAt = new Date();
    const expiresAt = new Date(Date.now() + validityDays * 24 * 60 * 60 * 1000);

    const certData = {
      subject: request.subject,
      issuer: 'CN=EdgeCloud Root CA,O=EdgeCloud',
      serialNumber,
      publicKey: request.publicKey,
      issuedAt: issuedAt.toISOString(),
      expiresAt: expiresAt.toISOString(),
    };

    const signature = this.sign(this.ca.privateKey, JSON.stringify(certData));

    const certificate = [
      '-----BEGIN [REDACTED]-----',
      Buffer.from(JSON.stringify({ ...certData, signature })).toString('base64'),
      '-----END [REDACTED]-----',
    ].join('\n');

    return {
      id: `cert-${serialNumber}`,
      serialNumber,
      subject: request.subject,
      issuer: 'EdgeCloud Root CA',
      publicKey: request.publicKey,
      certificate,
      issuedAt,
      expiresAt,
    };
  }

  private sign(privateKey: string, data: string): string {
    const sign = createSign('SHA256');
    sign.update(data);
    sign.end();
    return sign.sign(privateKey, 'hex');
  }

  private verifyCertificateSignature(certificate: string): boolean {
    try {
      if (!this.ca) {return false;}

      const certContent = certificate.split('\n').slice(1, -1).join('');
      const parsed = JSON.parse(Buffer.from(certContent, 'base64').toString());

      const { signature, ...certData } = parsed;
      const dataToVerify = JSON.stringify(certData);

      const verify = createVerify('SHA256');
      verify.update(dataToVerify);
      verify.end();

      return verify.verify(this.ca.publicKey, signature, 'hex');
    } catch {
      return false;
    }
  }

  private parseCertificate(certificate: string): any {
    const certContent = certificate.split('\n').slice(1, -1).join('');
    return JSON.parse(Buffer.from(certContent, 'base64').toString());
  }

  private extractPublicKeyFromCert(certificate: string): string {
    const parsed = this.parseCertificate(certificate);
    return parsed.publicKey;
  }
}

import axios, { AxiosInstance } from 'axios';
import { EventEmitter } from 'eventemitter3';

export interface VaultConfig {
  address: string;
  token?: string;
  roleId?: string;
  secretId?: string;
  tls?: {
    cert?: string;
    key?: string;
    ca?: string;
  };
}

export interface DatabaseCredentials {
  username: string;
  password: string;
  leaseId: string;
  leaseDuration: number;
  renewable: boolean;
}

export interface CertificateResponse {
  certificate: string;
  issuingCa: string;
  caChain: string[];
  privateKey: string;
  privateKeyType: string;
  serialNumber: string;
  leaseId: string;
  leaseDuration: number;
}

export class VaultClient extends EventEmitter {
  private client: AxiosInstance;
  private token: string | null = null;
  private tokenRenewalTimer: NodeJS.Timeout | null = null;
  private config: VaultConfig;

  constructor(config: VaultConfig) {
    super();
    this.config = config;
    this.client = axios.create({
      baseURL: config.address,
      timeout: 30000,
      headers: {
        'Content-Type': 'application/json',
      },
    });

    // Setup request interceptor for token
    this.client.interceptors.request.use(async (config) => {
      if (this.token) {
        config.headers['X-Vault-Token'] = this.token;
      }
      return config;
    });
  }

  async authenticate(): Promise<void> {
    if (this.config.token) {
      this.token = this.config.token;
      await this.validateToken();
    } else if (this.config.roleId && this.config.secretId) {
      await this.authenticateAppRole();
    } else {
      throw new Error('No authentication method provided');
    }

    this.scheduleTokenRenewal();
    this.emit('authenticated');
  }

  private async validateToken(): Promise<void> {
    try {
      await this.client.get('/v1/auth/token/lookup-self');
    } catch (error) {
      throw new Error('Invalid Vault token');
    }
  }

  private async authenticateAppRole(): Promise<void> {
    const response = await this.client.post('/v1/auth/approle/login', {
      role_id: this.config.roleId,
      secret_id: this.config.secretId,
    });

    this.token = response.data.auth.client_token;
    this.emit('tokenReceived', {
      token: this.token,
      leaseDuration: response.data.auth.lease_duration,
      renewable: response.data.auth.renewable,
    });
  }

  private scheduleTokenRenewal(): void {
    if (this.tokenRenewalTimer) {
      clearTimeout(this.tokenRenewalTimer);
    }

    // Renew token at 2/3 of its TTL
    const renewalInterval = 20 * 60 * 1000; // 20 minutes default

    this.tokenRenewalTimer = setTimeout(async () => {
      try {
        await this.renewToken();
      } catch (error) {
        this.emit('renewalFailed', error);
        // Re-authenticate
        await this.authenticate();
      }
    }, renewalInterval);
  }

  private async renewToken(): Promise<void> {
    const response = await this.client.post('/v1/auth/token/renew-self');
    this.emit('tokenRenewed', {
      leaseDuration: response.data.auth.lease_duration,
    });
  }

  // KV Secrets Engine v2
  async getSecret(path: string): Promise<Record<string, any>> {
    const response = await this.client.get(`/v1/secret/data/${path}`);
    return response.data.data.data;
  }

  async putSecret(path: string, data: Record<string, any>): Promise<void> {
    await this.client.post(`/v1/secret/data/${path}`, {
      data,
    });
  }

  // Database Secrets Engine
  async getDatabaseCredentials(role: string): Promise<DatabaseCredentials> {
    const response = await this.client.get(`/v1/database/creds/${role}`);
    const {data} = response.data;

    const creds: DatabaseCredentials = {
      username: data.username,
      password: data.password,
      leaseId: response.data.lease_id,
      leaseDuration: response.data.lease_duration,
      renewable: response.data.renewable,
    };

    // Schedule automatic renewal if renewable
    if (creds.renewable) {
      this.scheduleLeaseRenewal(creds.leaseId, creds.leaseDuration);
    }

    return creds;
  }

  private scheduleLeaseRenewal(leaseId: string, leaseDuration: number): void {
    const renewalTime = (leaseDuration * 1000 * 2) / 3; // Renew at 2/3 TTL

    setTimeout(async () => {
      try {
        await this.renewLease(leaseId);
      } catch (error) {
        this.emit('leaseRenewalFailed', { leaseId, error });
      }
    }, renewalTime);
  }

  async renewLease(leaseId: string): Promise<void> {
    await this.client.put('/v1/sys/leases/renew', {
      lease_id: leaseId,
    });
    this.emit('leaseRenewed', { leaseId });
  }

  async revokeLease(leaseId: string): Promise<void> {
    await this.client.put('/v1/sys/leases/revoke', {
      lease_id: leaseId,
    });
  }

  // PKI Secrets Engine
  async generateCertificate(
    role: string,
    commonName: string,
    options?: {
      ttl?: string;
      altNames?: string[];
      ipSans?: string[];
    }
  ): Promise<CertificateResponse> {
    const response = await this.client.post(`/v1/pki_int/issue/${role}`, {
      common_name: commonName,
      ttl: options?.ttl,
      alt_names: options?.altNames?.join(','),
      ip_sans: options?.ipSans?.join(','),
    });

    const {data} = response.data;
    return {
      certificate: data.certificate,
      issuingCa: data.issuing_ca,
      caChain: data.ca_chain,
      privateKey: data.private_key,
      privateKeyType: data.private_key_type,
      serialNumber: data.serial_number,
      leaseId: response.data.lease_id,
      leaseDuration: response.data.lease_duration,
    };
  }

  async revokeCertificate(serialNumber: string): Promise<void> {
    await this.client.post('/v1/pki_int/revoke', {
      serial_number: serialNumber,
    });
  }

  // Health check
  async healthCheck(): Promise<{
    initialized: boolean;
    sealed: boolean;
    standby: boolean;
  }> {
    const response = await this.client.get('/v1/sys/health');
    return {
      initialized: response.data.initialized,
      sealed: response.data.sealed,
      standby: response.data.standby,
    };
  }

  async close(): Promise<void> {
    if (this.tokenRenewalTimer) {
      clearTimeout(this.tokenRenewalTimer);
    }
  }
}

import { beforeEach,describe, expect, it } from 'vitest';

import { ABACEngine, Action, DEFAULT_POLICIES, Environment,PolicyBuilder, Resource, Subject } from '../src/abac';

describe('ABACEngine', () => {
  let engine: ABACEngine;

  beforeEach(() => {
    engine = new ABACEngine();
  });

  describe('policy management', () => {
    it('should add and retrieve policies', () => {
      const policy = new PolicyBuilder()
        .id('test-policy')
        .name('Test Policy')
        .allow()
        .subject('roles', 'contains', 'admin')
        .resource('type', 'equals', 'task')
        .action('name', 'equals', 'create')
        .build();
      
      engine.addPolicy(policy);
      
      expect(engine.getPolicies()).toHaveLength(1);
    });

    it('should remove policies', () => {
      const policy = new PolicyBuilder()
        .id('test-policy')
        .name('Test Policy')
        .allow()
        .build();
      
      engine.addPolicy(policy);
      engine.removePolicy('test-policy');
      
      expect(engine.getPolicies()).toHaveLength(0);
    });
  });

  describe('access decisions', () => {
    beforeEach(() => {
      // Add test policies
      engine.addPolicy(
        new PolicyBuilder()
          .id('admin-full-access')
          .name('Admin Access')
          .allow()
          .subject('roles', 'contains', 'admin')
          .priority(100)
          .build()
      );

      engine.addPolicy(
        new PolicyBuilder()
          .id('user-read-tasks')
          .name('User Task Access')
          .allow()
          .subject('roles', 'contains', 'user')
          .resource('type', 'equals', 'task')
          .action('name', 'equals', 'read')
          .priority(50)
          .build()
      );

      engine.addPolicy(
        new PolicyBuilder()
          .id('deny-guest-access')
          .name('Deny Guest')
          .deny()
          .subject('roles', 'contains', 'guest')
          .priority(10)
          .build()
      );
    });

    it('should allow admin full access', async () => {
      const subject: Subject = {
        id: 'user-1',
        type: 'user',
        attributes: { roles: ['admin'] },
        roles: ['admin'],
      };
      
      const resource: Resource = {
        id: 'task-1',
        type: 'task',
        attributes: { type: 'task' },
      };
      
      const action: Action = {
        name: 'delete',
        attributes: { name: 'delete' },
      };
      
      const environment: Environment = {
        time: new Date(),
      };
      
      const decision = await engine.evaluate({ subject, resource, action, environment });
      
      expect(decision.allowed).toBe(true);
    });

    it('should allow user read access to tasks', async () => {
      const subject: Subject = {
        id: 'user-2',
        type: 'user',
        attributes: { roles: ['user'] },
        roles: ['user'],
      };
      
      const resource: Resource = {
        id: 'task-1',
        type: 'task',
        attributes: { type: 'task' },
      };
      
      const action: Action = {
        name: 'read',
        attributes: { name: 'read' },
      };
      
      const decision = await engine.evaluate({ subject, resource, action, environment: { time: new Date() } });
      
      expect(decision.allowed).toBe(true);
    });

    it('should deny user write access to tasks', async () => {
      const subject: Subject = {
        id: 'user-2',
        type: 'user',
        attributes: { roles: ['user'] },
        roles: ['user'],
      };
      
      const resource: Resource = {
        id: 'task-1',
        type: 'task',
        attributes: { type: 'task' },
      };
      
      const action: Action = {
        name: 'delete',
        attributes: { name: 'delete' },
      };
      
      const decision = await engine.evaluate({ subject, resource, action, environment: { time: new Date() } });
      
      expect(decision.allowed).toBe(false);
    });

    it('should deny guest access', async () => {
      const subject: Subject = {
        id: 'guest-1',
        type: 'user',
        attributes: { roles: ['guest'] },
        roles: ['guest'],
      };
      
      const resource: Resource = {
        id: 'task-1',
        type: 'task',
        attributes: { type: 'task' },
      };
      
      const action: Action = {
        name: 'read',
        attributes: { name: 'read' },
      };
      
      const decision = await engine.evaluate({ subject, resource, action, environment: { time: new Date() } });
      
      expect(decision.allowed).toBe(false);
    });
  });

  describe('time-based conditions', () => {
    it('should deny access outside business hours', async () => {
      engine.addPolicy(
        new PolicyBuilder()
          .id('business-hours-only')
          .name('Business Hours Only')
          .allow()
          .environment('isBusinessHours', 'equals', true)
          .build()
      );

      // Create a date outside business hours (e.g., 2 AM)
      const nightTime = new Date();
      nightTime.setHours(2, 0, 0, 0);

      const subject: Subject = {
        id: 'user-1',
        type: 'user',
        attributes: { roles: ['user'] },
        roles: ['user'],
      };
      
      const resource: Resource = {
        id: 'sensitive-1',
        type: 'sensitive',
        attributes: { type: 'sensitive' },
      };
      
      const action: Action = {
        name: 'access',
        attributes: { name: 'access' },
      };
      
      const decision = await engine.evaluate({ 
        subject, 
        resource, 
        action, 
        environment: { time: nightTime, isBusinessHours: false } 
      });
      
      expect(decision.allowed).toBe(false);
    });
  });

  describe('obligations', () => {
    it('should include obligations in decision', async () => {
      engine.addPolicy(
        new PolicyBuilder()
          .id('log-access')
          .name('Log Access')
          .allow()
          .obligation('log', { level: 'info', message: 'Task accessed' })
          .build()
      );

      const subject: Subject = {
        id: 'user-1',
        type: 'user',
        attributes: { roles: ['user'] },
        roles: ['user'],
      };
      
      const resource: Resource = {
        id: 'task-1',
        type: 'task',
        attributes: { type: 'task' },
      };
      
      const action: Action = {
        name: 'read',
        attributes: { name: 'read' },
      };
      
      const decision = await engine.evaluate({ 
        subject, 
        resource, 
        action, 
        environment: { time: new Date() } 
      });
      
      expect(decision.allowed).toBe(true);
      expect(decision.obligations).toBeDefined();
      expect(decision.obligations).toHaveLength(1);
      expect(decision.obligations[0].type).toBe('log');
    });
  });
});

describe('PolicyBuilder', () => {
  it('should build a complete policy', () => {
    const policy = new PolicyBuilder()
      .id('test-policy')
      .name('Test Policy')
      .allow()
      .subject('roles', 'contains', 'admin')
      .resource('type', 'equals', 'task')
      .action('name', 'equals', 'create')
      .environment('region', 'in', ['us-east', 'us-west'])
      .obligation('audit', { action: 'log' })
      .priority(100)
      .build();
    
    expect(policy.id).toBe('test-policy');
    expect(policy.effect).toBe('allow');
    expect(policy.subjects).toHaveLength(1);
    expect(policy.resources).toHaveLength(1);
    expect(policy.actions).toHaveLength(1);
    expect(policy.environments).toHaveLength(1);
    expect(policy.obligations).toHaveLength(1);
    expect(policy.priority).toBe(100);
  });

  it('should create deny policy', () => {
    const policy = new PolicyBuilder()
      .id('deny-policy')
      .name('Deny Policy')
      .deny()
      .build();
    
    expect(policy.effect).toBe('deny');
  });
});

describe('DEFAULT_POLICIES', () => {
  it('should contain essential policies', () => {
    expect(DEFAULT_POLICIES.length).toBeGreaterThan(0);
    
    const policyIds = DEFAULT_POLICIES.map((p) => p.id);
    expect(policyIds).toContain('admin-full-access');
    expect(policyIds).toContain('user-task-access');
  });
});

