  const [cpuHistory, setCpuHistory] = useState<{ timestamp: Date; value: number }[]>([])
  const [costHistory, setCostHistory] = useState<{ timestamp: Date; value: number }[]>([])
  
  const intervalRef = useRef<ReturnType<typeof setInterval> | null>(null)
  const taskTimeoutsRef = useRef<Map<string, ReturnType<typeof setTimeout>>>(new Map())
  
  const addLog = useCallback((level: LogEntry['level'], source: string, message: string, metadata?: Record<string, unknown>) => {
    setLogs((prev) => {
      const newLog = createLogEntry(level, source, message, metadata)
      const updated = [newLog, ...prev]
      return updated.slice(0, MAX_LOGS)
    })
  }, [])
  
  const updateTaskStatus = useCallback((taskId: string, status: TaskStatus, updates?: Partial<Task>) => {
    setTasks((prev) => prev.map((task) => {
      if (task.id !== taskId) {return task}
      
      const updatedTask = { ...task, ...updates, status }
      
      if (status === 'running') {
        updatedTask.startedAt = new Date()
      } else if (status === 'completed' || status === 'failed') {
        updatedTask.completedAt = new Date()
      }
      
      return updatedTask
    }))
  }, [])
  
  const executeTask = useCallback((task: Task) => {
    if (task.target === 'edge' && task.nodeId) {
      setNodes((prev) => prev.map((node) => 
        node.id === task.nodeId 
          ? { ...node, tasksRunning: node.tasksRunning + 1 }
          : node
      ))
    }
    
    updateTaskStatus(task.id, 'running')
    addLog('info', 'Task Execution', `Task "${task.name}" started execution on ${task.target}`, { taskId: task.id })
    
    const timeout = setTimeout(() => {
      const shouldFail = Math.random() < FAILURE_RATE
      
      if (shouldFail) {
        updateTaskStatus(task.id, 'failed', { reason: 'Execution error: Task failed during processing' })
        addLog('error', 'Task Execution', `Task "${task.name}" failed during execution`, { taskId: task.id })
      } else {
        updateTaskStatus(task.id, 'completed')
        addLog('info', 'Task Execution', `Task "${task.name}" completed successfully`, { taskId: task.id })
      }
      
      if (task.target === 'edge' && task.nodeId) {
        setNodes((prev) => prev.map((node) => 
          node.id === task.nodeId 
            ? { ...node, tasksRunning: Math.max(0, node.tasksRunning - 1) }
            : node
        ))
      }
      
      taskTimeoutsRef.current.delete(task.id)
    }, task.duration)
    
    taskTimeoutsRef.current.set(task.id, timeout)
  }, [addLog, updateTaskStatus])
  
  const submitTask = useCallback((name: string, type: TaskType, priority: TaskPriority) => {
    try {
      const result = scheduleTask(name, type, priority, nodes, policy)
      
      setTasks((prev) => [...prev, result.task])
      setLogs((prev) => {
        const updated = [...result.logs, ...prev]
        return updated.slice(0, MAX_LOGS)
      })
      
      setTimeout(() => {
        executeTask(result.task)
      }, 100)
      
      return result.task
    } catch (error) {
      addLog('error', 'Scheduler', `Failed to schedule task: ${error instanceof Error ? error.message : 'Unknown error'}`)
      throw error
    }
  }, [nodes, policy, addLog, executeTask])
  
  const addNode = useCallback(() => {
    try {
      const newNodes = createInitialNodes(1)
      const newNode = { 
        ...newNodes[0], 
        id: generateId(),
        name: `edge-custom-${generateId().slice(0, 6)}`,
      }
      setNodes((prev) => [...prev, newNode])
      addLog('info', 'Node Management', `New node "${newNode.name}" registered at ${newNode.location}`, { nodeId: newNode.id })
    } catch (error) {
      addLog('error', 'Node Management', `Failed to add node: ${error instanceof Error ? error.message : 'Unknown error'}`)
    }
  }, [addLog])
  
  const removeNode = useCallback((nodeId: string) => {
    try {
      const node = nodes.find((n) => n.id === nodeId)
      if (!node) {
        addLog('warn', 'Node Management', `Node ${nodeId} not found`)
        return
      }
      
      if (node.tasksRunning > 0) {
        addLog('warn', 'Node Management', `Cannot remove node "${node.name}" - has ${node.tasksRunning} running tasks`)
        return
      }
      
      setNodes((prev) => prev.filter((n) => n.id !== nodeId))
      addLog('info', 'Node Management', `Node "${node.name}" deregistered`, { nodeId })
    } catch (error) {
      addLog('error', 'Node Management', `Failed to remove node: ${error instanceof Error ? error.message : 'Unknown error'}`)
    }
  }, [nodes, addLog])
  
  const updateNode = useCallback((nodeId: string, updates: Partial<EdgeNode>) => {
    try {
      setNodes((prev) => prev.map((node) => 
        node.id === nodeId ? { ...node, ...updates } : node
      ))
    } catch (error) {
      addLog('error', 'Node Management', `Failed to update node: ${error instanceof Error ? error.message : 'Unknown error'}`)
    }
  }, [addLog])
  
  const retryTask = useCallback((taskId: string) => {
    try {
      const task = tasks.find((t) => t.id === taskId)
      if (!task) {
        addLog('warn', 'Task Management', `Task ${taskId} not found`)
        return
      }
      
      if (task.status !== 'failed') {
        addLog('warn', 'Task Management', `Can only retry failed tasks`)
        return
      }
      
      if (task.retryCount >= task.maxRetries) {
        addLog('error', 'Task Management', `Task "${task.name}" exceeded max retries`)
        return
      }
      
      const retriedTask: Task = {
        ...task,
        id: generateId(),
        status: 'scheduled',
        retryCount: task.retryCount + 1,
        submittedAt: new Date(),
        completedAt: undefined,
        startedAt: undefined,
      }
      
      setTasks((prev) => [...prev, retriedTask])
      addLog('info', 'Task Management', `Retrying task "${task.name}" (attempt ${retriedTask.retryCount})`, { taskId: retriedTask.id })
      
      setTimeout(() => {
        executeTask(retriedTask)
      }, 100)
    } catch (error) {
      addLog('error', 'Task Management', `Failed to retry task: ${error instanceof Error ? error.message : 'Unknown error'}`)
    }
  }, [tasks, addLog, executeTask])
  
  const clearLogs = useCallback(() => {
    setLogs([])
    addLog('info', 'System', 'Logs cleared')
  }, [addLog])
  
  const runSimulation = useCallback(() => {
    try {
      setNodes((prevNodes) => {
        const { updatedNodes, logs: newLogs } = simulateNodeFluctuation(prevNodes)
        
        if (newLogs.length > 0) {
          setLogs((prev) => {
            const updated = [...newLogs, ...prev]
            return updated.slice(0, MAX_LOGS)
          })
        }
        
        return updatedNodes
      })
      
      if (Math.random() < AUTO_TASK_CHANCE) {
        const name = generateRandomTaskName()
        const type = getRandomTaskType()
        const priority = getRandomPriority()
        
        try {
          const result = scheduleTask(name, type, priority, nodes, policy)
          setTasks((prev) => [...prev, result.task])
          setLogs((prev) => {
            const updated = [...result.logs, ...prev]
            return updated.slice(0, MAX_LOGS)
          })
          
          setTimeout(() => {
            executeTask(result.task)
          }, 100)
        } catch (error) {
          console.error('Auto-task scheduling failed:', error)
        }
      }
    } catch (error) {
      addLog('error', 'Simulation', `Simulation error: ${error instanceof Error ? error.message : 'Unknown error'}`)
    }
  }, [nodes, policy, addLog, executeTask])
  
  useEffect(() => {
    if (isSimulating) {
      intervalRef.current = setInterval(runSimulation, SIMULATION_INTERVAL)
    }
    
    return () => {
      if (intervalRef.current) {
        clearInterval(intervalRef.current)
      }
    }
  }, [isSimulating, runSimulation])
  
  useEffect(() => {
    const avgCpu = nodes.length > 0 
      ? nodes.reduce((sum, n) => sum + n.cpu, 0) / nodes.length 
      : 0
    
    setCpuHistory((prev) => {
      const updated = [...prev, { timestamp: new Date(), value: avgCpu }]
      return updated.slice(-20)
    })
  }, [nodes])
  
  useEffect(() => {
    const totalCost = tasks.reduce((sum, t) => sum + t.cost, 0)
    setCostHistory((prev) => {
      const updated = [...prev, { timestamp: new Date(), value: totalCost }]
      return updated.slice(-50)
    })
  }, [tasks])
  
  useEffect(() => {
    return () => {
      taskTimeoutsRef.current.forEach((timeout) => clearTimeout(timeout))
      taskTimeoutsRef.current.clear()
    }
  }, [])
  
  const metrics = computeMetrics(nodes, tasks)
  
  return {
    nodes,
    tasks,
    logs,
    metrics,
    policy,
    isSimulating,
    cpuHistory,
    costHistory,
    setPolicy,
    setIsSimulating,
    submitTask,
    addNode,
    removeNode,
    updateNode,
    retryTask,
    clearLogs,
    addLog,
  }
}

import { useCallback,useEffect, useState } from 'react'

const STORAGE_KEY = 'edge-cloud-orchestrator'

interface PersistedState {
  theme: 'dark' | 'light'
  logRetentionSize: number
  autoScrollLogs: boolean
  updateInterval: number
  defaultPolicy: string
  dashboardTimeRange: string
  version: number
}

const DEFAULT_STATE: PersistedState = {
  theme: 'dark',
  logRetentionSize: 500,
  autoScrollLogs: true,
  updateInterval: 2000,
  defaultPolicy: 'latency-aware',
  dashboardTimeRange: '5m',
  version: 1,
}

export function usePersistentState() {
  const [state, setState] = useState<PersistedState>(DEFAULT_STATE)
  const [isLoaded, setIsLoaded] = useState(false)
  
  // Load from localStorage on mount
  useEffect(() => {
    try {
      const stored = localStorage.getItem(STORAGE_KEY)
      if (stored) {
        const parsed = JSON.parse(stored)
        setState({ ...DEFAULT_STATE, ...parsed })
      }
    } catch (error) {
      console.error('Failed to load persisted state:', error)
    }
    setIsLoaded(true)
  }, [])
  
  // Save to localStorage when state changes
  useEffect(() => {
    if (!isLoaded) {return}
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(state))
    } catch (error) {
      console.error('Failed to save persisted state:', error)
    }
  }, [state, isLoaded])
  
  const updateState = useCallback((updates: Partial<PersistedState>) => {
    setState((prev) => ({ ...prev, ...updates }))
  }, [])
  
  const resetState = useCallback(() => {
    setState(DEFAULT_STATE)
    localStorage.removeItem(STORAGE_KEY)
  }, [])
  
  return {
    state,
    isLoaded,
    updateState,
    resetState,
  }
}

export function useLocalStorage<T>(key: string, defaultValue: T): [T, (value: T | ((prev: T) => T)) => void] {
  const [value, setValue] = useState<T>(defaultValue)
  const [isLoaded, setIsLoaded] = useState(false)
  
  useEffect(() => {
    try {
      const stored = localStorage.getItem(key)
      if (stored) {
        setValue(JSON.parse(stored))
      }
    } catch (error) {
      console.error(`Failed to load ${key} from localStorage:`, error)
    }
    setIsLoaded(true)
  }, [key])
  
  useEffect(() => {
    if (!isLoaded) {return}
    try {
      localStorage.setItem(key, JSON.stringify(value))
    } catch (error) {
      console.error(`Failed to save ${key} to localStorage:`, error)
    }
  }, [key, value, isLoaded])
  
  const setStoredValue = useCallback((newValue: T | ((prev: T) => T)) => {
    setValue((prev) => {
      const valueToStore = newValue instanceof Function ? newValue(prev) : newValue
      return valueToStore
    })
  }, [])
  
  return [value, setStoredValue]
}

import { useCallback, useEffect,useRef, useState } from 'react'

import { metricsApi,nodesApi, tasksApi } from '../lib/api-simple'
import {
  transformMetricsFromApi,
  transformNodesFromApi,
  transformNodeToApi,
  transformTasksFromApi,
  transformTaskToApi} from '../lib/typeTransformers'
import { wsClient } from '../lib/websocketClient'

import type {
  EdgeNode,
  LogEntry,
  SchedulingPolicy,
  SystemMetrics,
  Task,
  TaskPriority,
  TaskType,
} from '../types'

const MAX_LOGS = 500
const POLLING_INTERVAL = 5000 // 5 seconds

interface OrchestratorState {
  nodes: EdgeNode[]
  tasks: Task[]
  logs: LogEntry[]
  metrics: SystemMetrics
  policy: SchedulingPolicy
  isLoading: boolean
  error: string | null
  cpuHistory: { timestamp: Date; value: number }[]
  isConnected: boolean
}

interface OrchestratorActions {
  setPolicy: (policy: SchedulingPolicy) => void
  submitTask: (name: string, type: TaskType, priority: TaskPriority) => Promise<boolean>
  addNode: (node: Partial<EdgeNode>) => Promise<boolean>
  removeNode: (nodeId: string) => Promise<boolean>
  updateNode: (nodeId: string, updates: Partial<EdgeNode>) => Promise<boolean>
  retryTask: (taskId: string) => Promise<boolean>
  cancelTask: (taskId: string) => Promise<boolean>
  clearLogs: () => void
  addLog: (level: LogEntry['level'], source: string, message: string, metadata?: Record<string, unknown>) => void
  refresh: () => Promise<void>
}

export function useRealOrchestrator(): OrchestratorState & OrchestratorActions {
  const [nodes, setNodes] = useState<EdgeNode[]>([])
  const [tasks, setTasks] = useState<Task[]>([])
  const [logs, setLogs] = useState<LogEntry[]>([])
  const [metrics, setMetrics] = useState<SystemMetrics>({
    totalNodes: 0,
    onlineNodes: 0,
    offlineNodes: 0,
    degradedNodes: 0,
    totalTasks: 0,
    runningTasks: 0,
    pendingTasks: 0,
    completedTasks: 0,
    failedTasks: 0,
    avgLatency: 0,
    totalCost: 0,
    edgeUtilization: 0,
    cloudUtilization: 0,
    throughput: 0,
    cpuHistory: [],
    taskDistribution: { edge: 0, cloud: 0 },
    healthScore: 100,
    completionRate: 0,
    costOverTime: [],
  })
  const [policy, setPolicy] = useState<SchedulingPolicy>('latency-aware')
  const [isLoading, setIsLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [cpuHistory, setCpuHistory] = useState<{ timestamp: Date; value: number }[]>([])

  const [isConnected, setIsConnected] = useState(false)
  
  const pollingRef = useRef<ReturnType<typeof setInterval> | null>(null)
  
  // Add log entry
  const addLog = useCallback((level: LogEntry['level'], source: string, message: string, metadata?: Record<string, unknown>) => {
    const newLog: LogEntry = {
      id: `log-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
      timestamp: new Date(),
      level,
      source,
      message,
      metadata,
    }
    setLogs((prev) => [newLog, ...prev].slice(0, MAX_LOGS))
  }, [])
  
  // Fetch all data from backend
  const fetchData = useCallback(async () => {
    try {
      const [nodesRes, tasksRes, metricsRes] = await Promise.all([
        nodesApi.list(),
        tasksApi.list(),
        metricsApi.getSystem(),
      ])
      
      if (nodesRes.data) {
        setNodes(transformNodesFromApi(nodesRes.data.data || []))
      }
      
      if (tasksRes.data) {
        setTasks(transformTasksFromApi(tasksRes.data.data || []))
      }
      
      if (metricsRes.data) {
        const transformedMetrics = transformMetricsFromApi(metricsRes.data)
        setMetrics(transformedMetrics)
        
        // Update CPU history
        setCpuHistory((prev) => {
          const cpuValue = transformedMetrics.cpuHistory?.length > 0 
            ? transformedMetrics.cpuHistory[transformedMetrics.cpuHistory.length - 1].value 
            : 0
          const newEntry = { timestamp: new Date(), value: cpuValue }
          return [...prev.slice(-59), newEntry]
        })
      }
      
      setError(null)
    } catch (err) {
      console.error('Failed to fetch data:', err)
      setError(err instanceof Error ? err.message : 'Failed to fetch data')
    }
  }, [])
  
  // Initial load and polling setup
  useEffect(() => {
    setIsLoading(true)
    fetchData().finally(() => setIsLoading(false))
    
    // Start polling
    pollingRef.current = setInterval(fetchData, POLLING_INTERVAL)
    
    // WebSocket subscriptions - setup after connection to avoid race condition
    let unsubNodes: (() => void) | null = null
    let unsubTasks: (() => void) | null = null
    let unsubConnect: (() => void) | null = null
    let unsubDisconnect: (() => void) | null = null
    
    const setupSubscriptions = async () => {
      // Wait for connection first
      await wsClient.connect()
      
      // Then subscribe to channels
      unsubNodes = wsClient.subscribe('nodes', (data: any) => {
        if (data.type === 'update') {
          setNodes((prev) => prev.map((n) => n.id === data.node.id ? transformNodesFromApi([data.node])[0] : n))
        } else if (data.type === 'create') {
          setNodes((prev) => [...prev, ...transformNodesFromApi([data.node])])
        } else if (data.type === 'delete') {
          setNodes((prev) => prev.filter((n) => n.id !== data.nodeId))
        }
      })
      
      unsubTasks = wsClient.subscribe('tasks', (data: any) => {
        if (data.type === 'update') {
          setTasks((prev) => prev.map((t) => t.id === data.task.id ? transformTasksFromApi([data.task])[0] : t))
        } else if (data.type === 'create') {
          setTasks((prev) => [...prev, ...transformTasksFromApi([data.task])])
        }
        addLog('info', 'Task Update', data.message || `Task ${data.task?.id} updated`)
      })
      
      unsubConnect = wsClient.onConnect(() => setIsConnected(true))
      unsubDisconnect = wsClient.onDisconnect(() => setIsConnected(false))
    }
    
    setupSubscriptions().catch(console.error)
    
    return () => {
      if (pollingRef.current) {clearInterval(pollingRef.current)}
      unsubNodes?.()
      unsubTasks?.()
      unsubConnect?.()
      unsubDisconnect?.()
      wsClient.disconnect()
    }
  }, [fetchData, addLog])
  
  // Submit task
  const submitTask = useCallback(async (name: string, type: TaskType, priority: TaskPriority): Promise<boolean> => {
    try {
      const taskData = transformTaskToApi({ name, type, priority })
      const response = await tasksApi.create(taskData)
      
      if (response.error) {
        addLog('error', 'Task Submission', `Failed to submit task: ${response.error}`)
        return false
      }
      
      addLog('info', 'Task Submission', `Task "${name}" submitted successfully`)
      await fetchData() // Refresh data
      return true
    } catch (err) {
      addLog('error', 'Task Submission', `Failed to submit task: ${err}`)
      return false
    }
  }, [addLog, fetchData])
  
  // Add node
  const addNode = useCallback(async (nodeData: Partial<EdgeNode>): Promise<boolean> => {
    try {
      const apiData = transformNodeToApi(nodeData)
      const response = await nodesApi.create(apiData)
      
      if (response.error) {
        addLog('error', 'Node Registration', `Failed to register node: ${response.error}`)
        return false
      }
      
      addLog('info', 'Node Registration', `Node "${nodeData.name}" registered successfully`)
      await fetchData()
      return true
    } catch (err) {
      addLog('error', 'Node Registration', `Failed to register node: ${err}`)
      return false
    }
  }, [addLog, fetchData])
  
  // Remove node
  const removeNode = useCallback(async (nodeId: string): Promise<boolean> => {
    try {
      const response = await nodesApi.delete(nodeId)
      
      if (response.error) {
        addLog('error', 'Node Removal', `Failed to remove node: ${response.error}`)
        return false
      }
      
      addLog('info', 'Node Removal', `Node removed successfully`)
      await fetchData()
      return true
    } catch (err) {
      addLog('error', 'Node Removal', `Failed to remove node: ${err}`)
      return false
    }
  }, [addLog, fetchData])
  
  // Update node
  const updateNode = useCallback(async (nodeId: string, updates: Partial<EdgeNode>): Promise<boolean> => {
    try {
      const response = await nodesApi.update(nodeId, updates)
      
      if (response.error) {
        addLog('error', 'Node Update', `Failed to update node: ${response.error}`)
        return false
      }
      
      addLog('info', 'Node Update', `Node updated successfully`)
      await fetchData()
      return true
    } catch (err) {
      addLog('error', 'Node Update', `Failed to update node: ${err}`)
      return false
    }
  }, [addLog, fetchData])
  
  // Retry task
  const retryTask = useCallback(async (taskId: string): Promise<boolean> => {
    try {
      const response = await tasksApi.retry(taskId)
      
      if (response.error) {
        addLog('error', 'Task Retry', `Failed to retry task: ${response.error}`)
        return false
      }
      
      addLog('info', 'Task Retry', `Task retry initiated`)
      await fetchData()
      return true
    } catch (err) {
      addLog('error', 'Task Retry', `Failed to retry task: ${err}`)
      return false
    }
  }, [addLog, fetchData])
  
  // Cancel task
  const cancelTask = useCallback(async (taskId: string): Promise<boolean> => {
    try {
      const response = await tasksApi.cancel(taskId)
      
      if (response.error) {
        addLog('error', 'Task Cancel', `Failed to cancel task: ${response.error}`)
        return false
      }
      
      addLog('info', 'Task Cancel', `Task cancelled successfully`)
      await fetchData()
      return true
    } catch (err) {
      addLog('error', 'Task Cancel', `Failed to cancel task: ${err}`)
      return false
    }
  }, [addLog, fetchData])
  
  // Clear logs
  const clearLogs = useCallback(() => {
    setLogs([])
  }, [])
  
  // Manual refresh
  const refresh = useCallback(async () => {
    setIsLoading(true)
    await fetchData()
    setIsLoading(false)
  }, [fetchData])
  
  return {
    // State
    nodes,
    tasks,
    logs,
    metrics,
    policy,
    isLoading,
    error,
    cpuHistory,

    isConnected,
    // Actions
    setPolicy,
    submitTask,
    addNode,
    removeNode,
    updateNode,
    retryTask,
    cancelTask,
    clearLogs,
    addLog,
    refresh,
  }
}

import { useCallback, useEffect,useState } from 'react'
import { toast } from 'sonner'

import { webhookManager } from '../lib/webhook'

import type { WebhookConfig, WebhookDelivery, WebhookEventType } from '../types/webhook'

export function useWebhooks() {
  const [webhooks, setWebhooks] = useState<WebhookConfig[]>([])
  const [deliveries, setDeliveries] = useState<WebhookDelivery[]>([])
  const [isLoading, setIsLoading] = useState(true)

  const loadWebhooks = useCallback(async () => {
    try {
      const data = await webhookManager.getWebhooks()
      setWebhooks(data)
    } catch (error) {
      toast.error('Failed to load webhooks')
      console.error(error)
    }
  }, [])

  const loadDeliveries = useCallback(async () => {
    try {
      const data = await webhookManager.getDeliveries(100)
      setDeliveries(data)
    } catch (error) {
      console.error('Failed to load deliveries:', error)
    }
  }, [])

  useEffect(() => {
    const load = async () => {
      setIsLoading(true)
      await Promise.all([loadWebhooks(), loadDeliveries()])
      setIsLoading(false)
    }
    load()
  }, [loadWebhooks, loadDeliveries])

  // Refresh deliveries periodically
  useEffect(() => {
    const interval = setInterval(loadDeliveries, 5000)
    return () => clearInterval(interval)
  }, [loadDeliveries])

  const createWebhook = useCallback(async (
    config: Omit<WebhookConfig, 'id' | 'createdAt' | 'updatedAt'>
  ): Promise<boolean> => {
    try {
      await webhookManager.createWebhook(config)
      await loadWebhooks()
      toast.success('Webhook created successfully')
      return true
    } catch (error) {
      toast.error('Failed to create webhook')
      console.error(error)
      return false
    }
  }, [loadWebhooks])

  const updateWebhook = useCallback(async (
    id: string,
    updates: Partial<WebhookConfig>
  ): Promise<boolean> => {
    try {
      await webhookManager.updateWebhook(id, updates)
      await loadWebhooks()
      toast.success('Webhook updated successfully')
      return true
    } catch (error) {
      toast.error('Failed to update webhook')
      console.error(error)
      return false
    }
  }, [loadWebhooks])

  const deleteWebhook = useCallback(async (id: string): Promise<boolean> => {
    try {
      await webhookManager.deleteWebhook(id)
      await loadWebhooks()
      toast.success('Webhook deleted successfully')
      return true
    } catch (error) {
      toast.error('Failed to delete webhook')
      console.error(error)
      return false
    }
  }, [loadWebhooks])

  const toggleWebhook = useCallback(async (id: string, enabled: boolean): Promise<void> => {
    await updateWebhook(id, { enabled })
  }, [updateWebhook])

  const retryDelivery = useCallback(async (deliveryId: string): Promise<void> => {
    try {
      await webhookManager.retryDelivery(deliveryId)
      await loadDeliveries()
      toast.success('Delivery queued for retry')
    } catch (error) {
      toast.error('Failed to retry delivery')
      console.error(error)
    }
  }, [loadDeliveries])

  const testWebhook = useCallback(async (webhookId: string): Promise<void> => {
    try {
      const webhook = await webhookManager.getWebhook(webhookId)
      if (!webhook) {
        toast.error('Webhook not found')
        return
      }

      await webhookManager.triggerEvent('metrics.updated', {
        nodesOnline: 5,
        totalNodes: 8,
        tasksCompleted: 100,
        tasksFailed: 2,
        avgLatency: 45.5,
        totalCost: 12.34,
        healthScore: 95,
      })

      toast.success('Test event sent')
      
      // Refresh deliveries after a short delay
      setTimeout(loadDeliveries, 1000)
    } catch (error) {
      toast.error('Failed to send test event')
      console.error(error)
    }
  }, [loadDeliveries])

  const stats = {
    total: webhooks.length,
    enabled: webhooks.filter((w) => w.enabled).length,
    recentDeliveries: deliveries.filter((d) => 
      d.createdAt > new Date(Date.now() - 24 * 60 * 60 * 1000)
    ).length,
    failedDeliveries: deliveries.filter((d) => d.status === 'failed').length,
  }

  return {
    webhooks,
    deliveries,
    isLoading,
    stats,
    createWebhook,
    updateWebhook,
    deleteWebhook,
    toggleWebhook,
    retryDelivery,
    testWebhook,
    refresh: loadWebhooks,
  }
}

// Hook to trigger webhook events from components
export function useWebhookTrigger() {
  const triggerEvent = useCallback(async (event: WebhookEventType, data: unknown) => {
    try {
      await webhookManager.triggerEvent(event, data)
    } catch (error) {
      console.error('Failed to trigger webhook event:', error)
    }
  }, [])

  return { triggerEvent }
}

