import { describe, expect, it, vi } from 'vitest'

import { Logger } from '../logger'

describe('Logger', () => {
  it('should log messages at or above min level', () => {
    const logger = new Logger({ minLevel: 'warn', enableStorage: true })

    logger.debug('debug message')
    logger.info('info message')
    logger.warn('warn message')
    logger.error('error message')

    const logs = logger.getLogs()
    expect(logs.length).toBe(2) // warn and error
    expect(logs[0].level).toBe('warn')
    expect(logs[1].level).toBe('error')
  })

  it('should include context in log entries', () => {
    const logger = new Logger({ minLevel: 'info', enableStorage: true })

    logger.info('test message', { key: 'value', count: 42 })

    const logs = logger.getLogs()
    expect(logs[0].context).toEqual({ key: 'value', count: 42 })
  })

  it('should include error in error entries', () => {
    const logger = new Logger({ minLevel: 'error', enableStorage: true })
    const error = new Error('test error')

    logger.error('error occurred', error, { context: 'test' })

    const logs = logger.getLogs()
    expect(logs[0].error).toBe(error)
  })

  it('should filter logs by level', () => {
    const logger = new Logger({ minLevel: 'debug', enableStorage: true })

    logger.debug('debug')
    logger.info('info')
    logger.warn('warn')
    logger.error('error')

    const errorLogs = logger.getLogs('error')
    expect(errorLogs.length).toBe(1)
    expect(errorLogs[0].level).toBe('error')
  })

  it('should limit returned logs', () => {
    const logger = new Logger({ minLevel: 'debug', enableStorage: true })

    for (let i = 0; i < 100; i++) {
      logger.info(`message ${i}`)
    }

    const logs = logger.getLogs(undefined, 10)
    expect(logs.length).toBe(10)
  })

  it('should notify subscribers', () => {
    const logger = new Logger({ minLevel: 'info' })
    const subscriber = vi.fn()

    logger.subscribe(subscriber)
    logger.info('test message')

    expect(subscriber).toHaveBeenCalledTimes(1)
    expect(subscriber).toHaveBeenCalledWith(expect.objectContaining({
      level: 'info',
      message: 'test message',
    }))
  })

  it('should unsubscribe correctly', () => {
    const logger = new Logger({ minLevel: 'info' })
    const subscriber = vi.fn()

    const unsubscribe = logger.subscribe(subscriber)
    logger.info('first')

    unsubscribe()
    logger.info('second')

    expect(subscriber).toHaveBeenCalledTimes(1)
  })

  it('should clear logs', () => {
    const logger = new Logger({ minLevel: 'info', enableStorage: true })

    logger.info('message 1')
    logger.info('message 2')
    expect(logger.getLogs().length).toBe(2)

    logger.clear()
    expect(logger.getLogs().length).toBe(0)
  })

  it('should export logs as JSON', () => {
    const logger = new Logger({ minLevel: 'info', enableStorage: true })

    logger.info('message 1', { key: 'value' })
    logger.error('message 2')

    const exported = logger.export()
    const parsed = JSON.parse(exported)

    expect(Array.isArray(parsed)).toBe(true)
    expect(parsed.length).toBe(2)
  })

  it('should limit storage entries', () => {
    const logger = new Logger({ minLevel: 'info', enableStorage: true, maxStorageEntries: 5 })

    for (let i = 0; i < 10; i++) {
      logger.info(`message ${i}`)
    }

    const logs = logger.getLogs()
    expect(logs.length).toBe(5)
    expect(logs[0].message).toBe('message 5')
  })
})

import { afterEach,beforeEach, describe, expect, it, vi } from 'vitest'

import { CircuitBreaker,RetryManager } from '../retry'

describe('RetryManager', () => {
  beforeEach(() => {
    vi.useFakeTimers()
  })

  afterEach(() => {
    vi.useRealTimers()
  })

  describe('execute', () => {
    it('should return result on first successful attempt', async () => {
      const retryManager = new RetryManager()
      const operation = vi.fn().mockResolvedValue('success')

      const result = await retryManager.execute(operation, 'test')

      expect(result).toBe('success')
      expect(operation).toHaveBeenCalledTimes(1)
    })

    it('should retry on retryable errors', async () => {
      const retryManager = new RetryManager({ maxAttempts: 3, initialDelayMs: 100 })
      const operation = vi.fn()
        .mockRejectedValueOnce(new Error('ECONNRESET'))
        .mockRejectedValueOnce(new Error('ETIMEDOUT'))
        .mockResolvedValue('success')

      const resultPromise = retryManager.execute(operation, 'test')

      // Fast-forward through delays
      await vi.runAllTimersAsync()

      const result = await resultPromise
      expect(result).toBe('success')
      expect(operation).toHaveBeenCalledTimes(3)
    })

    it('should throw after max attempts', async () => {
      const retryManager = new RetryManager({ maxAttempts: 2, initialDelayMs: 100 })
      const operation = vi.fn().mockRejectedValue(new Error('ECONNRESET'))

      const resultPromise = retryManager.execute(operation, 'test')
      await vi.runAllTimersAsync()

      await expect(resultPromise).rejects.toThrow('ECONNRESET')
      expect(operation).toHaveBeenCalledTimes(2)
    })

    it('should not retry non-retryable errors', async () => {
      const retryManager = new RetryManager()
      const operation = vi.fn().mockRejectedValue(new Error('ValidationError'))

      await expect(retryManager.execute(operation, 'test')).rejects.toThrow('ValidationError')
      expect(operation).toHaveBeenCalledTimes(1)
    })

    it('should call onRetry callback', async () => {
      const onRetry = vi.fn()
      const retryManager = new RetryManager({ maxAttempts: 3, initialDelayMs: 100, onRetry })
      const operation = vi.fn()
        .mockRejectedValueOnce(new Error('ECONNRESET'))
        .mockResolvedValue('success')

      const resultPromise = retryManager.execute(operation, 'test')
      await vi.runAllTimersAsync()

      await resultPromise
      expect(onRetry).toHaveBeenCalledTimes(1)
      expect(onRetry).toHaveBeenCalledWith(1, expect.any(Error), expect.any(Number))
    })

    it('should use exponential backoff', async () => {
      const retryManager = new RetryManager({
        maxAttempts: 4,
        initialDelayMs: 1000,
        backoffMultiplier: 2,
      })
      const operation = vi.fn()
        .mockRejectedValueOnce(new Error('ECONNRESET'))
        .mockRejectedValueOnce(new Error('ECONNRESET'))
        .mockRejectedValueOnce(new Error('ECONNRESET'))
        .mockResolvedValue('success')

      const resultPromise = retryManager.execute(operation, 'test')

      // Run all timers to complete
      await vi.runAllTimersAsync()

      const result = await resultPromise
      expect(result).toBe('success')
      expect(operation).toHaveBeenCalledTimes(4)
    })
  })
})

describe('CircuitBreaker', () => {
  it('should start in CLOSED state', () => {
    const cb = new CircuitBreaker()
    expect(cb.canExecute()).toBe(true)
    expect(cb.getState().state).toBe('CLOSED')
  })

  it('should open after failure threshold', () => {
    const cb = new CircuitBreaker({ failureThreshold: 3 })

    cb.recordFailure()
    cb.recordFailure()
    expect(cb.canExecute()).toBe(true)

    cb.recordFailure()
    expect(cb.canExecute()).toBe(false)
    expect(cb.getState().state).toBe('OPEN')
  })

  it('should reject requests when OPEN', () => {
    const cb = new CircuitBreaker({ failureThreshold: 1 })

    cb.recordFailure()
    expect(cb.canExecute()).toBe(false)
  })

  it('should transition to HALF_OPEN after timeout', async () => {
    const cb = new CircuitBreaker({ failureThreshold: 1, timeoutMs: 1000 })

    cb.recordFailure()
    expect(cb.canExecute()).toBe(false)

    // Wait for timeout
    await new Promise((resolve) => setTimeout(resolve, 1100))

    expect(cb.canExecute()).toBe(true)
    expect(cb.getState().state).toBe('HALF_OPEN')
  })

  it('should close after success threshold in HALF_OPEN', async () => {
    const cb = new CircuitBreaker({ failureThreshold: 1, successThreshold: 2, timeoutMs: 100 })
  
    cb.recordFailure()
    expect(cb.getState().state).toBe('OPEN')
  
    // Wait for timeout to transition to HALF_OPEN
    await new Promise((resolve) => setTimeout(resolve, 150))
    expect(cb.canExecute()).toBe(true) // Now in HALF_OPEN
  
    cb.recordSuccess() // First success in HALF_OPEN
    cb.recordSuccess() // Second success should close
  
    expect(cb.getState().state).toBe('CLOSED')
  })

  it('should reopen on failure in HALF_OPEN', () => {
    const cb = new CircuitBreaker({ failureThreshold: 1, successThreshold: 2 })

    cb.recordFailure()
    expect(cb.getState().state).toBe('OPEN')

    // First success transitions to HALF_OPEN
    // Failure should reopen
    cb.recordFailure()

    expect(cb.getState().state).toBe('OPEN')
  })

  it('should reset failure count on success', () => {
    const cb = new CircuitBreaker({ failureThreshold: 3 })

    cb.recordFailure()
    cb.recordFailure()
    expect(cb.getState().failureCount).toBe(2)

    cb.recordSuccess()
    expect(cb.getState().failureCount).toBe(0)
  })
})

import { describe, expect,it } from 'vitest'

import { array, number, sanitize, string, validateInput,Validator } from '../validation'

describe('Validation', () => {
  describe('String validators', () => {
    it('should validate required strings', () => {
      const rule = string.required()
      expect(rule.validate('test')).toBe(true)
      expect(rule.validate('')).toBe(false)
      expect(rule.validate('   ')).toBe(false)
    })

    it('should validate min length', () => {
      const rule = string.minLength(3)
      expect(rule.validate('ab')).toBe(false)
      expect(rule.validate('abc')).toBe(true)
      expect(rule.validate('abcd')).toBe(true)
    })

    it('should validate max length', () => {
      const rule = string.maxLength(5)
      expect(rule.validate('abcdef')).toBe(false)
      expect(rule.validate('abcde')).toBe(true)
      expect(rule.validate('ab')).toBe(true)
    })

    it('should validate email format', () => {
      const rule = string.email()
      expect(rule.validate('test@example.com')).toBe(true)
      expect(rule.validate('invalid')).toBe(false)
      expect(rule.validate('test@')).toBe(false)
    })

    it('should validate URL format', () => {
      const rule = string.url()
      expect(rule.validate('https://example.com')).toBe(true)
      expect(rule.validate('http://localhost:3000')).toBe(true)
      expect(rule.validate('not-a-url')).toBe(false)
    })

    it('should validate pattern matches', () => {
      const rule = string.matches(/^[A-Z]{2}\d{4}$/)
      expect(rule.validate('AB1234')).toBe(true)
      expect(rule.validate('ab1234')).toBe(false)
    })

    it('should validate oneOf', () => {
      const rule = string.oneOf(['active', 'inactive', 'pending'])
      expect(rule.validate('active')).toBe(true)
      expect(rule.validate('unknown')).toBe(false)
    })
  })

  describe('Number validators', () => {
    it('should validate required numbers', () => {
      const rule = number.required()
      expect(rule.validate(42)).toBe(true)
      expect(rule.validate(0)).toBe(true)
      expect(rule.validate(NaN)).toBe(false)
    })

    it('should validate min value', () => {
      const rule = number.min(10)
      expect(rule.validate(5)).toBe(false)
      expect(rule.validate(10)).toBe(true)
      expect(rule.validate(15)).toBe(true)
    })

    it('should validate max value', () => {
      const rule = number.max(100)
      expect(rule.validate(150)).toBe(false)
      expect(rule.validate(100)).toBe(true)
      expect(rule.validate(50)).toBe(true)
    })

    it('should validate integer', () => {
      const rule = number.integer()
      expect(rule.validate(42)).toBe(true)
      expect(rule.validate(42.5)).toBe(false)
    })

    it('should validate positive', () => {
      const rule = number.positive()
      expect(rule.validate(1)).toBe(true)
      expect(rule.validate(0)).toBe(false)
      expect(rule.validate(-1)).toBe(false)
    })
  })

  describe('Array validators', () => {
    it('should validate required arrays', () => {
      const rule = array.required()
      expect(rule.validate([1, 2, 3])).toBe(true)
      expect(rule.validate([])).toBe(false)
    })

    it('should validate min length', () => {
      const rule = array.minLength(2)
      expect(rule.validate([1])).toBe(false)
      expect(rule.validate([1, 2])).toBe(true)
    })

    it('should validate max length', () => {
      const rule = array.maxLength(3)
      expect(rule.validate([1, 2, 3, 4])).toBe(false)
      expect(rule.validate([1, 2, 3])).toBe(true)
    })
  })

  describe('Validator class', () => {
    interface TestUser {
      name: string
      age: number
      email: string
    }

    it('should validate valid data', () => {
      const validator = new Validator<TestUser>({
        name: [string.required(), string.minLength(2)],
        age: [number.required(), number.min(0), number.max(150)],
        email: [string.required(), string.email()],
      })

      const result = validator.validate({
        name: 'John',
        age: 30,
        email: 'john@example.com',
      })

      expect(result.valid).toBe(true)
      expect(result.errors).toEqual({})
    })

    it('should return errors for invalid data', () => {
      const validator = new Validator<TestUser>({
        name: [string.required(), string.minLength(2)],
        age: [number.required(), number.min(0), number.max(150)],
        email: [string.required(), string.email()],
      })

      const result = validator.validate({
        name: 'J',
        age: -5,
        email: 'invalid',
      })

      expect(result.valid).toBe(false)
      expect(result.errors.name).toBeDefined()
      expect(result.errors.age).toBeDefined()
      expect(result.errors.email).toBeDefined()
    })

    it('should validate single field', () => {
      const validator = new Validator<TestUser>({
        name: [string.required(), string.minLength(2)],
      })

      const errors = validator.validateField('name', 'J')
      expect(errors.length).toBeGreaterThan(0)

      const validErrors = validator.validateField('name', 'John')
      expect(validErrors.length).toBe(0)
    })
  })

  describe('Sanitization', () => {
    it('should sanitize strings', () => {
      expect(sanitize.string('  hello  ')).toBe('hello')
      expect(sanitize.string('<script>')).toBe('script')
    })

    it('should sanitize HTML', () => {
      expect(sanitize.html('<div>test</div>')).toBe('&lt;div&gt;test&lt;/div&gt;')
    })

    it('should sanitize email', () => {
      expect(sanitize.email('  TEST@EXAMPLE.COM  ')).toBe('test@example.com')
    })

    it('should sanitize URL', () => {
      expect(sanitize.url('https://example.com/path')).toBe('https://example.com/path')
      expect(sanitize.url('invalid')).toBe('')
    })
  })

  describe('validateInput helper', () => {
    interface LoginData {
      email: string
      password: string
    }

    it('should validate and return data', () => {
      const validate = validateInput<LoginData>({
        email: [string.required(), string.email()],
        password: [string.required(), string.minLength(8)],
      })

      const result = validate({
        email: 'test@example.com',
        password: 'password123',
      })

      expect(result.valid).toBe(true)
      expect(result.data).toBeDefined()
    })

    it('should return errors for invalid input', () => {
      const validate = validateInput<LoginData>({
        email: [string.required(), string.email()],
        password: [string.required(), string.minLength(8)],
      })

      const result = validate({
        email: 'invalid',
        password: 'short',
      })

      expect(result.valid).toBe(false)
      expect(result.errors).toBeDefined()
    })

    it('should reject non-object input', () => {
      const validate = validateInput<LoginData>({
        email: [string.required()],
      })

      const result = validate(null)
      expect(result.valid).toBe(false)
      expect(result.errors).toContain('Input must be an object')
    })
  })
})

import axios from 'axios'
import type { AxiosError,AxiosInstance, AxiosResponse } from 'axios'

interface AgentConnection {
  client: AxiosInstance
  lastUsed: number
  failureCount: number
  isHealthy: boolean
}

interface PoolConfig {
  maxConnections?: number
  connectionTimeout?: number
  keepAliveDuration?: number
  maxFailures?: number
}

const DEFAULT_CONFIG: PoolConfig = {
  maxConnections: 10,
  connectionTimeout: 5000,
  keepAliveDuration: 30000,
  maxFailures: 3
}

class AgentConnectionPool {
  private pools: Map<string, AgentConnection> = new Map()
  private config: PoolConfig

  constructor(config: PoolConfig = {}) {
    this.config = { ...DEFAULT_CONFIG, ...config }
    this.startCleanupInterval()
  }

  private getClient(agentUrl: string): AxiosInstance {
    let connection = this.pools.get(agentUrl)

    if (!connection || !connection.isHealthy) {
      connection = this.createConnection(agentUrl)
      this.pools.set(agentUrl, connection)
    }

    connection.lastUsed = Date.now()
    return connection.client
  }

  private createConnection(agentUrl: string): AgentConnection {
    const client = axios.create({
      baseURL: agentUrl,
      timeout: this.config.connectionTimeout,
      headers: {
        'Connection': 'keep-alive',
        'Keep-Alive': `timeout=${this.config.keepAliveDuration! / 1000}`
      }
    })

    // Add response interceptor for health tracking
    client.interceptors.response.use(
      (response: AxiosResponse) => {
        this.recordSuccess(agentUrl)
        return response
      },
      (error: AxiosError) => {
        this.recordFailure(agentUrl)
        return Promise.reject(error)
      }
    )

    return {
      client,
      lastUsed: Date.now(),
      failureCount: 0,
      isHealthy: true
    }
  }

  private recordSuccess(agentUrl: string) {
    const connection = this.pools.get(agentUrl)
    if (connection) {
      connection.failureCount = 0
      connection.isHealthy = true
    }
  }

  private recordFailure(agentUrl: string) {
    const connection = this.pools.get(agentUrl)
    if (connection) {
      connection.failureCount++
      if (connection.failureCount >= this.config.maxFailures!) {
        connection.isHealthy = false
      }
    }
  }

  async executeWithRetry<T>(
    agentUrl: string,
    operation: (client: AxiosInstance) => Promise<T>,
    retries = 3
  ): Promise<T> {
    const delays = [1000, 2000, 4000] // Exponential backoff

    for (let i = 0; i <= retries; i++) {
      try {
        const client = this.getClient(agentUrl)
        return await operation(client)
      } catch (error) {
        if (i === retries) {throw error}
        
        await this.delay(delays[i] || 4000)
        
        // Mark connection as unhealthy after failure
        const connection = this.pools.get(agentUrl)
        if (connection) {
          connection.isHealthy = false
        }
      }
    }

    throw new Error(`Failed after ${retries} retries`)
  }

  async getHealth(agentUrl: string): Promise<{ healthy: boolean; latency: number }> {
    const start = Date.now()
    try {
      const client = this.getClient(agentUrl)
      await client.get('/health', { timeout: 2000 })
      return { healthy: true, latency: Date.now() - start }
    } catch {
      return { healthy: false, latency: Date.now() - start }
    }
  }

  async executeTask(agentUrl: string, taskData: unknown): Promise<unknown> {
    return this.executeWithRetry(agentUrl, async (client) => {
      const response = await client.post('/run-task', taskData)
      return response.data
    })
  }

  async getMetrics(agentUrl: string): Promise<unknown> {
    return this.executeWithRetry(agentUrl, async (client) => {
      const response = await client.get('/metrics')
      return response.data
    }, 1) // Only 1 retry for metrics
  }

  private delay(ms: number): Promise<void> {
    return new Promise((resolve) => setTimeout(resolve, ms))
  }

  private startCleanupInterval() {
    setInterval(() => {
      const now = Date.now()
      const staleThreshold = this.config.keepAliveDuration! * 2

      for (const [url, connection] of this.pools.entries()) {
        // Remove stale connections
        if (now - connection.lastUsed > staleThreshold) {
          this.pools.delete(url)
        }
      }
    }, 60000) // Cleanup every minute
  }

  getPoolStats(): { total: number; healthy: number; unhealthy: number } {
    let healthy = 0
    let unhealthy = 0

    for (const connection of this.pools.values()) {
      if (connection.isHealthy) {healthy++}
      else {unhealthy++}
    }

    return {
      total: this.pools.size,
      healthy,
      unhealthy
    }
  }

  resetPool(agentUrl?: string) {
    if (agentUrl) {
      this.pools.delete(agentUrl)
    } else {
      this.pools.clear()
    }
  }
}

// Singleton instance
export const agentPool = new AgentConnectionPool()

export default AgentConnectionPool

/**
 * AI-Powered Anomaly Detection
 * Detect anomalies in system metrics using ML models
 */

import { logger } from '../logger'

// Types
export interface AnomalyDetectorConfig {
  sensitivity: 'low' | 'medium' | 'high'
  windowSize: number
  minDataPoints: number
  threshold: number
  algorithms: ('isolation-forest' | 'autoencoder' | 'statistical' | 'lstm')[]
}

export interface MetricDataPoint {
  timestamp: number
  value: number
  labels: Record<string, string>
}

export interface Anomaly {
  id: string
  type: 'spike' | 'drop' | 'trend-change' | 'outlier' | 'pattern-break'
  severity: 'low' | 'medium' | 'high' | 'critical'
  metric: string
  entityId: string
  entityType: 'node' | 'task' | 'cluster' | 'network'
  detectedAt: number
  value: number
  expectedValue: number
  deviation: number
  confidence: number
  context: Record<string, unknown>
  rootCause?: string
  recommendations: string[]
  status: 'active' | 'investigating' | 'resolved' | 'ignored'
}

export interface AnomalyModel {
  id: string
  name: string
  metric: string
  algorithm: string
  trainedAt: number
  dataPoints: number
  accuracy: number
  falsePositiveRate: number
  parameters: Record<string, unknown>
}

export interface AnomalyBaseline {
  metric: string
  entityId: string
  mean: number
  stdDev: number
  min: number
  max: number
  percentiles: { p5: number; p25: number; p50: number; p75: number; p95: number }
  seasonality?: { period: number; amplitude: number }
  trend?: { direction: 'up' | 'down' | 'stable'; slope: number }
  lastUpdated: number
}

type AnomalyEvent = 'anomaly.detected' | 'anomaly.resolved' | 'model.trained' | 'baseline.updated'
type AnomalyCallback = (event: AnomalyEvent, data: unknown) => void

const DEFAULT_CONFIG: AnomalyDetectorConfig = {
  sensitivity: 'medium',
  windowSize: 100,
  minDataPoints: 30,
  threshold: 2.5,
  algorithms: ['statistical', 'isolation-forest'],
}

/**
 * AI-Powered Anomaly Detector
 */
export class AIAnomalyDetector {
  private config: AnomalyDetectorConfig
  private baselines: Map<string, AnomalyBaseline> = new Map()
  private anomalies: Map<string, Anomaly> = new Map()
  private models: Map<string, AnomalyModel> = new Map()
  private metricHistory: Map<string, MetricDataPoint[]> = new Map()
  private callbacks: Map<AnomalyEvent, Set<AnomalyCallback>> = new Map()

  constructor(config: Partial<AnomalyDetectorConfig> = {}) {
    this.config = { ...DEFAULT_CONFIG, ...config }
  }

  /**
   * Ingest metric data point
   */
  ingestMetric(metric: string, entityId: string, value: number, labels: Record<string, string> = {}): void {
    const key = `${metric}:${entityId}`
    
    if (!this.metricHistory.has(key)) {
      this.metricHistory.set(key, [])
    }

    const history = this.metricHistory.get(key)!
    history.push({
      timestamp: Date.now(),
      value,
      labels,
    })

    // Trim to window size
    if (history.length > this.config.windowSize) {
      history.shift()
    }

    // Check for anomalies
    this.detectAnomalies(metric, entityId, value)
  }

  /**
   * Detect anomalies in metric
   */
  private detectAnomalies(metric: string, entityId: string, value: number): void {
    const key = `${metric}:${entityId}`
    const history = this.metricHistory.get(key) || []
    
    if (history.length < this.config.minDataPoints) {
      return
    }

    const baseline = this.getOrCreateBaseline(key, history)
    const deviation = Math.abs(value - baseline.mean) / Math.max(baseline.stdDev, 0.001)

    // Get sensitivity threshold
    const thresholds = { low: 3.5, medium: 2.5, high: 1.5 }
    const threshold = thresholds[this.config.sensitivity]

    if (deviation > threshold) {
      // Determine anomaly type
      const anomalyType = this.classifyAnomalyType(value, baseline, history)
      
      // Calculate confidence
      const confidence = Math.min(1, deviation / threshold / 2)

      // Determine severity
      const severity = this.determineSeverity(deviation, confidence, metric)

      const anomaly: Anomaly = {
        id: `anomaly-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
        type: anomalyType,
        severity,
        metric,
        entityId,
        entityType: this.inferEntityType(metric),
        detectedAt: Date.now(),
        value,
        expectedValue: baseline.mean,
        deviation,
        confidence,
        context: {
          baseline: baseline.mean,
          stdDev: baseline.stdDev,
          historyLength: history.length,
        },
        recommendations: this.generateRecommendations(metric, anomalyType, severity, deviation),
        status: 'active',
      }

      this.anomalies.set(anomaly.id, anomaly)
      this.emit('anomaly.detected', anomaly)

      logger.warn('Anomaly detected', {
        anomalyId: anomaly.id,
        type: anomalyType,
        metric,
        entityId,
        value,
        expectedValue: baseline.mean,
        deviation: deviation.toFixed(2),
      })
    }
  }

  /**
   * Get or create baseline for metric
   */
  private getOrCreateBaseline(key: string, history: MetricDataPoint[]): AnomalyBaseline {
    let baseline = this.baselines.get(key)
    
    if (!baseline || history.length % 10 === 0) {
      const values = history.map((h) => h.value)
      const mean = values.reduce((s, v) => s + v, 0) / values.length
      const variance = values.reduce((s, v) => s + Math.pow(v - mean, 2), 0) / values.length
      const stdDev = Math.sqrt(variance)

      const sorted = [...values].sort((a, b) => a - b)
      
      baseline = {
        metric: key.split(':')[0],
        entityId: key.split(':')[1],
        mean,
        stdDev,
        min: sorted[0] || 0,
        max: sorted[sorted.length - 1] || 0,
        percentiles: {
          p5: sorted[Math.floor(sorted.length * 0.05)] || 0,
          p25: sorted[Math.floor(sorted.length * 0.25)] || 0,
          p50: sorted[Math.floor(sorted.length * 0.5)] || 0,
          p75: sorted[Math.floor(sorted.length * 0.75)] || 0,
          p95: sorted[Math.floor(sorted.length * 0.95)] || 0,
        },
        lastUpdated: Date.now(),
      }

      this.baselines.set(key, baseline)
      this.emit('baseline.updated', baseline)
    }

    return baseline
  }

  /**
   * Classify anomaly type
   */
  private classifyAnomalyType(value: number, baseline: AnomalyBaseline, history: MetricDataPoint[]): Anomaly['type'] {
    const recent = history.slice(-10)
    const recentAvg = recent.reduce((s, h) => s + h.value, 0) / recent.length

    // Check for spike/drop
    if (value > baseline.percentiles.p95 * 1.5) {return 'spike'}
    if (value < baseline.percentiles.p5 * 0.5) {return 'drop'}

    // Check for trend change
    if (recent.length >= 5) {
      const older = history.slice(-20, -10)
      const olderAvg = older.reduce((s, h) => s + h.value, 0) / older.length
      const change = Math.abs(recentAvg - olderAvg) / Math.max(olderAvg, 0.001)
      
      if (change > 0.3) {return 'trend-change'}
    }

    // Check for pattern break
    if (baseline.seasonality && Math.abs(value - baseline.mean) > baseline.seasonality.amplitude * 2) {
      return 'pattern-break'
    }

    return 'outlier'
  }

  /**
   * Determine severity
   */
  private determineSeverity(deviation: number, confidence: number, metric: string): Anomaly['severity'] {
    // Critical metrics
    const criticalMetrics = ['cpu', 'memory', 'error_rate', 'latency']
    const isCriticalMetric = criticalMetrics.some((m) => metric.includes(m))

    if (deviation > 5 && confidence > 0.8 && isCriticalMetric) {return 'critical'}
    if (deviation > 4 && confidence > 0.7) {return 'high'}
    if (deviation > 3 && confidence > 0.5) {return 'medium'}
    return 'low'
  }

  /**
   * Infer entity type from metric
   */
  private inferEntityType(metric: string): Anomaly['entityType'] {
    if (metric.includes('node') || metric.includes('cpu') || metric.includes('memory')) {return 'node'}
    if (metric.includes('task') || metric.includes('job')) {return 'task'}
    if (metric.includes('cluster')) {return 'cluster'}
    if (metric.includes('network') || metric.includes('latency')) {return 'network'}
    return 'node'
  }

  /**
   * Generate recommendations
   */
  private generateRecommendations(
    metric: string,
    type: Anomaly['type'],
    severity: Anomaly['severity'],
    _deviation: number
  ): string[] {
    const recommendations: string[] = []

    if (metric.includes('cpu')) {
      if (type === 'spike') {
        recommendations.push('Investigate runaway processes')
        recommendations.push('Consider scaling horizontally')
      } else if (type === 'drop') {
        recommendations.push('Consider consolidating workloads')
        recommendations.push('Review scaling policies')
      }
    }

    if (metric.includes('memory')) {
      if (type === 'spike') {
        recommendations.push('Check for memory leaks')
        recommendations.push('Review recent deployments')
      }
    }

    if (metric.includes('latency')) {
      recommendations.push('Check network connectivity')
      recommendations.push('Review load balancer configuration')
      recommendations.push('Analyze recent traffic patterns')
    }

    if (metric.includes('error')) {
      recommendations.push('Review application logs')
      recommendations.push('Check downstream dependencies')
      recommendations.push('Verify recent configuration changes')
    }

    if (severity === 'critical') {
      recommendations.unshift('Immediate investigation required')
      recommendations.push('Consider triggering automated remediation')
    }

    return recommendations
  }

  /**
   * Train ML model for metric
   */
  async trainModel(metric: string, entityId: string, algorithm: string = 'isolation-forest'): Promise<AnomalyModel> {
    const key = `${metric}:${entityId}`
    const history = this.metricHistory.get(key) || []

    if (history.length < this.config.minDataPoints) {
      throw new Error(`Insufficient data points: ${history.length} < ${this.config.minDataPoints}`)
    }

    // Simulate model training
    await new Promise((resolve) => setTimeout(resolve, 100))

    const modelId = `model-${metric}-${entityId}-${Date.now()}`

    const model: AnomalyModel = {
      id: modelId,
      name: `${algorithm}-${metric}`,
      metric: key,
      algorithm,
      trainedAt: Date.now(),
      dataPoints: history.length,
      accuracy: 0.85 + Math.random() * 0.1,
      falsePositiveRate: 0.05 + Math.random() * 0.05,
      parameters: {
        contamination: 0.1,
        nEstimators: 100,
        windowSize: this.config.windowSize,
      },
    }

    this.models.set(modelId, model)
    this.emit('model.trained', model)

    logger.info('Anomaly model trained', { modelId, metric, entityId, algorithm, accuracy: model.accuracy.toFixed(2) })

    return model
  }

  /**
   * Resolve anomaly
   */
  resolveAnomaly(anomalyId: string, resolution: string): boolean {
    const anomaly = this.anomalies.get(anomalyId)
    if (!anomaly) {return false}

    anomaly.status = 'resolved'
    anomaly.rootCause = resolution

    this.emit('anomaly.resolved', { anomalyId, resolution })
    return true
  }

  /**
   * Get anomalies
   */
  getAnomalies(status?: Anomaly['status'], severity?: Anomaly['severity']): Anomaly[] {
    let results = Array.from(this.anomalies.values())
    
    if (status) {results = results.filter((a) => a.status === status)}
    if (severity) {results = results.filter((a) => a.severity === severity)}
    
    return results.sort((a, b) => b.detectedAt - a.detectedAt)
  }

  /**
   * Get baseline
   */
  getBaseline(metric: string, entityId: string): AnomalyBaseline | undefined {
    return this.baselines.get(`${metric}:${entityId}`)
  }

  /**
   * Get model
   */
  getModel(modelId: string): AnomalyModel | undefined {
    return this.models.get(modelId)
  }

  /**
   * Get statistics
   */
  getStats(): {
    totalAnomalies: number
    activeAnomalies: number
    resolvedAnomalies: number
    bySeverity: Record<Anomaly['severity'], number>
    byType: Record<Anomaly['type'], number>
    modelsTrained: number
    baselinesTracked: number
  } {
    const bySeverity: Record<Anomaly['severity'], number> = { low: 0, medium: 0, high: 0, critical: 0 }
    const byType: Record<Anomaly['type'], number> = { spike: 0, drop: 0, 'trend-change': 0, outlier: 0, 'pattern-break': 0 }

    let active = 0
    let resolved = 0

    for (const anomaly of this.anomalies.values()) {
      bySeverity[anomaly.severity]++
      byType[anomaly.type]++
      if (anomaly.status === 'active') {active++}
      if (anomaly.status === 'resolved') {resolved++}
    }

    return {
      totalAnomalies: this.anomalies.size,
      activeAnomalies: active,
      resolvedAnomalies: resolved,
      bySeverity,
      byType,
      modelsTrained: this.models.size,
      baselinesTracked: this.baselines.size,
    }
  }

  /**
   * Subscribe to events
   */
  on(event: AnomalyEvent, callback: AnomalyCallback): () => void {
    if (!this.callbacks.has(event)) {
      this.callbacks.set(event, new Set())
    }
    this.callbacks.get(event)!.add(callback)

    return () => {
      this.callbacks.get(event)?.delete(callback)
    }
  }

  private emit(event: AnomalyEvent, data: unknown): void {
    this.callbacks.get(event)?.forEach((cb) => {
      try {
        cb(event, data)
      } catch (error) {
        logger.error('Anomaly detector callback error', error as Error)
      }
    })
  }
}

