      costPerHour: 0.02,
      bandwidthIn: 50,
      bandwidthOut: 50,
      healthHistory: [],
      isMaintenanceMode: false,
      ...nodeData,
    } as EdgeNode
    
    const stored = localStorage.getItem('api_nodes')
    const nodes = stored ? JSON.parse(stored) : []
    nodes.push(newNode)
    localStorage.setItem('api_nodes', JSON.stringify(nodes))
    
    return {
      success: true,
      data: newNode,
