    const stored = localStorage.getItem('api_nodes')
    if (!stored) {
      return {
        success: false,
        error: 'Node not found',
        timestamp: new Date().toISOString(),
      }
    }
    
    const nodes = JSON.parse(stored)
    const filtered = nodes.filter((n: EdgeNode) => n.id !== nodeId)
