    return {
      success: true,
      timestamp: new Date().toISOString(),
    }
  },

  // Tasks
  async getTasks(): Promise<ApiResponse<Task[]>> {
    await simulateNetworkDelay()
    
    const stored = localStorage.getItem('api_tasks')
    const tasks = stored ? JSON.parse(stored) : []
    
    return {
      success: true,
      data: tasks,
      timestamp: new Date().toISOString(),
    }
  },

  async createTask(
    name: string,
    type: TaskType,
    priority: TaskPriority,
    policy: SchedulingPolicy
  ): Promise<ApiResponse<Task>> {
    await simulateNetworkDelay()
    
    const newTask: Task = {
      id: generateId(),
      name,
      type,
      status: 'pending',
      target: 'edge',
      priority,
      submittedAt: new Date(),
      duration: Math.floor(Math.random() * 3000) + 500,
      cost: Math.random() * 0.001,
      latencyMs: Math.random() * 100,
      reason: `Created via API with ${policy} policy`,
      retryCount: 0,
      maxRetries: 3,
    }
    
    const stored = localStorage.getItem('api_tasks')
    const tasks = stored ? JSON.parse(stored) : []
    tasks.push(newTask)
    localStorage.setItem('api_tasks', JSON.stringify(tasks))
    
    return {
      success: true,
      data: newTask,
      timestamp: new Date().toISOString(),
    }
  },

  // Logs
  async getLogs(limit = 100): Promise<ApiResponse<LogEntry[]>> {
    await simulateNetworkDelay()
    
    const stored = localStorage.getItem('api_logs')
    const logs = stored ? JSON.parse(stored).slice(-limit) : []
    
    return {
      success: true,
      data: logs,
      timestamp: new Date().toISOString(),
    }
  },

  // Metrics
  async getMetrics(): Promise<ApiResponse<{
    totalNodes: number
    onlineNodes: number
    totalTasks: number
    completedTasks: number
    failedTasks: number
    avgLatency: number
    totalCost: number
  }>> {
    await simulateNetworkDelay()
    
    const nodesStored = localStorage.getItem('api_nodes')
    const tasksStored = localStorage.getItem('api_tasks')
    
    const nodes = nodesStored ? JSON.parse(nodesStored) : []
    const tasks = tasksStored ? JSON.parse(tasksStored) : []
    
    const metrics = {
      totalNodes: nodes.length,
      onlineNodes: nodes.filter((n: EdgeNode) => n.status === 'online').length,
      totalTasks: tasks.length,
      completedTasks: tasks.filter((t: Task) => t.status === 'completed').length,
      failedTasks: tasks.filter((t: Task) => t.status === 'failed').length,
      avgLatency: nodes.length > 0 
        ? nodes.reduce((sum: number, n: EdgeNode) => sum + (n.latency || 0), 0) / nodes.length 
        : 0,
      totalCost: tasks.reduce((sum: number, t: Task) => sum + (t.cost || 0), 0),
    }
    
    return {
      success: true,
      data: metrics,
      timestamp: new Date().toISOString(),
    }
  },

  // Health check
  async healthCheck(): Promise<ApiResponse<{ status: string; version: string }>> {
    await simulateNetworkDelay()
    
    return {
      success: true,
      data: {
        status: 'healthy',
        version: '1.0.0',
      },
      timestamp: new Date().toISOString(),
    }
  },
}

// WebSocket client - uses real WebSocket when available, simulation otherwise
import { wsLogger as logger } from './logger'
import { websocketPool } from './websocket-pool'

export class WebSocketClient {
  private callbacks: Map<string, ((data: unknown) => void)[]> = new Map()
  private isConnected = false
  private reconnectInterval: ReturnType<typeof setInterval> | null = null
  private connectionId: string | null = null
  private realWsUrl: string | null = null
  private useRealWs = false

  constructor(wsUrl?: string) {
    // Check if a real WebSocket URL is provided
    this.realWsUrl = wsUrl || null
    this.useRealWs = !!wsUrl
  }

  async connect() {
    if (this.useRealWs && this.realWsUrl) {
      try {
        // Use real WebSocket pool
        this.connectionId = await websocketPool.acquire(this.realWsUrl)
        this.isConnected = true
        logger.info('Connected to real WebSocket', { url: this.realWsUrl })
        
        // Subscribe to all registered events
        this.callbacks.forEach((_, event) => {
          websocketPool.subscribe(this.connectionId!, event, (data: unknown) => {
            this.emit(event, data)
          })
        })
      } catch (error) {
        logger.error('Failed to connect to real WebSocket, falling back to simulation', error as Error)
        this.useRealWs = false
        this.startSimulation()
      }
    } else {
      this.startSimulation()
    }
  }

  private startSimulation() {
    this.isConnected = true
    logger.info('Using WebSocket simulation')
    
    // Simulate periodic updates
    this.reconnectInterval = setInterval(() => {
      this.emit('metrics', { timestamp: new Date().toISOString() })
    }, 2000)
  }

  disconnect() {
    if (this.useRealWs && this.connectionId) {
      websocketPool.release(this.connectionId)
      this.connectionId = null
    } else if (this.reconnectInterval) {
      clearInterval(this.reconnectInterval)
      this.reconnectInterval = null
    }
    this.isConnected = false
    logger.info('Disconnected')
  }

  on(event: string, callback: (data: unknown) => void) {
    if (!this.callbacks.has(event)) {
      this.callbacks.set(event, [])
    }
    this.callbacks.get(event)?.push(callback)

    // If using real WebSocket and already connected, subscribe to this event
    if (this.useRealWs && this.connectionId) {
      websocketPool.subscribe(this.connectionId, event, (data: unknown) => {
        callback(data)
      })
    }
  }

  off(event: string, callback: (data: unknown) => void) {
    const callbacks = this.callbacks.get(event)
    if (callbacks) {
      const index = callbacks.indexOf(callback)
      if (index > -1) {
        callbacks.splice(index, 1)
      }
    }
  }

  private emit(event: string, data: unknown) {
    const callbacks = this.callbacks.get(event)
    callbacks?.forEach((cb) => {
      try {
        cb(data)
      } catch (error) {
        logger.error('Error in callback', error as Error)
      }
    })
  }

  send(data: unknown): boolean {
    if (!this.isConnected) {return false}
    
    if (this.useRealWs && this.connectionId) {
      return websocketPool.send(this.connectionId, data)
    }
    
    // Simulation mode - just log
    logger.debug('Send (simulation)', { data })
    return true
  }

  isOpen() {
    return this.isConnected
  }

  // Get WebSocket pool stats
  getPoolStats() {
    return websocketPool.getStats()
  }
}

// Create WebSocket client - will use real WebSocket if VITE_WS_URL env is set
const wsUrl = import.meta.env?.VITE_WS_URL as string | undefined
export const wsClient = new WebSocketClient(wsUrl)

/**
 * Production API Endpoints for Edge-Cloud Orchestrator
 * Handles node registration, metrics, and cluster management
 */

import type { EdgeNode, Task } from '../../types'
import { agentAuthManager } from '../auth/AgentAuth'
import { leaderElection } from '../cluster/leaderElection'
import { discoveryService,nodeRegistry } from '../discovery/nodeRegistry'
import { logger } from '../logger'
import { metricsExporter } from '../metrics/exporter'
import { geoRouter } from '../routing/geoRouter'

// Types
export interface APIRequest {
  method: string
  path: string
  headers: Record<string, string>
  body?: unknown
  query: Record<string, string>
}

export interface APIResponse {
  status: number
  headers: Record<string, string>
  body: unknown
}

export interface RouteHandler {
  (req: APIRequest): Promise<APIResponse>
}

export interface APIConfig {
  requireAuth: boolean
  corsOrigins: string[]
  rateLimit: number
}

const DEFAULT_CONFIG: APIConfig = {
  requireAuth: true,
  corsOrigins: ['*'],
  rateLimit: 100,
}

/**
 * API Router
 */
export class APIRouter {
  private routes: Map<string, Map<string, RouteHandler>> = new Map()
  // @ts-expect-error - Config used for future features
  private config: APIConfig
  private middleware: Array<(req: APIRequest) => Promise<APIRequest | null>> = []

  constructor(config: Partial<APIConfig> = {}) {
    this.config = { ...DEFAULT_CONFIG, ...config }
    this.setupDefaultRoutes()
  }

  /**
   * Setup default routes
   */
  private setupDefaultRoutes(): void {
    // Health check
    this.get('/health', this.healthCheck.bind(this))
    
    // Node registration
    this.post('/nodes/register', this.registerNode.bind(this))
    this.post('/nodes/heartbeat', this.nodeHeartbeat.bind(this))
    this.delete('/nodes/:nodeId', this.deregisterNode.bind(this))
    this.get('/nodes', this.getNodes.bind(this))
    this.get('/nodes/:nodeId', this.getNode.bind(this))
    
    // Metrics
    this.get('/metrics', this.getMetrics.bind(this))
    this.get('/metrics/json', this.getMetricsJSON.bind(this))
    
    // Cluster
    this.get('/cluster/status', this.getClusterStatus.bind(this))
    this.get('/cluster/leader', this.getLeader.bind(this))
    
    // Geo-routing
    this.post('/routing/select', this.selectNode.bind(this))
    this.get('/routing/nearby', this.getNearbyNodes.bind(this))
    
    // Auth
    this.post('/auth/api-key', this.generateApiKey.bind(this))
    this.post('/auth/jwt', this.generateJWT.bind(this))
  }

  /**
   * Register route
   */
  private register(method: string, path: string, handler: RouteHandler): void {
    if (!this.routes.has(path)) {
      this.routes.set(path, new Map())
    }
    this.routes.get(path)!.set(method.toUpperCase(), handler)
  }

  get(path: string, handler: RouteHandler): void {
    this.register('GET', path, handler)
  }

  post(path: string, handler: RouteHandler): void {
    this.register('POST', path, handler)
  }

  put(path: string, handler: RouteHandler): void {
    this.register('PUT', path, handler)
  }

  delete(path: string, handler: RouteHandler): void {
    this.register('DELETE', path, handler)
  }

  /**
   * Add middleware
   */
  use(middleware: (req: APIRequest) => Promise<APIRequest | null>): void {
    this.middleware.push(middleware)
  }

  /**
   * Handle request
   */
  async handle(req: APIRequest): Promise<APIResponse> {
    try {
      // Run middleware
      for (const mw of this.middleware) {
        const result = await mw(req)
        if (result === null) {
          return this.error(401, 'Unauthorized')
        }
        req = result
      }

      // Find route
      const pathRoutes = this.routes.get(req.path)
      if (!pathRoutes) {
        // Try pattern matching
        const matchedRoute = this.matchRoute(req.path, req.method)
        if (matchedRoute) {
          return await matchedRoute.handler(req)
        }
        return this.error(404, 'Not Found')
      }

      const handler = pathRoutes.get(req.method)
      if (!handler) {
        return this.error(405, 'Method Not Allowed')
      }

      return await handler(req)
    } catch (error) {
      logger.error('API error', error as Error, { path: req.path, method: req.method })
      return this.error(500, 'Internal Server Error')
    }
  }

  /**
   * Match route with parameters
   */
  private matchRoute(path: string, method: string): { handler: RouteHandler; params: Record<string, string> } | null {
    for (const [routePath, methods] of this.routes) {
      const params = this.matchPath(routePath, path)
      if (params !== null && methods.has(method)) {
        return {
          handler: methods.get(method)!,
          params,
        }
      }
    }
    return null
  }

  /**
   * Match path pattern
   */
  private matchPath(pattern: string, path: string): Record<string, string> | null {
    const patternParts = pattern.split('/')
    const pathParts = path.split('/')
    
    if (patternParts.length !== pathParts.length) {return null}
    
    const params: Record<string, string> = {}
    
    for (let i = 0; i < patternParts.length; i++) {
      if (patternParts[i].startsWith(':')) {
        params[patternParts[i].slice(1)] = pathParts[i]
      } else if (patternParts[i] !== pathParts[i]) {
        return null
      }
    }
    
    return params
  }

  /**
   * Response helpers
   */
  private json(status: number, body: unknown): APIResponse {
    return {
      status,
      headers: {
        'Content-Type': 'application/json',
        'Access-Control-Allow-Origin': '*',
      },
      body,
    }
  }

  private error(status: number, message: string): APIResponse {
    return this.json(status, { error: message })
  }

  // Route handlers

  private async healthCheck(): Promise<APIResponse> {
    return this.json(200, {
      status: 'healthy',
      timestamp: new Date().toISOString(),
      version: '1.0.0',
    })
  }

  private async registerNode(req: APIRequest): Promise<APIResponse> {
    const body = req.body as {
      nodeId: string
      ip: string
      location: string
      region: string
      cpuCores: number
      memory: number
      storage: number
      dockerVersion: string
      capabilities?: string[]
      tags?: Record<string, string>
      latitude?: number
      longitude?: number
    }

    if (!body.nodeId || !body.ip) {
      return this.error(400, 'Missing required fields: nodeId, ip')
    }

    try {
      const result = await discoveryService.handleRegistration(body)
      
      if (result.success && result.node) {
        // Register geo info if provided
        if (body.latitude !== undefined && body.longitude !== undefined) {
          geoRouter.registerNode(body.nodeId, {
            nodeId: body.nodeId,
            location: { latitude: body.latitude, longitude: body.longitude },
            region: body.region,
            zone: body.region, // Use region as zone
            networkLatency: 0,
          })
        }
        
        return this.json(201, result.node)
      }
      
      return this.error(400, result.error || 'Registration failed')
    } catch (error) {
      return this.error(500, (error as Error).message)
    }
  }

  private async nodeHeartbeat(req: APIRequest): Promise<APIResponse> {
    const body = req.body as {
      nodeId: string
      cpu: number
      memory: number
      storage: number
      tasksRunning: number
      latency: number
    }

    if (!body.nodeId) {
      return this.error(400, 'Missing required field: nodeId')
    }

    const result = await discoveryService.handleHeartbeat({
      ...body,
      timestamp: Date.now(),
    })

    if (result.success) {
      return this.json(200, { acknowledged: true })
    }
    
    return this.error(400, result.error || 'Heartbeat failed')
  }

  private async deregisterNode(req: APIRequest): Promise<APIResponse> {
    const params = req.query as { nodeId: string }
    const {nodeId} = params
    
    if (!nodeId) {
      return this.error(400, 'Missing nodeId')
    }

    const result = await discoveryService.handleDeregistration(nodeId)
    
    if (result.success) {
      return this.json(200, { deregistered: true })
    }
    
    return this.error(400, result.error || 'Deregistration failed')
  }

  private async getNodes(): Promise<APIResponse> {
    const nodes = nodeRegistry.getAllNodes()
    return this.json(200, { nodes, count: nodes.length })
  }

  private async getNode(req: APIRequest): Promise<APIResponse> {
    const params = req.query as { nodeId: string }
    const node = nodeRegistry.getNode(params.nodeId)
    
    if (!node) {
      return this.error(404, 'Node not found')
    }
    
    return this.json(200, node)
  }

  private async getMetrics(): Promise<APIResponse> {
    const { contentType, body } = metricsExporter.getPrometheusMetrics()
    return {
      status: 200,
      headers: {
        'Content-Type': contentType,
      },
      body,
    }
  }

  private async getMetricsJSON(): Promise<APIResponse> {
    const { body } = metricsExporter.getJSONMetrics()
    return {
      status: 200,
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.parse(body),
    }
  }

  private async getClusterStatus(): Promise<APIResponse> {
    const nodeStats = nodeRegistry.getStats()
    const leaderState = leaderElection.getState()
    
    return this.json(200, {
      nodes: nodeStats,
      leadership: {
        isLeader: leaderState.isLeader,
        leaderId: leaderState.leaderId,
        term: leaderState.term,
      },
    })
  }

  private async getLeader(): Promise<APIResponse> {
    const state = leaderElection.getState()
    return this.json(200, {
      leaderId: state.leaderId,
      isLeader: state.isLeader,
      term: state.term,
    })
  }

  private async selectNode(req: APIRequest): Promise<APIResponse> {
    const body = req.body as {
      task: Task
      nodes: EdgeNode[]
      userLatitude?: number
      userLongitude?: number
    }

    if (!body.task || !body.nodes) {
      return this.error(400, 'Missing required fields: task, nodes')
    }

    const userLocation = body.userLatitude !== undefined && body.userLongitude !== undefined
      ? { latitude: body.userLatitude, longitude: body.userLongitude }
      : undefined

    const result = geoRouter.selectNode(body.task, body.nodes, userLocation)
    
    return this.json(200, result)
  }

  private async getNearbyNodes(req: APIRequest): Promise<APIResponse> {
    const query = req.query as {
      latitude: string
      longitude: string
      radiusKm: string
    }

    const latitude = parseFloat(query.latitude)
    const longitude = parseFloat(query.longitude)
    const radiusKm = parseFloat(query.radiusKm) || 100

    if (isNaN(latitude) || isNaN(longitude)) {
      return this.error(400, 'Invalid latitude or longitude')
    }

    const nodes = nodeRegistry.getAllNodes().map((r) => nodeRegistry.toEdgeNode(r))
    const nearby = geoRouter.getNodesWithinRadius(nodes, { latitude, longitude }, radiusKm)
    
    return this.json(200, { nodes: nearby, count: nearby.length })
  }

  private async generateApiKey(req: APIRequest): Promise<APIResponse> {
    const body = req.body as {
      agentId: string
      permissions?: string[]
    }

    if (!body.agentId) {
      return this.error(400, 'Missing required field: agentId')
    }

    const result = agentAuthManager.generateApiKey(body.agentId, body.permissions)
    
    return this.json(201, {
      id: result.id,
      key: result.key,
      message: 'Store this key securely. It will not be shown again.',
    })
  }

  private async generateJWT(req: APIRequest): Promise<APIResponse> {
    const body = req.body as {
      agentId: string
      nodeId: string
      location: string
      permissions?: string[]
    }

    if (!body.agentId || !body.nodeId) {
      return this.error(400, 'Missing required fields: agentId, nodeId')
    }

    const result = await agentAuthManager.generateJWT(
      body.agentId,
      body.nodeId,
      body.location || 'unknown',
      body.permissions || ['task:execute', 'metrics:report']
    )
    
    return this.json(201, {
      token: result.token,
      expiresAt: new Date(result.expiresAt).toISOString(),
    })
  }
}

/**
 * Authentication Middleware
 */
export async function authMiddleware(req: APIRequest): Promise<APIRequest | null> {
  // Skip auth for health endpoint
  if (req.path === '/health') {
    return req
  }

  const authHeader = req.headers['authorization'] || req.headers['Authorization']
  
  if (!authHeader) {
    return null
  }

  const result = await agentAuthManager.authenticate(req.headers, JSON.stringify(req.body))
  
  if (!result.authenticated) {
    return null
  }

  // Attach auth info to request
  return {
    ...req,
    headers: {
      ...req.headers,
      'x-auth-agent-id': result.agentId || '',
      'x-auth-permissions': (result.permissions || []).join(','),
    },
  }
}

/**
 * CORS Middleware
 */
export function corsMiddleware(_origins: string[] = ['*']): (req: APIRequest) => Promise<APIRequest> {
  return async (req: APIRequest) => {
    // Just pass through - CORS headers are added in response
    return req
  }
}

/**
 * Rate Limiter
 */
export class RateLimiter {
  private requests: Map<string, number[]> = new Map()
  private limit: number
  private windowMs: number

  constructor(limit: number = 100, windowMs: number = 60000) {
    this.limit = limit
    this.windowMs = windowMs
  }

  async check(clientId: string): Promise<boolean> {
    const now = Date.now()
    const requests = this.requests.get(clientId) || []
    
    // Filter out old requests
    const validRequests = requests.filter((t) => now - t < this.windowMs)
    
    if (validRequests.length >= this.limit) {
      return false
    }
    
    validRequests.push(now)
    this.requests.set(clientId, validRequests)
    
    return true
  }
}

// Factory functions
export function createAPIRouter(config: Partial<APIConfig> = {}): APIRouter {
  return new APIRouter(config)
}

export function createRateLimiter(limit: number, windowMs: number): RateLimiter {
  return new RateLimiter(limit, windowMs)
}

// Default instance
export const apiRouter = new APIRouter()

/**
 * Edge Agent Authentication Module
 * Implements mTLS, JWT tokens, and API key authentication
 */

import { logger } from '../logger'

// Types
export interface AgentCredentials {
  agentId: string
  apiKey: string
  publicKey?: string
  certificate?: string
}

export interface JWTClaims {
  sub: string        // Agent ID
  iss: string        // Issuer (orchestrator)
  aud: string        // Audience (edge-agent)
  exp: number        // Expiration timestamp
  iat: number        // Issued at timestamp
  jti: string        // JWT ID
  permissions: string[]
  nodeId: string
  location: string
}

export interface AuthResult {
  authenticated: boolean
  agentId?: string
  permissions?: string[]
  error?: string
  token?: string
  expiresAt?: number
}

export interface ApiKeyRecord {
  id: string
  agentId: string
  keyHash: string
  prefix: string
  permissions: string[]
  createdAt: Date
  lastUsed: Date
  expiresAt?: Date
  rateLimit: number
  enabled: boolean
}

export interface MTLSConfig {
  caCertificate: string
  verifyClient: boolean
  verifyDepth: number
  allowExpired: boolean
}

// AuthMethod types for documentation
// type AuthMethod = 'api-key' | 'jwt' | 'mtls' | 'hmac'

const API_KEY_PREFIX = 'ec_'
const JWT_ISSUER = 'edge-cloud-orchestrator'
const JWT_AUDIENCE = 'edge-agent'
const JWT_EXPIRY = 3600 // 1 hour
const HMAC_ALGORITHM = 'SHA-256'

/**
 * Authentication Manager for Edge Agents
 */
export class AgentAuthManager {
  private apiKeys: Map<string, ApiKeyRecord> = new Map()
  private jwtSecret: string
  private mtlsConfig: MTLSConfig
  private revokedTokens: Set<string> = new Set()
  private nonceCache: Map<string, number> = new Map()

  constructor(config?: { jwtSecret?: string; mtlsConfig?: Partial<MTLSConfig> }) {
    this.jwtSecret = config?.jwtSecret || this.generateSecret()
    this.mtlsConfig = {
      caCertificate: '',
      verifyClient: true,
      verifyDepth: 2,
      allowExpired: false,
      ...config?.mtlsConfig,
    }

    // Start cleanup interval
    this.startCleanup()
  }

  /**
   * Generate API Key for an agent
   */
  generateApiKey(agentId: string, permissions: string[] = ['task:execute', 'metrics:report']): { id: string; key: string } {
    const id = `key-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`
    const keyBytes = new Uint8Array(32)
    crypto.getRandomValues(keyBytes)
    const key = `${API_KEY_PREFIX}${this.base64Encode(keyBytes)}`
    
    const record: ApiKeyRecord = {
      id,
      agentId,
      keyHash: this.hashKey(key),
      prefix: key.substring(0, 10),
      permissions,
      createdAt: new Date(),
      lastUsed: new Date(),
      rateLimit: 100, // requests per minute
      enabled: true,
    }

    this.apiKeys.set(id, record)
    logger.info('API key generated', { agentId, keyId: id, permissions })

    return { id, key }
  }

  /**
   * Validate API Key
   */
  async validateApiKey(authHeader: string): Promise<AuthResult> {
    if (!authHeader.startsWith('Bearer ')) {
      return { authenticated: false, error: 'Invalid authorization header format' }
    }

    const key = authHeader.substring(7)
    
    if (!key.startsWith(API_KEY_PREFIX)) {
      return { authenticated: false, error: 'Invalid API key format' }
    }

    const keyHash = this.hashKey(key)
    
    for (const [, record] of this.apiKeys) {
      if (record.keyHash === keyHash) {
        if (!record.enabled) {
          return { authenticated: false, error: 'API key is disabled' }
        }

        if (record.expiresAt && record.expiresAt < new Date()) {
          return { authenticated: false, error: 'API key has expired' }
        }

        // Update last used
        record.lastUsed = new Date()

        return {
          authenticated: true,
          agentId: record.agentId,
          permissions: record.permissions,
        }
      }
    }

    return { authenticated: false, error: 'Invalid API key' }
  }

  /**
   * Generate JWT Token for an agent
   */
  async generateJWT(agentId: string, nodeId: string, location: string, permissions: string[]): Promise<{ token: string; expiresAt: number }> {
    const now = Math.floor(Date.now() / 1000)
    const jti = `${agentId}-${now}-${Math.random().toString(36).substr(2, 9)}`

    const claims: JWTClaims = {
      sub: agentId,
      iss: JWT_ISSUER,
      aud: JWT_AUDIENCE,
      exp: now + JWT_EXPIRY,
      iat: now,
      jti,
      permissions,
      nodeId,
      location,
    }

    const token = await this.signJWT(claims)

    return {
      token,
      expiresAt: claims.exp * 1000,
    }
  }

  /**
   * Validate JWT Token
   */
  async validateJWT(authHeader: string): Promise<AuthResult> {
    if (!authHeader.startsWith('Bearer ')) {
      return { authenticated: false, error: 'Invalid authorization header format' }
    }

    const token = authHeader.substring(7)

    // Check if revoked
    if (this.revokedTokens.has(token)) {
      return { authenticated: false, error: 'Token has been revoked' }
    }

    try {
      const claims = await this.verifyJWT(token)

      if (claims.exp < Date.now() / 1000) {
        return { authenticated: false, error: 'Token has expired' }
      }

      if (claims.iss !== JWT_ISSUER) {
        return { authenticated: false, error: 'Invalid token issuer' }
      }

      if (claims.aud !== JWT_AUDIENCE) {
        return { authenticated: false, error: 'Invalid token audience' }
      }

      return {
        authenticated: true,
        agentId: claims.sub,
        permissions: claims.permissions,
        token,
        expiresAt: claims.exp * 1000,
      }
    } catch (error) {
      return { authenticated: false, error: `Token verification failed: ${(error as Error).message}` }
    }
  }

  /**
   * Validate HMAC Signature (for webhook-style auth)
   */
  async validateHMAC(
    signature: string,
    timestamp: string,
    nonce: string,
    body: string,
    agentId: string
  ): Promise<AuthResult> {
    // Check timestamp (prevent replay attacks)
    const ts = parseInt(timestamp, 10)
    const now = Date.now()
    const maxDrift = 300000 // 5 minutes

    if (isNaN(ts) || Math.abs(now - ts) > maxDrift) {
      return { authenticated: false, error: 'Timestamp drift too large' }
    }

    // Check nonce (prevent replay)
    if (this.nonceCache.has(nonce)) {
      return { authenticated: false, error: 'Nonce already used' }
    }

    this.nonceCache.set(nonce, ts)

    // Find agent's API key
    let apiKey: ApiKeyRecord | null = null
    for (const record of this.apiKeys.values()) {
      if (record.agentId === agentId) {
        apiKey = record
        break
      }
    }

    if (!apiKey) {
      return { authenticated: false, error: 'Agent not found' }
    }

    // Verify signature
    const expectedSignature = await this.generateHMACSignature(
      `${timestamp}.${nonce}.${body}`,
      apiKey.keyHash
    )

    if (signature !== expectedSignature) {
      return { authenticated: false, error: 'Invalid HMAC signature' }
    }

    return {
      authenticated: true,
      agentId,
      permissions: apiKey.permissions,
    }
  }

  /**
   * Validate mTLS Certificate
   */
  validateMTLS(certificate: string, expectedAgentId: string): AuthResult {
    if (!this.mtlsConfig.verifyClient) {
      return { authenticated: true, agentId: expectedAgentId }
    }

    try {
      // Parse certificate (simplified - in production use proper X.509 parsing)
      const certInfo = this.parseCertificate(certificate)

      if (!certInfo) {
        return { authenticated: false, error: 'Invalid certificate format' }
      }

      // Check expiration
      if (!this.mtlsConfig.allowExpired && certInfo.expiresAt < Date.now()) {
        return { authenticated: false, error: 'Certificate has expired' }
      }

      // Verify agent ID matches certificate CN
      if (certInfo.commonName !== expectedAgentId) {
        return { authenticated: false, error: 'Certificate CN does not match agent ID' }
      }

      return {
        authenticated: true,
        agentId: expectedAgentId,
        permissions: ['task:execute', 'metrics:report', 'health:check'],
      }
    } catch (error) {
      return { authenticated: false, error: `Certificate validation failed: ${(error as Error).message}` }
    }
  }

  /**
   * Revoke a JWT token
   */
  revokeToken(token: string): void {
    this.revokedTokens.add(token)
    logger.warn('Token revoked', { tokenPrefix: token.substring(0, 20) })
  }

  /**
   * Revoke all tokens for an agent
   */
  revokeAgentTokens(agentId: string): void {
    for (const [id, record] of this.apiKeys) {
      if (record.agentId === agentId) {
        record.enabled = false
        logger.warn('API key disabled', { agentId, keyId: id })
      }
    }
  }

  /**
   * Unified authentication - tries multiple methods
   */
  async authenticate(
    headers: Record<string, string>,
    body?: string
  ): Promise<AuthResult> {
    const authHeader = headers['authorization'] || headers['Authorization']
    const signature = headers['x-signature']
    const timestamp = headers['x-timestamp']
    const nonce = headers['x-nonce']
    const agentId = headers['x-agent-id']
    const clientCert = headers['x-client-cert']

    // Try mTLS first (highest security)
    if (clientCert && agentId) {
      const result = this.validateMTLS(clientCert, agentId)
      if (result.authenticated) {
        return result
      }
    }

    // Try JWT
    if (authHeader && authHeader.split('.').length === 3) {
      const result = await this.validateJWT(authHeader)
      if (result.authenticated) {
        return result
      }
    }

    // Try HMAC signature
    if (signature && timestamp && nonce && body && agentId) {
      const result = await this.validateHMAC(signature, timestamp, nonce, body, agentId)
      if (result.authenticated) {
        return result
      }
    }

    // Try API Key
    if (authHeader) {
      const result = await this.validateApiKey(authHeader)
      if (result.authenticated) {
        return result
      }
    }

    return { authenticated: false, error: 'No valid authentication method found' }
  }

  // Private helper methods

  private generateSecret(): string {
    const bytes = new Uint8Array(32)
    crypto.getRandomValues(bytes)
    return this.base64Encode(bytes)
  }

  private hashKey(key: string): string {
    // Simple hash for demo - in production use proper hashing
    let hash = 0
    for (let i = 0; i < key.length; i++) {
      const char = key.charCodeAt(i)
      hash = ((hash << 5) - hash) + char
      hash = hash & hash
    }
    return hash.toString(16)
  }

  private base64Encode(bytes: Uint8Array): string {
    return btoa(String.fromCharCode(...bytes))
      .replace(/\+/g, '-')
      .replace(/\//g, '_')
      .replace(/=/g, '')
  }

  private async signJWT(claims: JWTClaims): Promise<string> {
    const header = { alg: 'HS256', typ: 'JWT' }
    const headerB64 = btoa(JSON.stringify(header))
    const payloadB64 = btoa(JSON.stringify(claims))
    
    const signature = await this.generateHMACSignature(
      `${headerB64}.${payloadB64}`,
      this.jwtSecret
    )

    return `${headerB64}.${payloadB64}.${signature}`
  }

  private async verifyJWT(token: string): Promise<JWTClaims> {
    const parts = token.split('.')
    if (parts.length !== 3) {
      throw new Error('Invalid token format')
    }

    const [headerB64, payloadB64, signature] = parts
    
    const expectedSignature = await this.generateHMACSignature(
      `${headerB64}.${payloadB64}`,
      this.jwtSecret
    )

    if (signature !== expectedSignature) {
      throw new Error('Invalid signature')
    }

    return JSON.parse(atob(payloadB64))
  }

  private async generateHMACSignature(message: string, secret: string): Promise<string> {
    const encoder = new TextEncoder()
    const key = await crypto.subtle.importKey(
      'raw',
      encoder.encode(secret),
      { name: 'HMAC', hash: HMAC_ALGORITHM },
      false,
      ['sign']
    )
    
    const signature = await crypto.subtle.sign('HMAC', key, encoder.encode(message))
    return this.base64Encode(new Uint8Array(signature))
  }

  private parseCertificate(cert: string): { commonName: string; expiresAt: number } | null {
    // Simplified certificate parsing - in production use proper X.509 library
    try {
      // Extract CN from certificate (very simplified)
      const cnMatch = cert.match(/CN=([^,]+)/)
      const commonName = cnMatch ? cnMatch[1] : ''

      // Assume 1 year validity
      return {
        commonName,
        expiresAt: Date.now() + 365 * 24 * 60 * 60 * 1000,
      }
    } catch {
      return null
    }
  }

  private startCleanup(): void {
    setInterval(() => {
      // Clean expired nonces
      const now = Date.now()
      for (const [nonce, timestamp] of this.nonceCache) {
        if (now - timestamp > 300000) { // 5 minutes
          this.nonceCache.delete(nonce)
        }
      }

      // Limit revoked tokens set size
      if (this.revokedTokens.size > 10000) {
        // Keep most recent 5000
        const tokens = Array.from(this.revokedTokens)
        this.revokedTokens.clear()
        tokens.slice(-5000).forEach((t) => this.revokedTokens.add(t))
      }
    }, 60000)
  }
}

// Singleton instance
export const agentAuthManager = new AgentAuthManager()

// Middleware helper for Express-style handlers
export function requireAuth(permissions: string[] = []) {
  return async (req: { headers: Record<string, string>; body?: string }, _res: unknown, next: () => void) => {
    const result = await agentAuthManager.authenticate(req.headers, req.body)

    if (!result.authenticated) {
      throw new Error(`Authentication failed: ${result.error}`)
    }

    // Check permissions
    if (permissions.length > 0) {
      const hasPermission = permissions.some((p) => 
        result.permissions?.includes(p) || result.permissions?.includes('*')
      )
      
      if (!hasPermission) {
        throw new Error('Insufficient permissions')
      }
    }

    // Attach auth info to request
    (req as unknown as Record<string, unknown>).auth = result
    next()
  }
}

// crypto polyfill for browser environment
const crypto = {
  randomUUID: (): string => `${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
  randomBytes: (_size: number): { toString: (enc?: string) => string } => ({
    toString: (enc?: string) => {
      if (enc === 'base64') {
        return btoa(Math.random().toString(36).repeat(5))
      }
      return Math.random().toString(36).repeat(5)
    }
  }),
  createHash: (_algo: string): { update: (data: string) => { digest: (enc?: string) => string } } => ({
    update: (data: string) => ({
      digest: (enc?: string) => {
        // Simple hash for demo - use proper hash in production
        let hash = 0
        for (let i = 0; i < data.length; i++) {
          const char = data.charCodeAt(i)
          hash = ((hash << 5) - hash) + char
          hash = hash & hash
        }
        const hex = Math.abs(hash).toString(16).padStart(64, '0')
        return enc === 'hex' ? hex : hex
      }
    })
  })
}

interface ApiKey {
  id: string
  key: string
  name: string
  permissions: string[]
  createdAt: number
  expiresAt?: number
  lastUsedAt?: number
  usageCount: number
  enabled: boolean
}

interface ApiKeyConfig {
  keyPrefix?: string
  keyLength?: number
  defaultExpiryDays?: number
}

class ApiKeyManager {
  private keys: Map<string, ApiKey> = new Map()
  private keyIndex: Map<string, string> = new Map() // key hash -> key id
  private config: Required<ApiKeyConfig>

  constructor(config: ApiKeyConfig = {}) {
    this.config = {
      keyPrefix: 'ec_',
      keyLength: 32,
      defaultExpiryDays: 365,
      ...config,
    }
  }

  generateKey(name: string, permissions: string[] = ['read'], expiryDays?: number): { key: string; apiKey: ApiKey } {
    const id = crypto.randomUUID()
    const keyBytes = crypto.randomBytes(this.config.keyLength)
    const key = `${this.config.keyPrefix}${keyBytes.toString('base64').replace(/[+/=]/g, '').substring(0, this.config.keyLength)}`

    const now = Date.now()
    const expiresAt = expiryDays !== undefined
      ? now + expiryDays * 24 * 60 * 60 * 1000
      : this.config.defaultExpiryDays > 0
        ? now + this.config.defaultExpiryDays * 24 * 60 * 60 * 1000
        : undefined

    const apiKey: ApiKey = {
      id,
      key: this.hashKey(key),
      name,
      permissions,
      createdAt: now,
      expiresAt,
      usageCount: 0,
      enabled: true,
    }

    this.keys.set(id, apiKey)
    this.keyIndex.set(apiKey.key, id)

    return { key, apiKey }
  }

  private hashKey(key: string): string {
    return crypto.createHash('sha256').update(key).digest('hex')
  }

  validateKey(key: string): { valid: boolean; apiKey?: ApiKey; error?: string } {
    const hashedKey = this.hashKey(key)
    const keyId = this.keyIndex.get(hashedKey)

    if (!keyId) {
      return { valid: false, error: 'Invalid API key' }
    }

    const apiKey = this.keys.get(keyId)
    if (!apiKey) {
      return { valid: false, error: 'API key not found' }
    }

    if (!apiKey.enabled) {
      return { valid: false, error: 'API key is disabled' }
    }

    if (apiKey.expiresAt && Date.now() > apiKey.expiresAt) {
      return { valid: false, error: 'API key has expired' }
    }

    // Update usage stats
    apiKey.lastUsedAt = Date.now()
    apiKey.usageCount++

    return { valid: true, apiKey }
  }

  hasPermission(apiKey: ApiKey, permission: string): boolean {
    return apiKey.permissions.includes(permission) || apiKey.permissions.includes('admin')
  }

  revokeKey(id: string): boolean {
    const apiKey = this.keys.get(id)
    if (!apiKey) {return false}

    apiKey.enabled = false
    this.keyIndex.delete(apiKey.key)
    return true
  }

  deleteKey(id: string): boolean {
    const apiKey = this.keys.get(id)
    if (!apiKey) {return false}

    this.keyIndex.delete(apiKey.key)
    return this.keys.delete(id)
  }

  getKey(id: string): ApiKey | undefined {
    return this.keys.get(id)
  }

  listKeys(): ApiKey[] {
    return Array.from(this.keys.values())
  }

  rotateKey(id: string): { key: string; apiKey: ApiKey } | null {
    const oldKey = this.keys.get(id)
    if (!oldKey) {return null}

    // Generate new key with same permissions
    const result = this.generateKey(oldKey.name, oldKey.permissions)

    // Disable old key
    this.revokeKey(id)

    return result
  }

  getStats(): {
    total: number
    active: number
    revoked: number
    expired: number
  } {
    const now = Date.now()
    let active = 0
    let revoked = 0
    let expired = 0

    for (const key of this.keys.values()) {
      if (!key.enabled) {
        revoked++
      } else if (key.expiresAt && now > key.expiresAt) {
        expired++
      } else {
        active++
      }
    }

    return {
      total: this.keys.size,
      active,
      revoked,
      expired,
    }
  }
}

// Middleware for API key authentication
function apiKeyAuthMiddleware(keyManager: ApiKeyManager, requiredPermission?: string) {
  return async (req: Request): Promise<Response | null> => {
    const authHeader = req.headers.get('Authorization')

    if (!authHeader) {
      return new Response(JSON.stringify({ error: 'Missing Authorization header' }), {
        status: 401,
        headers: { 'Content-Type': 'application/json' },
      })
    }

    const [scheme, key] = authHeader.split(' ')

    if (scheme !== 'Bearer' || !key) {
      return new Response(JSON.stringify({ error: 'Invalid Authorization format. Use: Bearer <api-key>' }), {
        status: 401,
        headers: { 'Content-Type': 'application/json' },
      })
    }

    const validation = keyManager.validateKey(key)

    if (!validation.valid) {
      return new Response(JSON.stringify({ error: validation.error }), {
        status: 401,
        headers: { 'Content-Type': 'application/json' },
      })
    }

    if (requiredPermission && !keyManager.hasPermission(validation.apiKey!, requiredPermission)) {
      return new Response(JSON.stringify({ error: 'Insufficient permissions' }), {
        status: 403,
        headers: { 'Content-Type': 'application/json' },
      })
    }

    // Attach API key info to request for downstream use
    (req as unknown as Record<string, unknown>).apiKey = validation.apiKey

    return null // Continue to next handler
  }
}

