// Default instance
export const leaderElection = new LeaderElection({ nodeId: `node-${Date.now()}` })

interface ClusterNode {
  id: string
  url: string
  weight: number
  healthy: boolean
  lastHeartbeat: number
  metadata: Record<string, unknown>
}

interface ClusterConfig {
  heartbeatInterval?: number
  nodeTimeout?: number
  loadBalancingStrategy?: 'round-robin' | 'least-connections' | 'weighted'
}

interface TaskDistribution {
  nodeId: string
  taskCount: number
  loadPercentage: number
}

class ClusterManager {
  private nodes: Map<string, ClusterNode> = new Map()
  private config: Required<ClusterConfig>
  private heartbeatInterval: ReturnType<typeof setInterval> | null = null
  private currentIndex = 0
  private taskDistribution: Map<string, number> = new Map()

  constructor(config: ClusterConfig = {}) {
    this.config = {
      heartbeatInterval: 30000, // 30 seconds
      nodeTimeout: 60000, // 1 minute
      loadBalancingStrategy: 'round-robin',
      ...config,
    }
    this.startHeartbeat()
  }

  private startHeartbeat(): void {
    this.heartbeatInterval = setInterval(() => {
      this.checkNodeHealth()
    }, this.config.heartbeatInterval)
  }

  private checkNodeHealth(): void {
    const now = Date.now()
    const timeout = this.config.nodeTimeout

    for (const [id, node] of this.nodes) {
      if (now - node.lastHeartbeat > timeout) {
        node.healthy = false
        console.warn(`Node ${id} marked as unhealthy (timeout)`)
      }
    }
  }

  registerNode(id: string, url: string, weight = 1, metadata: Record<string, unknown> = {}): ClusterNode {
    const node: ClusterNode = {
      id,
      url,
      weight,
      healthy: true,
      lastHeartbeat: Date.now(),
      metadata,
    }

    this.nodes.set(id, node)
    this.taskDistribution.set(id, 0)
    console.log(`Node ${id} registered: ${url}`)
    return node
  }

  unregisterNode(id: string): boolean {
    const deleted = this.nodes.delete(id)
    this.taskDistribution.delete(id)
    if (deleted) {
      console.log(`Node ${id} unregistered`)
    }
    return deleted
  }

  updateHeartbeat(id: string): boolean {
    const node = this.nodes.get(id)
    if (!node) {return false}

    node.lastHeartbeat = Date.now()
    node.healthy = true
    return true
  }

  getHealthyNodes(): ClusterNode[] {
    return Array.from(this.nodes.values()).filter((n) => n.healthy)
  }

  selectNode(): ClusterNode | null {
    const healthyNodes = this.getHealthyNodes()
    if (healthyNodes.length === 0) {return null}

    switch (this.config.loadBalancingStrategy) {
      case 'round-robin':
        return this.roundRobin(healthyNodes)
      case 'least-connections':
        return this.leastConnections(healthyNodes)
      case 'weighted':
        return this.weighted(healthyNodes)
      default:
        return this.roundRobin(healthyNodes)
    }
  }

  private roundRobin(nodes: ClusterNode[]): ClusterNode {
    const node = nodes[this.currentIndex % nodes.length]
    this.currentIndex++
    return node
  }

  private leastConnections(nodes: ClusterNode[]): ClusterNode {
    return nodes.reduce((best, node) => {
      const bestCount = this.taskDistribution.get(best.id) || 0
      const nodeCount = this.taskDistribution.get(node.id) || 0
      return nodeCount < bestCount ? node : best
    })
  }

  private weighted(nodes: ClusterNode[]): ClusterNode {
    const totalWeight = nodes.reduce((sum, n) => sum + n.weight, 0)
    let random = Math.random() * totalWeight

    for (const node of nodes) {
      random -= node.weight
      if (random <= 0) {return node}
    }

    return nodes[0]
  }

  assignTask(nodeId: string): void {
    const count = this.taskDistribution.get(nodeId) || 0
    this.taskDistribution.set(nodeId, count + 1)
  }

  completeTask(nodeId: string): void {
    const count = this.taskDistribution.get(nodeId) || 0
    if (count > 0) {
      this.taskDistribution.set(nodeId, count - 1)
    }
  }

  getTaskDistribution(): TaskDistribution[] {
    const total = Array.from(this.taskDistribution.values()).reduce((a, b) => a + b, 0)

    return Array.from(this.nodes.values()).map((node) => {
      const count = this.taskDistribution.get(node.id) || 0
      return {
        nodeId: node.id,
        taskCount: count,
        loadPercentage: total > 0 ? (count / total) * 100 : 0,
      }
    })
  }

  getStats(): {
    total: number
    healthy: number
    unhealthy: number
    totalTasks: number
    strategy: string
  } {
    const healthy = this.getHealthyNodes().length
    const totalTasks = Array.from(this.taskDistribution.values()).reduce((a, b) => a + b, 0)

    return {
      total: this.nodes.size,
      healthy,
      unhealthy: this.nodes.size - healthy,
      totalTasks,
      strategy: this.config.loadBalancingStrategy,
    }
  }

  broadcast(message: unknown): Promise<unknown[]> {
    const promises = Array.from(this.nodes.values())
      .filter((n) => n.healthy)
      .map(async (node) => {
        try {
          const response = await fetch(`${node.url}/broadcast`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(message),
          })
          return response.json()
        } catch (error) {
          return { error: error instanceof Error ? error.message : 'Unknown error' }
        }
      })

    return Promise.all(promises)
  }

  destroy(): void {
    if (this.heartbeatInterval) {
      clearInterval(this.heartbeatInterval)
    }
    this.nodes.clear()
    this.taskDistribution.clear()
  }
}

// Leader election for distributed coordination
class LeaderElection {
  private nodeId: string
  private isLeader = false
  private leaderId: string | null = null
  private callbacks: Array<(isLeader: boolean) => void> = []

  constructor(nodeId: string) {
    this.nodeId = nodeId
  }

  async elect(nodes: string[]): Promise<boolean> {
    // Simple leader election: lowest node ID wins
    const sorted = [...nodes].sort()
    const newLeader = sorted[0]

    const wasLeader = this.isLeader
    this.leaderId = newLeader
    this.isLeader = newLeader === this.nodeId

    if (wasLeader !== this.isLeader) {
      this.callbacks.forEach((cb) => cb(this.isLeader))
    }

    return this.isLeader
  }

  onLeadershipChange(callback: (isLeader: boolean) => void): () => void {
    this.callbacks.push(callback)
    return () => {
      const index = this.callbacks.indexOf(callback)
      if (index !== -1) {
        this.callbacks.splice(index, 1)
      }
    }
  }

  isCurrentLeader(): boolean {
    return this.isLeader
  }

  getLeaderId(): string | null {
    return this.leaderId
  }
}

// Singleton instance
export const clusterManager = new ClusterManager()

export { ClusterManager, LeaderElection }
export type { ClusterConfig, ClusterNode, TaskDistribution }

/**
 * Raft Consensus Implementation for Distributed Edge-Cloud Orchestrator
 * Implements leader election, log replication, and fault tolerance
 */

type RaftState = 'follower' | 'candidate' | 'leader'

interface LogEntry {
  term: number
  index: number
  command: RaftCommand
  timestamp: number
}

interface RaftCommand {
  type: 'schedule_task' | 'update_node' | 'change_policy' | 'add_node' | 'remove_node'
  data: unknown
}

interface RaftConfig {
  nodeId: string
  peers: string[]
  heartbeatInterval?: number
  electionTimeoutMin?: number
  electionTimeoutMax?: number
  rpcTimeout?: number
}

interface RequestVoteRequest {
  term: number
  candidateId: string
  lastLogIndex: number
  lastLogTerm: number
}

interface RequestVoteResponse {
  term: number
  voteGranted: boolean
}

interface AppendEntriesRequest {
  term: number
  leaderId: string
  prevLogIndex: number
  prevLogTerm: number
  entries: LogEntry[]
  leaderCommit: number
}

interface AppendEntriesResponse {
  term: number
  success: boolean
  matchIndex: number
}

interface RaftMetrics {
  state: RaftState
  currentTerm: number
  commitIndex: number
  lastApplied: number
  logLength: number
  leaderId: string | null
  votesReceived: number
  peers: number
}

type RaftEvent = 'state_change' | 'leader_elected' | 'log_committed' | 'term_change'
type RaftCallback = (event: RaftEvent, data: unknown) => void

const DEFAULT_CONFIG = {
  heartbeatInterval: 1000,      // 1 second
  electionTimeoutMin: 3000,     // 3 seconds
  electionTimeoutMax: 6000,     // 6 seconds
  rpcTimeout: 500,              // 500ms
}

export class RaftConsensus {
  private nodeId: string
  private peers: string[]
  private config: Required<Omit<RaftConfig, 'nodeId' | 'pees'>> & Pick<RaftConfig, 'nodeId' | 'peers'>

  // Persistent state
  private currentTerm = 0
  private votedFor: string | null = null
  private log: LogEntry[] = []

  // Volatile state
  private commitIndex = 0
  private lastApplied = 0
  private state: RaftState = 'follower'
  private leaderId: string | null = null

  // Leader state
  private nextIndex: Map<string, number> = new Map()
  private matchIndex: Map<string, number> = new Map()

  // Candidate state
  private votesReceived = 0

  // Timers
  private heartbeatTimer: ReturnType<typeof setInterval> | null = null
  private electionTimer: ReturnType<typeof setTimeout> | null = null

  // Event handlers
  private callbacks: Map<RaftEvent, Set<RaftCallback>> = new Map()

  // State machine
  private stateMachine: Map<string, unknown> = new Map()

  constructor(config: RaftConfig) {
    this.nodeId = config.nodeId
    this.peers = config.peers
    this.config = {
      ...DEFAULT_CONFIG,
      ...config,
    } as Required<RaftConfig>

    this.resetElectionTimer()
  }

  /**
   * Start the Raft node
   */
  start(): void {
    this.resetElectionTimer()
    console.log(`[Raft] Node ${this.nodeId} started as ${this.state}`)
  }

  /**
   * Stop the Raft node
   */
  stop(): void {
    this.clearTimers()
    console.log(`[Raft] Node ${this.nodeId} stopped`)
  }

  private clearTimers(): void {
    if (this.heartbeatTimer) {
      clearInterval(this.heartbeatTimer)
      this.heartbeatTimer = null
    }
    if (this.electionTimer) {
      clearTimeout(this.electionTimer)
      this.electionTimer = null
    }
  }

  private resetElectionTimer(): void {
    if (this.electionTimer) {
      clearTimeout(this.electionTimer)
    }

    const timeout = this.randomElectionTimeout()
    this.electionTimer = setTimeout(() => {
      this.startElection()
    }, timeout)
  }

  private randomElectionTimeout(): number {
    const { electionTimeoutMin, electionTimeoutMax } = this.config
    return Math.floor(Math.random() * (electionTimeoutMax - electionTimeoutMin) + electionTimeoutMin)
  }

  /**
   * Start an election
   */
  private startElection(): void {
    const previousState = this.state
    this.state = 'candidate'
    this.currentTerm++
    this.votedFor = this.nodeId
    this.votesReceived = 1 // Vote for self
    this.leaderId = null

    this.emit('state_change', { from: previousState, to: 'candidate', term: this.currentTerm })

    console.log(`[Raft] Node ${this.nodeId} starting election for term ${this.currentTerm}`)

    // Request votes from all peers
    const lastLogIndex = this.log.length - 1
    const lastLogTerm = this.log.length > 0 ? this.log[this.log.length - 1].term : 0

    const request: RequestVoteRequest = {
      term: this.currentTerm,
      candidateId: this.nodeId,
      lastLogIndex,
      lastLogTerm,
    }

    // Simulate sending RequestVote to peers (in real impl, use HTTP/WebSocket)
    this.peers.forEach((peerId) => {
      this.sendRequestVote(peerId, request)
    })

    // Reset election timer
    this.resetElectionTimer()
  }

  /**
   * Send RequestVote RPC to a peer (simulated)
   */
  private async sendRequestVote(peerId: string, request: RequestVoteRequest): Promise<void> {
    try {
      // In real implementation, this would be an HTTP/WebSocket call
      const response = await this.simulateRequestVote(peerId, request)
      this.handleRequestVoteResponse(response)
    } catch (error) {
      console.error(`[Raft] RequestVote to ${peerId} failed:`, error)
    }
  }

  /**
   * Simulate RequestVote (would be real RPC in production)
   */
  private async simulateRequestVote(_peerId: string, request: RequestVoteRequest): Promise<RequestVoteResponse> {
    // Simulate network delay
    await new Promise((resolve) => setTimeout(resolve, Math.random() * 100))

    // Simulate peer response (simplified - in real impl, this would be the peer's actual logic)
    const grantVote = Math.random() > 0.3 // 70% chance of granting vote

    return {
      term: request.term,
      voteGranted: grantVote,
    }
  }

  /**
   * Handle RequestVote response
   */
  private handleRequestVoteResponse(response: RequestVoteResponse): void {
    if (this.state !== 'candidate') {return}

    if (response.term > this.currentTerm) {
      // Discovered higher term, convert to follower
      this.currentTerm = response.term
      this.becomeFollower(response.term, null)
      return
    }

    if (response.voteGranted) {
      this.votesReceived++
      
      // Check if we have majority
      const majority = Math.floor((this.peers.length + 1) / 2) + 1
      if (this.votesReceived >= majority) {
        this.becomeLeader()
      }
    }
  }

  /**
   * Become the leader
   */
  private becomeLeader(): void {
    const previousState = this.state
    this.state = 'leader'
    this.leaderId = this.nodeId

    // Initialize leader state
    const lastLogIndex = this.log.length - 1
    this.peers.forEach((peerId) => {
      this.nextIndex.set(peerId, lastLogIndex + 1)
      this.matchIndex.set(peerId, 0)
    })

    this.emit('state_change', { from: previousState, to: 'leader', term: this.currentTerm })
    this.emit('leader_elected', { leaderId: this.nodeId, term: this.currentTerm })

    console.log(`[Raft] Node ${this.nodeId} became leader for term ${this.currentTerm}`)

    // Start sending heartbeats
    this.startHeartbeats()
  }

  /**
   * Become a follower
   */
  private becomeFollower(term: number, leaderId: string | null): void {
    const previousState = this.state
    this.state = 'follower'
    this.currentTerm = term
    this.leaderId = leaderId
    this.votedFor = null

    this.emit('state_change', { from: previousState, to: 'follower', term })

    // Stop heartbeats if we were leader
    if (this.heartbeatTimer) {
      clearInterval(this.heartbeatTimer)
      this.heartbeatTimer = null
    }

    this.resetElectionTimer()
  }

  /**
   * Start sending heartbeats (leader only)
   */
  private startHeartbeats(): void {
    if (this.heartbeatTimer) {
      clearInterval(this.heartbeatTimer)
    }

    this.heartbeatTimer = setInterval(() => {
      this.sendHeartbeats()
    }, this.config.heartbeatInterval)
  }

  /**
   * Send heartbeats to all peers
   */
  private sendHeartbeats(): void {
    if (this.state !== 'leader') {return}

    this.peers.forEach((peerId) => {
      const nextIndex = this.nextIndex.get(peerId) || 0
      const prevLogIndex = nextIndex - 1
      const prevLogTerm = prevLogIndex >= 0 ? this.log[prevLogIndex].term : 0

      const entries = this.log.slice(nextIndex)

      const request: AppendEntriesRequest = {
        term: this.currentTerm,
        leaderId: this.nodeId,
        prevLogIndex,
        prevLogTerm,
        entries,
        leaderCommit: this.commitIndex,
      }

      this.sendAppendEntries(peerId, request)
    })
  }

  /**
   * Send AppendEntries RPC to a peer
   */
  private async sendAppendEntries(peerId: string, request: AppendEntriesRequest): Promise<void> {
    try {
      const response = await this.simulateAppendEntries(peerId, request)
      this.handleAppendEntriesResponse(peerId, response)
    } catch (error) {
      console.error(`[Raft] AppendEntries to ${peerId} failed:`, error)
    }
  }

  /**
   * Simulate AppendEntries (would be real RPC in production)
   */
  private async simulateAppendEntries(_peerId: string, request: AppendEntriesRequest): Promise<AppendEntriesResponse> {
    await new Promise((resolve) => setTimeout(resolve, Math.random() * 50))

    return {
      term: request.term,
      success: Math.random() > 0.1, // 90% success rate
      matchIndex: request.prevLogIndex + request.entries.length,
    }
  }

  /**
   * Handle AppendEntries response
   */
  private handleAppendEntriesResponse(peerId: string, response: AppendEntriesResponse): void {
    if (this.state !== 'leader') {return}

    if (response.term > this.currentTerm) {
      this.becomeFollower(response.term, null)
      return
    }

    if (response.success) {
      this.matchIndex.set(peerId, response.matchIndex)
      this.nextIndex.set(peerId, response.matchIndex + 1)

      // Check if we can commit
      this.updateCommitIndex()
    } else {
      // Decrement nextIndex and retry
      const current = this.nextIndex.get(peerId) || 1
      this.nextIndex.set(peerId, Math.max(0, current - 1))
    }
  }

  /**
   * Update commit index based on replicated entries
   */
  private updateCommitIndex(): void {
    for (let n = this.commitIndex + 1; n < this.log.length; n++) {
      const count = Array.from(this.matchIndex.values()).filter((i) => i >= n).length + 1
      const majority = Math.floor((this.peers.length + 1) / 2) + 1

      if (count >= majority && this.log[n].term === this.currentTerm) {
        this.commitIndex = n
        this.applyCommittedEntries()
      }
    }
  }

  /**
   * Apply committed entries to state machine
   */
  private applyCommittedEntries(): void {
    while (this.lastApplied < this.commitIndex) {
      this.lastApplied++
      const entry = this.log[this.lastApplied]
      this.applyToStateMachine(entry)
      this.emit('log_committed', { index: entry.index, command: entry.command })
    }
  }

  /**
   * Apply a log entry to the state machine
   */
  private applyToStateMachine(entry: LogEntry): void {
    const { command } = entry
    
    switch (command.type) {
      case 'schedule_task':
        this.stateMachine.set(`task-${Date.now()}`, command.data)
        break
      case 'update_node':
        this.stateMachine.set(`node-${(command.data as { id: string }).id}`, command.data)
        break
      case 'change_policy':
        this.stateMachine.set('policy', command.data)
        break
      case 'add_node':
        this.stateMachine.set(`node-${(command.data as { id: string }).id}`, command.data)
        break
      case 'remove_node':
        this.stateMachine.delete(`node-${(command.data as { id: string }).id}`)
        break
    }
  }

  /**
   * Propose a command (leader only)
   */
  propose(command: RaftCommand): boolean {
    if (this.state !== 'leader') {
      console.warn('[Raft] Only leader can propose commands')
      return false
    }

    const entry: LogEntry = {
      term: this.currentTerm,
      index: this.log.length,
      command,
      timestamp: Date.now(),
    }

    this.log.push(entry)
    this.matchIndex.set(this.nodeId, entry.index)

    console.log(`[Raft] Leader ${this.nodeId} proposed:`, command.type)
    return true
  }

  /**
   * Handle incoming RequestVote RPC
   */
  handleRequestVote(request: RequestVoteRequest): RequestVoteResponse {
    if (request.term > this.currentTerm) {
      this.currentTerm = request.term
      this.votedFor = null
      this.becomeFollower(request.term, null)
    }

    const logOk = request.lastLogIndex >= this.log.length - 1 &&
      (request.lastLogTerm > (this.log[this.log.length - 1]?.term || 0) ||
        request.lastLogTerm === (this.log[this.log.length - 1]?.term || 0) &&
        request.lastLogIndex >= this.log.length - 1)

    const grantVote = request.term === this.currentTerm &&
      (this.votedFor === null || this.votedFor === request.candidateId) &&
      logOk

    if (grantVote) {
      this.votedFor = request.candidateId
      this.resetElectionTimer()
    }

    return {
      term: this.currentTerm,
      voteGranted: grantVote,
    }
  }

  /**
   * Handle incoming AppendEntries RPC
   */
  handleAppendEntries(request: AppendEntriesRequest): AppendEntriesResponse {
    if (request.term > this.currentTerm) {
      this.currentTerm = request.term
      this.votedFor = null
    }

    if (request.term < this.currentTerm) {
      return { term: this.currentTerm, success: false, matchIndex: -1 }
    }

    this.becomeFollower(request.term, request.leaderId)

    // Check log consistency
    if (request.prevLogIndex >= 0) {
      if (this.log.length <= request.prevLogIndex) {
        return { term: this.currentTerm, success: false, matchIndex: this.log.length - 1 }
      }
      if (this.log[request.prevLogIndex].term !== request.prevLogTerm) {
        // Delete conflicting entries
        this.log = this.log.slice(0, request.prevLogIndex)
        return { term: this.currentTerm, success: false, matchIndex: this.log.length - 1 }
      }
    }

    // Append new entries
    for (const entry of request.entries) {
      if (this.log.length <= entry.index || this.log[entry.index].term !== entry.term) {
        this.log[entry.index] = entry
      }
    }

    // Update commit index
    if (request.leaderCommit > this.commitIndex) {
      this.commitIndex = Math.min(request.leaderCommit, this.log.length - 1)
      this.applyCommittedEntries()
    }

    return { term: this.currentTerm, success: true, matchIndex: this.log.length - 1 }
  }

  /**
   * Check if this node is the leader
   */
  isLeader(): boolean {
    return this.state === 'leader'
  }

  /**
   * Get the current leader ID
   */
  getLeader(): string | null {
    return this.leaderId
  }

  /**
   * Get current state
   */
  getState(): RaftState {
    return this.state
  }

  /**
   * Get metrics
   */
  getMetrics(): RaftMetrics {
    return {
      state: this.state,
      currentTerm: this.currentTerm,
      commitIndex: this.commitIndex,
      lastApplied: this.lastApplied,
      logLength: this.log.length,
      leaderId: this.leaderId,
      votesReceived: this.votesReceived,
      peers: this.peers.length,
    }
  }

  /**
   * Subscribe to events
   */
  on(event: RaftEvent, callback: RaftCallback): () => void {
    if (!this.callbacks.has(event)) {
      this.callbacks.set(event, new Set())
    }
    this.callbacks.get(event)!.add(callback)

    return () => {
      this.callbacks.get(event)?.delete(callback)
    }
  }

  private emit(event: RaftEvent, data: unknown): void {
    this.callbacks.get(event)?.forEach((cb) => {
      try {
        cb(event, data)
      } catch (error) {
        console.error('[Raft] Callback error:', error)
      }
    })
  }
}

// Factory function to create a Raft cluster
export function createRaftCluster(nodeIds: string[]): RaftConsensus[] {
  return nodeIds.map((nodeId, _index, all) => {
    const peers = all.filter((id) => id !== nodeId)
    return new RaftConsensus({
      nodeId,
      peers,
    })
  })
}

export type { LogEntry, RaftCommand, RaftConfig, RaftMetrics,RaftState }

/**
 * Control Plane - Separated from Execution Layer
 * Handles scheduling decisions, policy management, and cluster coordination
 * WITHOUT directly executing tasks
 */

import { logger } from '../logger'
import type { EdgeNode, SchedulingPolicy,Task, TaskPriority } from '../../types'

// Types
export interface ControlPlaneConfig {
  nodeId: string
  region: string
  schedulerShards: number
  decisionTimeout: number
  maxPendingDecisions: number
}

export interface SchedulingDecision {
  id: string
  taskId: string
  nodeId: string
  policy: SchedulingPolicy
  priority: TaskPriority
  reason: string
  constraints: SchedulingConstraints
  createdAt: number
  expiresAt: number
  status: 'pending' | 'dispatched' | 'acknowledged' | 'expired'
}

export interface SchedulingConstraints {
  minCpu?: number
  minMemory?: number
  minStorage?: number
  maxLatency?: number
  requiredCapabilities?: string[]
  regionPreference?: string[]
  antiAffinity?: string[] // Node IDs to avoid
}

export interface ExecutionCommand {
  decisionId: string
  taskId: string
  nodeId: string
  action: 'execute' | 'cancel' | 'migrate' | 'checkpoint'
  payload: unknown
  createdAt: number
}

export interface ExecutionAck {
  decisionId: string
  nodeId: string
  status: 'accepted' | 'rejected' | 'failed'
  reason?: string
  timestamp: number
}

type ControlPlaneEvent = 'decision.created' | 'decision.dispatched' | 'decision.acknowledged' | 'decision.expired'
type ControlPlaneCallback = (event: ControlPlaneEvent, data: unknown) => void

const DEFAULT_CONFIG: Omit<ControlPlaneConfig, 'nodeId' | 'region'> = {
  schedulerShards: 4,
  decisionTimeout: 30000, // 30 seconds
  maxPendingDecisions: 1000,
}

/**
 * Control Plane Manager
 * Separates scheduling decisions from task execution
 */
export class ControlPlaneManager {
  private config: ControlPlaneConfig
  private pendingDecisions: Map<string, SchedulingDecision> = new Map()
  private dispatchedCommands: Map<string, ExecutionCommand> = new Map()
  private executionLayer: ((command: ExecutionCommand) => Promise<ExecutionAck>) | null = null
  private nodeRegistry: (() => EdgeNode[]) | null = null
  private scheduler: ((task: Task, nodes: EdgeNode[], constraints: SchedulingConstraints) => string | null) | null = null
  private callbacks: Map<ControlPlaneEvent, Set<ControlPlaneCallback>> = new Map()
  private cleanupTimer: ReturnType<typeof setInterval> | null = null

  constructor(config: Partial<ControlPlaneConfig> & { nodeId: string; region: string }) {
    this.config = { ...DEFAULT_CONFIG, ...config }
    this.startCleanupTimer()
  }

  /**
   * Register execution layer (decoupled from control plane)
   */
  registerExecutionLayer(
    executor: (command: ExecutionCommand) => Promise<ExecutionAck>
  ): void {
    this.executionLayer = executor
    logger.info('Execution layer registered with control plane', { nodeId: this.config.nodeId })
  }

  /**
   * Register node registry provider
   */
  registerNodeRegistry(provider: () => EdgeNode[]): void {
    this.nodeRegistry = provider
  }

  /**
   * Register scheduler function
   */
  registerScheduler(
    scheduler: (task: Task, nodes: EdgeNode[], constraints: SchedulingConstraints) => string | null
  ): void {
    this.scheduler = scheduler
  }

  /**
   * Create scheduling decision (control plane only)
   */
  async createDecision(
    task: Task,
    policy: SchedulingPolicy,
    constraints: SchedulingConstraints = {}
  ): Promise<SchedulingDecision | null> {
    // Check capacity
    if (this.pendingDecisions.size >= this.config.maxPendingDecisions) {
      logger.warn('Control plane at capacity, rejecting decision', { taskId: task.id })
      return null
    }

    // Get available nodes
    const nodes = this.nodeRegistry ? this.nodeRegistry() : []
    if (nodes.length === 0) {
      logger.warn('No nodes available for scheduling', { taskId: task.id })
      return null
    }

    // Apply constraints filtering
    const filteredNodes = this.applyConstraints(nodes, constraints)
    if (filteredNodes.length === 0) {
      logger.warn('No nodes match constraints', { taskId: task.id, constraints })
      return null
    }

    // Get scheduling decision from scheduler
    const selectedNodeId = this.scheduler 
      ? this.scheduler(task, filteredNodes, constraints)
      : filteredNodes[0]?.id

    if (!selectedNodeId) {
      return null
    }

    const decision: SchedulingDecision = {
      id: `decision-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
      taskId: task.id,
      nodeId: selectedNodeId,
      policy,
      priority: task.priority,
      reason: `Scheduled via ${policy} policy`,
      constraints,
      createdAt: Date.now(),
      expiresAt: Date.now() + this.config.decisionTimeout,
      status: 'pending',
    }

    this.pendingDecisions.set(decision.id, decision)
    this.emit('decision.created', decision)

    logger.info('Scheduling decision created', {
      decisionId: decision.id,
      taskId: task.id,
      nodeId: selectedNodeId,
      policy,
    })

    return decision
  }

  /**
   * Dispatch decision to execution layer
   */
  async dispatchDecision(decisionId: string): Promise<ExecutionAck | null> {
    const decision = this.pendingDecisions.get(decisionId)
    if (!decision) {
      logger.warn('Decision not found for dispatch', { decisionId })
      return null
    }

    if (!this.executionLayer) {
      logger.error('No execution layer registered')
      return null
    }

    // Create execution command
    const command: ExecutionCommand = {
      decisionId: decision.id,
      taskId: decision.taskId,
      nodeId: decision.nodeId,
      action: 'execute',
      payload: { decision },
      createdAt: Date.now(),
    }

    decision.status = 'dispatched'
    this.dispatchedCommands.set(decision.id, command)
    this.emit('decision.dispatched', { decisionId, nodeId: decision.nodeId })

    try {
      const ack = await this.executionLayer(command)
      
      if (ack.status === 'accepted') {
        decision.status = 'acknowledged'
        this.pendingDecisions.delete(decisionId)
        this.emit('decision.acknowledged', { decisionId, nodeId: decision.nodeId })
      }

      return ack
    } catch (error) {
      logger.error('Failed to dispatch decision', error as Error, { decisionId })
      return null
    }
  }

  /**
   * Cancel a pending decision
   */
  async cancelDecision(decisionId: string, reason: string): Promise<boolean> {
    const decision = this.pendingDecisions.get(decisionId)
    if (!decision) {return false}

    if (decision.status === 'dispatched' && this.executionLayer) {
      // Send cancel command to execution layer
      await this.executionLayer({
        decisionId,
        taskId: decision.taskId,
        nodeId: decision.nodeId,
        action: 'cancel',
        payload: { reason },
        createdAt: Date.now(),
      })
    }

    this.pendingDecisions.delete(decisionId)
    logger.info('Decision cancelled', { decisionId, reason })
    return true
  }

  /**
   * Get decision by ID
   */
  getDecision(decisionId: string): SchedulingDecision | undefined {
    return this.pendingDecisions.get(decisionId)
  }

  /**
   * Get all pending decisions
   */
  getPendingDecisions(): SchedulingDecision[] {
    return Array.from(this.pendingDecisions.values())
      .filter((d) => d.status === 'pending')
  }

  /**
   * Get decisions by node
   */
  getDecisionsByNode(nodeId: string): SchedulingDecision[] {
    return Array.from(this.pendingDecisions.values())
      .filter((d) => d.nodeId === nodeId)
  }

  /**
   * Get control plane statistics
   */
  getStats(): {
    pendingDecisions: number
    dispatchedCommands: number
    byPriority: Record<TaskPriority, number>
    byStatus: Record<string, number>
    shardId: number
  } {
    const byPriority: Record<TaskPriority, number> = {
      critical: 0,
      high: 0,
      medium: 0,
      low: 0,
    }
    const byStatus: Record<string, number> = {}

    for (const decision of this.pendingDecisions.values()) {
      byPriority[decision.priority]++
      byStatus[decision.status] = (byStatus[decision.status] || 0) + 1
    }

    return {
      pendingDecisions: this.pendingDecisions.size,
      dispatchedCommands: this.dispatchedCommands.size,
      byPriority,
      byStatus,
      shardId: this.getShardId(),
    }
  }

  /**
   * Apply constraints to filter nodes
   */
  private applyConstraints(nodes: EdgeNode[], constraints: SchedulingConstraints): EdgeNode[] {
    return nodes.filter((node) => {
      // CPU constraint
      if (constraints.minCpu && (100 - node.cpu) < constraints.minCpu) {
        return false
      }

      // Memory constraint
      if (constraints.minMemory && (100 - node.memory) < constraints.minMemory) {
        return false
      }

      // Storage constraint
      if (constraints.minStorage && node.storage < constraints.minStorage) {
        return false
      }

      // Latency constraint
      if (constraints.maxLatency && node.latency > constraints.maxLatency) {
        return false
      }

      // Region preference
      if (constraints.regionPreference && constraints.regionPreference.length > 0) {
        if (!constraints.regionPreference.includes(node.region)) {
          return false
        }
      }

      // Anti-affinity
      if (constraints.antiAffinity && constraints.antiAffinity.includes(node.id)) {
        return false
      }

      return true
    })
  }

  /**
   * Get shard ID for this control plane instance
   */
  private getShardId(): number {
    let hash = 0
    for (let i = 0; i < this.config.nodeId.length; i++) {
      hash = ((hash << 5) - hash) + this.config.nodeId.charCodeAt(i)
      hash = hash & hash
    }
    return Math.abs(hash) % this.config.schedulerShards
  }

  /**
   * Start cleanup timer for expired decisions
   */
  private startCleanupTimer(): void {
    this.cleanupTimer = setInterval(() => {
      const now = Date.now()
      for (const [id, decision] of this.pendingDecisions) {
        if (decision.expiresAt < now) {
          decision.status = 'expired'
          this.pendingDecisions.delete(id)
          this.emit('decision.expired', { decisionId: id, taskId: decision.taskId })
          logger.warn('Decision expired', { decisionId: id, taskId: decision.taskId })
        }
      }
    }, 5000)
  }

  /**
   * Stop control plane
   */
  stop(): void {
    if (this.cleanupTimer) {
      clearInterval(this.cleanupTimer)
      this.cleanupTimer = null
    }
  }

  /**
   * Subscribe to events
   */
  on(event: ControlPlaneEvent, callback: ControlPlaneCallback): () => void {
    if (!this.callbacks.has(event)) {
      this.callbacks.set(event, new Set())
    }
    this.callbacks.get(event)!.add(callback)

    return () => {
      this.callbacks.get(event)?.delete(callback)
    }
  }

  private emit(event: ControlPlaneEvent, data: unknown): void {
    this.callbacks.get(event)?.forEach((cb) => {
      try {
        cb(event, data)
      } catch (error) {
        logger.error('Control plane callback error', error as Error)
      }
    })
  }
}

/**
 * Execution Layer Interface
 * To be implemented by the execution layer
 */
export interface ExecutionLayerInterface {
  execute(command: ExecutionCommand): Promise<ExecutionAck>
  cancel(decisionId: string): Promise<boolean>
  getStatus(nodeId: string): Promise<{ running: number; queued: number }>
  migrate(taskId: string, fromNode: string, toNode: string): Promise<boolean>
}

/**
 * Create control plane instance
 */
export function createControlPlane(config: Partial<ControlPlaneConfig> & { nodeId: string; region: string }): ControlPlaneManager {
  return new ControlPlaneManager(config)
}

// Default instance
export const controlPlane = new ControlPlaneManager({ nodeId: 'default', region: 'default' })

/**
 * Distributed Scheduler with Sharding
 * Eliminates single scheduler bottleneck through horizontal scaling
 */

import { logger } from '../logger'
import type { EdgeNode, SchedulingPolicy,Task } from '../../types'

// Types
export interface ShardConfig {
  shardId: number
  totalShards: number
  hashKey: 'task-type' | 'region' | 'priority' | 'round-robin'
  syncInterval: number
  rebalanceThreshold: number
}

export interface ShardInfo {
  shardId: number
  nodeIds: string[]
  taskCount: number
  load: number
  lastSync: number
  isHealthy: boolean
}

export interface SchedulerShard {
  id: number
  nodes: Set<string>
  tasks: Map<string, Task>
  load: number
  lastHeartbeat: number
}

export interface DistributedScheduleResult {
  taskId: string
  nodeId: string
  shardId: number
  policy: SchedulingPolicy
  timestamp: number
}

type ShardEvent = 'shard.assigned' | 'shard.rebalanced' | 'shard.failed' | 'task.scheduled'
type ShardCallback = (event: ShardEvent, data: unknown) => void

const DEFAULT_CONFIG: Omit<ShardConfig, 'shardId' | 'totalShards'> = {
  hashKey: 'task-type',
  syncInterval: 5000,
  rebalanceThreshold: 0.2, // 20% imbalance triggers rebalance
}

/**
 * Distributed Scheduler with consistent hashing
 */
export class DistributedScheduler {
  private config: ShardConfig
  private shards: Map<number, SchedulerShard> = new Map()
  private nodeToShard: Map<string, number> = new Map()
  private taskQueue: Map<number, Task[]> = new Map()
  private roundRobinIndex = 0
  private syncTimer: ReturnType<typeof setInterval> | null = null
  private callbacks: Map<ShardEvent, Set<ShardCallback>> = new Map()
  private nodeProvider: (() => EdgeNode[]) | null = null
  private policyApplier: ((task: Task, nodes: EdgeNode[], policy: SchedulingPolicy) => string | null) | null = null

  constructor(config: Partial<ShardConfig> & { shardId: number; totalShards: number }) {
    this.config = { ...DEFAULT_CONFIG, ...config }
    this.initializeShards()
  }

  /**
   * Initialize shards
   */
  private initializeShards(): void {
    for (let i = 0; i < this.config.totalShards; i++) {
      this.shards.set(i, {
        id: i,
        nodes: new Set(),
        tasks: new Map(),
        load: 0,
        lastHeartbeat: Date.now(),
      })
      this.taskQueue.set(i, [])
    }
  }

  /**
   * Set node provider
   */
  setNodeProvider(provider: () => EdgeNode[]): void {
    this.nodeProvider = provider
  }

  /**
   * Set policy applier
   */
  setPolicyApplier(
    applier: (task: Task, nodes: EdgeNode[], policy: SchedulingPolicy) => string | null
  ): void {
    this.policyApplier = applier
  }

  /**
   * Register a node to a shard
   */
  registerNode(node: EdgeNode): number {
    const shardId = this.getShardForNode(node)
    const shard = this.shards.get(shardId)
    
    if (shard) {
      shard.nodes.add(node.id)
      this.nodeToShard.set(node.id, shardId)
      this.emit('shard.assigned', { nodeId: node.id, shardId })
      logger.info('Node registered to shard', { nodeId: node.id, shardId })
    }
    
    return shardId
  }

  /**
   * Unregister a node
   */
  unregisterNode(nodeId: string): void {
    const shardId = this.nodeToShard.get(nodeId)
    if (shardId !== undefined) {
      const shard = this.shards.get(shardId)
      if (shard) {
        shard.nodes.delete(nodeId)
      }
      this.nodeToShard.delete(nodeId)
    }
  }

  /**
   * Get shard for a node using consistent hashing
   */
  private getShardForNode(node: EdgeNode): number {
    const key = `${node.region}:${node.id}`
    return this.hash(key) % this.config.totalShards
  }

  /**
   * Get shard for a task
   */
  private getShardForTask(task: Task): number {
    let key: string
    
    switch (this.config.hashKey) {
      case 'task-type':
        key = task.type
        break
      case 'region':
        key = task.nodeId || 'default'
        break
      case 'priority':
        key = task.priority
        break
      case 'round-robin':
        this.roundRobinIndex = (this.roundRobinIndex + 1) % this.config.totalShards
        return this.roundRobinIndex
      default:
        key = task.type
    }
    
    return this.hash(key) % this.config.totalShards
  }

  /**
   * Hash function for consistent hashing
   */
  private hash(key: string): number {
    let hash = 5381
    for (let i = 0; i < key.length; i++) {
      hash = ((hash << 5) + hash) + key.charCodeAt(i)
    }
    return Math.abs(hash)
  }

  /**
   * Schedule a task across shards
   */
  async scheduleTask(task: Task, policy: SchedulingPolicy): Promise<DistributedScheduleResult | null> {
    const shardId = this.getShardForTask(task)
    const shard = this.shards.get(shardId)
    
    if (!shard || shard.nodes.size === 0) {
      // Try to find another shard with nodes
      const fallbackShard = this.findAvailableShard()
      if (!fallbackShard) {
        logger.warn('No available shards for task', { taskId: task.id })
        return null
      }
      return this.scheduleOnShard(task, policy, fallbackShard)
    }
    
    return this.scheduleOnShard(task, policy, shardId)
  }

  /**
   * Schedule task on specific shard
   */
  private async scheduleOnShard(task: Task, policy: SchedulingPolicy, shardId: number): Promise<DistributedScheduleResult | null> {
    const shard = this.shards.get(shardId)
    if (!shard) {return null}

    // Get nodes for this shard
    const nodes = this.nodeProvider ? this.nodeProvider().filter((n) => shard.nodes.has(n.id)) : []
    
    if (nodes.length === 0) {
      // Queue task for later
      const queue = this.taskQueue.get(shardId) || []
      queue.push(task)
      this.taskQueue.set(shardId, queue)
      logger.info('Task queued (no nodes available)', { taskId: task.id, shardId })
      return null
    }

    // Apply scheduling policy
    const selectedNodeId = this.policyApplier 
      ? this.policyApplier(task, nodes, policy)
      : nodes[0]?.id

    if (!selectedNodeId) {
      return null
    }

    // Update shard load
    shard.tasks.set(task.id, task)
    shard.load = shard.tasks.size / Math.max(shard.nodes.size, 1)

    const result: DistributedScheduleResult = {
      taskId: task.id,
      nodeId: selectedNodeId,
      shardId,
      policy,
      timestamp: Date.now(),
    }

    this.emit('task.scheduled', result)
    logger.info('Task scheduled on shard', { taskId: task.id, nodeId: selectedNodeId, shardId })

    return result
  }

  /**
   * Find an available shard
   */
  private findAvailableShard(): number | null {
    for (const [shardId, shard] of this.shards) {
      if (shard.nodes.size > 0) {
        return shardId
      }
    }
    return null
  }

  /**
   * Rebalance shards if load is imbalanced
   */
  rebalance(): { moved: number; from: number[]; to: number[] } {
    const loads = Array.from(this.shards.values()).map((s) => s.load)
    const avgLoad = loads.reduce((a, b) => a + b, 0) / loads.length
    
    const overloaded: number[] = []
    const underloaded: number[] = []
    
    for (const [shardId, shard] of this.shards) {
      const deviation = Math.abs(shard.load - avgLoad) / avgLoad
      if (deviation > this.config.rebalanceThreshold) {
        if (shard.load > avgLoad) {
          overloaded.push(shardId)
        } else {
          underloaded.push(shardId)
        }
      }
    }

    let moved = 0
    
    // Move nodes from overloaded to underloaded shards
    for (const fromShardId of overloaded) {
      const fromShard = this.shards.get(fromShardId)
      if (!fromShard || fromShard.nodes.size === 0) {continue}
      
      for (const toShardId of underloaded) {
        if (fromShard.nodes.size <= 1) {break} // Keep at least one node
        
        const nodeToMove = Array.from(fromShard.nodes)[0]
        fromShard.nodes.delete(nodeToMove)
        
        const toShard = this.shards.get(toShardId)
        if (toShard) {
          toShard.nodes.add(nodeToMove)
          this.nodeToShard.set(nodeToMove, toShardId)
          moved++
        }
      }
    }

    if (moved > 0) {
      this.emit('shard.rebalanced', { moved, overloaded, underloaded })
      logger.info('Shards rebalanced', { moved, overloaded, underloaded })
    }

    return { moved, from: overloaded, to: underloaded }
  }

  /**
   * Get shard information
   */
  getShardInfo(): ShardInfo[] {
    return Array.from(this.shards.values()).map((shard) => ({
      shardId: shard.id,
      nodeIds: Array.from(shard.nodes),
      taskCount: shard.tasks.size,
      load: shard.load,
      lastSync: shard.lastHeartbeat,
      isHealthy: Date.now() - shard.lastHeartbeat < 30000,
    }))
  }

  /**
   * Get statistics
   */
  getStats(): {
    totalShards: number
    totalNodes: number
    totalTasks: number
    avgLoad: number
    maxLoad: number
    minLoad: number
    queuedTasks: number
  } {
    let totalNodes = 0
    let totalTasks = 0
    let totalLoad = 0
    let maxLoad = 0
    let minLoad = Infinity
    let queuedTasks = 0

    for (const shard of this.shards.values()) {
      totalNodes += shard.nodes.size
      totalTasks += shard.tasks.size
      totalLoad += shard.load
      maxLoad = Math.max(maxLoad, shard.load)
      minLoad = Math.min(minLoad, shard.load)
    }

    for (const queue of this.taskQueue.values()) {
      queuedTasks += queue.length
    }

    return {
      totalShards: this.config.totalShards,
      totalNodes,
      totalTasks,
      avgLoad: totalLoad / this.config.totalShards,
      maxLoad,
      minLoad: minLoad === Infinity ? 0 : minLoad,
      queuedTasks,
    }
  }

  /**
   * Mark task complete
   */
  completeTask(taskId: string, shardId: number): void {
    const shard = this.shards.get(shardId)
    if (shard) {
      shard.tasks.delete(taskId)
      shard.load = shard.tasks.size / Math.max(shard.nodes.size, 1)
    }
  }

  /**
   * Start sync timer
   */
  startSync(): void {
    this.syncTimer = setInterval(() => {
      this.sync()
    }, this.config.syncInterval)
  }

  /**
   * Stop sync timer
   */
  stopSync(): void {
    if (this.syncTimer) {
      clearInterval(this.syncTimer)
      this.syncTimer = null
    }
  }

  /**
   * Sync shard state
   */
  private sync(): void {
    const now = Date.now()
    for (const shard of this.shards.values()) {
      shard.lastHeartbeat = now
    }
  }

  /**
   * Subscribe to events
   */
  on(event: ShardEvent, callback: ShardCallback): () => void {
    if (!this.callbacks.has(event)) {
      this.callbacks.set(event, new Set())
    }
    this.callbacks.get(event)!.add(callback)

    return () => {
      this.callbacks.get(event)?.delete(callback)
    }
  }

  private emit(event: ShardEvent, data: unknown): void {
    this.callbacks.get(event)?.forEach((cb) => {
      try {
        cb(event, data)
      } catch (error) {
        logger.error('Distributed scheduler callback error', error as Error)
      }
    })
  }
}

/**
 * Create distributed scheduler
 */
export function createDistributedScheduler(config: Partial<ShardConfig> & { shardId: number; totalShards: number }): DistributedScheduler {
  return new DistributedScheduler(config)
}

// Default instance
export const distributedScheduler = new DistributedScheduler({ shardId: 0, totalShards: 4 })

/**
 * ML-Based Cost Optimization Engine
 * Analyzes resource usage and provides cost-saving recommendations
 */

import { logger } from '../logger'
import type { EdgeNode } from '../../types'

// Types
export interface CostMetrics {
  nodeId: string
  timestamp: number
  cpuUsage: number
  memoryUsage: number
  storageUsage: number
  networkInBytes: number
  networkOutBytes: number
  tasksProcessed: number
  energyConsumption: number // kWh
  costPerHour: number
  region: string
}

export interface CostAnalysis {
  id: string
  timestamp: number
  totalCost: number
  breakdown: {
    compute: number
    network: number
    storage: number
    energy: number
  }
  trends: {
    daily: number[]
    weekly: number[]
    monthly: number[]
  }
  anomalies: CostAnomaly[]
}

export interface CostAnomaly {
  id: string
  type: 'spike' | 'inefficiency' | 'idle-resource' | 'over-provisioned'
  nodeId?: string
  severity: 'low' | 'medium' | 'high'
  description: string
  impact: number // Cost impact in $
  detectedAt: number
}

export interface CostRecommendation {
  id: string
  type: 'scale-down' | 'scale-up' | 'consolidate' | 'migrate' | 'schedule' | 'right-size' | 'reserve'
  priority: 'low' | 'medium' | 'high' | 'critical'
  title: string
  description: string
  affectedNodes: string[]
  currentCost: number
  projectedSavings: number
  savingsPercentage: number
  implementation: string
  risk: 'low' | 'medium' | 'high'
  estimatedEffort: 'minutes' | 'hours' | 'days'
  createdAt: number
  status: 'pending' | 'approved' | 'implemented' | 'dismissed'
}

export interface PricingModel {
  region: string
  cpuCostPerCoreHour: number
  memoryCostPerGBHour: number
  storageCostPerGBMonth: number
  networkCostPerGB: number
  energyCostPerKWh: number
}

export interface CostOptimizationConfig {
  analysisInterval: number
  historyRetentionDays: number
  anomalyThreshold: number // Percentage deviation
  minSavingsThreshold: number // Minimum $ to report
  pricingModels: PricingModel[]
}

type CostEvent = 'analysis.completed' | 'anomaly.detected' | 'recommendation.generated' | 'savings.achieved'
type CostCallback = (event: CostEvent, data: unknown) => void

const DEFAULT_PRICING: PricingModel[] = [
  { region: 'us-east', cpuCostPerCoreHour: 0.04, memoryCostPerGBHour: 0.01, storageCostPerGBMonth: 0.10, networkCostPerGB: 0.09, energyCostPerKWh: 0.12 },
  { region: 'us-west', cpuCostPerCoreHour: 0.045, memoryCostPerGBHour: 0.011, storageCostPerGBMonth: 0.11, networkCostPerGB: 0.09, energyCostPerKWh: 0.14 },
  { region: 'eu-west', cpuCostPerCoreHour: 0.05, memoryCostPerGBHour: 0.012, storageCostPerGBMonth: 0.12, networkCostPerGB: 0.10, energyCostPerKWh: 0.18 },
  { region: 'asia-east', cpuCostPerCoreHour: 0.055, memoryCostPerGBHour: 0.013, storageCostPerGBMonth: 0.13, networkCostPerGB: 0.12, energyCostPerKWh: 0.16 },
]

const DEFAULT_CONFIG: Omit<CostOptimizationConfig, 'pricingModels'> = {
  analysisInterval: 3600000, // 1 hour
  historyRetentionDays: 90,
  anomalyThreshold: 20, // 20% deviation
  minSavingsThreshold: 10, // $10 minimum
}

/**
 * Cost Optimization Engine
 */
export class CostOptimizationEngine {
  private config: CostOptimizationConfig
  private metricsHistory: Map<string, CostMetrics[]> = new Map()
  private analyses: Map<string, CostAnalysis> = new Map()
  private recommendations: Map<string, CostRecommendation> = new Map()
  private callbacks: Map<CostEvent, Set<CostCallback>> = new Map()
  private analysisTimer: ReturnType<typeof setInterval> | null = null
  private nodeProvider: (() => EdgeNode[]) | null = null

  constructor(config: Partial<CostOptimizationConfig> = {}) {
    this.config = { ...DEFAULT_CONFIG, pricingModels: DEFAULT_PRICING, ...config }
  }

  /**
   * Set node provider
   */
  setNodeProvider(provider: () => EdgeNode[]): void {
    this.nodeProvider = provider
  }

  /**
   * Record cost metrics for a node
   */
  recordMetrics(metrics: CostMetrics): void {
    if (!this.metricsHistory.has(metrics.nodeId)) {
      this.metricsHistory.set(metrics.nodeId, [])
    }

    const history = this.metricsHistory.get(metrics.nodeId)!
    history.push(metrics)

    // Trim old data
    const cutoff = Date.now() - this.config.historyRetentionDays * 24 * 60 * 60 * 1000
    const filtered = history.filter((m) => m.timestamp > cutoff)
    this.metricsHistory.set(metrics.nodeId, filtered)
  }

  /**
   * Get pricing model for region
   */
  private getPricing(region: string): PricingModel {
    return this.config.pricingModels.find((p) => p.region === region) || this.config.pricingModels[0]
  }

  /**
   * Calculate cost for a node
   */
  calculateNodeCost(node: EdgeNode, durationHours: number = 1): number {
    const pricing = this.getPricing(node.region)
    
    // Use node's costPerHour if available, otherwise estimate
    if (node.costPerHour) {
      return node.costPerHour * durationHours
    }
    
    // Estimate based on maxTasks as proxy for capacity
    const estimatedCores = Math.max(1, Math.floor(node.maxTasks / 2))
    const estimatedMemory = Math.max(1, node.maxTasks)
    
    const cpuCost = estimatedCores * pricing.cpuCostPerCoreHour * durationHours
    const memoryCost = estimatedMemory * pricing.memoryCostPerGBHour * durationHours
    const storageCost = (node.storage || 100) * pricing.storageCostPerGBMonth / (30 * 24) * durationHours
    
    return cpuCost + memoryCost + storageCost
  }

  /**
   * Run cost analysis
   */
  async analyze(): Promise<CostAnalysis> {
    const nodes = this.nodeProvider ? this.nodeProvider() : []
    const analysisId = `analysis-${Date.now()}`

    let totalCompute = 0
    const totalNetwork = 0
    let totalStorage = 0
    let totalEnergy = 0
    const anomalies: CostAnomaly[] = []

    for (const node of nodes) {
      const pricing = this.getPricing(node.region)
      const history = this.metricsHistory.get(node.id) || []
      
      // Calculate costs
      const nodeCost = this.calculateNodeCost(node, 1)
      totalCompute += nodeCost * (node.cpu / 100)
      totalStorage += (node.storage || 100) * pricing.storageCostPerGBMonth / 720
      
      // Energy cost estimation
      const estimatedCores = Math.max(1, Math.floor(node.maxTasks / 2))
      const energyCost = estimatedCores * 0.1 * pricing.energyCostPerKWh
      totalEnergy += energyCost

      // Detect anomalies
      if (history.length > 10) {
        const recent = history.slice(-10)
        const avgCpu = recent.reduce((s, m) => s + m.cpuUsage, 0) / recent.length
        
        // Idle resource detection
        if (avgCpu < 10 && node.status === 'online') {
          anomalies.push({
            id: `anomaly-${Date.now()}-${node.id}`,
            type: 'idle-resource',
            nodeId: node.id,
            severity: 'medium',
            description: `Node ${node.id} has low CPU utilization (${avgCpu.toFixed(1)}%)`,
            impact: this.calculateNodeCost(node, 24) * 0.5,
            detectedAt: Date.now(),
          })
        }

        // Over-provisioned detection
        if (avgCpu < 30 && node.memory < 30) {
          anomalies.push({
            id: `anomaly-${Date.now()}-${node.id}-over`,
            type: 'over-provisioned',
            nodeId: node.id,
            severity: 'low',
            description: `Node ${node.id} appears over-provisioned`,
            impact: this.calculateNodeCost(node, 24) * 0.3,
            detectedAt: Date.now(),
          })
        }
      }
    }

    const analysis: CostAnalysis = {
      id: analysisId,
      timestamp: Date.now(),
      totalCost: totalCompute + totalNetwork + totalStorage + totalEnergy,
      breakdown: {
        compute: totalCompute,
        network: totalNetwork,
        storage: totalStorage,
        energy: totalEnergy,
      },
      trends: this.calculateTrends(),
      anomalies,
    }

    this.analyses.set(analysisId, analysis)
    
    // Generate recommendations
    await this.generateRecommendations(analysis, nodes)

    this.emit('analysis.completed', analysis)
    logger.info('Cost analysis completed', { analysisId, totalCost: analysis.totalCost.toFixed(2) })

    return analysis
  }

  /**
   * Calculate cost trends
   */
  private calculateTrends(): { daily: number[]; weekly: number[]; monthly: number[] } {
    const daily: number[] = []
    const weekly: number[] = []
    const monthly: number[] = []

    // Simulate trend data (in production, would aggregate from history)
    for (let i = 0; i < 7; i++) {
      daily.push(100 + Math.random() * 50)
    }
    for (let i = 0; i < 4; i++) {
      weekly.push(700 + Math.random() * 200)
    }
    for (let i = 0; i < 3; i++) {
      monthly.push(3000 + Math.random() * 500)
    }

    return { daily, weekly, monthly }
  }

  /**
   * Generate cost optimization recommendations
   */
  private async generateRecommendations(analysis: CostAnalysis, nodes: EdgeNode[]): Promise<void> {
    // 1. Scale-down recommendations for idle nodes
    const idleNodes = nodes.filter((n) => n.cpu < 15 && n.memory < 20 && n.status === 'online')
    if (idleNodes.length > 0) {
      const savings = idleNodes.reduce((sum, n) => sum + this.calculateNodeCost(n, 24) * 0.7, 0)
      
      if (savings >= this.config.minSavingsThreshold) {
        this.addRecommendation({
          type: 'scale-down',
          priority: savings > 100 ? 'high' : 'medium',
          title: 'Scale Down Idle Nodes',
          description: `${idleNodes.length} nodes have low utilization and can be scaled down`,
          affectedNodes: idleNodes.map((n) => n.id),
          currentCost: savings / 0.7,
          projectedSavings: savings,
          savingsPercentage: 70,
          implementation: 'Reduce node count or switch to smaller instance types',
          risk: 'low',
          estimatedEffort: 'hours',
        })
      }
    }

    // 2. Consolidation recommendations
    const lowUtilNodes = nodes.filter((n) => n.cpu < 40 && n.memory < 50)
    if (lowUtilNodes.length >= 2) {
      const potentialSavings = lowUtilNodes.slice(1).reduce((sum, n) => sum + this.calculateNodeCost(n, 24) * 0.5, 0)
      
      if (potentialSavings >= this.config.minSavingsThreshold) {
        this.addRecommendation({
          type: 'consolidate',
          priority: 'medium',
          title: 'Consolidate Under-Utilized Nodes',
          description: `${lowUtilNodes.length} nodes can be consolidated to reduce costs`,
          affectedNodes: lowUtilNodes.map((n) => n.id),
          currentCost: potentialSavings / 0.5,
          projectedSavings: potentialSavings,
          savingsPercentage: 50,
          implementation: 'Migrate workloads and decommission excess nodes',
          risk: 'medium',
          estimatedEffort: 'days',
        })
      }
    }

    // 3. Region migration recommendations
    const expensiveRegions = new Map<string, { nodes: EdgeNode[]; cost: number }>()
    for (const node of nodes) {
      const cost = this.calculateNodeCost(node, 24)
      const {region} = node
      
      if (!expensiveRegions.has(region)) {
        expensiveRegions.set(region, { nodes: [], cost: 0 })
      }
      expensiveRegions.get(region)!.nodes.push(node)
      expensiveRegions.get(region)!.cost += cost
    }

    // Find cheaper region
    const cheapestRegion = this.config.pricingModels.reduce((min, p) => 
      p.cpuCostPerCoreHour < min.cpuCostPerCoreHour ? p : min
    )

    for (const [region, data] of expensiveRegions) {
      if (region !== cheapestRegion.region && data.cost > 50) {
        const newCost = data.nodes.reduce((sum, n) => {
          const pricing = this.getPricing(cheapestRegion.region)
          const estimatedCores = Math.max(1, Math.floor(n.maxTasks / 2))
          return sum + estimatedCores * pricing.cpuCostPerCoreHour * 24
        }, 0)
        
        const savings = data.cost - newCost
        
        if (savings >= this.config.minSavingsThreshold) {
          this.addRecommendation({
            type: 'migrate',
            priority: 'low',
            title: `Migrate Workloads to ${cheapestRegion.region}`,
            description: `Moving ${data.nodes.length} nodes from ${region} to ${cheapestRegion.region} can reduce costs`,
            affectedNodes: data.nodes.map((n) => n.id),
            currentCost: data.cost,
            projectedSavings: savings,
            savingsPercentage: (savings / data.cost) * 100,
            implementation: `Migrate nodes to ${cheapestRegion.region} region`,
            risk: 'high',
            estimatedEffort: 'days',
          })
        }
      }
    }

    // 4. Scheduled scaling recommendations
    this.addRecommendation({
      type: 'schedule',
      priority: 'medium',
      title: 'Implement Scheduled Scaling',
      description: 'Scale down during off-peak hours to reduce costs',
      affectedNodes: nodes.map((n) => n.id),
      currentCost: analysis.totalCost * 0.3,
      projectedSavings: analysis.totalCost * 0.15,
      savingsPercentage: 15,
      implementation: 'Configure auto-scaling schedules for non-peak hours',
      risk: 'low',
      estimatedEffort: 'hours',
    })

    // 5. Reserved capacity recommendations
    const steadyNodes = nodes.filter((n) => n.tasksRunning > 0)
    if (steadyNodes.length > 0) {
      const monthlyCost = steadyNodes.reduce((sum, n) => sum + this.calculateNodeCost(n, 720), 0)
      const reservedSavings = monthlyCost * 0.3 // ~30% savings with reserved

      if (reservedSavings >= this.config.minSavingsThreshold * 30) {
        this.addRecommendation({
          type: 'reserve',
          priority: 'high',
          title: 'Purchase Reserved Capacity',
          description: `${steadyNodes.length} nodes have steady workloads suitable for reserved pricing`,
          affectedNodes: steadyNodes.map((n) => n.id),
          currentCost: monthlyCost,
          projectedSavings: reservedSavings,
          savingsPercentage: 30,
          implementation: 'Purchase 1-year or 3-year reserved instances',
          risk: 'low',
          estimatedEffort: 'hours',
        })
      }
    }
  }

  /**
   * Add a recommendation
   */
  private addRecommendation(base: Omit<CostRecommendation, 'id' | 'createdAt' | 'status'>): void {
    const recommendation: CostRecommendation = {
      ...base,
      id: `rec-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
      createdAt: Date.now(),
      status: 'pending',
    }

    this.recommendations.set(recommendation.id, recommendation)
    this.emit('recommendation.generated', recommendation)
    
    logger.info('Cost recommendation generated', { 
      id: recommendation.id, 
      type: recommendation.type, 
      savings: recommendation.projectedSavings.toFixed(2) 
    })
  }

  /**
   * Get recommendations
   */
  getRecommendations(status?: CostRecommendation['status']): CostRecommendation[] {
    const all = Array.from(this.recommendations.values())
    return status ? all.filter((r) => r.status === status) : all
  }

  /**
   * Apply recommendation
   */
  async applyRecommendation(recommendationId: string): Promise<boolean> {
    const recommendation = this.recommendations.get(recommendationId)
    if (!recommendation || recommendation.status !== 'pending') {
      return false
    }

    recommendation.status = 'approved'
    
    // Simulate implementation
    await new Promise((resolve) => setTimeout(resolve, 100))
    
    recommendation.status = 'implemented'
    this.emit('savings.achieved', { recommendation, savings: recommendation.projectedSavings })
    
    logger.info('Recommendation applied', { id: recommendationId, savings: recommendation.projectedSavings })
    return true
  }

  /**
   * Dismiss recommendation
   */
  dismissRecommendation(recommendationId: string): boolean {
    const recommendation = this.recommendations.get(recommendationId)
    if (!recommendation) {return false}

    recommendation.status = 'dismissed'
    return true
  }

  /**
   * Get latest analysis
   */
  getLatestAnalysis(): CostAnalysis | undefined {
    const all = Array.from(this.analyses.values())
    return all.sort((a, b) => b.timestamp - a.timestamp)[0]
  }

  /**
   * Get cost summary
   */
  getCostSummary(): {
    currentHourlyRate: number
    projectedMonthly: number
    potentialSavings: number
    recommendationsCount: number
  } {
    const nodes = this.nodeProvider ? this.nodeProvider() : []
    const currentHourlyRate = nodes.reduce((sum, n) => sum + this.calculateNodeCost(n, 1), 0)
    
    const pendingRecs = this.getRecommendations('pending')
    const potentialSavings = pendingRecs.reduce((sum, r) => sum + r.projectedSavings, 0)

    return {
      currentHourlyRate,
      projectedMonthly: currentHourlyRate * 720,
      potentialSavings,
      recommendationsCount: pendingRecs.length,
    }
  }

  /**
   * Start periodic analysis
   */
  startAnalysis(): void {
    this.analysisTimer = setInterval(() => {
      this.analyze()
    }, this.config.analysisInterval)
    
    // Run initial analysis
    this.analyze()
  }

  /**
   * Stop analysis
   */
  stopAnalysis(): void {
    if (this.analysisTimer) {
      clearInterval(this.analysisTimer)
      this.analysisTimer = null
    }
  }

  /**
   * Subscribe to events
   */
  on(event: CostEvent, callback: CostCallback): () => void {
    if (!this.callbacks.has(event)) {
      this.callbacks.set(event, new Set())
    }
    this.callbacks.get(event)!.add(callback)

    return () => {
      this.callbacks.get(event)?.delete(callback)
    }
  }

  private emit(event: CostEvent, data: unknown): void {
    this.callbacks.get(event)?.forEach((cb) => {
      try {
        cb(event, data)
      } catch (error) {
        logger.error('Cost optimization callback error', error as Error)
      }
    })
  }
}

/**
 * Create cost optimization engine
 */
export function createCostOptimizationEngine(config: Partial<CostOptimizationConfig> = {}): CostOptimizationEngine {
  return new CostOptimizationEngine(config)
}

// Default instance
export const costOptimizationEngine = new CostOptimizationEngine()

import type { AuditLog,EdgeNode, LogEntry, Task } from '../types'
import type { WebhookConfig, WebhookDelivery } from '../types/webhook'

const DB_NAME = 'EdgeCloudOrchestratorDB'
const DB_VERSION = 1

interface DatabaseSchema {
  nodes: EdgeNode
  tasks: Task
  logs: LogEntry
  auditLogs: AuditLog
  webhooks: WebhookConfig
  webhookDeliveries: WebhookDelivery
}

class Database {
  private db: IDBDatabase | null = null
  private initPromise: Promise<void> | null = null

  async init(): Promise<void> {
    if (this.initPromise) {return this.initPromise}
    if (this.db) {return}

    this.initPromise = new Promise((resolve, reject) => {
      const request = indexedDB.open(DB_NAME, DB_VERSION)

      request.onerror = () => reject(request.error)
      request.onsuccess = () => {
        this.db = request.result
        resolve()
      }

      request.onupgradeneeded = (event) => {
        const db = (event.target as IDBOpenDBRequest).result

        // Nodes store
        if (!db.objectStoreNames.contains('nodes')) {
          const nodeStore = db.createObjectStore('nodes', { keyPath: 'id' })
          nodeStore.createIndex('status', 'status', { unique: false })
          nodeStore.createIndex('region', 'region', { unique: false })
        }

        // Tasks store
        if (!db.objectStoreNames.contains('tasks')) {
          const taskStore = db.createObjectStore('tasks', { keyPath: 'id' })
          taskStore.createIndex('status', 'status', { unique: false })
          taskStore.createIndex('nodeId', 'nodeId', { unique: false })
          taskStore.createIndex('submittedAt', 'submittedAt', { unique: false })
        }

        // Logs store
        if (!db.objectStoreNames.contains('logs')) {
          const logStore = db.createObjectStore('logs', { keyPath: 'id' })
          logStore.createIndex('timestamp', 'timestamp', { unique: false })
          logStore.createIndex('level', 'level', { unique: false })
        }

        // Audit logs store
        if (!db.objectStoreNames.contains('auditLogs')) {
          const auditStore = db.createObjectStore('auditLogs', { keyPath: 'id' })
          auditStore.createIndex('timestamp', 'timestamp', { unique: false })
          auditStore.createIndex('userId', 'userId', { unique: false })
          auditStore.createIndex('action', 'action', { unique: false })
        }

        // Webhooks store
        if (!db.objectStoreNames.contains('webhooks')) {
          const webhookStore = db.createObjectStore('webhooks', { keyPath: 'id' })
          webhookStore.createIndex('enabled', 'enabled', { unique: false })
        }

        // Webhook deliveries store
        if (!db.objectStoreNames.contains('webhookDeliveries')) {
          const deliveryStore = db.createObjectStore('webhookDeliveries', { keyPath: 'id' })
          deliveryStore.createIndex('webhookId', 'webhookId', { unique: false })
          deliveryStore.createIndex('status', 'status', { unique: false })
          deliveryStore.createIndex('event', 'event', { unique: false })
          deliveryStore.createIndex('createdAt', 'createdAt', { unique: false })
        }
      }
    })

    return this.initPromise
  }

  private getStore<T extends keyof DatabaseSchema>(
    storeName: T,
    mode: IDBTransactionMode = 'readonly'
  ): IDBObjectStore {
    if (!this.db) {throw new Error('Database not initialized')}
    const transaction = this.db.transaction(storeName, mode)
    return transaction.objectStore(storeName)
  }

  // Generic CRUD operations
  async add<T extends keyof DatabaseSchema>(
    storeName: T,
    data: DatabaseSchema[T]
  ): Promise<void> {
    await this.init()
    return new Promise((resolve, reject) => {
      const store = this.getStore(storeName, 'readwrite')
      const request = store.add(data)
      request.onsuccess = () => resolve()
      request.onerror = () => reject(request.error)
    })
  }

  async put<T extends keyof DatabaseSchema>(
    storeName: T,
    data: DatabaseSchema[T]
  ): Promise<void> {
    await this.init()
    return new Promise((resolve, reject) => {
      const store = this.getStore(storeName, 'readwrite')
      const request = store.put(data)
      request.onsuccess = () => resolve()
      request.onerror = () => reject(request.error)
    })
  }

  async get<T extends keyof DatabaseSchema>(
    storeName: T,
    id: string
  ): Promise<DatabaseSchema[T] | undefined> {
    await this.init()
    return new Promise((resolve, reject) => {
      const store = this.getStore(storeName)
      const request = store.get(id)
      request.onsuccess = () => resolve(request.result)
      request.onerror = () => reject(request.error)
    })
  }

  async getAll<T extends keyof DatabaseSchema>(
    storeName: T
  ): Promise<DatabaseSchema[T][]> {
    await this.init()
    return new Promise((resolve, reject) => {
      const store = this.getStore(storeName)
      const request = store.getAll()
      request.onsuccess = () => resolve(request.result || [])
      request.onerror = () => reject(request.error)
    })
  }

  async delete<T extends keyof DatabaseSchema>(
    storeName: T,
    id: string
  ): Promise<void> {
    await this.init()
    return new Promise((resolve, reject) => {
      const store = this.getStore(storeName, 'readwrite')
      const request = store.delete(id)
      request.onsuccess = () => resolve()
      request.onerror = () => reject(request.error)
    })
  }

  async clear<T extends keyof DatabaseSchema>(storeName: T): Promise<void> {
    await this.init()
    return new Promise((resolve, reject) => {
      const store = this.getStore(storeName, 'readwrite')
      const request = store.clear()
      request.onsuccess = () => resolve()
      request.onerror = () => reject(request.error)
    })
  }

  // Query with index
  async query<T extends keyof DatabaseSchema>(
    storeName: T,
    indexName: string,
    value: string | number
  ): Promise<DatabaseSchema[T][]> {
    await this.init()
    return new Promise((resolve, reject) => {
      const store = this.getStore(storeName)
      const index = store.index(indexName)
      const request = index.getAll(value)
      request.onsuccess = () => resolve(request.result || [])
      request.onerror = () => reject(request.error)
    })
  }

  // Get recent items with limit
  async getRecent<T extends keyof DatabaseSchema>(
    storeName: T,
    limit: number,
    indexName = 'timestamp'
  ): Promise<DatabaseSchema[T][]> {
    await this.init()
    return new Promise((resolve, reject) => {
      const store = this.getStore(storeName)
      const index = store.index(indexName)
      const request = index.openCursor(null, 'prev')
      const results: DatabaseSchema[T][] = []

      request.onsuccess = () => {
        const cursor = request.result
        if (cursor && results.length < limit) {
          results.push(cursor.value)
          cursor.continue()
        } else {
          resolve(results)
        }
      }
      request.onerror = () => reject(request.error)
    })
  }

  // Close connection
  close(): void {
    if (this.db) {
      this.db.close()
      this.db = null
      this.initPromise = null
    }
  }
}

