// Import data
export async function importData(data: {
  nodes?: EdgeNode[]
  tasks?: Task[]
  logs?: LogEntry[]
}): Promise<void> {
  const promises: Promise<void>[] = []

  if (data.nodes) {
    promises.push(...data.nodes.map((n) => db.put('nodes', n)))
  }
  if (data.tasks) {
    promises.push(...data.tasks.map((t) => db.put('tasks', t)))
  }
  if (data.logs) {
    promises.push(...data.logs.map((l) => db.put('logs', l)))
  }

  await Promise.all(promises)
}

interface RequestKey {
  method: string
  url: string
  body: string
}

interface InFlightRequest<T> {
  key: string
  promise: Promise<T>
  timestamp: number
  subscribers: number
}

interface DeduplicationConfig {
  ttlMs?: number
  maxInFlight?: number
}

class RequestDeduplicator {
  private inFlight: Map<string, InFlightRequest<unknown>> = new Map()
  private completed: Map<string, { result: unknown; timestamp: number }> = new Map()
  private config: Required<DeduplicationConfig>
  private cleanupInterval: ReturnType<typeof setInterval> | null = null

  constructor(config: DeduplicationConfig = {}) {
    this.config = {
      ttlMs: 5000, // 5 seconds default
      maxInFlight: 100,
      ...config,
    }
    this.startCleanup()
  }

  private startCleanup(): void {
    this.cleanupInterval = setInterval(() => {
      this.cleanup()
    }, 10000) // Cleanup every 10 seconds
  }

  private cleanup(): void {
    const now = Date.now()
    const ttl = this.config.ttlMs

    // Clean completed requests
    for (const [key, entry] of this.completed) {
      if (now - entry.timestamp > ttl) {
        this.completed.delete(key)
      }
    }

    // Clean stale in-flight requests
    for (const [key, request] of this.inFlight) {
      if (now - request.timestamp > ttl * 2) {
        this.inFlight.delete(key)
      }
    }
  }

  private generateKey(method: string, url: string, body?: unknown): string {
    const bodyStr = body ? JSON.stringify(body) : ''
    return `${method}:${url}:${bodyStr}`
  }

  async deduplicate<T>(
    method: string,
    url: string,
    factory: () => Promise<T>,
    body?: unknown
  ): Promise<T> {
    const key = this.generateKey(method, url, body)

    // Check if we have a recent completed result
    const completed = this.completed.get(key)
    if (completed) {
      const age = Date.now() - completed.timestamp
      if (age < this.config.ttlMs) {
        return completed.result as T
      }
      // Expired, remove it
      this.completed.delete(key)
    }

    // Check if there's an in-flight request
    const inFlight = this.inFlight.get(key)
    if (inFlight) {
      inFlight.subscribers++
      return inFlight.promise as Promise<T>
    }

    // Check max in-flight limit
    if (this.inFlight.size >= this.config.maxInFlight) {
      // Remove oldest in-flight request
      const oldest = Array.from(this.inFlight.entries())
        .sort((a, b) => a[1].timestamp - b[1].timestamp)[0]
      if (oldest) {
        this.inFlight.delete(oldest[0])
      }
    }

    // Create new request
    const promise = this.executeRequest(key, factory)

    const request: InFlightRequest<T> = {
      key,
      promise,
      timestamp: Date.now(),
      subscribers: 1,
    }

    this.inFlight.set(key, request as InFlightRequest<unknown>)

    return promise
  }

  private async executeRequest<T>(key: string, factory: () => Promise<T>): Promise<T> {
    try {
      const result = await factory()

      // Store completed result
      this.completed.set(key, {
        result,
        timestamp: Date.now(),
      })

      // Remove from in-flight
      this.inFlight.delete(key)

      return result
    } catch (error) {
      // Remove from in-flight on error
      this.inFlight.delete(key)
      throw error
    }
  }

  // For mutations - skip deduplication but track
  async track<T>(key: string, factory: () => Promise<T>): Promise<T> {
    // Add timestamp to key to make it unique
    const uniqueKey = `${key}:${Date.now()}`
    return this.deduplicate('TRACK', uniqueKey, factory)
  }

  // Invalidate cached result
  invalidate(method: string, url: string, body?: unknown): boolean {
    const key = this.generateKey(method, url, body)
    const hadCompleted = this.completed.delete(key)
    const hadInFlight = this.inFlight.delete(key)
    return hadCompleted || hadInFlight
  }

  // Invalidate by pattern
  invalidatePattern(pattern: RegExp): number {
    let count = 0

    for (const key of this.completed.keys()) {
      if (pattern.test(key)) {
        this.completed.delete(key)
        count++
      }
    }

    for (const key of this.inFlight.keys()) {
      if (pattern.test(key)) {
        this.inFlight.delete(key)
        count++
      }
    }

    return count
  }

  getStats(): {
    inFlight: number
    completed: number
    totalSubscribers: number
  } {
    let totalSubscribers = 0
    for (const request of this.inFlight.values()) {
      totalSubscribers += request.subscribers
    }

    return {
      inFlight: this.inFlight.size,
      completed: this.completed.size,
      totalSubscribers,
    }
  }

  clear(): void {
    this.inFlight.clear()
    this.completed.clear()
  }

  destroy(): void {
    if (this.cleanupInterval) {
      clearInterval(this.cleanupInterval)
    }
    this.clear()
  }
}

// HTTP client with deduplication
class DeduplicatingHttpClient {
  private deduplicator: RequestDeduplicator

  constructor(config?: DeduplicationConfig) {
    this.deduplicator = new RequestDeduplicator(config)
  }

  async get<T>(url: string, options?: { deduplicate?: boolean; ttlMs?: number }): Promise<T> {
    const shouldDeduplicate = options?.deduplicate !== false

    if (shouldDeduplicate) {
      return this.deduplicator.deduplicate('GET', url, async () => {
        const response = await fetch(url)
        if (!response.ok) {throw new Error(`HTTP ${response.status}`)}
        return response.json()
      })
    } else {
      const response = await fetch(url)
      if (!response.ok) {throw new Error(`HTTP ${response.status}`)}
      return response.json()
    }
  }

  async post<T>(url: string, body: unknown, options?: { deduplicate?: boolean }): Promise<T> {
    const shouldDeduplicate = options?.deduplicate ?? false // Default false for mutations

    const factory = async () => {
      const response = await fetch(url, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body),
      })
      if (!response.ok) {throw new Error(`HTTP ${response.status}`)}
      return response.json()
    }

    if (shouldDeduplicate) {
      return this.deduplicator.deduplicate('POST', url, factory, body)
    } else {
      return factory()
    }
  }

  invalidate(url: string): boolean {
    return this.deduplicator.invalidate('GET', url)
  }

  getStats() {
    return this.deduplicator.getStats()
  }
}

// Singleton instances
export const requestDeduplicator = new RequestDeduplicator()
export const httpClient = new DeduplicatingHttpClient()

export { DeduplicatingHttpClient,RequestDeduplicator }
export type { DeduplicationConfig,InFlightRequest, RequestKey }

/**
 * Blue-Green Deployment Manager for Edge Agents
 * Zero-downtime deployments with automatic rollback
 */

import { logger } from '../logger'
import type { EdgeNode } from '../../types'

// Types
export interface DeploymentConfig {
  name: string
  version: string
  artifactUrl: string
  checksum: string
  environment: Record<string, string>
  healthCheckEndpoint: string
  healthCheckInterval: number
  healthCheckTimeout: number
  minHealthyNodes: number
  rolloutStrategy: 'rolling' | 'blue-green' | 'canary'
  rolloutPercentage: number
  rollbackOnFailure: boolean
  rollbackThreshold: number // Error rate percentage
}

export interface DeploymentSlot {
  name: 'blue' | 'green'
  version: string
  nodes: Set<string>
  status: 'active' | 'idle' | 'deploying' | 'draining' | 'failed'
  createdAt: number
  healthScore: number
  requestCount: number
  errorCount: number
}

export interface DeploymentRecord {
  id: string
  config: DeploymentConfig
  status: 'pending' | 'deploying' | 'validating' | 'active' | 'rolling-back' | 'completed' | 'failed'
  blueSlot: DeploymentSlot
  greenSlot: DeploymentSlot
  activeSlot: 'blue' | 'green'
  startTime: number
  endTime?: number
  progress: number
  error?: string
  metrics: {
    nodesDeployed: number
    nodesHealthy: number
    nodesFailed: number
    trafficShifted: number
  }
}

export interface TrafficSplit {
  bluePercentage: number
  greenPercentage: number
  lastUpdated: number
}

type DeploymentEvent = 'deployment.started' | 'deployment.progress' | 'deployment.completed' | 'deployment.failed' | 'traffic.shifted' | 'rollback.triggered'
type DeploymentCallback = (event: DeploymentEvent, data: unknown) => void

/**
 * Blue-Green Deployment Manager
 */
export class BlueGreenDeploymentManager {
  private deployments: Map<string, DeploymentRecord> = new Map()
  private activeDeployment: DeploymentRecord | null = null
  private trafficSplit: TrafficSplit = { bluePercentage: 100, greenPercentage: 0, lastUpdated: Date.now() }
  private callbacks: Map<DeploymentEvent, Set<DeploymentCallback>> = new Map()
  private nodeProvider: (() => EdgeNode[]) | null = null
  private healthChecker: ((nodeId: string, endpoint: string) => Promise<boolean>) | null = null

  /**
   * Set node provider
   */
  setNodeProvider(provider: () => EdgeNode[]): void {
    this.nodeProvider = provider
  }

  /**
   * Set health checker
   */
  setHealthChecker(checker: (nodeId: string, endpoint: string) => Promise<boolean>): void {
    this.healthChecker = checker
  }

  /**
   * Start a new deployment
   */
  async startDeployment(config: DeploymentConfig): Promise<DeploymentRecord> {
    if (this.activeDeployment && this.activeDeployment.status === 'deploying') {
      throw new Error('Another deployment is in progress')
    }

    const deploymentId = `deploy-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`

    // Determine target slot (opposite of active)
    const targetSlot: 'blue' | 'green' = this.trafficSplit.bluePercentage >= 50 ? 'green' : 'blue'
    const idleSlot: 'blue' | 'green' = targetSlot === 'blue' ? 'green' : 'blue'

    const deployment: DeploymentRecord = {
      id: deploymentId,
      config,
      status: 'pending',
      blueSlot: {
        name: 'blue',
        version: targetSlot === 'blue' ? config.version : 'previous',
        nodes: new Set(),
        status: targetSlot === 'blue' ? 'deploying' : (this.trafficSplit.bluePercentage > 0 ? 'active' : 'idle'),
        createdAt: Date.now(),
        healthScore: 100,
        requestCount: 0,
        errorCount: 0,
      },
      greenSlot: {
        name: 'green',
        version: targetSlot === 'green' ? config.version : 'previous',
        nodes: new Set(),
        status: targetSlot === 'green' ? 'deploying' : (this.trafficSplit.greenPercentage > 0 ? 'active' : 'idle'),
        createdAt: Date.now(),
        healthScore: 100,
        requestCount: 0,
        errorCount: 0,
      },
      activeSlot: idleSlot,
      startTime: Date.now(),
      progress: 0,
      metrics: { nodesDeployed: 0, nodesHealthy: 0, nodesFailed: 0, trafficShifted: 0 },
    }

    this.deployments.set(deploymentId, deployment)
    this.activeDeployment = deployment

    this.emit('deployment.started', { deploymentId, config, targetSlot })
    logger.info('Deployment started', { deploymentId, version: config.version, targetSlot })

    // Execute deployment
    await this.executeDeployment(deployment, targetSlot)

    return deployment
  }

  /**
   * Execute deployment process
   */
  private async executeDeployment(deployment: DeploymentRecord, targetSlot: 'blue' | 'green'): Promise<void> {
    const slot = targetSlot === 'blue' ? deployment.blueSlot : deployment.greenSlot

    try {
      deployment.status = 'deploying'

      // Get nodes for deployment
      const nodes = this.nodeProvider ? this.nodeProvider().filter((n) => n.status === 'online') : []
      
      if (nodes.length === 0) {
        throw new Error('No online nodes available for deployment')
      }

      // Phase 1: Deploy to target slot
      deployment.progress = 10
      this.emit('deployment.progress', { deploymentId: deployment.id, progress: 10, phase: 'deploying' })

      for (let i = 0; i < nodes.length; i++) {
        const node = nodes[i]
        
        // Simulate deployment to node
        const success = await this.deployToNode(node, deployment.config)
        
        if (success) {
          slot.nodes.add(node.id)
          deployment.metrics.nodesDeployed++
        } else {
          deployment.metrics.nodesFailed++
        }

        deployment.progress = 10 + Math.floor((i / nodes.length) * 40)
        this.emit('deployment.progress', { deploymentId: deployment.id, progress: deployment.progress })
      }

      // Phase 2: Health check validation
      deployment.status = 'validating'
      deployment.progress = 50
      this.emit('deployment.progress', { deploymentId: deployment.id, progress: 50, phase: 'validating' })

      const healthyNodes = await this.validateHealth(slot, deployment.config)
      deployment.metrics.nodesHealthy = healthyNodes

      if (healthyNodes < deployment.config.minHealthyNodes) {
        throw new Error(`Insufficient healthy nodes: ${healthyNodes} < ${deployment.config.minHealthyNodes}`)
      }

      // Phase 3: Traffic shift
      deployment.progress = 70
      this.emit('deployment.progress', { deploymentId: deployment.id, progress: 70, phase: 'traffic-shifting' })

      await this.shiftTraffic(targetSlot, deployment.config.rolloutPercentage / 100)

      // Phase 4: Monitor for rollback
      deployment.progress = 80
      this.emit('deployment.progress', { deploymentId: deployment.id, progress: 80, phase: 'monitoring' })

      if (deployment.config.rollbackOnFailure) {
        await this.monitorForRollback(deployment, slot)
      }

      // Complete
      deployment.status = 'active'
      deployment.progress = 100
      deployment.endTime = Date.now()
      deployment.activeSlot = targetSlot
      slot.status = 'active'

      this.emit('deployment.completed', deployment)
      logger.info('Deployment completed', { deploymentId: deployment.id, version: deployment.config.version })

    } catch (error) {
      deployment.status = 'failed'
      deployment.error = (error as Error).message
      deployment.endTime = Date.now()
      slot.status = 'failed'

      if (deployment.config.rollbackOnFailure) {
        await this.rollback(deployment)
      }

      this.emit('deployment.failed', { deploymentId: deployment.id, error: deployment.error })
      logger.error('Deployment failed', error as Error, { deploymentId: deployment.id })
    }
  }

  /**
   * Deploy to a single node
   */
  private async deployToNode(node: EdgeNode, config: DeploymentConfig): Promise<boolean> {
    // Simulate deployment (in production, would use SSH/Docker API)
    await new Promise((resolve) => setTimeout(resolve, 100))

    // Simulate 95% success rate
    const success = Math.random() > 0.05

    if (success) {
      logger.debug('Deployed to node', { nodeId: node.id, version: config.version })
    } else {
      logger.warn('Failed to deploy to node', { nodeId: node.id })
    }

    return success
  }

  /**
   * Validate health of deployed nodes
   */
  private async validateHealth(slot: DeploymentSlot, config: DeploymentConfig): Promise<number> {
    let healthyCount = 0

    for (const nodeId of slot.nodes) {
      let isHealthy = false

      if (this.healthChecker) {
        isHealthy = await this.healthChecker(nodeId, config.healthCheckEndpoint)
      } else {
        // Simulate health check (90% healthy)
        isHealthy = Math.random() > 0.1
      }

      if (isHealthy) {
        healthyCount++
      }
    }

    return healthyCount
  }

  /**
   * Shift traffic between slots
   */
  private async shiftTraffic(targetSlot: 'blue' | 'green', percentage: number): Promise<void> {
    const previousSplit = { ...this.trafficSplit }

    if (targetSlot === 'blue') {
      this.trafficSplit.bluePercentage = Math.floor(percentage * 100)
      this.trafficSplit.greenPercentage = 100 - this.trafficSplit.bluePercentage
    } else {
      this.trafficSplit.greenPercentage = Math.floor(percentage * 100)
      this.trafficSplit.bluePercentage = 100 - this.trafficSplit.greenPercentage
    }

    this.trafficSplit.lastUpdated = Date.now()

    this.emit('traffic.shifted', { from: previousSplit, to: this.trafficSplit })
    logger.info('Traffic shifted', { targetSlot, percentage })
  }

  /**
   * Monitor for automatic rollback
   */
  private async monitorForRollback(deployment: DeploymentRecord, slot: DeploymentSlot): Promise<void> {
    const monitorDuration = 60000 // 1 minute
    const checkInterval = 5000
    const checks = monitorDuration / checkInterval

    for (let i = 0; i < checks; i++) {
      await new Promise((resolve) => setTimeout(resolve, checkInterval))

      // Calculate error rate
      const totalRequests = slot.requestCount || 1
      const errorRate = (slot.errorCount / totalRequests) * 100

      // Simulate some requests
      slot.requestCount += Math.floor(Math.random() * 100)
      slot.errorCount += Math.floor(Math.random() * 5)
      slot.healthScore = Math.max(0, 100 - errorRate)

      if (errorRate > deployment.config.rollbackThreshold) {
        logger.warn('Error rate exceeded threshold, triggering rollback', { errorRate, threshold: deployment.config.rollbackThreshold })
        await this.rollback(deployment)
        throw new Error(`Error rate ${errorRate.toFixed(1)}% exceeded threshold ${deployment.config.rollbackThreshold}%`)
      }
    }
  }

  /**
   * Rollback deployment
   */
  async rollback(deployment: DeploymentRecord): Promise<void> {
    const previousSlot = deployment.activeSlot

    deployment.status = 'rolling-back'
    this.emit('rollback.triggered', { deploymentId: deployment.id, previousSlot })

    // Shift traffic back
    await this.shiftTraffic(previousSlot, 1.0)

    deployment.status = 'failed'
    deployment.endTime = Date.now()

    logger.warn('Rollback completed', { deploymentId: deployment.id, revertedTo: previousSlot })
  }

  /**
   * Get current traffic split
   */
  getTrafficSplit(): TrafficSplit {
    return { ...this.trafficSplit }
  }

  /**
   * Get active deployment
   */
  getActiveDeployment(): DeploymentRecord | null {
    return this.activeDeployment
  }

  /**
   * Get deployment by ID
   */
  getDeployment(deploymentId: string): DeploymentRecord | undefined {
    return this.deployments.get(deploymentId)
  }

  /**
   * Get all deployments
   */
  getAllDeployments(): DeploymentRecord[] {
    return Array.from(this.deployments.values())
  }

  /**
   * Cancel active deployment
   */
  async cancelDeployment(deploymentId: string): Promise<boolean> {
    const deployment = this.deployments.get(deploymentId)
    if (!deployment || !['pending', 'deploying', 'validating'].includes(deployment.status)) {
      return false
    }

    await this.rollback(deployment)
    return true
  }

  /**
   * Get deployment statistics
   */
  getStats(): {
    totalDeployments: number
    successfulDeployments: number
    failedDeployments: number
    activeSlot: 'blue' | 'green'
    trafficSplit: TrafficSplit
  } {
    let successful = 0
    let failed = 0

    for (const deployment of this.deployments.values()) {
      if (deployment.status === 'active' || deployment.status === 'completed') {successful++}
      if (deployment.status === 'failed') {failed++}
    }

    return {
      totalDeployments: this.deployments.size,
      successfulDeployments: successful,
      failedDeployments: failed,
      activeSlot: this.trafficSplit.bluePercentage >= 50 ? 'blue' : 'green',
      trafficSplit: this.getTrafficSplit(),
    }
  }

  /**
   * Subscribe to events
   */
  on(event: DeploymentEvent, callback: DeploymentCallback): () => void {
    if (!this.callbacks.has(event)) {
      this.callbacks.set(event, new Set())
    }
    this.callbacks.get(event)!.add(callback)

    return () => {
      this.callbacks.get(event)?.delete(callback)
    }
  }

  private emit(event: DeploymentEvent, data: unknown): void {
    this.callbacks.get(event)?.forEach((cb) => {
      try {
        cb(event, data)
      } catch (error) {
        logger.error('Deployment callback error', error as Error)
      }
    })
  }
}

/**
 * Create blue-green deployment manager
 */
export function createBlueGreenDeploymentManager(): BlueGreenDeploymentManager {
  return new BlueGreenDeploymentManager()
}

// Default instance
export const blueGreenDeploymentManager = new BlueGreenDeploymentManager()

/**
 * Edge Node Auto-Discovery Registry
 * Handles automatic node registration, heartbeat tracking, and discovery
 */

import { logger } from '../logger'
import type { EdgeNode } from '../../types'

// Types
export interface NodeRegistration {
  nodeId: string
  ip: string
  location: string
  region: string
  cpuCores: number
  memory: number
  storage: number
  dockerVersion: string
  capabilities: string[]
  tags: Record<string, string>
  registeredAt: number
  lastHeartbeat: number
  status: 'online' | 'offline' | 'maintenance'
  metadata: Record<string, unknown>
}

export interface HeartbeatData {
  nodeId: string
  cpu: number
  memory: number
  storage: number
  tasksRunning: number
  latency: number
  timestamp: number
}

export interface DiscoveryConfig {
  heartbeatTimeout: number // Time without heartbeat before node is considered offline
  cleanupInterval: number // Interval to clean up offline nodes
  maxNodes: number // Maximum number of nodes in registry
}

type DiscoveryEvent = 'node.registered' | 'node.offline' | 'node.removed' | 'node.heartbeat' | 'node.updated'
type DiscoveryCallback = (event: DiscoveryEvent, data: unknown) => void

const DEFAULT_CONFIG: DiscoveryConfig = {
  heartbeatTimeout: 15000, // 15 seconds
  cleanupInterval: 30000, // 30 seconds
  maxNodes: 1000,
}

/**
 * Node Registry - Manages edge node discovery and lifecycle
 */
export class NodeRegistry {
  private config: DiscoveryConfig
  private nodes: Map<string, NodeRegistration> = new Map()
  private nodeMetrics: Map<string, HeartbeatData> = new Map()
  private cleanupTimer: ReturnType<typeof setInterval> | null = null
  private callbacks: Map<DiscoveryEvent, Set<DiscoveryCallback>> = new Map()

  constructor(config: Partial<DiscoveryConfig> = {}) {
    this.config = { ...DEFAULT_CONFIG, ...config }
  }

  /**
   * Start the registry
   */
  start(): void {
    // Start cleanup timer
    this.cleanupTimer = setInterval(() => {
      this.cleanupOfflineNodes()
    }, this.config.cleanupInterval)

    logger.info('Node registry started', { 
      heartbeatTimeout: this.config.heartbeatTimeout,
      maxNodes: this.config.maxNodes 
    })
  }

  /**
   * Stop the registry
   */
  stop(): void {
    if (this.cleanupTimer) {
      clearInterval(this.cleanupTimer)
      this.cleanupTimer = null
    }

    logger.info('Node registry stopped', { registeredNodes: this.nodes.size })
  }

  /**
   * Register a new node
   */
  register(registration: Omit<NodeRegistration, 'registeredAt' | 'lastHeartbeat' | 'status'>): NodeRegistration {
    const existingNode = this.nodes.get(registration.nodeId)
    
    if (existingNode) {
      // Update existing node
      const updated: NodeRegistration = {
        ...existingNode,
        ...registration,
        status: 'online',
        lastHeartbeat: Date.now(),
      }
      
      this.nodes.set(registration.nodeId, updated)
      this.emit('node.updated', { nodeId: registration.nodeId })
      logger.info('Node re-registered', { nodeId: registration.nodeId, ip: registration.ip })
      
      return updated
    }

    // Check max nodes
    if (this.nodes.size >= this.config.maxNodes) {
      throw new Error('Maximum number of nodes reached')
    }

    // Create new registration
    const node: NodeRegistration = {
      ...registration,
      registeredAt: Date.now(),
      lastHeartbeat: Date.now(),
      status: 'online',
    }

    this.nodes.set(registration.nodeId, node)
    this.emit('node.registered', { nodeId: registration.nodeId, ip: registration.ip })
    logger.info('Node registered', { 
      nodeId: registration.nodeId, 
      ip: registration.ip, 
      location: registration.location,
      region: registration.region 
    })

    return node
  }

  /**
   * Process heartbeat from a node
   */
  heartbeat(data: HeartbeatData): boolean {
    const node = this.nodes.get(data.nodeId)
    
    if (!node) {
      logger.warn('Heartbeat from unknown node', { nodeId: data.nodeId })
      return false
    }

    // Update node status
    node.lastHeartbeat = data.timestamp || Date.now()
    node.status = 'online'

    // Store metrics
    this.nodeMetrics.set(data.nodeId, data)
    this.emit('node.heartbeat', { nodeId: data.nodeId, metrics: data })

    return true
  }

  /**
   * Deregister a node
   */
  deregister(nodeId: string): boolean {
    const node = this.nodes.get(nodeId)
    
    if (!node) {
      return false
    }

    this.nodes.delete(nodeId)
    this.nodeMetrics.delete(nodeId)
    
    this.emit('node.removed', { nodeId })
    logger.info('Node deregistered', { nodeId })

    return true
  }

  /**
   * Get node by ID
   */
  getNode(nodeId: string): NodeRegistration | undefined {
    return this.nodes.get(nodeId)
  }

  /**
   * Get all nodes
   */
  getAllNodes(): NodeRegistration[] {
    return Array.from(this.nodes.values())
  }

  /**
   * Get online nodes
   */
  getOnlineNodes(): NodeRegistration[] {
    return this.getAllNodes().filter((n) => n.status === 'online')
  }

  /**
   * Get nodes by region
   */
  getNodesByRegion(region: string): NodeRegistration[] {
    return this.getAllNodes().filter((n) => n.region === region)
  }

  /**
   * Get nodes by capability
   */
  getNodesByCapability(capability: string): NodeRegistration[] {
    return this.getAllNodes().filter((n) => n.capabilities.includes(capability))
  }

  /**
   * Get node metrics
   */
  getNodeMetrics(nodeId: string): HeartbeatData | undefined {
    return this.nodeMetrics.get(nodeId)
  }

  /**
   * Check if node is online
   */
  isNodeOnline(nodeId: string): boolean {
    const node = this.nodes.get(nodeId)
    if (!node) {return false}

    const now = Date.now()
    return node.status === 'online' && (now - node.lastHeartbeat) < this.config.heartbeatTimeout
  }

  /**
   * Get registry statistics
   */
  getStats(): {
    totalNodes: number
    onlineNodes: number
    offlineNodes: number
    maintenanceNodes: number
    regions: Record<string, number>
  } {
    const nodes = this.getAllNodes()
    const now = Date.now()

    let onlineNodes = 0
    let offlineNodes = 0
    let maintenanceNodes = 0
    const regions: Record<string, number> = {}

    for (const node of nodes) {
      // Check if actually online based on heartbeat
      const isOnline = (now - node.lastHeartbeat) < this.config.heartbeatTimeout
      
      if (node.status === 'maintenance') {
        maintenanceNodes++
      } else if (isOnline) {
        onlineNodes++
      } else {
        offlineNodes++
      }

      // Count by region
      regions[node.region] = (regions[node.region] || 0) + 1
    }

    return {
      totalNodes: nodes.length,
      onlineNodes,
      offlineNodes,
      maintenanceNodes,
      regions,
    }
  }

  /**
   * Convert to EdgeNode format for compatibility
   */
  toEdgeNode(registration: NodeRegistration): EdgeNode {
    const metrics = this.nodeMetrics.get(registration.nodeId)
    
    return {
      id: registration.nodeId,
      name: `edge-${registration.nodeId.slice(0, 8)}`,
      location: registration.location,
      region: registration.region,
      status: registration.status === 'online' ? 'online' : 'offline',
      cpu: metrics?.cpu || 0,
      memory: metrics?.memory || 0,
      storage: registration.storage,
      latency: metrics?.latency || 0,
      uptime: 99.9, // Would be calculated from history
      tasksRunning: metrics?.tasksRunning || 0,
      maxTasks: Math.floor(registration.cpuCores * 2), // Rough estimate
      lastHeartbeat: new Date(registration.lastHeartbeat),
      ip: registration.ip,
      url: `http://${registration.ip}:4000`,
      costPerHour: 0.02, // Default
      bandwidthIn: 50,
      bandwidthOut: 50,
      healthHistory: [],
      isMaintenanceMode: registration.status === 'maintenance',
    }
  }

  /**
   * Cleanup offline nodes
   */
  private cleanupOfflineNodes(): void {
    const now = Date.now()
    const offlineThreshold = this.config.heartbeatTimeout * 2 // Double timeout before removal

    for (const [nodeId, node] of this.nodes) {
      const timeSinceHeartbeat = now - node.lastHeartbeat

      if (timeSinceHeartbeat > this.config.heartbeatTimeout && node.status === 'online') {
        // Mark as offline
        node.status = 'offline'
        this.emit('node.offline', { nodeId, lastHeartbeat: node.lastHeartbeat })
        logger.warn('Node marked offline', { nodeId, timeSinceHeartbeat })
      }

      if (timeSinceHeartbeat > offlineThreshold) {
        // Remove completely
        this.nodes.delete(nodeId)
        this.nodeMetrics.delete(nodeId)
        this.emit('node.removed', { nodeId, reason: 'timeout' })
        logger.info('Node removed due to timeout', { nodeId, timeSinceHeartbeat })
      }
    }
  }

  /**
   * Subscribe to events
   */
  on(event: DiscoveryEvent, callback: DiscoveryCallback): () => void {
    if (!this.callbacks.has(event)) {
      this.callbacks.set(event, new Set())
    }
    this.callbacks.get(event)!.add(callback)

    return () => {
      this.callbacks.get(event)?.delete(callback)
    }
  }

  private emit(event: DiscoveryEvent, data: unknown): void {
    this.callbacks.get(event)?.forEach((cb) => {
      try {
        cb(event, data)
      } catch (error) {
        logger.error('Node registry callback error', error as Error)
      }
    })
  }
}

/**
 * Node Discovery Service - API for node registration
 */
export class NodeDiscoveryService {
  private registry: NodeRegistry
  private authMiddleware?: (nodeId: string, token: string) => Promise<boolean>

  constructor(registry: NodeRegistry) {
    this.registry = registry
  }

  /**
   * Set authentication middleware
   */
  setAuthMiddleware(middleware: (nodeId: string, token: string) => Promise<boolean>): void {
    this.authMiddleware = middleware
  }

  /**
   * Handle registration request
   */
  async handleRegistration(
    request: {
      nodeId: string
      ip: string
      location: string
      region: string
      cpuCores: number
      memory: number
      storage: number
      dockerVersion: string
      capabilities?: string[]
      tags?: Record<string, string>
      metadata?: Record<string, unknown>
      token?: string
    }
  ): Promise<{ success: boolean; node?: NodeRegistration; error?: string }> {
    try {
      // Authenticate if middleware is set
      if (this.authMiddleware && request.token) {
        const authenticated = await this.authMiddleware(request.nodeId, request.token)
        if (!authenticated) {
          return { success: false, error: 'Authentication failed' }
        }
      }

      const node = this.registry.register({
        nodeId: request.nodeId,
        ip: request.ip,
        location: request.location,
        region: request.region,
        cpuCores: request.cpuCores,
        memory: request.memory,
        storage: request.storage,
        dockerVersion: request.dockerVersion,
        capabilities: request.capabilities || [],
        tags: request.tags || {},
        metadata: request.metadata || {},
      })

      return { success: true, node }
    } catch (error) {
      return { success: false, error: (error as Error).message }
    }
  }

  /**
   * Handle heartbeat request
   */
  async handleHeartbeat(
    data: HeartbeatData & { token?: string }
  ): Promise<{ success: boolean; error?: string }> {
    // Authenticate if middleware is set
    if (this.authMiddleware && data.token) {
      const authenticated = await this.authMiddleware(data.nodeId, data.token)
      if (!authenticated) {
        return { success: false, error: 'Authentication failed' }
      }
    }

    const success = this.registry.heartbeat(data)
    return { success }
  }

  /**
   * Handle deregistration request
   */
  async handleDeregistration(
    nodeId: string,
    token?: string
  ): Promise<{ success: boolean; error?: string }> {
    // Authenticate if middleware is set
    if (this.authMiddleware && token) {
      const authenticated = await this.authMiddleware(nodeId, token)
      if (!authenticated) {
        return { success: false, error: 'Authentication failed' }
      }
    }

    const success = this.registry.deregister(nodeId)
    return { success }
  }

  /**
   * Get registry statistics
   */
  getStats() {
    return this.registry.getStats()
  }
}

// Factory functions
export function createNodeRegistry(config: Partial<DiscoveryConfig> = {}): NodeRegistry {
  return new NodeRegistry(config)
}

export function createDiscoveryService(registry: NodeRegistry): NodeDiscoveryService {
  return new NodeDiscoveryService(registry)
}

// Default instances
export const nodeRegistry = new NodeRegistry()
export const discoveryService = new NodeDiscoveryService(nodeRegistry)

import type { DockerContainer, DockerImage, TaskContainerMapping } from '../types/docker'

const DOCKER_API_BASE = 'http://localhost:2375/v1.41'

class DockerClient {
  private async fetch(path: string, options?: RequestInit): Promise<Response> {
    const url = `${DOCKER_API_BASE}${path}`
    const response = await fetch(url, {
      ...options,
      headers: {
        'Content-Type': 'application/json',
        ...options?.headers,
      },
    })
    
    if (!response.ok) {
      const error = await response.text()
      throw new Error(`Docker API error: ${response.status} - ${error}`)
    }
    
    return response
  }

  async listContainers(all = false): Promise<DockerContainer[]> {
    try {
      const response = await this.fetch(`/containers/json?all=${all}`)
      const containers = await response.json()
      
      return containers.map((c: unknown) => this.parseContainer(c))
    } catch (error) {
      console.error('Failed to list containers:', error)
      return []
    }
  }

  async getContainerStats(containerId: string): Promise<{ cpu: number; memory: number } | null> {
    try {
      const response = await this.fetch(`/containers/${containerId}/stats?stream=false`)
      const stats = await response.json()
      
      // Calculate CPU percentage
      const cpuDelta = stats.cpu_stats.cpu_usage.total_usage - stats.precpu_stats.cpu_usage.total_usage
      const systemDelta = stats.cpu_stats.system_cpu_usage - stats.precpu_stats.system_cpu_usage
      const cpuPercent = systemDelta > 0 ? (cpuDelta / systemDelta) * 100 : 0
      
      // Calculate memory usage
      const memoryUsage = stats.memory_stats.usage || 0
      const memoryLimit = stats.memory_stats.limit || 1
      const memoryPercent = (memoryUsage / memoryLimit) * 100
      
      return {
        cpu: Math.round(cpuPercent * 100) / 100,
        memory: Math.round(memoryPercent * 100) / 100,
      }
    } catch (error) {
      console.error('Failed to get container stats:', error)
      return null
    }
  }

  async createContainer(config: {
    image: string
    name: string
    cmd?: string[]
    env?: string[]
    ports?: Record<string, {}>
    labels?: Record<string, string>
    resources?: {
      CpuShares?: number
      Memory?: number
    }
  }): Promise<string> {
    // Create container
    const createResponse = await this.fetch('/containers/create', {
      method: 'POST',
      body: JSON.stringify({
        Image: config.image,
        Cmd: config.cmd,
        Env: config.env,
        ExposedPorts: config.ports,
        Labels: config.labels,
        HostConfig: {
          PortBindings: config.ports,
          Resources: config.resources,
        },
      }),
    })
    
    const { Id } = await createResponse.json()
    
    // Rename container
    await this.fetch(`/containers/${Id}/rename?name=${config.name}`, {
      method: 'POST',
    })
    
    return Id
  }

  async startContainer(containerId: string): Promise<void> {
    await this.fetch(`/containers/${containerId}/start`, {
      method: 'POST',
    })
  }

  async stopContainer(containerId: string, timeout = 30): Promise<void> {
    await this.fetch(`/containers/${containerId}/stop?t=${timeout}`, {
      method: 'POST',
    })
  }

  async removeContainer(containerId: string, force = false): Promise<void> {
    await this.fetch(`/containers/${containerId}?force=${force}`, {
      method: 'DELETE',
    })
  }

  async getContainerLogs(containerId: string, tail = 100): Promise<string> {
    const response = await this.fetch(
      `/containers/${containerId}/logs?stdout=true&stderr=true&tail=${tail}`
    )
    const logs = await response.text()
    // Docker logs have an 8-byte header, strip it
    return logs.replace(/[\x00-\x08]/g, '').trim()
  }

  async pullImage(image: string): Promise<void> {
    const response = await this.fetch(`/images/create?fromImage=${encodeURIComponent(image)}`, {
      method: 'POST',
    })
    // Wait for pull to complete
    await response.text()
  }

  async listImages(): Promise<DockerImage[]> {
    try {
      const response = await this.fetch('/images/json')
      const images = await response.json()
      
      return images.map((img: unknown) => ({
        id: (img as { Id: string }).Id,
        name: ((img as { RepoTags: string[] }).RepoTags?.[0] || 'none').split(':')[0],
        tag: ((img as { RepoTags: string[] }).RepoTags?.[0] || 'none').split(':')[1] || 'latest',
        size: (img as { Size: number }).Size,
        created: new Date((img as { Created: number }).Created * 1000),
        containers: (img as { Containers: number }).Containers || 0,
      }))
    } catch (error) {
      console.error('Failed to list images:', error)
      return []
    }
  }

  async getSystemInfo(): Promise<{ version: string; cpus: number; memory: number } | null> {
    try {
      const response = await this.fetch('/info')
      const info = await response.json()
      
      return {
        version: info.ServerVersion,
        cpus: info.NCPU,
        memory: info.MemTotal,
      }
    } catch (error) {
      console.error('Failed to get system info:', error)
      return null
    }
  }

  isAvailable(): boolean {
    // Check if Docker API is accessible
    return typeof window !== 'undefined' && window.location.hostname === 'localhost'
  }

  private parseContainer(c: unknown): DockerContainer {
    const container = c as {
      Id: string
      Names: string[]
      Image: string
      State: string
      Status: string
      Created: number
      Ports: Array<{
        PrivatePort: number
        PublicPort?: number
        Type: string
      }>
      Labels: Record<string, string>
    }
    
    return {
      id: container.Id,
      name: container.Names[0]?.replace('/', '') || 'unknown',
      image: container.Image,
      status: this.parseStatus(container.State),
      state: container.Status,
      cpuPercent: 0,
      memoryUsage: 0,
      memoryLimit: 0,
      networkRx: 0,
      networkTx: 0,
      created: new Date(container.Created * 1000),
      ports: container.Ports?.map((p) => ({
        privatePort: p.PrivatePort,
        publicPort: p.PublicPort,
        type: p.Type as 'tcp' | 'udp',
      })) || [],
      labels: container.Labels || {},
    }
  }

  private parseStatus(state: string): DockerContainer['status'] {
    switch (state) {
      case 'running':
        return 'running'
      case 'exited':
      case 'dead':
        return 'stopped'
      case 'paused':
        return 'paused'
      case 'restarting':
        return 'restarting'
      default:
        return 'stopped'
    }
  }
}

