/**
 * Event Stream Architecture
 * Provides event sourcing and real-time event streaming
 */

import { logger } from '../logger'

// Types
export interface Event {
  id: string
  type: string
  aggregateId: string
  aggregateType: string
  version: number
  timestamp: number
  payload: unknown
  metadata: {
    correlationId?: string
    causationId?: string
    userId?: string
    source: string
  }
}

export interface EventSubscription {
  id: string
  eventType: string | RegExp
  callback: (event: Event) => Promise<void>
  filter?: (event: Event) => boolean
  createdAt: number
  active: boolean
}

export interface EventStreamConfig {
  maxEventsInMemory: number
  snapshotInterval: number
  retentionMs: number
  batchSize: number
}

export interface EventReplay {
  id: string
  fromVersion: number
  toVersion: number
  aggregateType?: string
  status: 'pending' | 'running' | 'completed' | 'failed'
  processedCount: number
  startedAt?: number
  completedAt?: number
}

type EventStreamEvent = 'event.appended' | 'event.published' | 'subscription.added' | 'replay.started' | 'replay.completed'
type EventStreamCallback = (event: EventStreamEvent, data: unknown) => void

const DEFAULT_CONFIG: EventStreamConfig = {
  maxEventsInMemory: 10000,
  snapshotInterval: 100,
  retentionMs: 86400000, // 24 hours
  batchSize: 100,
}

/**
 * Event Store - Append-only log of all events
 */
export class EventStore {
  private config: EventStreamConfig
  private events: Event[] = []
  private eventIndex: Map<string, number> = new Map() // eventId -> index
  private aggregateVersions: Map<string, number> = new Map() // aggregateId -> version
  private subscriptions: Map<string, EventSubscription> = new Map()
  private projections: Map<string, (events: Event[]) => unknown> = new Map()
  private callbacks: Map<EventStreamEvent, Set<EventStreamCallback>> = new Map()
  private publisher: ((event: Event) => Promise<void>) | null = null

  constructor(config: Partial<EventStreamConfig> = {}) {
    this.config = { ...DEFAULT_CONFIG, ...config }
  }

  /**
   * Set external publisher (e.g., Kafka, Redis Streams)
   */
  setPublisher(publisher: (event: Event) => Promise<void>): void {
    this.publisher = publisher
  }

  /**
   * Append event to store
   */
  async append(
    type: string,
    aggregateId: string,
    aggregateType: string,
    payload: unknown,
    metadata: Event['metadata']
  ): Promise<Event> {
    // Get current version
    const currentVersion = this.aggregateVersions.get(aggregateId) || 0
    const newVersion = currentVersion + 1

    const event: Event = {
      id: `evt-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
      type,
      aggregateId,
      aggregateType,
      version: newVersion,
      timestamp: Date.now(),
      payload,
      metadata: {
        ...metadata,
        source: metadata.source || 'event-store',
      },
    }

    // Append to store
    this.events.push(event)
    this.eventIndex.set(event.id, this.events.length - 1)
    this.aggregateVersions.set(aggregateId, newVersion)

    // Trim old events
    if (this.events.length > this.config.maxEventsInMemory) {
      const removed = this.events.length - this.config.maxEventsInMemory
      this.events = this.events.slice(removed)
      this.rebuildIndex()
    }

    this.emit('event.appended', event)
    logger.debug('Event appended', { eventId: event.id, type, aggregateId, version: newVersion })

    // Publish to subscribers
    await this.publish(event)

    return event
  }

  /**
   * Publish event to subscribers
   */
  private async publish(event: Event): Promise<void> {
    // External publisher
    if (this.publisher) {
      await this.publisher(event)
    }

    // Internal subscriptions
    const promises: Promise<void>[] = []

    for (const subscription of this.subscriptions.values()) {
      if (!subscription.active) {continue}

      // Check event type match
      const typeMatch = typeof subscription.eventType === 'string'
        ? subscription.eventType === event.type
        : subscription.eventType.test(event.type)

      if (!typeMatch) {continue}

      // Apply filter
      if (subscription.filter && !subscription.filter(event)) {continue}

      promises.push(subscription.callback(event))
    }

    await Promise.allSettled(promises)
    this.emit('event.published', { eventId: event.id, subscriberCount: promises.length })
  }

  /**
   * Subscribe to events
   */
  subscribe(
    eventType: string | RegExp,
    callback: (event: Event) => Promise<void>,
    filter?: (event: Event) => boolean
  ): string {
    const subscriptionId = `sub-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`

    const subscription: EventSubscription = {
      id: subscriptionId,
      eventType,
      callback,
      filter,
      createdAt: Date.now(),
      active: true,
    }

    this.subscriptions.set(subscriptionId, subscription)
    this.emit('subscription.added', { subscriptionId, eventType: eventType.toString() })

    return subscriptionId
  }

  /**
   * Unsubscribe
   */
  unsubscribe(subscriptionId: string): boolean {
    return this.subscriptions.delete(subscriptionId)
  }

  /**
   * Get events for aggregate
   */
  getEvents(aggregateId: string, fromVersion: number = 0): Event[] {
    return this.events.filter(
      (e) => e.aggregateId === aggregateId && e.version > fromVersion
    )
  }

  /**
   * Get events by type
   */
  getEventsByType(type: string, limit: number = 100): Event[] {
    return this.events.filter((e) => e.type === type).slice(-limit)
  }

  /**
   * Get events in time range
   */
  getEventsByTimeRange(start: number, end: number): Event[] {
    return this.events.filter((e) => e.timestamp >= start && e.timestamp <= end)
  }

  /**
   * Replay events
   */
  async replay(
    fromVersion: number,
    toVersion: number,
    handler: (event: Event) => Promise<void>,
    aggregateType?: string
  ): Promise<EventReplay> {
    const replay: EventReplay = {
      id: `replay-${Date.now()}`,
      fromVersion,
      toVersion,
      aggregateType,
      status: 'running',
      processedCount: 0,
      startedAt: Date.now(),
    }

    this.emit('replay.started', replay)

    try {
      const events = this.events.filter((e) => {
        if (e.version < fromVersion || e.version > toVersion) {return false}
        if (aggregateType && e.aggregateType !== aggregateType) {return false}
        return true
      })

      for (const event of events) {
        await handler(event)
        replay.processedCount++
      }

      replay.status = 'completed'
      replay.completedAt = Date.now()
    } catch (error) {
      replay.status = 'failed'
      logger.error('Event replay failed', error as Error, { replayId: replay.id })
    }

    this.emit('replay.completed', replay)
    return replay
  }

  /**
   * Register projection
   */
  registerProjection(name: string, projector: (events: Event[]) => unknown): void {
    this.projections.set(name, projector)
  }

  /**
   * Run projection
   */
  runProjection(name: string, aggregateId?: string): unknown {
    const projector = this.projections.get(name)
    if (!projector) {return null}

    const events = aggregateId
      ? this.getEvents(aggregateId)
      : this.events

    return projector(events)
  }

  /**
   * Rebuild index
   */
  private rebuildIndex(): void {
    this.eventIndex.clear()
    this.events.forEach((event, index) => {
      this.eventIndex.set(event.id, index)
    })
  }

  /**
   * Get statistics
   */
  getStats(): {
    totalEvents: number
    totalAggregates: number
    totalSubscriptions: number
    oldestEvent: number | null
    newestEvent: number | null
  } {
    return {
      totalEvents: this.events.length,
      totalAggregates: this.aggregateVersions.size,
      totalSubscriptions: this.subscriptions.size,
      oldestEvent: this.events[0]?.timestamp || null,
      newestEvent: this.events[this.events.length - 1]?.timestamp || null,
    }
  }

  /**
   * Subscribe to stream events
   */
  on(event: EventStreamEvent, callback: EventStreamCallback): () => void {
    if (!this.callbacks.has(event)) {
      this.callbacks.set(event, new Set())
    }
    this.callbacks.get(event)!.add(callback)

    return () => {
      this.callbacks.get(event)?.delete(callback)
    }
  }

  private emit(event: EventStreamEvent, data: unknown): void {
    this.callbacks.get(event)?.forEach((cb) => {
      try {
        cb(event, data)
      } catch (error) {
        logger.error('Event stream callback error', error as Error)
      }
    })
  }
}

/**
 * Event Types for the orchestrator
 */
export const EventTypes = {
  // Node events
  NODE_REGISTERED: 'node.registered',
  NODE_DEREGISTERED: 'node.deregistered',
  NODE_HEARTBEAT: 'node.heartbeat',
  NODE_STATUS_CHANGED: 'node.status_changed',
  
  // Task events
  TASK_CREATED: 'task.created',
  TASK_SCHEDULED: 'task.scheduled',
  TASK_STARTED: 'task.started',
  TASK_COMPLETED: 'task.completed',
  TASK_FAILED: 'task.failed',
  TASK_MIGRATED: 'task.migrated',
  
  // Scheduler events
  SCHEDULER_DECISION: 'scheduler.decision',
  SCHEDULER_POLICY_CHANGED: 'scheduler.policy_changed',
  
  // Cluster events
  LEADER_ELECTED: 'cluster.leader_elected',
  LEADER_DEMOTED: 'cluster.leader_demoted',
  
  // Alert events
  ALERT_TRIGGERED: 'alert.triggered',
  ALERT_RESOLVED: 'alert.resolved',
  
  // Recovery events
  FAILURE_DETECTED: 'recovery.failure_detected',
  RECOVERY_STARTED: 'recovery.started',
  RECOVERY_COMPLETED: 'recovery.completed',
} as const

/**
 * Event Builder - Helper for creating events
 */
export class EventBuilder {
  private type: string = ''
  private aggregateId: string = ''
  private aggregateType: string = ''
  private payload: unknown = null
  private metadata: Event['metadata'] = { source: 'unknown' }

  withType(type: string): this {
    this.type = type
    return this
  }

  forAggregate(id: string, type: string): this {
    this.aggregateId = id
    this.aggregateType = type
    return this
  }

  withPayload(payload: unknown): this {
    this.payload = payload
    return this
  }

  withMetadata(metadata: Partial<Event['metadata']>): this {
    this.metadata = { ...this.metadata, ...metadata }
    return this
  }

  withCorrelationId(id: string): this {
    this.metadata.correlationId = id
    return this
  }

  withSource(source: string): this {
    this.metadata.source = source
    return this
  }

  build(): { type: string; aggregateId: string; aggregateType: string; payload: unknown; metadata: Event['metadata'] } {
    return {
      type: this.type,
      aggregateId: this.aggregateId,
      aggregateType: this.aggregateType,
      payload: this.payload,
      metadata: this.metadata,
    }
  }
}

/**
 * Create event store
 */
export function createEventStore(config: Partial<EventStreamConfig> = {}): EventStore {
  return new EventStore(config)
}

/**
 * Create event builder
 */
export function event(): EventBuilder {
  return new EventBuilder()
}

// Default instance
export const eventStore = new EventStore()

import type { ContainerExecution, TaskContainerMapping } from '../types/docker'
import { agentPool } from './agent-pool'
import { circuitBreakerRegistry } from './circuit-breaker'
import { DEFAULT_TASK_MAPPINGS,dockerClient } from './docker'
import { webhookManager } from './webhook'
import type { Task } from '../types'

class TaskExecutor {
  private executions: Map<string, ContainerExecution> = new Map()
  private taskMappings: TaskContainerMapping[] = DEFAULT_TASK_MAPPINGS

  async executeTask(task: Task, targetNodeUrl?: string): Promise<void> {
    const execution: ContainerExecution = {
      containerId: '',
      taskId: task.id,
      taskName: task.name,
      status: 'pending',
      logs: [],
    }

    this.executions.set(task.id, execution)

    // Use circuit breaker for the target node
    const nodeUrl = targetNodeUrl || 'local'
    const circuitBreaker = circuitBreakerRegistry.get(`node-${nodeUrl}`, {
      failureThreshold: 3,
      timeout: 30000
    })

    try {
      await circuitBreaker.execute(async () => {
        // If target node specified and not local, use agent pool
        if (targetNodeUrl && targetNodeUrl !== 'local') {
          await this.executeOnRemoteNode(task, execution, targetNodeUrl)
          return
        }

        // Check if Docker is available locally
        if (!dockerClient.isAvailable()) {
          // Fall back to simulation mode
          await this.simulateExecution(task, execution)
          return
        }

        // Get container mapping for task type
        const mapping = this.taskMappings.find((m) => m.taskType === task.type)
        if (!mapping) {
          throw new Error(`No container mapping for task type: ${task.type}`)
        }

        // Update status
        execution.status = 'pulling'
        
        // Pull image
        try {
          await dockerClient.pullImage(mapping.image)
        } catch (error) {
          console.warn('Failed to pull image, may already exist:', error)
        }

        // Create container
        const containerName = `edgecloud-task-${task.id}`
        execution.containerId = await dockerClient.createContainer({
          image: mapping.image,
          name: containerName,
          cmd: mapping.command,
          env: mapping.env ? Object.entries(mapping.env).map(([k, v]) => `${k}=${v}`) : undefined,
          labels: {
            'edgecloud.task.id': task.id,
            'edgecloud.task.name': task.name,
            'edgecloud.task.type': task.type,
          },
          resources: mapping.resources,
        })

        // Start container
        execution.status = 'running'
        execution.startTime = new Date()
        await dockerClient.startContainer(execution.containerId)

        // Monitor container
        await this.monitorContainer(task, execution)
      })
    } catch (error) {
      execution.status = 'failed'
      execution.error = error instanceof Error ? error.message : 'Unknown error'
      execution.endTime = new Date()

      // Trigger webhook
      await webhookManager.triggerEvent('task.failed', {
        taskId: task.id,
        taskName: task.name,
        error: execution.error,
        retryCount: task.retryCount,
        maxRetries: task.maxRetries,
      })
    }
  }

  private async executeOnRemoteNode(
    task: Task,
    execution: ContainerExecution,
    nodeUrl: string
  ): Promise<void> {
    const mapping = this.taskMappings.find((m) => m.taskType === task.type)
    if (!mapping) {
      throw new Error(`No container mapping for task type: ${task.type}`)
    }

    execution.status = 'running'
    execution.startTime = new Date()

    const result = await agentPool.executeTask(nodeUrl, {
      taskId: task.id,
      taskName: task.name,
      image: mapping.image,
      resources: mapping.resources
    }) as { status: string; exitCode: number; stdout: string; stderr: string }

    execution.endTime = new Date()

    if (result.status === 'completed' && result.exitCode === 0) {
      execution.status = 'completed'
      execution.logs = result.stdout.split('\n')

      await webhookManager.triggerEvent('task.completed', {
        taskId: task.id,
        taskName: task.name,
        duration: execution.endTime.getTime() - (execution.startTime?.getTime() || 0),
        cost: task.cost,
        output: result.stdout,
      })
    } else {
      execution.status = 'failed'
      execution.error = result.stderr || 'Remote execution failed'
      execution.logs = [result.stderr || 'Unknown error']

      await webhookManager.triggerEvent('task.failed', {
        taskId: task.id,
        taskName: task.name,
        error: execution.error,
        retryCount: task.retryCount,
        maxRetries: task.maxRetries,
      })
    }
  }

  private async monitorContainer(task: Task, execution: ContainerExecution): Promise<void> {
    const checkInterval = setInterval(async () => {
      try {
        const containers = await dockerClient.listContainers(true)
        const container = containers.find((c) => c.id === execution.containerId)

        if (!container) {
          // Container removed
          clearInterval(checkInterval)
          execution.status = 'completed'
          execution.endTime = new Date()
          
          // Get logs
          try {
            const logs = await dockerClient.getContainerLogs(execution.containerId, 50)
            execution.logs = logs.split('\n')
          } catch {
            // Ignore log errors
          }

          // Trigger webhook
          await webhookManager.triggerEvent('task.completed', {
            taskId: task.id,
            taskName: task.name,
            duration: execution.endTime.getTime() - (execution.startTime?.getTime() || 0),
            cost: task.cost,
            output: execution.logs.join('\n'),
          })

          return
        }

        if (container.status === 'stopped') {
          clearInterval(checkInterval)
          execution.status = 'completed'
          execution.endTime = new Date()

          // Get logs
          try {
            const logs = await dockerClient.getContainerLogs(execution.containerId, 50)
            execution.logs = logs.split('\n')
          } catch {
            // Ignore log errors
          }

          // Trigger webhook
          await webhookManager.triggerEvent('task.completed', {
            taskId: task.id,
            taskName: task.name,
            duration: execution.endTime.getTime() - (execution.startTime?.getTime() || 0),
            cost: task.cost,
            output: execution.logs.join('\n'),
          })

          // Cleanup container
          try {
            await dockerClient.removeContainer(execution.containerId, true)
          } catch {
            // Ignore cleanup errors
          }
        }

      } catch (error) {
        console.error('Error monitoring container:', error)
      }
    }, 1000)

    // Timeout after task duration + 30 seconds
    setTimeout(() => {
      clearInterval(checkInterval)
      if (execution.status === 'running') {
        execution.status = 'failed'
        execution.error = 'Execution timeout'
        execution.endTime = new Date()

        // Stop and remove container
        dockerClient.stopContainer(execution.containerId, 0).catch(() => {})
        dockerClient.removeContainer(execution.containerId, true).catch(() => {})

        // Trigger webhook
        webhookManager.triggerEvent('task.failed', {
          taskId: task.id,
          taskName: task.name,
          error: 'Execution timeout',
          retryCount: task.retryCount,
          maxRetries: task.maxRetries,
        }).catch(() => {})
      }
    }, task.duration + 30000)
  }

  private async simulateExecution(task: Task, execution: ContainerExecution): Promise<void> {
    // Simulate execution with setTimeout
    setTimeout(async () => {
      const isFailed = Math.random() < 0.08
      
      if (isFailed) {
        execution.status = 'failed'
        execution.error = 'Simulated execution error'
        execution.endTime = new Date()

        await webhookManager.triggerEvent('task.failed', {
          taskId: task.id,
          taskName: task.name,
          error: execution.error,
          retryCount: task.retryCount,
          maxRetries: task.maxRetries,
        })
      } else {
        execution.status = 'completed'
        execution.endTime = new Date()
        execution.logs = [`Task ${task.name} completed successfully`]

        await webhookManager.triggerEvent('task.completed', {
          taskId: task.id,
          taskName: task.name,
          duration: task.duration,
          cost: task.cost,
          output: execution.logs.join('\n'),
        })
      }
    }, task.duration)
  }

  getExecution(taskId: string): ContainerExecution | undefined {
    return this.executions.get(taskId)
  }

  getAllExecutions(): ContainerExecution[] {
    return Array.from(this.executions.values())
  }

  setTaskMappings(mappings: TaskContainerMapping[]): void {
    this.taskMappings = mappings
  }

  getTaskMappings(): TaskContainerMapping[] {
    return this.taskMappings
  }
}

export const taskExecutor = new TaskExecutor()

/**
 * Federated Learning Support
 * Distributed ML training across edge nodes without centralizing data
 */

import { logger } from '../logger'
import type { EdgeNode } from '../../types'

// Types
export interface FLModel {
  id: string
  name: string
  version: string
  architecture: string
  inputShape: number[]
  outputShape: number[]
  parameters: number
  createdAt: number
  updatedAt: number
}

export interface FLClient {
  nodeId: string
  status: 'idle' | 'training' | 'uploading' | 'syncing' | 'error'
  lastSync: number
  localEpochs: number
  localSamples: number
  modelVersion: string
  gradientNorm: number
  loss: number
  accuracy: number
}

export interface FLRound {
  id: string
  roundNumber: number
  status: 'pending' | 'aggregating' | 'completed' | 'failed'
  startedAt: number
  completedAt?: number
  participatingClients: string[]
  globalModelVersion: string
  aggregatedUpdates: Map<string, number[]>
  metrics: {
    avgLoss: number
    avgAccuracy: number
    clientCount: number
    totalSamples: number
  }
}

export interface FLConfig {
  minClients: number
  maxClients: number
  minSamplesPerClient: number
  localEpochs: number
  learningRate: number
  aggregationStrategy: 'fedavg' | 'fedprox' | 'fedadam'
  privacyBudget?: number // Differential privacy
  noiseMultiplier?: number
  gradientClipNorm?: number
  roundsPerEvaluation: number
  convergenceThreshold: number
}

export interface FLTrainingSession {
  id: string
  modelId: string
  config: FLConfig
  status: 'initializing' | 'running' | 'paused' | 'completed' | 'failed'
  currentRound: number
  totalRounds: number
  clients: Map<string, FLClient>
  rounds: FLRound[]
  globalModel: FLModel
  startedAt: number
  completedAt?: number
  metrics: {
    bestAccuracy: number
    bestRound: number
    convergenceHistory: number[]
  }
}

type FLEvent = 'session.started' | 'round.started' | 'round.completed' | 'client.joined' | 'client.updated' | 'session.completed'
type FLCallback = (event: FLEvent, data: unknown) => void

const DEFAULT_CONFIG: FLConfig = {
  minClients: 3,
  maxClients: 10,
  minSamplesPerClient: 100,
  localEpochs: 5,
  learningRate: 0.01,
  aggregationStrategy: 'fedavg',
  roundsPerEvaluation: 5,
  convergenceThreshold: 0.001,
}

/**
 * Federated Learning Coordinator
 */
export class FederatedLearningCoordinator {
  private sessions: Map<string, FLTrainingSession> = new Map()
  private models: Map<string, FLModel> = new Map()
  private callbacks: Map<FLEvent, Set<FLCallback>> = new Map()
  private nodeProvider: (() => EdgeNode[]) | null = null
  private modelStorage: Map<string, number[]> = new Map() // modelId -> weights

  constructor() {}

  /**
   * Set node provider
   */
  setNodeProvider(provider: () => EdgeNode[]): void {
    this.nodeProvider = provider
  }

  /**
   * Register a model for federated training
   */
  registerModel(model: Omit<FLModel, 'createdAt' | 'updatedAt'>): FLModel {
    const flModel: FLModel = {
      ...model,
      createdAt: Date.now(),
      updatedAt: Date.now(),
    }

    this.models.set(model.id, flModel)
    
    // Initialize random weights (simulated)
    const weights = this.initializeWeights(model.parameters)
    this.modelStorage.set(model.id, weights)

    logger.info('FL model registered', { modelId: model.id, name: model.name })
    return flModel
  }

  /**
   * Initialize model weights
   */
  private initializeWeights(paramCount: number): number[] {
    // Xavier initialization
    const scale = Math.sqrt(2 / paramCount)
    return Array.from({ length: Math.min(paramCount, 1000) }, () => 
      (Math.random() - 0.5) * 2 * scale
    )
  }

  /**
   * Start a federated training session
   */
  async startTrainingSession(
    modelId: string,
    config: Partial<FLConfig> = {},
    totalRounds: number = 10
  ): Promise<FLTrainingSession> {
    const model = this.models.get(modelId)
    if (!model) {
      throw new Error(`Model ${modelId} not found`)
    }

    const sessionId = `fl-session-${Date.now()}`
    const fullConfig: FLConfig = { ...DEFAULT_CONFIG, ...config }

    // Get available clients
    const nodes = this.nodeProvider ? this.nodeProvider().filter((n) => n.status === 'online') : []
    const clientCount = Math.min(nodes.length, fullConfig.maxClients)

    if (clientCount < fullConfig.minClients) {
      throw new Error(`Insufficient clients: ${clientCount} < ${fullConfig.minClients}`)
    }

    const clients = new Map<string, FLClient>()
    for (let i = 0; i < clientCount; i++) {
      clients.set(nodes[i].id, {
        nodeId: nodes[i].id,
        status: 'idle',
        lastSync: Date.now(),
        localEpochs: 0,
        localSamples: Math.floor(Math.random() * 10000) + fullConfig.minSamplesPerClient,
        modelVersion: '0',
        gradientNorm: 0,
        loss: 1.0,
        accuracy: 0,
      })
    }

    const session: FLTrainingSession = {
      id: sessionId,
      modelId,
      config: fullConfig,
      status: 'initializing',
      currentRound: 0,
      totalRounds,
      clients,
      rounds: [],
      globalModel: model,
      startedAt: Date.now(),
      metrics: {
        bestAccuracy: 0,
        bestRound: 0,
        convergenceHistory: [],
      },
    }

    this.sessions.set(sessionId, session)
    this.emit('session.started', { sessionId, modelId, clientCount })

    logger.info('FL training session started', { sessionId, modelId, clientCount, totalRounds })

    // Run training
    await this.runTraining(session)

    return session
  }

  /**
   * Run federated training loop
   */
  private async runTraining(session: FLTrainingSession): Promise<void> {
    session.status = 'running'

    for (let round = 1; round <= session.totalRounds; round++) {
      if (session.status !== 'running') {break}

      session.currentRound = round
      const flRound = await this.executeRound(session, round)
      session.rounds.push(flRound)

      // Check convergence
      if (flRound.metrics.avgAccuracy > session.metrics.bestAccuracy) {
        session.metrics.bestAccuracy = flRound.metrics.avgAccuracy
        session.metrics.bestRound = round
      }
      session.metrics.convergenceHistory.push(flRound.metrics.avgAccuracy)

      // Early stopping
      if (round > session.config.roundsPerEvaluation) {
        const recent = session.metrics.convergenceHistory.slice(-session.config.roundsPerEvaluation)
        const improvement = Math.max(...recent) - Math.min(...recent)
        if (improvement < session.config.convergenceThreshold) {
          logger.info('FL training converged early', { sessionId: session.id, round })
          break
        }
      }
    }

    session.status = 'completed'
    session.completedAt = Date.now()
    this.emit('session.completed', session)
    logger.info('FL training completed', { sessionId: session.id, rounds: session.currentRound })
  }

  /**
   * Execute a single federated round
   */
  private async executeRound(session: FLTrainingSession, roundNumber: number): Promise<FLRound> {
    const roundId = `round-${session.id}-${roundNumber}`
    
    const round: FLRound = {
      id: roundId,
      roundNumber,
      status: 'pending',
      startedAt: Date.now(),
      participatingClients: Array.from(session.clients.keys()),
      globalModelVersion: `${roundNumber}`,
      aggregatedUpdates: new Map(),
      metrics: { avgLoss: 0, avgAccuracy: 0, clientCount: 0, totalSamples: 0 },
    }

    this.emit('round.started', { sessionId: session.id, roundNumber })

    // Phase 1: Distribute global model to clients
    await this.distributeModel(session, round)

    // Phase 2: Local training on each client
    const updates = await this.localTraining(session, round)

    // Phase 3: Aggregate updates
    round.status = 'aggregating'
    const aggregated = this.aggregateUpdates(session, updates, round)
    round.aggregatedUpdates = aggregated

    // Phase 4: Update global model
    this.updateGlobalModel(session, aggregated)

    // Calculate metrics
    round.metrics = this.calculateRoundMetrics(session, updates)
    round.status = 'completed'
    round.completedAt = Date.now()

    this.emit('round.completed', { sessionId: session.id, roundNumber, metrics: round.metrics })

    return round
  }

  /**
   * Distribute global model to clients
   */
  private async distributeModel(session: FLTrainingSession, _round: FLRound): Promise<void> {
    for (const [_nodeId, client] of session.clients) {
      client.status = 'syncing'
      client.modelVersion = _round.globalModelVersion
      
      // Simulate model distribution
      await new Promise((resolve) => setTimeout(resolve, 10))
      
      client.status = 'training'
    }
  }

  /**
   * Execute local training on clients
   */
  private async localTraining(
    session: FLTrainingSession,
    _round: FLRound
  ): Promise<Map<string, { gradients: number[]; samples: number; loss: number; accuracy: number }>> {
    const updates = new Map<string, { gradients: number[]; samples: number; loss: number; accuracy: number }>()

    for (const [nodeId, client] of session.clients) {
      // Simulate local training
      const localUpdates = await this.simulateLocalTraining(client, session.config)
      updates.set(nodeId, localUpdates)

      client.status = 'uploading'
      client.localEpochs += session.config.localEpochs
      client.loss = localUpdates.loss
      client.accuracy = localUpdates.accuracy
      client.gradientNorm = Math.sqrt(localUpdates.gradients.reduce((s, g) => s + g * g, 0))

      this.emit('client.updated', { sessionId: session.id, nodeId, accuracy: client.accuracy })
    }

    return updates
  }

  /**
   * Simulate local training (in production, would call actual ML framework)
   */
  private async simulateLocalTraining(
    client: FLClient,
    _config: FLConfig
  ): Promise<{ gradients: number[]; samples: number; loss: number; accuracy: number }> {
    await new Promise((resolve) => setTimeout(resolve, 50))

    // Simulate training improvement
    const improvement = Math.random() * 0.05
    const baseAccuracy = client.accuracy || 0.5
    const newAccuracy = Math.min(0.99, baseAccuracy + improvement)
    const newLoss = Math.max(0.01, (1 - newAccuracy) + Math.random() * 0.1)

    // Simulate gradients
    const gradients = Array.from({ length: 100 }, () => (Math.random() - 0.5) * 0.1)

    return {
      gradients,
      samples: client.localSamples,
      loss: newLoss,
      accuracy: newAccuracy,
    }
  }

  /**
   * Aggregate client updates (FedAvg)
   */
  private aggregateUpdates(
    session: FLTrainingSession,
    updates: Map<string, { gradients: number[]; samples: number; loss: number; accuracy: number }>,
    _round: FLRound
  ): Map<string, number[]> {
    const aggregated = new Map<string, number[]>()
    
    const totalSamples = Array.from(updates.values()).reduce((s, u) => s + u.samples, 0)
    
    // Weighted average of gradients
    const avgGradients: number[] = []
    const gradientLength = 100 // Simplified

    for (let i = 0; i < gradientLength; i++) {
      let weightedSum = 0
      for (const [, update] of updates) {
        weightedSum += (update.gradients[i] || 0) * (update.samples / totalSamples)
      }
      avgGradients.push(weightedSum)
    }

    // Apply differential privacy noise if configured
    if (session.config.privacyBudget && session.config.noiseMultiplier) {
      const noiseScale = session.config.noiseMultiplier / session.config.privacyBudget
      for (let i = 0; i < avgGradients.length; i++) {
        avgGradients[i] += (Math.random() - 0.5) * 2 * noiseScale
      }
    }

    // Clip gradients if configured
    if (session.config.gradientClipNorm) {
      const norm = Math.sqrt(avgGradients.reduce((s, g) => s + g * g, 0))
      if (norm > session.config.gradientClipNorm) {
        const scale = session.config.gradientClipNorm / norm
        for (let i = 0; i < avgGradients.length; i++) {
          avgGradients[i] *= scale
        }
      }
    }

    aggregated.set('global', avgGradients)
    return aggregated
  }

  /**
   * Update global model with aggregated updates
   */
  private updateGlobalModel(
    session: FLTrainingSession,
    aggregated: Map<string, number[]>
  ): void {
    const currentWeights = this.modelStorage.get(session.modelId) || []
    const gradients = aggregated.get('global') || []

    // SGD update
    const newWeights = currentWeights.map((w, i) => 
      w - session.config.learningRate * (gradients[i] || 0)
    )

    this.modelStorage.set(session.modelId, newWeights)
    
    // Update model
    const model = this.models.get(session.modelId)
    if (model) {
      model.updatedAt = Date.now()
    }
  }

  /**
   * Calculate round metrics
   */
  private calculateRoundMetrics(
    _session: FLTrainingSession,
    updates: Map<string, { gradients: number[]; samples: number; loss: number; accuracy: number }>
  ): FLRound['metrics'] {
    const values = Array.from(updates.values())
    const totalSamples = values.reduce((s, u) => s + u.samples, 0)

    return {
      avgLoss: values.reduce((s, u) => s + u.loss, 0) / values.length,
      avgAccuracy: values.reduce((s, u) => s + u.accuracy, 0) / values.length,
      clientCount: values.length,
      totalSamples,
    }
  }

  /**
   * Get session
   */
  getSession(sessionId: string): FLTrainingSession | undefined {
    return this.sessions.get(sessionId)
  }

  /**
   * Get model
   */
  getModel(modelId: string): FLModel | undefined {
    return this.models.get(modelId)
  }

  /**
   * Get model weights
   */
  getModelWeights(modelId: string): number[] | undefined {
    return this.modelStorage.get(modelId)
  }

  /**
   * Get all sessions
   */
  getAllSessions(): FLTrainingSession[] {
    return Array.from(this.sessions.values())
  }

  /**
   * Pause training
   */
  pauseSession(sessionId: string): boolean {
    const session = this.sessions.get(sessionId)
    if (!session || session.status !== 'running') {return false}
    session.status = 'paused'
    return true
  }

  /**
   * Resume training
   */
  async resumeSession(sessionId: string): Promise<boolean> {
    const session = this.sessions.get(sessionId)
    if (!session || session.status !== 'paused') {return false}
    session.status = 'running'
    await this.runTraining(session)
    return true
  }

  /**
   * Get statistics
   */
  getStats(): {
    totalModels: number
    totalSessions: number
    activeSessions: number
    completedSessions: number
  } {
    let active = 0
    let completed = 0

    for (const session of this.sessions.values()) {
      if (session.status === 'running') {active++}
      if (session.status === 'completed') {completed++}
    }

    return {
      totalModels: this.models.size,
      totalSessions: this.sessions.size,
      activeSessions: active,
      completedSessions: completed,
    }
  }

  /**
   * Subscribe to events
   */
  on(event: FLEvent, callback: FLCallback): () => void {
    if (!this.callbacks.has(event)) {
      this.callbacks.set(event, new Set())
    }
    this.callbacks.get(event)!.add(callback)

    return () => {
      this.callbacks.get(event)?.delete(callback)
    }
  }

  private emit(event: FLEvent, data: unknown): void {
    this.callbacks.get(event)?.forEach((cb) => {
      try {
        cb(event, data)
      } catch (error) {
        logger.error('FL callback error', error as Error)
      }
    })
  }
}

