/**
 * ML Model Training for Predictive Scheduler
 * Replaces heuristics with actual trained models
 */

import { logger } from '../logger'
import type { EdgeNode,Task } from '../../types'

// Types
export interface TrainingSample {
  features: number[]
  label: number // Execution time
  taskType: string
  nodeId: string
  timestamp: number
}

export interface ModelWeights {
  bias: number
  weights: number[]
}

export interface TrainedModel {
  taskType: string
  weights: ModelWeights
  featureMeans: number[]
  featureStds: number[]
  trainingSamples: number
  lastUpdated: number
  mse: number
  r2Score: number
}

export interface TrainingConfig {
  learningRate: number
  epochs: number
  batchSize: number
  regularization: number
  minSamples: number
  featureCount: number
}

export interface PredictionResult {
  estimatedTime: number
  confidence: number
  features: Record<string, number>
  modelVersion: string
}

type ModelEvent = 'model.trained' | 'model.updated' | 'prediction.made'
type ModelCallback = (event: ModelEvent, data: unknown) => void

const DEFAULT_CONFIG: TrainingConfig = {
  learningRate: 0.01,
  epochs: 100,
  batchSize: 32,
  regularization: 0.001,
  minSamples: 50,
  featureCount: 10,
}

// Feature names for interpretability
const FEATURE_NAMES = [
  'cpu_usage',
  'memory_usage',
  'network_latency',
  'disk_io',
  'task_complexity',
  'historical_avg',
  'time_of_day',
  'day_of_week',
  'concurrent_tasks',
  'node_load',
]

/**
 * Linear Regression Model with Gradient Descent
 */
class LinearRegressionModel {
  private weights: ModelWeights
  private featureMeans: number[] = []
  private featureStds: number[] = []
  private trained = false

  constructor(featureCount: number) {
    this.weights = {
      bias: 0,
      weights: new Array(featureCount).fill(0),
    }
  }

  /**
   * Normalize features
   */
  private normalize(features: number[]): number[] {
    return features.map((f, i) => {
      if (this.featureStds[i] === 0) {return 0}
      return (f - this.featureMeans[i]) / this.featureStds[i]
    })
  }

  /**
   * Fit the model using gradient descent
   */
  fit(samples: TrainingSample[], config: TrainingConfig): { mse: number; r2Score: number } {
    if (samples.length < config.minSamples) {
      throw new Error(`Need at least ${config.minSamples} samples, got ${samples.length}`)
    }

    // Extract features and labels
    const X = samples.map((s) => s.features)
    const y = samples.map((s) => s.label)

    // Calculate feature statistics for normalization
    this.featureMeans = new Array(config.featureCount).fill(0)
    this.featureStds = new Array(config.featureCount).fill(0)

    for (let j = 0; j < config.featureCount; j++) {
      const values = X.map((x) => x[j])
      this.featureMeans[j] = values.reduce((a, b) => a + b, 0) / values.length
      const variance = values.reduce((sum, v) => sum + Math.pow(v - this.featureMeans[j], 2), 0) / values.length
      this.featureStds[j] = Math.sqrt(variance) || 1
    }

    // Normalize features
    const XNormalized = X.map((f) => this.normalize(f))

    // Gradient descent
    const n = samples.length
    
    for (let epoch = 0; epoch < config.epochs; epoch++) {
      // Shuffle data
      const indices = Array.from({ length: n }, (_, i) => i)
      for (let i = n - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1))
        ;[indices[i], indices[j]] = [indices[j], indices[i]]
      }

      // Mini-batch gradient descent
      for (let batch = 0; batch < n; batch += config.batchSize) {
        const batchIndices = indices.slice(batch, batch + config.batchSize)
        
        let gradientBias = 0
        const gradientWeights = new Array(config.featureCount).fill(0)

        for (const i of batchIndices) {
          const prediction = this.predictSingle(XNormalized[i])
          const error = prediction - y[i]

          gradientBias += error
          for (let j = 0; j < config.featureCount; j++) {
            gradientWeights[j] += error * XNormalized[i][j]
          }
        }

        // Update weights with L2 regularization
        const batchSize = batchIndices.length
        this.weights.bias -= config.learningRate * (gradientBias / batchSize)
        for (let j = 0; j < config.featureCount; j++) {
          this.weights.weights[j] -= config.learningRate * (
            gradientWeights[j] / batchSize + 
            config.regularization * this.weights.weights[j]
          )
        }
      }
    }

    this.trained = true

    // Calculate metrics
    const predictions = XNormalized.map((f) => this.predictSingle(f))
    const mse = predictions.reduce((sum, p, i) => sum + Math.pow(p - y[i], 2), 0) / n
    
    const yMean = y.reduce((a, b) => a + b, 0) / n
    const ssRes = predictions.reduce((sum, p, i) => sum + Math.pow(y[i] - p, 2), 0)
    const ssTot = y.reduce((sum, yi) => sum + Math.pow(yi - yMean, 2), 0)
    const r2Score = 1 - (ssRes / ssTot)

    return { mse, r2Score }
  }

  /**
   * Predict for a single sample
   */
  private predictSingle(features: number[]): number {
    let prediction = this.weights.bias
    for (let i = 0; i < features.length; i++) {
      prediction += this.weights.weights[i] * features[i]
    }
    return prediction
  }

  /**
   * Predict execution time
   */
  predict(features: number[]): number {
    if (!this.trained) {return 1000} // Default 1 second
    const normalized = this.normalize(features)
    return Math.max(0, this.predictSingle(normalized))
  }

  /**
   * Get model weights
   */
  getWeights(): ModelWeights {
    return { ...this.weights }
  }

  /**
   * Set model weights
   */
  setWeights(weights: ModelWeights): void {
    this.weights = { ...weights }
    this.trained = true
  }

  /**
   * Set normalization parameters
   */
  setNormalization(means: number[], stds: number[]): void {
    this.featureMeans = means
    this.featureStds = stds
  }
}

/**
 * ML Model Manager
 */
export class MLModelManager {
  private config: TrainingConfig
  private models: Map<string, LinearRegressionModel> = new Map()
  private trainingData: Map<string, TrainingSample[]> = new Map()
  private modelVersions: Map<string, TrainedModel> = new Map()
  private callbacks: Map<ModelEvent, Set<ModelCallback>> = new Map()
  private maxSamplesPerType = 10000

  constructor(config: Partial<TrainingConfig> = {}) {
    this.config = { ...DEFAULT_CONFIG, ...config }
  }

  /**
   * Extract features from task and node
   */
  extractFeatures(task: Task, node: EdgeNode, historicalAvg?: number): number[] {
    const now = new Date()
    
    return [
      node.cpu / 100,                              // cpu_usage (normalized 0-1)
      node.memory / 100,                           // memory_usage (normalized 0-1)
      (node.latency || 50) / 100,                  // network_latency (normalized)
      (node.storage || 50) / 100,                  // disk_io (proxy)
      this.getTaskComplexity(task),                // task_complexity
      (historicalAvg || 1000) / 10000,            // historical_avg (normalized)
      now.getHours() / 24,                         // time_of_day
      now.getDay() / 7,                            // day_of_week
      node.tasksRunning / Math.max(node.maxTasks, 1), // concurrent_tasks
      (node.cpu + node.memory) / 200,             // node_load
    ]
  }

  /**
   * Get task complexity score
   */
  private getTaskComplexity(task: Task): number {
    const complexityMap: Record<string, number> = {
      'Image Classification': 0.7,
      'Data Aggregation': 0.3,
      'Model Inference': 0.9,
      'Sensor Fusion': 0.8,
      'Video Processing': 0.95,
      'Log Analysis': 0.4,
      'Anomaly Detection': 0.6,
    }
    return complexityMap[task.type] || 0.5
  }

  /**
   * Add training sample
   */
  addSample(
    task: Task,
    node: EdgeNode,
    executionTime: number,
    historicalAvg?: number
  ): void {
    const features = this.extractFeatures(task, node, historicalAvg)
    
    const sample: TrainingSample = {
      features,
      label: executionTime,
      taskType: task.type,
      nodeId: node.id,
      timestamp: Date.now(),
    }

    if (!this.trainingData.has(task.type)) {
      this.trainingData.set(task.type, [])
    }

    const samples = this.trainingData.get(task.type)!
    samples.push(sample)

    // Trim to max samples
    if (samples.length > this.maxSamplesPerType) {
      this.trainingData.set(task.type, samples.slice(-this.maxSamplesPerType))
    }
  }

  /**
   * Train model for a task type
   */
  train(taskType: string): TrainedModel | null {
    const samples = this.trainingData.get(taskType)
    
    if (!samples || samples.length < this.config.minSamples) {
      logger.warn('Not enough samples for training', { taskType, samples: samples?.length || 0 })
      return null
    }

    // Create or get model
    let model = this.models.get(taskType)
    if (!model) {
      model = new LinearRegressionModel(this.config.featureCount)
    }

    try {
      const { mse, r2Score } = model.fit(samples, this.config)
      
      const trainedModel: TrainedModel = {
        taskType,
        weights: model.getWeights(),
        featureMeans: model['featureMeans'],
        featureStds: model['featureStds'],
        trainingSamples: samples.length,
        lastUpdated: Date.now(),
        mse,
        r2Score,
      }

      this.models.set(taskType, model)
      this.modelVersions.set(taskType, trainedModel)

      this.emit('model.trained', { taskType, mse, r2Score, samples: samples.length })
      logger.info('Model trained', { taskType, mse, r2Score, samples: samples.length })

      return trainedModel
    } catch (error) {
      logger.error('Model training failed', error as Error, { taskType })
      return null
    }
  }

  /**
   * Predict execution time
   */
  predict(task: Task, node: EdgeNode, historicalAvg?: number): PredictionResult {
    const model = this.models.get(task.type)
    const features = this.extractFeatures(task, node, historicalAvg)
    
    let estimatedTime = 1000 // Default 1 second
    let confidence = 0.3

    if (model) {
      estimatedTime = model.predict(features)
      
      const modelInfo = this.modelVersions.get(task.type)
      if (modelInfo) {
        confidence = Math.min(0.9, 0.3 + (modelInfo.r2Score * 0.5) + (modelInfo.trainingSamples / 1000) * 0.1)
      }
    }

    const featureMap: Record<string, number> = {}
    FEATURE_NAMES.forEach((name, i) => {
      featureMap[name] = features[i]
    })

    const result: PredictionResult = {
      estimatedTime,
      confidence,
      features: featureMap,
      modelVersion: `${task.type}-v${Date.now()}`,
    }

    this.emit('prediction.made', { taskId: task.id, nodeId: node.id, estimatedTime, confidence })
    
    return result
  }

  /**
   * Get best node based on ML prediction
   */
  predictBestNode(
    task: Task,
    nodes: EdgeNode[],
    historicalAvgs: Map<string, number> = new Map()
  ): { node: EdgeNode; estimatedTime: number; confidence: number } | null {
    if (nodes.length === 0) {return null}

    let bestNode: EdgeNode | null = null
    let bestTime = Infinity
    let bestConfidence = 0

    for (const node of nodes) {
      if (node.status !== 'online') {continue}
      
      const historicalAvg = historicalAvgs.get(node.id)
      const prediction = this.predict(task, node, historicalAvg)

      if (prediction.estimatedTime < bestTime) {
        bestTime = prediction.estimatedTime
        bestNode = node
        bestConfidence = prediction.confidence
      }
    }

    return bestNode ? { node: bestNode, estimatedTime: bestTime, confidence: bestConfidence } : null
  }

  /**
   * Get model info
   */
  getModelInfo(taskType: string): TrainedModel | undefined {
    return this.modelVersions.get(taskType)
  }

  /**
   * Get all model info
   */
  getAllModels(): TrainedModel[] {
    return Array.from(this.modelVersions.values())
  }

  /**
   * Get training data stats
   */
  getTrainingStats(): Record<string, { samples: number; hasModel: boolean }> {
    const stats: Record<string, { samples: number; hasModel: boolean }> = {}
    
    for (const [taskType, samples] of this.trainingData) {
      stats[taskType] = {
        samples: samples.length,
        hasModel: this.models.has(taskType),
      }
    }

    return stats
  }

  /**
   * Export model for persistence
   */
  exportModel(taskType: string): TrainedModel | null {
    return this.modelVersions.get(taskType) || null
  }

  /**
   * Import model from persistence
   */
  importModel(model: TrainedModel): void {
    const lrModel = new LinearRegressionModel(this.config.featureCount)
    lrModel.setWeights(model.weights)
    lrModel.setNormalization(model.featureMeans, model.featureStds)
    
    this.models.set(model.taskType, lrModel)
    this.modelVersions.set(model.taskType, model)
    
    logger.info('Model imported', { taskType: model.taskType, samples: model.trainingSamples })
  }

  /**
   * Subscribe to events
   */
  on(event: ModelEvent, callback: ModelCallback): () => void {
    if (!this.callbacks.has(event)) {
      this.callbacks.set(event, new Set())
    }
    this.callbacks.get(event)!.add(callback)

    return () => {
      this.callbacks.get(event)?.delete(callback)
    }
  }

  private emit(event: ModelEvent, data: unknown): void {
    this.callbacks.get(event)?.forEach((cb) => {
      try {
        cb(event, data)
      } catch (error) {
        logger.error('ML model callback error', error as Error)
      }
    })
  }
}

/**
 * Create ML model manager
 */
export function createMLModelManager(config: Partial<TrainingConfig> = {}): MLModelManager {
  return new MLModelManager(config)
}

// Default instance
export const mlModelManager = new MLModelManager()

interface SpanContext {
  traceId: string
  spanId: string
  parentSpanId?: string
  sampled: boolean
  baggage: Record<string, string>
}

interface Span {
  context: SpanContext
  operationName: string
  startTime: number
  duration: number
  tags: Record<string, unknown>
  logs: Array<{ timestamp: number; fields: Record<string, unknown> }>
  references: Array<{ type: 'child_of' | 'follows_from'; context: SpanContext }>
}

interface JaegerConfig {
  serviceName: string
  agentHost?: string
  agentPort?: number
  flushIntervalMs?: number
  maxQueueSize?: number
}

class JaegerTracer {
  private config: Required<JaegerConfig>
  private spans: Span[] = []
  private currentSpan: Map<string, Span> = new Map()
  private flushInterval: ReturnType<typeof setInterval> | null = null

  constructor(config: JaegerConfig) {
    this.config = {
      agentHost: 'localhost',
      agentPort: 6832,
      flushIntervalMs: 1000,
      maxQueueSize: 1000,
      ...config,
    }
    this.startFlushInterval()
  }

  private startFlushInterval(): void {
    this.flushInterval = setInterval(() => {
      this.flush()
    }, this.config.flushIntervalMs)
  }

  private generateId(): string {
    return Math.random().toString(16).substring(2) + Date.now().toString(16)
  }

  startSpan(
    operationName: string,
    options?: {
      childOf?: SpanContext
      references?: Array<{ type: 'child_of' | 'follows_from'; context: SpanContext }>
      tags?: Record<string, unknown>
    }
  ): SpanContext {
    const traceId = options?.childOf?.traceId ?? this.generateId()
    const spanId = this.generateId()

    const context: SpanContext = {
      traceId,
      spanId,
      parentSpanId: options?.childOf?.spanId,
      sampled: options?.childOf?.sampled ?? true,
      baggage: options?.childOf?.baggage ?? {},
    }

    const span: Span = {
      context,
      operationName,
      startTime: Date.now() * 1000, // Microseconds
      duration: 0,
      tags: {
        'service.name': this.config.serviceName,
        ...options?.tags,
      },
      logs: [],
      references: options?.references ?? [],
    }

    if (options?.childOf) {
      span.references.push({ type: 'child_of', context: options.childOf })
    }

    this.currentSpan.set(spanId, span)

    return context
  }

  finishSpan(spanId: string, tags?: Record<string, unknown>): void {
    const span = this.currentSpan.get(spanId)
    if (!span) {return}

    span.duration = Date.now() * 1000 - span.startTime

    if (tags) {
      span.tags = { ...span.tags, ...tags }
    }

    this.currentSpan.delete(spanId)

    // Add to queue
    this.spans.push(span)

    // Flush if queue is full
    if (this.spans.length >= this.config.maxQueueSize) {
      this.flush()
    }
  }

  log(spanId: string, fields: Record<string, unknown>): void {
    const span = this.currentSpan.get(spanId)
    if (!span) {return}

    span.logs.push({
      timestamp: Date.now() * 1000,
      fields,
    })
  }

  setTag(spanId: string, key: string, value: unknown): void {
    const span = this.currentSpan.get(spanId)
    if (!span) {return}

    span.tags[key] = value
  }

  inject(context: SpanContext, format: 'http' | 'text_map', carrier: Record<string, string>): void {
    switch (format) {
      case 'http':
      case 'text_map':
        carrier['uber-trace-id'] = `${context.traceId}:${context.spanId}:${context.parentSpanId ?? '0'}:${context.sampled ? '1' : '0'}`
        Object.entries(context.baggage).forEach(([key, value]) => {
          carrier[`uberctx-${key}`] = value
        })
        break
    }
  }

  extract(format: 'http' | 'text_map', carrier: Record<string, string>): SpanContext | null {
    switch (format) {
      case 'http':
      case 'text_map': {
        const traceId = carrier['uber-trace-id']
        if (!traceId) {return null}

        const parts = traceId.split(':')
        if (parts.length !== 4) {return null}

        const baggage: Record<string, string> = {}
        Object.entries(carrier).forEach(([key, value]) => {
          if (key.startsWith('uberctx-')) {
            baggage[key.substring(8)] = value
          }
        })

        return {
          traceId: parts[0],
          spanId: parts[1],
          parentSpanId: parts[2] !== '0' ? parts[2] : undefined,
          sampled: parts[3] === '1',
          baggage,
        }
      }
      default:
        return null
    }
  }

  private flush(): void {
    if (this.spans.length === 0) {return}

    const batch = [...this.spans]
    this.spans = []

    // Send to Jaeger agent via UDP (Thrift compact protocol)
    // In browser environment, we'll use HTTP instead
    this.sendSpans(batch).catch(console.error)
  }

  private async sendSpans(spans: Span[]): Promise<void> {
    // Convert to Jaeger Thrift format
    const payload = {
      process: {
        serviceName: this.config.serviceName,
        tags: [],
      },
      spans: spans.map((span) => ({
        traceIdLow: this.parseTraceId(span.context.traceId).low,
        traceIdHigh: this.parseTraceId(span.context.traceId).high,
        spanId: this.parseSpanId(span.context.spanId),
        parentSpanId: span.context.parentSpanId ? this.parseSpanId(span.context.parentSpanId) : 0,
        operationName: span.operationName,
        references: span.references.map((ref) => ({
          refType: ref.type === 'child_of' ? 0 : 1,
          traceIdLow: this.parseTraceId(ref.context.traceId).low,
          traceIdHigh: this.parseTraceId(ref.context.traceId).high,
          spanId: this.parseSpanId(ref.context.spanId),
        })),
        flags: span.context.sampled ? 1 : 0,
        startTime: span.startTime,
        duration: span.duration,
        tags: Object.entries(span.tags).map(([key, value]) => ({
          key,
          vType: this.getTagType(value),
          vStr: typeof value === 'string' ? value : undefined,
          vBool: typeof value === 'boolean' ? value : undefined,
          vLong: typeof value === 'number' ? value : undefined,
        })),
        logs: span.logs.map((log) => ({
          timestamp: log.timestamp,
          fields: Object.entries(log.fields).map(([key, value]) => ({
            key,
            vType: this.getTagType(value),
            vStr: typeof value === 'string' ? value : undefined,
          })),
        })),
      })),
    }

    // Send via HTTP to Jaeger collector
    try {
      await fetch(`http://${this.config.agentHost}:${this.config.agentPort}/api/traces`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(payload),
      })
    } catch (error) {
      console.error('Failed to send spans to Jaeger:', error)
    }
  }

  private parseTraceId(traceId: string): { low: number; high: number } {
    // Simplified - in production use proper 128-bit parsing
    const num = parseInt(traceId.substring(0, 16), 16) || Date.now()
    return { low: num, high: 0 }
  }

  private parseSpanId(spanId: string): number {
    return parseInt(spanId.substring(0, 16), 16) || Date.now()
  }

  private getTagType(value: unknown): number {
    switch (typeof value) {
      case 'string':
        return 0 // STRING
      case 'boolean':
        return 1 // BOOL
      case 'number':
        return Number.isInteger(value) ? 2 : 3 // LONG : DOUBLE
      default:
        return 0
    }
  }

  destroy(): void {
    if (this.flushInterval) {
      clearInterval(this.flushInterval)
    }
    this.flush()
  }
}

// Helper for automatic span creation around async functions
async function traceAsync<T>(
  tracer: JaegerTracer,
  operationName: string,
  fn: (span: SpanContext) => Promise<T>,
  parentContext?: SpanContext
): Promise<T> {
  const span = tracer.startSpan(operationName, { childOf: parentContext })

  try {
    const result = await fn(span)
    tracer.finishSpan(span.spanId, { 'span.status': 'ok' })
    return result
  } catch (error) {
    tracer.finishSpan(span.spanId, {
      'span.status': 'error',
      'error.message': error instanceof Error ? error.message : 'Unknown error',
    })
    throw error
  }
}

// Singleton instance
export const jaegerTracer = new JaegerTracer({
  serviceName: 'edge-cloud-orchestrator',
})

export { JaegerTracer, traceAsync }
export type { JaegerConfig,Span, SpanContext }

interface MetricValue {
  value: number
  timestamp: number
  labels: Record<string, string>
}

interface MetricDefinition {
  name: string
  help: string
  type: 'counter' | 'gauge' | 'histogram' | 'summary'
}

class PrometheusMetrics {
  private metrics: Map<string, MetricDefinition> = new Map()
  private values: Map<string, MetricValue[]> = new Map()
  private histogramBuckets = [0.005, 0.01, 0.025, 0.05, 0.1, 0.25, 0.5, 1, 2.5, 5, 10]

  register(definition: MetricDefinition): void {
    this.metrics.set(definition.name, definition)
    if (!this.values.has(definition.name)) {
      this.values.set(definition.name, [])
    }
  }

  counter(name: string, labels: Record<string, string> = {}, value = 1): void {
    const def = this.metrics.get(name)
    if (!def) {
      console.warn(`Metric ${name} not registered`)
      return
    }

    // const key = this.getLabelKey(name, labels)  // Reserved for future use
    const values = this.values.get(name) || []
    const existing = values.find((v) => this.labelsMatch(v.labels, labels))

    if (existing) {
      existing.value += value
      existing.timestamp = Date.now()
    } else {
      values.push({ value, timestamp: Date.now(), labels })
    }

    this.values.set(name, values)
  }

  gauge(name: string, labels: Record<string, string> = {}, value: number): void {
    const def = this.metrics.get(name)
    if (!def) {
      console.warn(`Metric ${name} not registered`)
      return
    }

    const values = this.values.get(name) || []
    const existing = values.find((v) => this.labelsMatch(v.labels, labels))

    if (existing) {
      existing.value = value
      existing.timestamp = Date.now()
    } else {
      values.push({ value, timestamp: Date.now(), labels })
    }

    this.values.set(name, values)
  }

  histogram(name: string, labels: Record<string, string> = {}, value: number): void {
    const def = this.metrics.get(name)
    if (!def) {
      console.warn(`Metric ${name} not registered`)
      return
    }

    const key = `${name}_bucket`
    const values = this.values.get(key) || []

    // Create bucket counters
    for (const bucket of this.histogramBuckets) {
      const bucketLabels = { ...labels, le: bucket.toString() }
      const existing = values.find((v) => this.labelsMatch(v.labels, bucketLabels))

      if (existing) {
        if (value <= bucket) {
          existing.value += 1
        }
        existing.timestamp = Date.now()
      } else {
        values.push({
          value: value <= bucket ? 1 : 0,
          timestamp: Date.now(),
          labels: bucketLabels,
        })
      }
    }

    // +Inf bucket
    const infLabels = { ...labels, le: '+Inf' }
    const infExisting = values.find((v) => this.labelsMatch(v.labels, infLabels))
    if (infExisting) {
      infExisting.value += 1
      infExisting.timestamp = Date.now()
    } else {
      values.push({ value: 1, timestamp: Date.now(), labels: infLabels })
    }

    this.values.set(key, values)

    // Store sum and count
    this.storeHistogramSumCount(name, labels, value)
  }

  private storeHistogramSumCount(name: string, labels: Record<string, string>, value: number): void {
    // Sum
    const sumKey = `${name}_sum`
    const sumValues = this.values.get(sumKey) || []
    const sumExisting = sumValues.find((v) => this.labelsMatch(v.labels, labels))
    if (sumExisting) {
      sumExisting.value += value
      sumExisting.timestamp = Date.now()
    } else {
      sumValues.push({ value, timestamp: Date.now(), labels })
    }
    this.values.set(sumKey, sumValues)

    // Count
    const countKey = `${name}_count`
    const countValues = this.values.get(countKey) || []
    const countExisting = countValues.find((v) => this.labelsMatch(v.labels, labels))
    if (countExisting) {
      countExisting.value += 1
      countExisting.timestamp = Date.now()
    } else {
      countValues.push({ value: 1, timestamp: Date.now(), labels })
    }
    this.values.set(countKey, countValues)
  }

  private labelsMatch(a: Record<string, string>, b: Record<string, string>): boolean {
    const keysA = Object.keys(a)
    const keysB = Object.keys(b)
    if (keysA.length !== keysB.length) {return false}

    return keysA.every((key) => a[key] === b[key])
  }

  // private getLabelKey(name: string, labels: Record<string, string>): string {
  //   const labelStr = Object.entries(labels)
  //     .sort(([a], [b]) => a.localeCompare(b))
  //     .map(([k, v]) => `${k}="${v}"`)
  //     .join(',')
  //   return `${name}{${labelStr}}`
  // }

  export(): string {
    let output = ''

    for (const [name, def] of this.metrics) {
      output += `# HELP ${name} ${def.help}\n`
      output += `# TYPE ${name} ${def.type}\n`

      if (def.type === 'histogram') {
        // Export histogram buckets
        const bucketValues = this.values.get(`${name}_bucket`) || []
        for (const v of bucketValues) {
          output += `${name}_bucket${this.formatLabels(v.labels)} ${v.value}\n`
        }

        // Export sum
        const sumValues = this.values.get(`${name}_sum`) || []
        for (const v of sumValues) {
          output += `${name}_sum${this.formatLabels(v.labels)} ${v.value}\n`
        }

        // Export count
        const countValues = this.values.get(`${name}_count`) || []
        for (const v of countValues) {
          output += `${name}_count${this.formatLabels(v.labels)} ${v.value}\n`
        }
      } else {
        const values = this.values.get(name) || []
        for (const v of values) {
          output += `${name}${this.formatLabels(v.labels)} ${v.value}\n`
        }
      }

      output += '\n'
    }

    return output
  }

  private formatLabels(labels: Record<string, string>): string {
    const entries = Object.entries(labels)
    if (entries.length === 0) {return ''}

    const labelStr = entries
      .sort(([a], [b]) => a.localeCompare(b))
      .map(([k, v]) => `${k}="${v}"`)
      .join(',')

    return `{${labelStr}}`
  }

  getMetric(name: string): MetricValue[] {
    return this.values.get(name) || []
  }

  clear(): void {
    this.values.clear()
  }
}

