// Token management
const TOKEN_KEY = 'auth_token'
const REFRESH_TOKEN_KEY = 'refresh_token'
const USER_KEY = 'user_data'

export const authStorage = {
  getToken: (): string | null => localStorage.getItem(TOKEN_KEY),
  setToken: (token: string) => localStorage.setItem(TOKEN_KEY, token),
  getRefreshToken: (): string | null => localStorage.getItem(REFRESH_TOKEN_KEY),
  setRefreshToken: (token: string) => localStorage.setItem(REFRESH_TOKEN_KEY, token),
  getUser: (): User | null => {
    const user = localStorage.getItem(USER_KEY)
    return user ? JSON.parse(user) : null
  },
  setUser: (user: User) => localStorage.setItem(USER_KEY, JSON.stringify(user)),
  clear: () => {
    localStorage.removeItem(TOKEN_KEY)
    localStorage.removeItem(REFRESH_TOKEN_KEY)
    localStorage.removeItem(USER_KEY)
  },
}

// HTTP Client with auth
class ApiClient {
  private baseUrl: string

  constructor(baseUrl: string) {
    this.baseUrl = baseUrl
  }

  private async request<T>(
    endpoint: string,
    options: RequestInit = {}
  ): Promise<ApiResponse<T>> {
    const token = authStorage.getToken()
    
    const headers: HeadersInit = {
      'Content-Type': 'application/json',
      ...options.headers,
    }

    if (token) {
      (headers as Record<string, string>)['Authorization'] = `Bearer ${token}`
    }

    try {
      const response = await fetch(`${this.baseUrl}${endpoint}`, {
        ...options,
        headers,
      })

      const data = await response.json()

      if (!response.ok) {
        if (response.status === 401) {
          // Try to refresh token
          const refreshed = await this.refreshToken()
          if (refreshed) {
            // Retry the request
            return this.request<T>(endpoint, options)
          } else {
            authStorage.clear()
            // Don't redirect - let ProtectedRoute handle it
          }
        }
        return { error: data.error || data.message || 'Request failed' }
      }

      return { data }
    } catch (error) {
      return { error: error instanceof Error ? error.message : 'Network error' }
    }
  }

  private async refreshToken(): Promise<boolean> {
    const refreshToken = authStorage.getRefreshToken()
    if (!refreshToken) {return false}

    try {
      const response = await fetch(`${this.baseUrl}/api/auth/refresh`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ refreshToken }),
      })

      if (!response.ok) {return false}

      const data = await response.json()
      authStorage.setToken(data.token)
      authStorage.setRefreshToken(data.refreshToken)
      return true
    } catch {
      return false
    }
  }

  // HTTP methods
  get<T>(endpoint: string) {
    return this.request<T>(endpoint, { method: 'GET' })
  }

  post<T>(endpoint: string, body?: unknown) {
    return this.request<T>(endpoint, {
      method: 'POST',
      body: body ? JSON.stringify(body) : undefined,
    })
  }

  patch<T>(endpoint: string, body?: unknown) {
    return this.request<T>(endpoint, {
      method: 'PATCH',
      body: body ? JSON.stringify(body) : undefined,
    })
  }

  delete<T>(endpoint: string) {
    return this.request<T>(endpoint, { method: 'DELETE' })
  }
}

// Create a dynamic API client that reads config at request time
class DynamicApiClient {
  private getBaseUrl: () => string

  constructor(getBaseUrl: () => string) {
    this.getBaseUrl = getBaseUrl
  }

  private async requestDynamic<T>(
    endpoint: string,
    options: RequestInit = {}
  ): Promise<ApiResponse<T>> {
    const token = authStorage.getToken()
    const baseUrl = this.getBaseUrl()
    
    console.log('[API] Request:', options.method, endpoint, 'baseUrl:', baseUrl)
    
    const headers: HeadersInit = {
      'Content-Type': 'application/json',
      ...options.headers,
    }

    if (token) {
      (headers as Record<string, string>)['Authorization'] = `Bearer ${token}`
    }

    try {
      const url = `${baseUrl}${endpoint}`
      console.log('[API] Fetching:', url)
      const response = await fetch(url, {
        ...options,
        headers,
      })
      console.log('[API] Response status:', response.status)

      const data = await response.json()

      if (!response.ok) {
        if (response.status === 401) {
          const refreshed = await this.refreshToken()
          if (refreshed) {
            return this.requestDynamic<T>(endpoint, options)
          } else {
            authStorage.clear()
          }
        }
        return { error: data.error || data.message || 'Request failed' }
      }

      return { data }
    } catch (error) {
      return { error: error instanceof Error ? error.message : 'Network error' }
    }
  }

  private async refreshToken(): Promise<boolean> {
    const refreshToken = authStorage.getRefreshToken()
    if (!refreshToken) {return false}

    try {
      const baseUrl = this.getBaseUrl()
      const response = await fetch(`${baseUrl}/api/auth/refresh`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ refreshToken }),
      })

      if (!response.ok) {
        return false
      }

      const data = await response.json()
      if (data.token) {
        authStorage.setToken(data.token)
        return true
      }
      return false
    } catch {
      return false
    }
  }

  get<T>(endpoint: string) {
    return this.requestDynamic<T>(endpoint, { method: 'GET' })
  }

  post<T>(endpoint: string, body?: unknown) {
    return this.requestDynamic<T>(endpoint, {
      method: 'POST',
      body: body ? JSON.stringify(body) : undefined,
    })
  }

  patch<T>(endpoint: string, body?: unknown) {
    return this.requestDynamic<T>(endpoint, {
      method: 'PATCH',
      body: body ? JSON.stringify(body) : undefined,
    })
  }

  delete<T>(endpoint: string) {
    return this.requestDynamic<T>(endpoint, { method: 'DELETE' })
  }
}

