export function createInitialNodes(count: number): EdgeNode[] {
  const nodes: EdgeNode[] = []
  
  for (let i = 0; i < count; i++) {
    const location = LOCATIONS[i % LOCATIONS.length]
    const node: EdgeNode = {
      id: generateId(),
      name: `edge-${location.region}-${String(i + 1).padStart(2, '0')}`,
      location: location.city,
      region: location.region,
      status: 'online',
      cpu: getRandomFloat(20, 60),
      memory: getRandomFloat(30, 70),
      storage: getRandomFloat(100, 500),
      latency: getRandomFloat(10, 100),
      uptime: getRandomFloat(95, 99.9),
      tasksRunning: 0,
      maxTasks: getRandomInt(5, 20),
      lastHeartbeat: new Date(),
      ip: `10.${getRandomInt(0, 255)}.${getRandomInt(0, 255)}.${getRandomInt(1, 254)}`,
      url: `http://localhost:${4001 + i}`, // Simulated agent URLs
      costPerHour: getRandomFloat(0.01, 0.05),
      bandwidthIn: getRandomFloat(10, 100),
      bandwidthOut: getRandomFloat(10, 100),
      healthHistory: [],
      isMaintenanceMode: false,
    }
    nodes.push(node)
  }
  
  return nodes
}

export function simulateNodeFluctuation(nodes: EdgeNode[]): { updatedNodes: EdgeNode[]; logs: LogEntry[] } {
  const updatedNodes: EdgeNode[] = []
  const logs: LogEntry[] = []
  
  for (const node of nodes) {
    const updatedNode = { ...node }
    
    if (node.status === 'offline') {
      if (Math.random() < 0.1) {
        updatedNode.status = 'online'
        updatedNode.lastHeartbeat = new Date()
        logs.push(createLogEntry('info', 'Node Recovery', `Node ${node.name} has recovered and is back online`, { nodeId: node.id }))
      }
    } else {
      updatedNode.cpu = clamp(node.cpu + getRandomFloat(-10, 10), 5, 95)
      updatedNode.memory = clamp(node.memory + getRandomFloat(-8, 8), 10, 90)
      updatedNode.latency = clamp(node.latency + getRandomFloat(-15, 15), 5, 200)
      updatedNode.lastHeartbeat = new Date()
      
      updatedNode.healthHistory.push({
        timestamp: new Date(),
        cpu: updatedNode.cpu,
        memory: updatedNode.memory,
        latency: updatedNode.latency,
      })
      
      if (updatedNode.healthHistory.length > 50) {
        updatedNode.healthHistory.shift()
      }
      
      if (Math.random() < 0.02) {
        updatedNode.status = 'degraded'
        logs.push(createLogEntry('warn', 'Node Status', `Node ${node.name} status degraded due to high load`, { nodeId: node.id, cpu: updatedNode.cpu }))
      } else if (Math.random() < 0.01) {
        updatedNode.status = 'offline'
        logs.push(createLogEntry('error', 'Node Failure', `Node ${node.name} went offline unexpectedly`, { nodeId: node.id }))
      } else if (node.status === 'degraded' && updatedNode.cpu < 70 && Math.random() < 0.3) {
        updatedNode.status = 'online'
        logs.push(createLogEntry('info', 'Node Recovery', `Node ${node.name} recovered from degraded state`, { nodeId: node.id }))
      }
    }
    
    updatedNodes.push(updatedNode)
  }
  
  return { updatedNodes, logs }
}

export function scheduleTask(
  name: string,
  type: TaskType,
  priority: TaskPriority,
  nodes: EdgeNode[],
  policy: SchedulingPolicy
): SchedulingResult {
  const taskId = generateId()
  const onlineNodes = nodes.filter((n) => n.status !== 'offline' && !n.isMaintenanceMode)
  
  if (onlineNodes.length === 0) {
    const task: Task = {
      id: taskId,
      name,
      type,
      status: 'failed',
      target: 'cloud',
      priority,
      submittedAt: new Date(),
      duration: 0,
      cost: 0,
      latencyMs: 0,
      reason: 'No online nodes available - task failed',
      retryCount: 0,
      maxRetries: 3,
    }
    return {
      task,
      logs: [createLogEntry('error', 'Scheduler', `Task "${name}" failed - no online nodes available`, { taskId })],
    }
  }
  
  let selectedNode: EdgeNode | null = null
  let target: ExecutionTarget = 'edge'
  let reason = ''
  
  // Try predictive scheduling first if we have history
  const predictedNode = predictiveScheduler.predictBestNode(
    { id: taskId, name, type, priority, submittedAt: new Date(), status: 'pending', target: 'edge', duration: 0, cost: 0, latencyMs: 0, reason: '', retryCount: 0, maxRetries: 3 },
    onlineNodes
  )
  
  if (predictedNode) {
    const prediction = predictiveScheduler.predictExecutionTime(
      { id: taskId, name, type, priority, submittedAt: new Date(), status: 'pending', target: 'edge', duration: 0, cost: 0, latencyMs: 0, reason: '', retryCount: 0, maxRetries: 3 },
      predictedNode
    )
    
    if (prediction.confidence > 0.6 && prediction.estimated < 5000) {
      selectedNode = predictedNode
      reason = `AI-predicted optimal node (${prediction.estimated.toFixed(0)}ms, ${(prediction.confidence * 100).toFixed(0)}% confidence)`
    }
  }
  
  // Fall back to policy-based selection if no prediction
  if (!selectedNode) {
  try {
    switch (policy) {
      case 'latency-aware': {
        const bestNode = onlineNodes.reduce((best, node) => 
          node.latency < best.latency ? node : best
        )
        if (bestNode.latency < 50 && bestNode.cpu < 80) {
          selectedNode = bestNode
          reason = `Low latency (${bestNode.latency.toFixed(1)}ms) and acceptable CPU (${bestNode.cpu.toFixed(1)}%)`
        } else {
          target = 'cloud'
          reason = `Edge latency too high (${bestNode.latency.toFixed(1)}ms) or CPU saturated (${bestNode.cpu.toFixed(1)}%) - routed to cloud`
        }
        break
      }
      
      case 'cost-aware': {
        const cheapestNode = onlineNodes.reduce((cheapest, node) => 
          node.costPerHour < cheapest.costPerHour ? node : cheapest
        )
        if (cheapestNode.cpu < 70) {
          selectedNode = cheapestNode
          reason = `Cost-optimized (${cheapestNode.costPerHour.toFixed(4)}/hr) with acceptable load (${cheapestNode.cpu.toFixed(1)}%)`
        } else {
          target = 'cloud'
          reason = `Cheapest node overloaded (${cheapestNode.cpu.toFixed(1)}%) - routed to cloud for cost efficiency`
        }
        break
      }
      
      case 'round-robin': {
        const leastLoaded = onlineNodes.reduce((least, node) => 
          node.tasksRunning < least.tasksRunning ? node : least
        )
        if (leastLoaded.tasksRunning < leastLoaded.maxTasks) {
          selectedNode = leastLoaded
          reason = `Round-robin selection - fewest tasks (${leastLoaded.tasksRunning}/${leastLoaded.maxTasks})`
        } else {
          target = 'cloud'
          reason = 'All edge nodes at capacity - routed to cloud'
        }
        break
      }
      
      case 'load-balanced': {
        const scoredNodes = onlineNodes.map((node) => ({
          node,
          score: node.cpu * 0.4 + node.memory * 0.3 + (node.latency / 2) * 0.3,
        }))
        scoredNodes.sort((a, b) => a.score - b.score)
        const bestScored = scoredNodes[0]
        if (bestScored.score < 60) {
          selectedNode = bestScored.node
          reason = `Load-balanced (score: ${bestScored.score.toFixed(1)}) - optimal resource utilization`
        } else {
          target = 'cloud'
          reason = `Edge load too high (score: ${bestScored.score.toFixed(1)}) - routed to cloud for load balancing`
        }
        break
      }
      
      default:
        throw new Error(`Unknown scheduling policy: ${policy}`)
    }
  } catch (error) {
    target = 'cloud'
    reason = `Scheduling error: ${error instanceof Error ? error.message : 'Unknown error'} - fallback to cloud`
  }
  } // Close if (!selectedNode) block
  
  const durationRange = TASK_DURATIONS[type]
  const baseDuration = getRandomInt(durationRange.min, durationRange.max)
  const duration = Math.round(baseDuration * PRIORITY_MULTIPLIERS[priority])
  
  let cost = 0
  if (target === 'edge' && selectedNode) {
    cost = (selectedNode.costPerHour / 3600) * (duration / 1000)
  } else {
    cost = 0.0001 * (duration / 1000)
  }
  
  const task: Task = {
    id: taskId,
    name,
    type,
    status: 'scheduled',
    target,
    priority,
    submittedAt: new Date(),
    duration,
    nodeId: selectedNode?.id,
    cost,
    latencyMs: selectedNode?.latency || getRandomFloat(50, 150),
    reason,
    retryCount: 0,
    maxRetries: 3,
  }
  
  const logs: LogEntry[] = [
    createLogEntry('info', 'Scheduler', `Task "${name}" scheduled (${type}, ${priority} priority)`, { taskId, policy }),
  ]
  
  if (target === 'edge' && selectedNode) {
    logs.push(createLogEntry('debug', 'Scheduler', `Routed to edge node ${selectedNode.name}: ${reason}`, { taskId, nodeId: selectedNode.id }))
  } else {
    logs.push(createLogEntry('debug', 'Scheduler', `Routed to cloud: ${reason}`, { taskId }))
  }
  
  return { task, logs }
}

export function computeMetrics(nodes: EdgeNode[], tasks: Task[]): SystemMetrics {
  const onlineNodes = nodes.filter((n) => n.status === 'online')
  const offlineNodes = nodes.filter((n) => n.status === 'offline')
  const degradedNodes = nodes.filter((n) => n.status === 'degraded')
  
  const pendingTasks = tasks.filter((t) => t.status === 'pending')
  const runningTasks = tasks.filter((t) => t.status === 'running')
  const completedTasks = tasks.filter((t) => t.status === 'completed')
  const failedTasks = tasks.filter((t) => t.status === 'failed')
  
  const avgLatency = onlineNodes.length > 0
    ? onlineNodes.reduce((sum, n) => sum + n.latency, 0) / onlineNodes.length
    : 0
  
  const totalCost = tasks.reduce((sum, t) => sum + t.cost, 0)
  
  const edgeUtilization = onlineNodes.length > 0
    ? onlineNodes.reduce((sum, n) => sum + n.cpu, 0) / onlineNodes.length
    : 0
  
  const cloudTasks = tasks.filter((t) => t.target === 'cloud')
  const cloudUtilization = cloudTasks.length > 0
    ? cloudTasks.reduce((sum, t) => sum + (t.status === 'running' ? 1 : 0), 0) / cloudTasks.length * 100
    : 0
  
  const throughput = completedTasks.length > 0
    ? completedTasks.length / Math.max(1, (Date.now() - Math.min(...completedTasks.map((t) => t.submittedAt.getTime()))) / 60000)
    : 0
  
  const cpuHistory = onlineNodes.map((n) => ({
    timestamp: new Date(),
    value: n.cpu,
  }))
  
  const edgeTasks = tasks.filter((t) => t.target === 'edge').length
  const cloudTaskCount = tasks.filter((t) => t.target === 'cloud').length
  
  const total = edgeTasks + cloudTaskCount
  const healthScore = total > 0
    ? Math.round((completedTasks.length / total) * 100 - (failedTasks.length / total) * 50 + (onlineNodes.length / nodes.length) * 25)
    : 100
  
  const completionRate = tasks.length > 0
    ? (completedTasks.length / tasks.length) * 100
    : 0
  
  return {
    totalNodes: nodes.length,
    onlineNodes: onlineNodes.length,
    offlineNodes: offlineNodes.length,
    degradedNodes: degradedNodes.length,
    totalTasks: tasks.length,
    pendingTasks: pendingTasks.length,
    runningTasks: runningTasks.length,
    completedTasks: completedTasks.length,
    failedTasks: failedTasks.length,
    avgLatency,
    totalCost,
    edgeUtilization,
    cloudUtilization,
    throughput,
    cpuHistory,
    taskDistribution: { edge: edgeTasks, cloud: cloudTaskCount },
    healthScore: clamp(healthScore, 0, 100),
    completionRate,
    costOverTime: [{ timestamp: new Date(), value: totalCost }],
  }
}

export function createLogEntry(
  level: LogLevel,
  source: string,
  message: string,
  metadata?: Record<string, unknown>
): LogEntry {
  return {
    id: generateId(),
    timestamp: new Date(),
    level,
    source,
    message,
    metadata,
  }
}

export function generateRandomTaskName(): string {
  const prefixes = ['Process', 'Analyze', 'Compute', 'Transform', 'Sync', 'Validate', 'Index']
  const suffixes = ['Batch', 'Stream', 'Job', 'Task', 'Operation', 'Workflow', 'Pipeline']
  return `${prefixes[getRandomInt(0, prefixes.length - 1)]}-${suffixes[getRandomInt(0, suffixes.length - 1)]}-${getRandomInt(1000, 9999)}`
}

export function getRandomTaskType(): TaskType {
  return TASK_TYPES[getRandomInt(0, TASK_TYPES.length - 1)]
}

export function getRandomPriority(): TaskPriority {
  const priorities: TaskPriority[] = ['low', 'medium', 'high', 'critical']
  const weights = [0.4, 0.35, 0.2, 0.05]
  const random = Math.random()
  let cumulative = 0
  for (let i = 0; i < priorities.length; i++) {
    cumulative += weights[i]
    if (random <= cumulative) {return priorities[i]}
  }
  return 'medium'
}

/**
 * Carbon Footprint Tracking
 * Monitor and optimize environmental impact of edge infrastructure
 */

import { logger } from '../logger'
import type { EdgeNode } from '../../types'

// Types
export interface CarbonMetrics {
  timestamp: number
  nodeId?: string
  region: string
  energyKwh: number
  carbonKg: number
  source: 'grid' | 'renewable' | 'mixed'
  renewablePercent: number
  pue: number // Power Usage Effectiveness
  cost: number
}

export interface CarbonBaseline {
  region: string
  gridIntensity: number // gCO2/kWh
  renewableAvailable: number // %
  avgPue: number
  lastUpdated: number
}

export interface CarbonGoal {
  id: string
  name: string
  type: 'reduction' | 'offset' | 'renewable'
  targetValue: number
  targetUnit: string
  targetDate: number
  currentValue: number
  progress: number
  status: 'on-track' | 'at-risk' | 'achieved' | 'failed'
}

export interface CarbonReport {
  id: string
  period: 'daily' | 'weekly' | 'monthly' | 'yearly'
  startDate: number
  endDate: number
  totalEnergyKwh: number
  totalCarbonKg: number
  totalOffsetKg: number
  netCarbonKg: number
  renewablePercent: number
  avgPue: number
  byRegion: Map<string, { energy: number; carbon: number }>
  bySource: Map<string, number>
  recommendations: CarbonRecommendation[]
  comparison: {
    previousPeriod: number
    changePercent: number
  }
}

export interface CarbonRecommendation {
  id: string
  type: 'optimize' | 'migrate' | 'schedule' | 'offset' | 'renewable'
  priority: 'low' | 'medium' | 'high'
  title: string
  description: string
  potentialSavings: number // kg CO2
  costImpact: number
  effort: 'low' | 'medium' | 'high'
  region?: string
  nodeId?: string
}

export interface CarbonConfig {
  reportingInterval: number
  gridIntensityAPI?: string
  defaultPUE: number
  carbonPricePerKg: number
  offsetProvider?: string
}

type CarbonEvent = 'metrics.recorded' | 'goal.progress' | 'report.generated' | 'recommendation.created'
type CarbonCallback = (event: CarbonEvent, data: unknown) => void

// Grid intensity by region (gCO2/kWh) - approximate values
const GRID_INTENSITY: Record<string, number> = {
  'us-east': 350,
  'us-west': 250,
  'eu-west': 200,
  'eu-central': 300,
  'asia-east': 500,
  'asia-southeast': 450,
  'australia': 700,
  'south-america': 300,
}

const DEFAULT_CONFIG: Omit<CarbonConfig, 'gridIntensityAPI' | 'offsetProvider'> = {
  reportingInterval: 3600000, // 1 hour
  defaultPUE: 1.5,
  carbonPricePerKg: 0.05,
}

/**
 * Carbon Footprint Tracker
 */
export class CarbonTracker {
  private config: CarbonConfig
  private metrics: CarbonMetrics[] = []
  private baselines: Map<string, CarbonBaseline> = new Map()
  private goals: Map<string, CarbonGoal> = new Map()
  private reports: Map<string, CarbonReport> = new Map()
  private callbacks: Map<CarbonEvent, Set<CarbonCallback>> = new Map()
  private nodeProvider: (() => EdgeNode[]) | null = null
  private reportingTimer: ReturnType<typeof setInterval> | null = null

  constructor(config: Partial<CarbonConfig> = {}) {
    this.config = { ...DEFAULT_CONFIG, ...config }
    this.initializeBaselines()
  }

  /**
   * Set node provider
   */
  setNodeProvider(provider: () => EdgeNode[]): void {
    this.nodeProvider = provider
  }

  /**
   * Initialize regional baselines
   */
  private initializeBaselines(): void {
    for (const [region, intensity] of Object.entries(GRID_INTENSITY)) {
      this.baselines.set(region, {
        region,
        gridIntensity: intensity,
        renewableAvailable: 20 + Math.random() * 40,
        avgPue: this.config.defaultPUE,
        lastUpdated: Date.now(),
      })
    }
  }

  /**
   * Record carbon metrics
   */
  recordMetrics(metrics: Omit<CarbonMetrics, 'timestamp'> & { timestamp?: number }): void {
    const fullMetrics: CarbonMetrics = {
      ...metrics,
      timestamp: metrics.timestamp || Date.now(),
    }

    this.metrics.push(fullMetrics)

    // Update goals
    this.updateGoalProgress(fullMetrics)

    this.emit('metrics.recorded', fullMetrics)
    logger.debug('Carbon metrics recorded', {
      region: metrics.region,
      energy: metrics.energyKwh.toFixed(2),
      carbon: metrics.carbonKg.toFixed(2),
    })
  }

  /**
   * Calculate carbon for energy consumption
   */
  calculateCarbon(energyKwh: number, region: string): number {
    const baseline = this.baselines.get(region)
    const gridIntensity = baseline?.gridIntensity || 400 // gCO2/kWh
    
    // Adjust for renewable percentage
    const renewableFactor = (100 - (baseline?.renewableAvailable || 0)) / 100
    
    // Convert to kg CO2
    return (energyKwh * gridIntensity * renewableFactor) / 1000
  }

  /**
   * Calculate node energy consumption
   */
  calculateNodeEnergy(node: EdgeNode, durationHours: number = 1): number {
    // Estimate power consumption based on utilization
    // Typical edge server: 200-500W at full load
    const basePower = 200 // Watts
    const maxPower = 500 // Watts
    
    const utilization = (node.cpu + node.memory) / 200 // Average utilization
    const power = basePower + (maxPower - basePower) * utilization
    
    // Apply PUE
    const pue = this.config.defaultPUE
    
    return (power * pue * durationHours) / 1000 // kWh
  }

  /**
   * Collect metrics from all nodes
   */
  async collectMetrics(): Promise<CarbonMetrics[]> {
    const nodes = this.nodeProvider ? this.nodeProvider() : []
    const collected: CarbonMetrics[] = []

    for (const node of nodes) {
      if (node.status !== 'online') {continue}

      const baseline = this.baselines.get(node.region) || this.baselines.values().next().value
      const energyKwh = this.calculateNodeEnergy(node)
      const carbonKg = this.calculateCarbon(energyKwh, node.region)
      const renewableAvailable = baseline?.renewableAvailable || 0
      const avgPue = baseline?.avgPue || this.config.defaultPUE

      const metrics: CarbonMetrics = {
        timestamp: Date.now(),
        nodeId: node.id,
        region: node.region,
        energyKwh,
        carbonKg,
        source: renewableAvailable > 50 ? 'renewable' : renewableAvailable > 20 ? 'mixed' : 'grid',
        renewablePercent: renewableAvailable,
        pue: avgPue,
        cost: carbonKg * this.config.carbonPricePerKg,
      }

      this.recordMetrics(metrics)
      collected.push(metrics)
    }

    return collected
  }

  /**
   * Generate carbon report
   */
  generateReport(period: CarbonReport['period']): CarbonReport {
    const now = Date.now()
    const periodMs: Record<string, number> = {
      daily: 86400000,
      weekly: 604800000,
      monthly: 2592000000,
      yearly: 31536000000,
    }

    const startDate = now - periodMs[period]
    const periodMetrics = this.metrics.filter((m) => m.timestamp >= startDate)

    let totalEnergy = 0
    let totalCarbon = 0
    let totalRenewable = 0
    let totalPue = 0
    const byRegion = new Map<string, { energy: number; carbon: number }>()
    const bySource = new Map<string, number>()

    for (const m of periodMetrics) {
      totalEnergy += m.energyKwh
      totalCarbon += m.carbonKg
      totalRenewable += m.renewablePercent * m.energyKwh
      totalPue += m.pue

      const region = byRegion.get(m.region) || { energy: 0, carbon: 0 }
      region.energy += m.energyKwh
      region.carbon += m.carbonKg
      byRegion.set(m.region, region)

      bySource.set(m.source, (bySource.get(m.source) || 0) + m.carbonKg)
    }

    const avgRenewable = totalEnergy > 0 ? totalRenewable / totalEnergy : 0
    const avgPue = periodMetrics.length > 0 ? totalPue / periodMetrics.length : this.config.defaultPUE

    // Compare with previous period
    const previousMetrics = this.metrics.filter((m) => 
      m.timestamp >= startDate - periodMs[period] && m.timestamp < startDate
    )
    const previousCarbon = previousMetrics.reduce((s, m) => s + m.carbonKg, 0)
    const changePercent = previousCarbon > 0 
      ? ((totalCarbon - previousCarbon) / previousCarbon) * 100 
      : 0

    const report: CarbonReport = {
      id: `report-${period}-${Date.now()}`,
      period,
      startDate,
      endDate: now,
      totalEnergyKwh: totalEnergy,
      totalCarbonKg: totalCarbon,
      totalOffsetKg: 0, // Would track offsets
      netCarbonKg: totalCarbon,
      renewablePercent: avgRenewable,
      avgPue,
      byRegion,
      bySource,
      recommendations: this.generateRecommendations(periodMetrics),
      comparison: {
        previousPeriod: previousCarbon,
        changePercent,
      },
    }

    this.reports.set(report.id, report)
    this.emit('report.generated', report)

    logger.info('Carbon report generated', {
      period,
      totalCarbon: totalCarbon.toFixed(2),
      renewablePercent: avgRenewable.toFixed(1),
      changePercent: changePercent.toFixed(1),
    })

    return report
  }

  /**
   * Generate carbon reduction recommendations
   */
  private generateRecommendations(metrics: CarbonMetrics[]): CarbonRecommendation[] {
    const recommendations: CarbonRecommendation[] = []

    // Group by region
    const byRegion = new Map<string, CarbonMetrics[]>()
    for (const m of metrics) {
      const region = byRegion.get(m.region) || []
      region.push(m)
      byRegion.set(m.region, region)
    }

    // Find high-carbon regions
    for (const [region, regionMetrics] of byRegion) {
      const totalCarbon = regionMetrics.reduce((s, m) => s + m.carbonKg, 0)
      const avgRenewable = regionMetrics.reduce((s, m) => s + m.renewablePercent, 0) / regionMetrics.length

      if (avgRenewable < 30) {
        recommendations.push({
          id: `rec-${Date.now()}-${region}-renewable`,
          type: 'renewable',
          priority: 'high',
          title: `Increase Renewable Energy in ${region}`,
          description: `Region has only ${avgRenewable.toFixed(0)}% renewable energy. Consider purchasing renewable credits or migrating workloads.`,
          potentialSavings: totalCarbon * 0.5,
          costImpact: -100, // Cost savings
          effort: 'medium',
          region,
        })
      }

      // Compare with cleaner regions
      const baseline = this.baselines.get(region)
      if (baseline && baseline.gridIntensity > 400) {
        const cleanerRegions = Array.from(this.baselines.values())
          .filter((b) => b.gridIntensity < baseline.gridIntensity * 0.7)
        
        if (cleanerRegions.length > 0) {
          recommendations.push({
            id: `rec-${Date.now()}-${region}-migrate`,
            type: 'migrate',
            priority: 'medium',
            title: `Migrate Workloads from ${region}`,
            description: `Consider migrating workloads to ${cleanerRegions[0].region} which has ${cleanerRegions[0].gridIntensity} gCO2/kWh vs ${baseline.gridIntensity} gCO2/kWh`,
            potentialSavings: totalCarbon * 0.3,
            costImpact: 200, // Migration cost
            effort: 'high',
            region,
          })
        }
      }
    }

    // PUE optimization
    const avgPue = metrics.reduce((s, m) => s + m.pue, 0) / metrics.length
    if (avgPue > 1.4) {
      recommendations.push({
        id: `rec-${Date.now()}-pue`,
        type: 'optimize',
        priority: 'medium',
        title: 'Improve Data Center Efficiency',
        description: `Average PUE of ${avgPue.toFixed(2)} can be improved through better cooling and power management.`,
        potentialSavings: metrics.reduce((s, m) => s + m.carbonKg, 0) * 0.15,
        costImpact: 5000, // Infrastructure investment
        effort: 'high',
      })
    }

    // Scheduling optimization
    recommendations.push({
      id: `rec-${Date.now()}-schedule`,
      type: 'schedule',
      priority: 'low',
      title: 'Optimize Workload Scheduling',
      description: 'Schedule high-energy workloads during times of higher renewable energy availability.',
      potentialSavings: metrics.reduce((s, m) => s + m.carbonKg, 0) * 0.1,
      costImpact: 0,
      effort: 'low',
    })

    for (const rec of recommendations) {
      this.emit('recommendation.created', rec)
    }

    return recommendations
  }

  /**
   * Create carbon reduction goal
   */
  createGoal(goal: Omit<CarbonGoal, 'id' | 'currentValue' | 'progress' | 'status'>): CarbonGoal {
    const fullGoal: CarbonGoal = {
      ...goal,
      id: `goal-${Date.now()}`,
      currentValue: 0,
      progress: 0,
      status: 'on-track',
    }

    this.goals.set(fullGoal.id, fullGoal)
    return fullGoal
  }

  /**
   * Update goal progress
   */
  private updateGoalProgress(metrics: CarbonMetrics): void {
    for (const goal of this.goals.values()) {
      if (goal.type === 'reduction') {
        goal.currentValue += metrics.carbonKg
        goal.progress = Math.min(100, (1 - goal.currentValue / goal.targetValue) * 100)
      } else if (goal.type === 'renewable') {
        goal.currentValue = metrics.renewablePercent
        goal.progress = (goal.currentValue / goal.targetValue) * 100
      }

      // Update status
      const timeProgress = (Date.now() - (goal.targetDate - 365 * 24 * 60 * 60 * 1000)) / 
                          (goal.targetDate - (goal.targetDate - 365 * 24 * 60 * 60 * 1000))
      
      if (goal.progress >= 100) {
        goal.status = 'achieved'
      } else if (goal.progress / 100 < timeProgress * 0.8) {
        goal.status = 'at-risk'
      }

      this.emit('goal.progress', goal)
    }
  }

  /**
   * Get carbon summary
   */
  getSummary(): {
    totalCarbonKg: number
    totalEnergyKwh: number
    avgRenewablePercent: number
    avgPue: number
    byRegion: Record<string, { energy: number; carbon: number }>
  } {
    const last24h = this.metrics.filter((m) => m.timestamp > Date.now() - 86400000)
    
    let totalCarbon = 0
    let totalEnergy = 0
    let totalRenewable = 0
    let totalPue = 0
    const byRegion: Record<string, { energy: number; carbon: number }> = {}

    for (const m of last24h) {
      totalCarbon += m.carbonKg
      totalEnergy += m.energyKwh
      totalRenewable += m.renewablePercent
      totalPue += m.pue

      if (!byRegion[m.region]) {
        byRegion[m.region] = { energy: 0, carbon: 0 }
      }
      byRegion[m.region].energy += m.energyKwh
      byRegion[m.region].carbon += m.carbonKg
    }

    return {
      totalCarbonKg: totalCarbon,
      totalEnergyKwh: totalEnergy,
      avgRenewablePercent: last24h.length > 0 ? totalRenewable / last24h.length : 0,
      avgPue: last24h.length > 0 ? totalPue / last24h.length : this.config.defaultPUE,
      byRegion,
    }
  }

  /**
   * Get goals
   */
  getGoals(): CarbonGoal[] {
    return Array.from(this.goals.values())
  }

  /**
   * Get reports
   */
  getReports(): CarbonReport[] {
    return Array.from(this.reports.values()).sort((a, b) => b.endDate - a.endDate)
  }

  /**
   * Start periodic reporting
   */
  startReporting(): void {
    this.reportingTimer = setInterval(() => {
      this.collectMetrics()
    }, this.config.reportingInterval)
  }

  /**
   * Stop reporting
   */
  stopReporting(): void {
    if (this.reportingTimer) {
      clearInterval(this.reportingTimer)
      this.reportingTimer = null
    }
  }

  /**
   * Subscribe to events
   */
  on(event: CarbonEvent, callback: CarbonCallback): () => void {
    if (!this.callbacks.has(event)) {
      this.callbacks.set(event, new Set())
    }
    this.callbacks.get(event)!.add(callback)

    return () => {
      this.callbacks.get(event)?.delete(callback)
    }
  }

  private emit(event: CarbonEvent, data: unknown): void {
    this.callbacks.get(event)?.forEach((cb) => {
      try {
        cb(event, data)
      } catch (error) {
        logger.error('Carbon tracker callback error', error as Error)
      }
    })
  }
}

/**
 * Create carbon tracker
 */
export function createCarbonTracker(config: Partial<CarbonConfig> = {}): CarbonTracker {
  return new CarbonTracker(config)
}

// Default instance
export const carbonTracker = new CarbonTracker()

import type { Task, TaskPriority } from '../types'

interface QueuedTask {
  id: string
  task: Task
  priority: number
  submittedAt: number
  retryCount: number
  maxRetries: number
}

interface QueueStats {
  total: number
  pending: number
  processing: number
  byPriority: Record<TaskPriority, number>
  avgWaitTime: number
}

const PRIORITY_WEIGHTS: Record<TaskPriority, number> = {
  critical: 100,
  high: 75,
  medium: 50,
  low: 25
}

class PriorityTaskQueue {
  private queue: QueuedTask[] = []
  private processing: Set<string> = new Set()
  private maxConcurrent: number
  private processingCallback: ((task: Task) => Promise<void>) | null = null

  constructor(maxConcurrent = 5) {
    this.maxConcurrent = maxConcurrent
  }

  enqueue(task: Task): void {
    const existingIndex = this.queue.findIndex((qt) => qt.id === task.id)
    
    if (existingIndex !== -1) {
      // Update existing task if already queued
      this.queue[existingIndex].task = task
      this.reorderQueue()
      return
    }

    const queuedTask: QueuedTask = {
      id: task.id,
      task,
      priority: this.calculatePriority(task),
      submittedAt: Date.now(),
      retryCount: 0,
      maxRetries: task.maxRetries || 3
    }

    // Insert by priority (higher first)
    const insertIndex = this.queue.findIndex(
      (qt) => qt.priority < queuedTask.priority
    )
    
    if (insertIndex === -1) {
      this.queue.push(queuedTask)
    } else {
      this.queue.splice(insertIndex, 0, queuedTask)
    }

    this.processQueue()
  }

  private calculatePriority(task: Task): number {
    const basePriority = PRIORITY_WEIGHTS[task.priority] || 25
    const ageBonus = Math.min((Date.now() - task.submittedAt.getTime()) / 1000 / 60, 10) // Max 10 points for age
    return basePriority + ageBonus
  }

  private reorderQueue(): void {
    // Recalculate priorities and re-sort
    this.queue.forEach((qt) => {
      qt.priority = this.calculatePriority(qt.task)
    })
    this.queue.sort((a, b) => b.priority - a.priority)
  }

  private async processQueue(): Promise<void> {
    if (!this.processingCallback) {return}
    if (this.processing.size >= this.maxConcurrent) {return}
    if (this.queue.length === 0) {return}

    const nextTask = this.queue.shift()
    if (!nextTask) {return}

    this.processing.add(nextTask.id)

    try {
      await this.processingCallback(nextTask.task)
    } catch (error) {
      console.error(`Task ${nextTask.id} failed:`, error)
      
      if (nextTask.retryCount < nextTask.maxRetries) {
        nextTask.retryCount++
        // Re-queue with exponential backoff delay
        const backoffDelay = Math.pow(2, nextTask.retryCount) * 1000
        setTimeout(() => {
          this.queue.push(nextTask)
          this.reorderQueue()
        }, backoffDelay)
      }
    } finally {
      this.processing.delete(nextTask.id)
      // Process next task
      this.processQueue()
    }
  }

  dequeue(): Task | undefined {
    const queued = this.queue.shift()
    return queued?.task
  }

  peek(): Task | undefined {
    return this.queue[0]?.task
  }

  remove(taskId: string): boolean {
    const index = this.queue.findIndex((qt) => qt.id === taskId)
    if (index !== -1) {
      this.queue.splice(index, 1)
      return true
    }
    return false
  }

  setProcessor(callback: (task: Task) => Promise<void>): void {
    this.processingCallback = callback
    this.processQueue()
  }

  setMaxConcurrent(max: number): void {
    this.maxConcurrent = max
    this.processQueue()
  }

  getStats(): QueueStats {
    const now = Date.now()
    const waitTimes = this.queue.map((qt) => now - qt.submittedAt)
    const avgWaitTime = waitTimes.length > 0 
      ? waitTimes.reduce((a, b) => a + b, 0) / waitTimes.length 
      : 0

    const byPriority: Record<TaskPriority, number> = {
      critical: 0,
      high: 0,
      medium: 0,
      low: 0
    }

    this.queue.forEach((qt) => {
      byPriority[qt.task.priority]++
    })

    return {
      total: this.queue.length + this.processing.size,
      pending: this.queue.length,
      processing: this.processing.size,
      byPriority,
      avgWaitTime
    }
  }

  getQueue(): Task[] {
    return this.queue.map((qt) => qt.task)
  }

  getPosition(taskId: string): number {
    return this.queue.findIndex((qt) => qt.id === taskId)
  }

  clear(): void {
    this.queue = []
    this.processing.clear()
  }

  isProcessing(taskId: string): boolean {
    return this.processing.has(taskId)
  }

  isQueued(taskId: string): boolean {
    return this.queue.some((qt) => qt.id === taskId)
  }

  size(): number {
    return this.queue.length
  }

  processingCount(): number {
    return this.processing.size
  }
}

