    type: [string.required(), string.oneOf(['routing', 'resource', 'security'])],
    rules: [array.required(), array.minLength(1)],
  },

  apiKey: {
    name: [string.required(), string.minLength(1), string.maxLength(100)],
    permissions: [array.required()],
  },
}

