import type { 
  WebhookConfig, 
  WebhookDelivery, 
  WebhookEventType, 
  WebhookPayload 
} from '../types/webhook'
import { webhooksApi } from './realApi'

const MAX_RETRIES = 3
const RETRY_DELAYS = [1000, 5000, 15000] // 1s, 5s, 15s

// Simple ID generator
const generateId = () => crypto.randomUUID()

class WebhookManager {
  private isProcessing = false
  private cache: WebhookConfig[] = []
  private deliveryCache: WebhookDelivery[] = []

  async createWebhook(config: Omit<WebhookConfig, 'id' | 'createdAt' | 'updatedAt'>): Promise<WebhookConfig> {
    const response = await webhooksApi.create({
      name: config.name,
      url: config.url,
      events: config.events,
      secret: config.secret,
      enabled: config.enabled,
    })
    
    if (response.error || !response.data) {
      throw new Error(response.error || 'Failed to create webhook')
    }
    
    const webhook: WebhookConfig = {
      id: response.data.id,
      name: response.data.name,
      url: response.data.url,
      events: response.data.events as WebhookEventType[],
      secret: response.data.secret,
      enabled: response.data.enabled ?? true,
      createdAt: new Date(response.data.createdAt),
      updatedAt: new Date(response.data.createdAt),
      retryCount: config.retryCount || 3,
      timeoutMs: config.timeoutMs || 30000,
    }
    
    this.cache.push(webhook)
    return webhook
  }

  async updateWebhook(id: string, updates: Partial<WebhookConfig>): Promise<void> {
    const response = await webhooksApi.update(id, {
      name: updates.name,
      url: updates.url,
      events: updates.events,
      secret: updates.secret,
      enabled: updates.enabled,
    })
    
    if (response.error) {
      throw new Error(response.error)
    }
    
    // Update cache
    const index = this.cache.findIndex((w) => w.id === id)
    if (index !== -1 && response.data) {
      this.cache[index] = {
        ...this.cache[index],
        ...updates,
        updatedAt: new Date(),
      }
    }
  }

  async deleteWebhook(id: string): Promise<void> {
    const response = await webhooksApi.delete(id)
    if (response.error) {
      throw new Error(response.error)
    }
    this.cache = this.cache.filter((w) => w.id !== id)
  }

  async getWebhooks(): Promise<WebhookConfig[]> {
    const response = await webhooksApi.list()
    if (response.error || !response.data) {
      return this.cache // Return cached data on error
    }
    
    this.cache = response.data.map((w: any) => ({
      id: w.id,
      name: w.name,
      url: w.url,
      events: w.events as WebhookEventType[],
      secret: w.secret,
      enabled: w.enabled ?? true,
      createdAt: new Date(w.createdAt),
      updatedAt: new Date(w.updatedAt || w.createdAt),
      retryCount: w.retryCount || 3,
      timeoutMs: w.timeoutMs || 30000,
    }))
    
    return this.cache
  }

  async getWebhook(id: string): Promise<WebhookConfig | undefined> {
    // Check cache first
    const cached = this.cache.find((w) => w.id === id)
    if (cached) {return cached}
    
    // Refresh cache
    await this.getWebhooks()
    return this.cache.find((w) => w.id === id)
  }

  async triggerEvent(event: WebhookEventType, data: unknown): Promise<void> {
    const webhooks = await this.getWebhooks()
    const enabledWebhooks = webhooks.filter((w) => w.enabled && w.events.includes(event))

    for (const webhook of enabledWebhooks) {
      const payload: WebhookPayload = {
        event,
        timestamp: new Date().toISOString(),
        data,
      }

      const delivery: WebhookDelivery = {
        id: generateId(),
        webhookId: webhook.id,
        webhookName: webhook.name,
        event,
        payload,
        status: 'pending',
        attemptCount: 0,
        createdAt: new Date(),
      }

      await this.queueDelivery(delivery)
    }
  }

  private async queueDelivery(delivery: WebhookDelivery): Promise<void> {
    this.deliveryCache.unshift(delivery)
    if (this.deliveryCache.length > 100) {
      this.deliveryCache = this.deliveryCache.slice(0, 100)
    }
    this.processQueue()
  }

  private async processQueue(): Promise<void> {
    if (this.isProcessing) {return}
    this.isProcessing = true

    try {
      const pending = this.deliveryCache.filter((d) => d.status === 'pending')
      const retrying = this.deliveryCache.filter((d) => d.status === 'retrying')
      
      const now = new Date()
      const dueForRetry = retrying.filter((d) => !d.nextRetryAt || d.nextRetryAt <= now)

      const allDeliveries = [...pending, ...dueForRetry]

      for (const delivery of allDeliveries) {
        await this.executeDelivery(delivery)
      }
    } finally {
      this.isProcessing = false
      
      // Schedule next check if there are retrying deliveries
      const retrying = this.deliveryCache.filter((d) => d.status === 'retrying')
      if (retrying.length > 0) {
        setTimeout(() => this.processQueue(), 1000)
      }
    }
  }

  private async executeDelivery(delivery: WebhookDelivery): Promise<void> {
    const webhook = await this.getWebhook(delivery.webhookId)
    if (!webhook || !webhook.enabled) {
      delivery.status = 'failed'
      delivery.errorMessage = 'Webhook disabled or deleted'
      delivery.completedAt = new Date()
      return
    }

    delivery.attemptCount++
    delivery.status = 'retrying'

    try {
      const headers: Record<string, string> = {
        'Content-Type': 'application/json',
        'X-Webhook-ID': delivery.webhookId,
        'X-Webhook-Event': delivery.event,
        'X-Webhook-Attempt': delivery.attemptCount.toString(),
        ...webhook.headers,
      }

      // Add HMAC signature if secret is configured
      if (webhook.secret) {
        const signature = await this.generateSignature(
          JSON.stringify(delivery.payload),
          webhook.secret
        )
        headers['X-Webhook-Signature'] = signature
      }

      const controller = new AbortController()
      const timeoutId = setTimeout(() => controller.abort(), webhook.timeoutMs)

      const response = await fetch(webhook.url, {
        method: 'POST',
        headers,
        body: JSON.stringify(delivery.payload),
        signal: controller.signal,
      })

      clearTimeout(timeoutId)

      const responseBody = await response.text()

      if (response.ok) {
        delivery.status = 'success'
        delivery.responseStatus = response.status
        delivery.responseBody = responseBody
        delivery.completedAt = new Date()
      } else {
        throw new Error(`HTTP ${response.status}: ${responseBody}`)
      }
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Unknown error'
      delivery.errorMessage = errorMessage

      if (delivery.attemptCount < Math.min(webhook.retryCount, MAX_RETRIES)) {
        delivery.status = 'retrying'
        const delay = RETRY_DELAYS[delivery.attemptCount - 1] || RETRY_DELAYS[RETRY_DELAYS.length - 1]
        delivery.nextRetryAt = new Date(Date.now() + delay)
      } else {
        delivery.status = 'failed'
        delivery.completedAt = new Date()
      }
    }
  }

  private async generateSignature(payload: string, secret: string): Promise<string> {
    const encoder = new TextEncoder()
    const key = await crypto.subtle.importKey(
      'raw',
      encoder.encode(secret),
      { name: 'HMAC', hash: 'SHA-256' },
      false,
      ['sign']
    )
    const signature = await crypto.subtle.sign('HMAC', key, encoder.encode(payload))
    return btoa(String.fromCharCode(...new Uint8Array(signature)))
  }

  async getDeliveries(limit = 100): Promise<WebhookDelivery[]> {
    // Try to get from API first
    try {
      const response = await webhooksApi.getDeliveries('all', limit)
      if (response.data) {
        this.deliveryCache = response.data.map((d: any) => ({
          id: d.id,
          webhookId: d.webhookId,
          webhookName: d.webhookName || 'Unknown',
          event: d.event as WebhookEventType,
          payload: d.payload,
          status: d.status,
          attemptCount: d.attemptCount || 1,
          createdAt: new Date(d.createdAt),
          completedAt: d.completedAt ? new Date(d.completedAt) : undefined,
          responseStatus: d.responseStatus,
          responseBody: d.responseBody,
          errorMessage: d.errorMessage,
        }))
        return this.deliveryCache
      }
    } catch {
      // Fall back to local cache
    }
    return this.deliveryCache.slice(0, limit)
  }

  async retryDelivery(deliveryId: string): Promise<void> {
    const delivery = this.deliveryCache.find((d) => d.id === deliveryId)
    if (!delivery) {throw new Error('Delivery not found')}

    if (delivery.status === 'failed') {
      delivery.status = 'pending'
      delivery.attemptCount = 0
      delivery.errorMessage = undefined
      delivery.completedAt = undefined
      delivery.nextRetryAt = undefined
      this.processQueue()
    }
  }

  async clearOldDeliveries(olderThanDays = 7): Promise<number> {
    const cutoff = new Date(Date.now() - olderThanDays * 24 * 60 * 60 * 1000)
    const oldDeliveries = this.deliveryCache.filter((d) => 
      d.completedAt && d.completedAt < cutoff
    )

    this.deliveryCache = this.deliveryCache.filter((d) => 
      !d.completedAt || d.completedAt >= cutoff
    )

    return oldDeliveries.length
  }
}

export const webhookManager = new WebhookManager()

type WebSocketState = 'connecting' | 'open' | 'closing' | 'closed'

interface WebSocketConnection {
  id: string
  url: string
  socket: WebSocket | null
  state: WebSocketState
  lastUsed: number
  messageQueue: string[]
  reconnectAttempts: number
  subscriptions: Set<string>
}

interface PoolConfig {
  maxConnections?: number
  maxConnectionsPerHost?: number
  reconnectInterval?: number
  maxReconnectAttempts?: number
  connectionTimeout?: number
  idleTimeout?: number
}

interface MessageHandler {
  (data: unknown): void
}

const DEFAULT_CONFIG: Required<PoolConfig> = {
  maxConnections: 50,
  maxConnectionsPerHost: 10,
  reconnectInterval: 3000,
  maxReconnectAttempts: 5,
  connectionTimeout: 10000,
  idleTimeout: 300000, // 5 minutes
}

class WebSocketPool {
  private connections: Map<string, WebSocketConnection> = new Map()
  private handlers: Map<string, Set<MessageHandler>> = new Map()
  private config: Required<PoolConfig>
  private cleanupInterval: ReturnType<typeof setInterval> | null = null

  constructor(config: PoolConfig = {}) {
    this.config = { ...DEFAULT_CONFIG, ...config }
    this.startCleanup()
  }

  private startCleanup(): void {
    this.cleanupInterval = setInterval(() => {
      this.cleanupIdleConnections()
    }, 60000) // Cleanup every minute
  }

  private cleanupIdleConnections(): void {
    const now = Date.now()
    const idleThreshold = this.config.idleTimeout

    for (const [id, conn] of this.connections) {
      if (conn.state === 'open' && now - conn.lastUsed > idleThreshold) {
        if (conn.subscriptions.size === 0) {
          this.closeConnection(id)
        }
      }
    }
  }

  async acquire(url: string, subscription?: string): Promise<string> {
    // Check existing connections to same host
    const hostConnections = Array.from(this.connections.values()).filter(
      (c) => c.url === url && c.state === 'open'
    )

    // Reuse existing connection if available
    if (hostConnections.length > 0) {
      const conn = hostConnections[0]
      if (subscription) {
        conn.subscriptions.add(subscription)
      }
      conn.lastUsed = Date.now()
      return conn.id
    }

    // Check connection limits
    if (this.connections.size >= this.config.maxConnections) {
      throw new Error('Maximum WebSocket connections reached')
    }

    const hostCount = hostConnections.length
    if (hostCount >= this.config.maxConnectionsPerHost) {
      throw new Error(`Maximum connections per host (${this.config.maxConnectionsPerHost}) reached`)
    }

    // Create new connection
    return this.createConnection(url, subscription)
  }

  private async createConnection(url: string, subscription?: string): Promise<string> {
    const id = `ws-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`

    const conn: WebSocketConnection = {
      id,
      url,
      socket: null,
      state: 'connecting',
      lastUsed: Date.now(),
      messageQueue: [],
      reconnectAttempts: 0,
      subscriptions: subscription ? new Set([subscription]) : new Set(),
    }

    this.connections.set(id, conn)
    await this.connect(conn)

    return id
  }

  private async connect(conn: WebSocketConnection): Promise<void> {
    return new Promise((resolve, reject) => {
      const timeout = setTimeout(() => {
        reject(new Error('Connection timeout'))
      }, this.config.connectionTimeout)

      try {
        const socket = new WebSocket(conn.url)
        conn.socket = socket

        socket.onopen = () => {
          clearTimeout(timeout)
          conn.state = 'open'
          conn.reconnectAttempts = 0
          this.flushMessageQueue(conn)
          resolve()
        }

        socket.onmessage = (event) => {
          this.handleMessage(conn, event.data)
        }

        socket.onclose = () => {
          conn.state = 'closed'
          this.handleDisconnect(conn)
        }

        socket.onerror = (error) => {
          clearTimeout(timeout)
          conn.state = 'closed'
          reject(error)
        }
      } catch (error) {
        clearTimeout(timeout)
        reject(error)
      }
    })
  }

  private handleMessage(conn: WebSocketConnection, data: string): void {
    conn.lastUsed = Date.now()

    try {
      const parsed = JSON.parse(data)

      // Notify subscription handlers
      conn.subscriptions.forEach((sub) => {
        const handlers = this.handlers.get(sub)
        if (handlers) {
          handlers.forEach((handler) => {
            try {
              handler(parsed)
            } catch (error) {
              console.error('Message handler error:', error)
            }
          })
        }
      })
    } catch {
      // Handle non-JSON messages
      console.log('Received non-JSON message:', data)
    }
  }

  private handleDisconnect(conn: WebSocketConnection): void {
    if (conn.reconnectAttempts < this.config.maxReconnectAttempts) {
      conn.reconnectAttempts++
      setTimeout(() => {
        if (conn.subscriptions.size > 0) {
          this.connect(conn).catch(() => {
            // Reconnection failed, will retry
          })
        }
      }, this.config.reconnectInterval * conn.reconnectAttempts)
    } else {
      this.connections.delete(conn.id)
    }
  }

  private flushMessageQueue(conn: WebSocketConnection): void {
    while (conn.messageQueue.length > 0 && conn.state === 'open') {
      const message = conn.messageQueue.shift()
      if (message) {
        conn.socket?.send(message)
      }
    }
  }

  send(connectionId: string, data: unknown): boolean {
    const conn = this.connections.get(connectionId)
    if (!conn) {return false}

    const message = typeof data === 'string' ? data : JSON.stringify(data)

    if (conn.state === 'open') {
      conn.socket?.send(message)
      conn.lastUsed = Date.now()
      return true
    } else {
      conn.messageQueue.push(message)
      return false
    }
  }

  subscribe(connectionId: string, topic: string, handler: MessageHandler): () => void {
    const conn = this.connections.get(connectionId)
    if (conn) {
      conn.subscriptions.add(topic)
    }

    // Register handler
    if (!this.handlers.has(topic)) {
      this.handlers.set(topic, new Set())
    }
    this.handlers.get(topic)!.add(handler)

    // Return unsubscribe function
    return () => {
      this.unsubscribe(connectionId, topic, handler)
    }
  }

  private unsubscribe(connectionId: string, topic: string, handler: MessageHandler): void {
    const conn = this.connections.get(connectionId)
    if (conn) {
      conn.subscriptions.delete(topic)
    }

    const handlers = this.handlers.get(topic)
    if (handlers) {
      handlers.delete(handler)
      if (handlers.size === 0) {
        this.handlers.delete(topic)
      }
    }
  }

  closeConnection(id: string): void {
    const conn = this.connections.get(id)
    if (!conn) {return}

    conn.state = 'closing'
    conn.socket?.close()
    this.connections.delete(id)

    // Clean up handlers
    conn.subscriptions.forEach((topic) => {
      this.handlers.delete(topic)
    })
  }

  release(id: string): void {
    // Mark connection as idle but keep for reuse
    const conn = this.connections.get(id)
    if (conn) {
      conn.lastUsed = Date.now()
    }
  }

  getStats(): {
    total: number
    open: number
    connecting: number
    closing: number
    closed: number
    queuedMessages: number
  } {
    const stats = {
      total: this.connections.size,
      open: 0,
      connecting: 0,
      closing: 0,
      closed: 0,
      queuedMessages: 0,
    }

    for (const conn of this.connections.values()) {
      stats[conn.state]++
      stats.queuedMessages += conn.messageQueue.length
    }

    return stats
  }

  destroy(): void {
    if (this.cleanupInterval) {
      clearInterval(this.cleanupInterval)
    }

    for (const id of this.connections.keys()) {
      this.closeConnection(id)
    }

    this.handlers.clear()
  }
}

// Singleton instance
export const websocketPool = new WebSocketPool()

export { WebSocketPool }
export type { MessageHandler,PoolConfig, WebSocketConnection, WebSocketState }

// WebSocket client for real-time communication with the backend

type MessageHandler = (data: any) => void
type ConnectionHandler = () => void
type ErrorHandler = (error: Event) => void

interface WebSocketMessage {
  type: string
  channel?: string
  data?: any
  timestamp?: string
}

class WebSocketClient {
  private ws: WebSocket | null = null
  private url: string
  private reconnectAttempts = 0
  private maxReconnectAttempts = 5
  private reconnectDelay = 1000
  private reconnectTimer: ReturnType<typeof setTimeout> | null = null
  private pingTimer: ReturnType<typeof setInterval> | null = null
  private messageQueue: WebSocketMessage[] = []
  private pendingSubscriptions: Array<{ channel: string; handler: MessageHandler }> = []
  private subscriptions: Map<string, Set<MessageHandler>> = new Map()
  private connectionHandlers: Set<ConnectionHandler> = new Set()
  private disconnectionHandlers: Set<ConnectionHandler> = new Set()
  private errorHandlers: Set<ErrorHandler> = new Set()
  private isConnecting = false
  private token: string | null = null

  constructor(url: string) {
    this.url = url
  }

  setToken(token: string | null) {
    this.token = token
  }

  connect(): Promise<void> {
    return new Promise((resolve, reject) => {
      if (this.ws?.readyState === WebSocket.OPEN) {
        resolve()
        return
      }

      if (this.isConnecting) {
        const checkConnected = () => {
          if (this.ws?.readyState === WebSocket.OPEN) {
            resolve()
          } else {
            setTimeout(checkConnected, 100)
          }
        }
        checkConnected()
        return
      }

      this.isConnecting = true

      try {
        const wsUrl = this.token 
          ? `${this.url}?token=${this.token}`
          : this.url
        
        this.ws = new WebSocket(wsUrl)

        this.ws.onopen = () => {
          console.log('[WebSocket] Connected')
          this.isConnecting = false
          this.reconnectAttempts = 0
          
          // Send queued messages
          while (this.messageQueue.length > 0) {
            const msg = this.messageQueue.shift()
            if (msg) {this.send(msg)}
          }

          // Flush pending subscriptions (CRITICAL FIX: prevents race condition)
          this.flushPendingSubscriptions()

          // Start ping interval
          this.startPing()
          
          this.connectionHandlers.forEach((handler) => handler())
          resolve()
        }

        this.ws.onmessage = (event) => {
          try {
            const message: WebSocketMessage = JSON.parse(event.data)
            this.handleMessage(message)
          } catch (error) {
            console.error('[WebSocket] Failed to parse message:', error)
          }
        }

        this.ws.onerror = (error) => {
          console.error('[WebSocket] Error:', error)
          this.isConnecting = false
          this.errorHandlers.forEach((handler) => handler(error))
          reject(error)
        }

        this.ws.onclose = () => {
          console.log('[WebSocket] Disconnected')
          this.isConnecting = false
          this.stopPing()
          this.disconnectionHandlers.forEach((handler) => handler())
          this.scheduleReconnect()
        }
      } catch (error) {
        this.isConnecting = false
        reject(error)
      }
    })
  }

  private handleMessage(message: WebSocketMessage) {
    const { type, channel, data } = message

    if (channel) {
      const handlers = this.subscriptions.get(channel)
      if (handlers) {
        handlers.forEach((handler) => handler(data || message))
      }
    }

    // Handle specific message types
    switch (type) {
      case 'node:status':
        this.notifySubscribers('nodes', data)
        break
      case 'task:update':
        this.notifySubscribers('tasks', data)
        break
      case 'metrics:update':
        this.notifySubscribers('metrics', data)
        break
      case 'alert':
        this.notifySubscribers('alerts', data)
        break
      case 'workflow:progress':
        this.notifySubscribers('workflows', data)
        break
      case 'fl:round':
        this.notifySubscribers('federated-learning', data)
        break
    }
  }

  private notifySubscribers(channel: string, data: any) {
    const handlers = this.subscriptions.get(channel)
    if (handlers) {
      handlers.forEach((handler) => handler(data))
    }
  }

  /**
   * Flush pending subscriptions after connection
   * CRITICAL FIX: Prevents race condition where subscribe() called before connect() completes
   */
  private flushPendingSubscriptions(): void {
    console.log(`[WebSocket] Flushing ${this.pendingSubscriptions.length} pending subscriptions`)
    
    for (const { channel, handler } of this.pendingSubscriptions) {
      // Add to subscriptions map if not already present
      if (!this.subscriptions.has(channel)) {
        this.subscriptions.set(channel, new Set())
      }
      
      // Add handler to the set
      this.subscriptions.get(channel)!.add(handler)
      
      // Send subscribe message to server
      this.send({ type: 'subscribe', channel })
    }
    
    // Clear pending queue
    this.pendingSubscriptions = []
  }

  private send(message: WebSocketMessage) {
    if (this.ws?.readyState === WebSocket.OPEN) {
      this.ws.send(JSON.stringify(message))
    } else {
      this.messageQueue.push(message)
    }
  }

  private startPing() {
    this.pingTimer = setInterval(() => {
      this.send({ type: 'ping' })
    }, 30000) // Ping every 30 seconds
  }

  private stopPing() {
    if (this.pingTimer) {
      clearInterval(this.pingTimer)
      this.pingTimer = null
    }
  }

  private scheduleReconnect() {
    if (this.reconnectAttempts >= this.maxReconnectAttempts) {
      console.error('[WebSocket] Max reconnect attempts reached')
      return
    }

    this.reconnectAttempts++
    const delay = this.reconnectDelay * Math.pow(2, this.reconnectAttempts - 1)
    
    console.log(`[WebSocket] Reconnecting in ${delay}ms (attempt ${this.reconnectAttempts})`)
    
    this.reconnectTimer = setTimeout(() => {
      this.connect().catch(console.error)
    }, delay)
  }

  // Public API

  /**
   * Subscribe to a channel
   * CRITICAL: If not connected, subscription will be queued and flushed on connect
   */
  subscribe(channel: string, handler: MessageHandler): () => void {
    if (!this.subscriptions.has(channel)) {
      this.subscriptions.set(channel, new Set())
      
      // If not connected, queue the subscription to prevent race condition
      if (!this.isConnected) {
        console.log(`[WebSocket] Queueing subscription to "${channel}" (not connected yet)`)
        this.pendingSubscriptions.push({ channel, handler })
        
        // Return unsubscribe function
        return () => {
          const idx = this.pendingSubscriptions.findIndex(
            (sub) => sub.channel === channel && sub.handler === handler
          )
          if (idx !== -1) {
            this.pendingSubscriptions.splice(idx, 1)
          }
        }
      }
      
      // Connected - send immediately
      this.send({ type: 'subscribe', channel })
    }
    
    this.subscriptions.get(channel)!.add(handler)

    // Return unsubscribe function
    return () => {
      const handlers = this.subscriptions.get(channel)
      if (handlers) {
        handlers.delete(handler)
        if (handlers.size === 0) {
          this.subscriptions.delete(channel)
          this.send({ type: 'unsubscribe', channel })
        }
      }
    }
  }

  onConnect(handler: ConnectionHandler): () => void {
    this.connectionHandlers.add(handler)
    return () => this.connectionHandlers.delete(handler)
  }

  onDisconnect(handler: ConnectionHandler): () => void {
    this.disconnectionHandlers.add(handler)
    return () => this.disconnectionHandlers.delete(handler)
  }

  onError(handler: ErrorHandler): () => void {
    this.errorHandlers.add(handler)
    return () => this.errorHandlers.delete(handler)
  }

  disconnect() {
    if (this.reconnectTimer) {
      clearTimeout(this.reconnectTimer)
      this.reconnectTimer = null
    }
    this.stopPing()
    
    if (this.ws) {
      this.ws.close()
      this.ws = null
    }
  }

  get isConnected(): boolean {
    return this.ws?.readyState === WebSocket.OPEN
  }
}

// Singleton instance
import { config } from './realApi'

export const wsClient = new WebSocketClient(config.wsUrl)

// React hook for WebSocket
import { useCallback,useEffect, useState } from 'react'

export function useWebSocket() {
  const [isConnected, setIsConnected] = useState(wsClient.isConnected)
  const [error, setError] = useState<Event | null>(null)

  useEffect(() => {
    const unsubConnect = wsClient.onConnect(() => setIsConnected(true))
    const unsubDisconnect = wsClient.onDisconnect(() => setIsConnected(false))
    const unsubError = wsClient.onError((e) => setError(e))

    // Auto-connect if not connected
    if (!wsClient.isConnected) {
      wsClient.connect().catch(console.error)
    }

    return () => {
      unsubConnect()
      unsubDisconnect()
      unsubError()
    }
  }, [])

  const connect = useCallback(() => wsClient.connect(), [])
  const disconnect = useCallback(() => wsClient.disconnect(), [])

  return { isConnected, error, connect, disconnect }
}

// Hook for subscribing to a channel
export function useWebSocketChannel<T = any>(channel: string, handler: (data: T) => void) {
  useEffect(() => {
    const unsubscribe = wsClient.subscribe(channel, handler)
    return unsubscribe
  }, [channel, handler])
}

/**
 * Workflow Orchestration - DAG-based Task Execution Engine
 */

import { logger } from '../logger'
import type { Task, TaskPriority, TaskStatus } from '../../types'

// Types
export interface WorkflowDefinition {
  id: string
  name: string
  version: string
  description?: string
  nodes: WorkflowNode[]
  edges: WorkflowEdge[]
  variables: Record<string, unknown>
  timeout: number
  retryPolicy: RetryPolicy
}

export interface WorkflowNode {
  id: string
  name: string
  type: 'task' | 'decision' | 'parallel' | 'subworkflow' | 'wait' | 'notification'
  config: Record<string, unknown>
  inputs: string[]
  outputs: string[]
  retryPolicy?: RetryPolicy
  timeout?: number
}

export interface WorkflowEdge {
  id: string
  from: string
  to: string
  condition?: string // Expression for conditional edges
  label?: string
}

export interface RetryPolicy {
  maxRetries: number
  initialDelay: number
  maxDelay: number
  multiplier: number
}

export interface WorkflowExecution {
  id: string
  workflowId: string
  workflowVersion: string
  status: 'pending' | 'running' | 'completed' | 'failed' | 'cancelled' | 'paused'
  startTime: number
  endTime?: number
  currentNode: string | null
  completedNodes: string[]
  failedNodes: string[]
  variables: Record<string, unknown>
  nodeOutputs: Map<string, unknown>
  executionPath: string[]
  error?: string
}

export interface NodeExecution {
  nodeId: string
  executionId: string
  status: TaskStatus
  startTime: number
  endTime?: number
  output?: unknown
  error?: string
  retryCount: number
}

type WorkflowEvent = 'workflow.started' | 'workflow.completed' | 'workflow.failed' | 'node.started' | 'node.completed' | 'node.failed'
type WorkflowCallback = (event: WorkflowEvent, data: unknown) => void

/**
 * Workflow Engine - Executes DAG-based workflows
 */
export class WorkflowEngine {
  private definitions: Map<string, WorkflowDefinition> = new Map()
  private executions: Map<string, WorkflowExecution> = new Map()
  private nodeExecutions: Map<string, NodeExecution> = new Map()
  private callbacks: Map<WorkflowEvent, Set<WorkflowCallback>> = new Map()
  private taskExecutor: ((task: Task) => Promise<unknown>) | null = null

  /**
   * Set task executor
   */
  setTaskExecutor(executor: (task: Task) => Promise<unknown>): void {
    this.taskExecutor = executor
  }

  /**
   * Register workflow definition
   */
  registerWorkflow(definition: WorkflowDefinition): void {
    this.validateDefinition(definition)
    this.definitions.set(definition.id, definition)
    logger.info('Workflow registered', { workflowId: definition.id, name: definition.name })
  }

  /**
   * Validate workflow definition
   */
  private validateDefinition(definition: WorkflowDefinition): void {
    // Check for cycles
    const visited = new Set<string>()
    const recursionStack = new Set<string>()

    const hasCycle = (nodeId: string): boolean => {
      visited.add(nodeId)
      recursionStack.add(nodeId)

      const outgoingEdges = definition.edges.filter((e) => e.from === nodeId)
      for (const edge of outgoingEdges) {
        if (!visited.has(edge.to)) {
          if (hasCycle(edge.to)) {return true}
        } else if (recursionStack.has(edge.to)) {
          return true
        }
      }

      recursionStack.delete(nodeId)
      return false
    }

    const startNodes = this.getStartNodes(definition)
    for (const startNode of startNodes) {
      if (hasCycle(startNode.id)) {
        throw new Error(`Workflow ${definition.id} contains a cycle`)
      }
    }

    // Check all nodes are reachable
    const allNodeIds = new Set(definition.nodes.map((n) => n.id))
    const reachable = new Set<string>()
    
    const markReachable = (nodeId: string): void => {
      reachable.add(nodeId)
      const outgoing = definition.edges.filter((e) => e.from === nodeId)
      for (const edge of outgoing) {
        if (!reachable.has(edge.to)) {
          markReachable(edge.to)
        }
      }
    }

    for (const startNode of startNodes) {
      markReachable(startNode.id)
    }

    for (const nodeId of allNodeIds) {
      if (!reachable.has(nodeId)) {
        logger.warn(`Node ${nodeId} is not reachable in workflow ${definition.id}`)
      }
    }
  }

  /**
   * Get start nodes (nodes with no incoming edges)
   */
  private getStartNodes(definition: WorkflowDefinition): WorkflowNode[] {
    const hasIncoming = new Set(definition.edges.map((e) => e.to))
    return definition.nodes.filter((n) => !hasIncoming.has(n.id))
  }

  /**
   * Start workflow execution
   */
  async startWorkflow(workflowId: string, variables: Record<string, unknown> = {}): Promise<WorkflowExecution> {
    const definition = this.definitions.get(workflowId)
    if (!definition) {
      throw new Error(`Workflow ${workflowId} not found`)
    }

    const executionId = `exec-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`

    const execution: WorkflowExecution = {
      id: executionId,
      workflowId,
      workflowVersion: definition.version,
      status: 'running',
      startTime: Date.now(),
      currentNode: null,
      completedNodes: [],
      failedNodes: [],
      variables: { ...definition.variables, ...variables },
      nodeOutputs: new Map(),
      executionPath: [],
    }

    this.executions.set(executionId, execution)
    this.emit('workflow.started', { executionId, workflowId })

    logger.info('Workflow started', { executionId, workflowId })

    // Start execution
    await this.executeWorkflow(execution, definition)

    return execution
  }

  /**
   * Execute workflow
   */
  private async executeWorkflow(execution: WorkflowExecution, definition: WorkflowDefinition): Promise<void> {
    try {
      // Get start nodes
      const startNodes = this.getStartNodes(definition)
      
      // Execute from start nodes
      for (const startNode of startNodes) {
        await this.executeNode(execution, definition, startNode)
      }

      // Check if workflow is complete
      if (execution.status === 'running') {
        const allNodesComplete = definition.nodes.every((n) => 
          execution.completedNodes.includes(n.id) || execution.failedNodes.includes(n.id)
        )

        if (allNodesComplete) {
          execution.status = 'completed'
          execution.endTime = Date.now()
          this.emit('workflow.completed', { executionId: execution.id })
          logger.info('Workflow completed', { executionId: execution.id })
        }
      }
    } catch (error) {
      execution.status = 'failed'
      execution.error = (error as Error).message
      execution.endTime = Date.now()
      this.emit('workflow.failed', { executionId: execution.id, error: execution.error })
      logger.error('Workflow failed', error as Error, { executionId: execution.id })
    }
  }

  /**
   * Execute a single node
   */
  private async executeNode(
    execution: WorkflowExecution,
    definition: WorkflowDefinition,
    node: WorkflowNode
  ): Promise<void> {
    if (execution.status !== 'running') {return}
    if (execution.completedNodes.includes(node.id)) {return}
    if (execution.failedNodes.includes(node.id)) {return}

    // Check dependencies
    const incomingEdges = definition.edges.filter((e) => e.to === node.id)
    for (const edge of incomingEdges) {
      if (!execution.completedNodes.includes(edge.from)) {
        // Dependency not met, wait
        return
      }
    }

    execution.currentNode = node.id
    execution.executionPath.push(node.id)

    const nodeExecutionId = `node-${execution.id}-${node.id}`
    const nodeExecution: NodeExecution = {
      nodeId: node.id,
      executionId: nodeExecutionId,
      status: 'running',
      startTime: Date.now(),
      retryCount: 0,
    }

    this.nodeExecutions.set(nodeExecutionId, nodeExecution)
    this.emit('node.started', { executionId: execution.id, nodeId: node.id })

    logger.debug('Node started', { executionId: execution.id, nodeId: node.id, type: node.type })

    try {
      let output: unknown

      switch (node.type) {
        case 'task':
          output = await this.executeTaskNode(node, execution, definition)
          break
        case 'decision':
          output = await this.executeDecisionNode(node, execution, definition)
          break
        case 'parallel':
          output = await this.executeParallelNode(node, execution, definition)
          break
        case 'wait':
          output = await this.executeWaitNode(node, execution)
          break
        case 'notification':
          output = await this.executeNotificationNode(node, execution)
          break
        case 'subworkflow':
          output = await this.executeSubworkflowNode(node, execution)
          break
        default:
          throw new Error(`Unknown node type: ${node.type}`)
      }

      nodeExecution.status = 'completed'
      nodeExecution.endTime = Date.now()
      nodeExecution.output = output
      execution.completedNodes.push(node.id)
      execution.nodeOutputs.set(node.id, output)

      this.emit('node.completed', { executionId: execution.id, nodeId: node.id, output })
      logger.debug('Node completed', { executionId: execution.id, nodeId: node.id })

      // Execute next nodes
      const outgoingEdges = definition.edges.filter((e) => e.from === node.id)
      for (const edge of outgoingEdges) {
        if (edge.condition) {
          const conditionMet = this.evaluateCondition(edge.condition, execution)
          if (!conditionMet) {continue}
        }

        const nextNode = definition.nodes.find((n) => n.id === edge.to)
        if (nextNode) {
          await this.executeNode(execution, definition, nextNode)
        }
      }
    } catch (error) {
      nodeExecution.status = 'failed'
      nodeExecution.endTime = Date.now()
      nodeExecution.error = (error as Error).message
      execution.failedNodes.push(node.id)

      this.emit('node.failed', { executionId: execution.id, nodeId: node.id, error: nodeExecution.error })
      logger.error('Node failed', error as Error, { executionId: execution.id, nodeId: node.id })

      // Check retry policy
      const retryPolicy = node.retryPolicy || definition.retryPolicy
      if (nodeExecution.retryCount < retryPolicy.maxRetries) {
        nodeExecution.retryCount++
        const delay = Math.min(
          retryPolicy.initialDelay * Math.pow(retryPolicy.multiplier, nodeExecution.retryCount),
          retryPolicy.maxDelay
        )

        await new Promise((resolve) => setTimeout(resolve, delay))
        execution.failedNodes = execution.failedNodes.filter((id) => id !== node.id)
        await this.executeNode(execution, definition, node)
      }
    }
  }

  /**
   * Execute task node
   */
  private async executeTaskNode(
    node: WorkflowNode,
    execution: WorkflowExecution,
    _definition: WorkflowDefinition
  ): Promise<unknown> {
    if (!this.taskExecutor) {
      throw new Error('Task executor not configured')
    }

    const task: Task = {
      id: `task-${execution.id}-${node.id}`,
      name: node.name,
      type: node.config['taskType'] as Task['type'] || 'Data Aggregation',
      status: 'pending',
      target: 'edge',
      priority: (node.config['priority'] as TaskPriority) || 'medium',
      submittedAt: new Date(),
      duration: 0,
      cost: 0,
      latencyMs: 0,
      reason: `Workflow task: ${node.name}`,
      retryCount: 0,
      maxRetries: 3,
    }

    return await this.taskExecutor(task)
  }

  /**
   * Execute decision node
   */
  private async executeDecisionNode(
    node: WorkflowNode,
    execution: WorkflowExecution,
    _definition: WorkflowDefinition
  ): Promise<string> {
    const expression = node.config['expression'] as string
    const result = this.evaluateExpression(expression, execution.variables)
    return result ? 'true' : 'false'
  }

  /**
   * Execute parallel node
   */
  private async executeParallelNode(
    node: WorkflowNode,
    execution: WorkflowExecution,
    definition: WorkflowDefinition
  ): Promise<unknown[]> {
    const branchNodes = node.config['branches'] as string[] || []
    const results: unknown[] = []

    for (const branchNodeId of branchNodes) {
      const branchNode = definition.nodes.find((n) => n.id === branchNodeId)
      if (branchNode) {
        // Execute in parallel (simplified - would use Promise.all in production)
        const result = await this.executeNode(execution, definition, branchNode)
        results.push(result)
      }
    }

    return results
  }

  /**
   * Execute wait node
   */
  private async executeWaitNode(node: WorkflowNode, _execution: WorkflowExecution): Promise<void> {
    const duration = node.config['duration'] as number || 1000
    await new Promise((resolve) => setTimeout(resolve, duration))
  }

  /**
   * Execute notification node
   */
  private async executeNotificationNode(node: WorkflowNode, execution: WorkflowExecution): Promise<void> {
    const message = node.config['message'] as string || 'Workflow notification'
    logger.info('Workflow notification', { executionId: execution.id, message })
  }

  /**
   * Execute subworkflow node
   */
  private async executeSubworkflowNode(node: WorkflowNode, _execution: WorkflowExecution): Promise<unknown> {
    const subWorkflowId = node.config['workflowId'] as string
    if (!subWorkflowId) {return null}

    // Would recursively start subworkflow
    logger.info('Starting subworkflow', { subWorkflowId })
    return { subWorkflowId }
  }

  /**
   * Evaluate condition expression
   */
  private evaluateCondition(expression: string, execution: WorkflowExecution): boolean {
    try {
      // Simple expression evaluation (in production, use a proper expression engine)
      const result = this.evaluateExpression(expression, execution.variables)
      return Boolean(result)
    } catch {
      return false
    }
  }

  /**
   * Evaluate expression
   */
  private evaluateExpression(expression: string, variables: Record<string, unknown>): unknown {
    // Simple variable substitution
    let result = expression
    for (const [key, value] of Object.entries(variables)) {
      result = result.replace(new RegExp(`\\$\\{${key}\\}`, 'g'), String(value))
    }
    return result
  }

  /**
   * Get execution status
   */
  getExecution(executionId: string): WorkflowExecution | undefined {
    return this.executions.get(executionId)
  }

  /**
   * Cancel execution
   */
  cancelExecution(executionId: string): boolean {
    const execution = this.executions.get(executionId)
    if (!execution || execution.status !== 'running') {return false}

    execution.status = 'cancelled'
    execution.endTime = Date.now()
    logger.info('Workflow cancelled', { executionId })
    return true
  }

  /**
   * Pause execution
   */
  pauseExecution(executionId: string): boolean {
    const execution = this.executions.get(executionId)
    if (!execution || execution.status !== 'running') {return false}

    execution.status = 'paused'
    logger.info('Workflow paused', { executionId })
    return true
  }

  /**
   * Resume execution
   */
  async resumeExecution(executionId: string): Promise<boolean> {
    const execution = this.executions.get(executionId)
    if (!execution || execution.status !== 'paused') {return false}

    execution.status = 'running'
    const definition = this.definitions.get(execution.workflowId)
    if (definition) {
      await this.executeWorkflow(execution, definition)
    }
    return true
  }

  /**
   * Get statistics
   */
  getStats(): {
    totalWorkflows: number
    totalExecutions: number
    runningExecutions: number
    completedExecutions: number
    failedExecutions: number
  } {
    let running = 0
    let completed = 0
    let failed = 0

    for (const execution of this.executions.values()) {
      if (execution.status === 'running') {running++}
      if (execution.status === 'completed') {completed++}
      if (execution.status === 'failed') {failed++}
    }

    return {
      totalWorkflows: this.definitions.size,
      totalExecutions: this.executions.size,
      runningExecutions: running,
      completedExecutions: completed,
      failedExecutions: failed,
    }
  }

  /**
   * Subscribe to events
   */
  on(event: WorkflowEvent, callback: WorkflowCallback): () => void {
    if (!this.callbacks.has(event)) {
      this.callbacks.set(event, new Set())
    }
    this.callbacks.get(event)!.add(callback)

    return () => {
      this.callbacks.get(event)?.delete(callback)
    }
  }

  private emit(event: WorkflowEvent, data: unknown): void {
    this.callbacks.get(event)?.forEach((cb) => {
      try {
        cb(event, data)
      } catch (error) {
        logger.error('Workflow callback error', error as Error)
      }
    })
  }
}

/**
 * Create workflow engine
 */
export function createWorkflowEngine(): WorkflowEngine {
  return new WorkflowEngine()
}

// Default instance
export const workflowEngine = new WorkflowEngine()

/**
 * Workers Module Exports
 */

export type { 
  TaskExecution, 
  WorkerConfig, 
  WorkerStats 
} from './taskWorker'
export { 
  createWorker,
  createWorkerPool,
  TaskWorker, 
  WorkerPool} from './taskWorker'

/**
 * Task Worker Service
 * Consumes tasks from the queue and dispatches them to edge agents
 */

import { logger } from '../lib/logger'

import type { EdgeNode, Task, TaskPriority } from '../types'

// Types
export interface WorkerConfig {
  id: string
  concurrency: number
  pollInterval: number
  heartbeatInterval: number
  taskTimeout: number
  retryDelay: number
}

export interface TaskExecution {
  taskId: string
  nodeId: string
  startTime: number
  status: 'running' | 'completed' | 'failed'
  error?: string
  result?: unknown
}

export interface WorkerStats {
  id: string
  status: 'idle' | 'running' | 'stopped'
  tasksProcessed: number
  tasksSucceeded: number
  tasksFailed: number
  avgExecutionTime: number
  currentLoad: number
  uptime: number
}

type WorkerEvent = 'task.started' | 'task.completed' | 'task.failed' | 'worker.started' | 'worker.stopped'
type WorkerCallback = (event: WorkerEvent, data: unknown) => void

const DEFAULT_CONFIG: WorkerConfig = {
  id: `worker-${Date.now()}`,
  concurrency: 5,
  pollInterval: 100,
  heartbeatInterval: 5000,
  taskTimeout: 30000,
  retryDelay: 1000,
}

/**
 * Task Worker - Consumes tasks and executes them on edge nodes
 */
export class TaskWorker {
  private config: WorkerConfig
  private status: 'idle' | 'running' | 'stopped' = 'stopped'
  private taskQueue: Array<{ task: Task; priority: TaskPriority }> = []
  private runningTasks: Map<string, TaskExecution> = new Map()
  private stats: WorkerStats
  private startTime = 0
  private pollTimer: ReturnType<typeof setInterval> | null = null
  private heartbeatTimer: ReturnType<typeof setInterval> | null = null
  private callbacks: Map<WorkerEvent, Set<WorkerCallback>> = new Map()
  
  // Scheduler integration
  private nodeSelector: (task: Task) => EdgeNode | null
  private taskExecutor: (task: Task, node: EdgeNode) => Promise<unknown>

  constructor(
    config: Partial<WorkerConfig> = {},
    nodeSelector: (task: Task) => EdgeNode | null = () => null,
    taskExecutor: (task: Task, node: EdgeNode) => Promise<unknown> = async () => null
  ) {
    this.config = { ...DEFAULT_CONFIG, ...config }
    this.nodeSelector = nodeSelector
    this.taskExecutor = taskExecutor
    
    this.stats = {
      id: this.config.id,
      status: 'stopped',
      tasksProcessed: 0,
      tasksSucceeded: 0,
      tasksFailed: 0,
      avgExecutionTime: 0,
      currentLoad: 0,
      uptime: 0,
    }
  }

  /**
   * Start the worker
   */
  async start(): Promise<void> {
    if (this.status === 'running') {
      logger.warn('Worker already running', { workerId: this.config.id })
      return
    }

    this.status = 'running'
    this.startTime = Date.now()
    this.stats.status = 'running'

    // Start polling for tasks
    this.pollTimer = setInterval(() => this.poll(), this.config.pollInterval)
    
    // Start heartbeat
    this.heartbeatTimer = setInterval(() => this.heartbeat(), this.config.heartbeatInterval)

    this.emit('worker.started', { workerId: this.config.id })
    logger.info('Task worker started', { workerId: this.config.id, concurrency: this.config.concurrency })
  }

  /**
   * Stop the worker gracefully
   */
  async stop(): Promise<void> {
    this.status = 'stopped'
    this.stats.status = 'stopped'

    if (this.pollTimer) {
      clearInterval(this.pollTimer)
      this.pollTimer = null
    }

    if (this.heartbeatTimer) {
      clearInterval(this.heartbeatTimer)
      this.heartbeatTimer = null
    }

    // Wait for running tasks to complete
    const runningCount = this.runningTasks.size
    if (runningCount > 0) {
      logger.info('Waiting for running tasks to complete', { workerId: this.config.id, count: runningCount })
      
      // Give tasks 30 seconds to complete
      const timeout = 30000
      const startTime = Date.now()
      
      while (this.runningTasks.size > 0 && Date.now() - startTime < timeout) {
        await new Promise((resolve) => setTimeout(resolve, 100))
      }
    }

    this.emit('worker.stopped', { workerId: this.config.id })
    logger.info('Task worker stopped', { workerId: this.config.id })
  }

  /**
   * Enqueue a task for execution
   */
  enqueue(task: Task, priority: TaskPriority = 'medium'): void {
    this.taskQueue.push({ task, priority })
    this.sortQueue()
    logger.debug('Task enqueued', { taskId: task.id, priority, queueSize: this.taskQueue.length })
  }

  /**
   * Poll for tasks and execute
   */
  private async poll(): Promise<void> {
    if (this.status !== 'running') {return}
    if (this.runningTasks.size >= this.config.concurrency) {return}
    if (this.taskQueue.length === 0) {return}

    const item = this.taskQueue.shift()
    if (!item) {return}

    await this.executeTask(item.task)
  }

  /**
   * Execute a task
   */
  private async executeTask(task: Task): Promise<void> {
    // Select node for task
    const node = this.nodeSelector(task)
    
    if (!node) {
      logger.warn('No suitable node found for task', { taskId: task.id })
      this.handleTaskFailure(task, 'No suitable node available')
      return
    }

    const execution: TaskExecution = {
      taskId: task.id,
      nodeId: node.id,
      startTime: Date.now(),
      status: 'running',
    }

    this.runningTasks.set(task.id, execution)
    this.stats.currentLoad = this.runningTasks.size / this.config.concurrency

    this.emit('task.started', { taskId: task.id, nodeId: node.id })
    logger.info('Task execution started', { taskId: task.id, nodeId: node.id })

    try {
      // Execute with timeout
      const result = await this.executeWithTimeout(task, node)
      
      execution.status = 'completed'
      execution.result = result
      
      this.stats.tasksProcessed++
      this.stats.tasksSucceeded++
      this.updateAvgExecutionTime(Date.now() - execution.startTime)
      
      this.emit('task.completed', { taskId: task.id, nodeId: node.id, duration: Date.now() - execution.startTime })
      logger.info('Task completed', { taskId: task.id, nodeId: node.id, duration: Date.now() - execution.startTime })
    } catch (error) {
      execution.status = 'failed'
      execution.error = (error as Error).message
      
      this.stats.tasksProcessed++
      this.stats.tasksFailed++
      
      this.emit('task.failed', { taskId: task.id, nodeId: node.id, error: (error as Error).message })
      logger.error('Task failed', error as Error, { taskId: task.id, nodeId: node.id })
      
      // Handle retry
      if (task.retryCount < task.maxRetries) {
        this.scheduleRetry(task)
      }
    } finally {
      this.runningTasks.delete(task.id)
      this.stats.currentLoad = this.runningTasks.size / this.config.concurrency
    }
  }

  /**
   * Execute task with timeout
   */
  private async executeWithTimeout(task: Task, node: EdgeNode): Promise<unknown> {
    return new Promise<unknown>((resolve, reject) => {
      const timeoutId = setTimeout(() => {
        reject(new Error(`Task timeout after ${this.config.taskTimeout}ms`))
      }, this.config.taskTimeout)

      this.taskExecutor(task, node)
        .then((result) => {
          clearTimeout(timeoutId)
          resolve(result)
        })
        .catch((error) => {
          clearTimeout(timeoutId)
          reject(error)
        })
    })
  }

  /**
   * Handle task failure
   */
  private handleTaskFailure(task: Task, error: string): void {
    this.stats.tasksProcessed++
    this.stats.tasksFailed++
    
    this.emit('task.failed', { taskId: task.id, error })
    logger.error('Task failed', new Error(error), { taskId: task.id })

    if (task.retryCount < task.maxRetries) {
      this.scheduleRetry(task)
    }
  }

  /**
   * Schedule task retry
   */
  private scheduleRetry(task: Task): void {
    task.retryCount++
    const delay = this.config.retryDelay * Math.pow(2, task.retryCount - 1)
    
    setTimeout(() => {
      if (this.status === 'running') {
        this.enqueue(task, task.priority)
      }
    }, delay)
    
    logger.info('Task retry scheduled', { taskId: task.id, retryCount: task.retryCount, delay })
  }

  /**
   * Sort queue by priority
   */
  private sortQueue(): void {
    const priorityOrder: Record<TaskPriority, number> = {
      critical: 0,
      high: 1,
      medium: 2,
      low: 3,
    }
    
    this.taskQueue.sort((a, b) => priorityOrder[a.priority] - priorityOrder[b.priority])
  }

  /**
   * Send heartbeat
   */
  private heartbeat(): void {
    this.stats.uptime = Date.now() - this.startTime
    logger.debug('Worker heartbeat', { 
      workerId: this.config.id, 
      status: this.status,
      queueSize: this.taskQueue.length,
      runningTasks: this.runningTasks.size,
      load: this.stats.currentLoad.toFixed(2)
    })
  }

  /**
   * Update average execution time
   */
  private updateAvgExecutionTime(duration: number): void {
    const count = this.stats.tasksSucceeded
    this.stats.avgExecutionTime = ((this.stats.avgExecutionTime * (count - 1)) + duration) / count
  }

  /**
   * Get worker statistics
   */
  getStats(): WorkerStats {
    return { ...this.stats }
  }

  /**
   * Get current queue size
   */
  getQueueSize(): number {
    return this.taskQueue.length
  }

  /**
   * Get running task count
   */
  getRunningCount(): number {
    return this.runningTasks.size
  }

  /**
   * Subscribe to events
   */
  on(event: WorkerEvent, callback: WorkerCallback): () => void {
    if (!this.callbacks.has(event)) {
      this.callbacks.set(event, new Set())
    }
    this.callbacks.get(event)!.add(callback)

    return () => {
      this.callbacks.get(event)?.delete(callback)
    }
  }

  private emit(event: WorkerEvent, data: unknown): void {
    this.callbacks.get(event)?.forEach((cb) => {
      try {
        cb(event, data)
      } catch (error) {
        logger.error('Worker callback error', error as Error)
      }
    })
  }
}

/**
 * Worker Pool - Manages multiple workers
 */
export class WorkerPool {
  private workers: Map<string, TaskWorker> = new Map()
  private _nodeSelector: (task: Task) => EdgeNode | null
  private _taskExecutor: (task: Task, node: EdgeNode) => Promise<unknown>

  constructor(
    nodeSelector: (task: Task) => EdgeNode | null,
    taskExecutor: (task: Task, node: EdgeNode) => Promise<unknown>
  ) {
    this._nodeSelector = nodeSelector
    this._taskExecutor = taskExecutor
  }

  /**
   * Add a worker to the pool
   */
  addWorker(config: Partial<WorkerConfig> = {}): string {
    const id = config.id || `worker-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`
    
    const worker = new TaskWorker(
      { ...config, id },
      this._nodeSelector,
      this._taskExecutor
    )

    this.workers.set(id, worker)
    logger.info('Worker added to pool', { workerId: id })
    
    return id
  }

  /**
   * Remove a worker from the pool
   */
  async removeWorker(id: string): Promise<void> {
    const worker = this.workers.get(id)
    if (worker) {
      await worker.stop()
      this.workers.delete(id)
      logger.info('Worker removed from pool', { workerId: id })
    }
  }

  /**
   * Start all workers
   */
  async startAll(): Promise<void> {
    const promises = Array.from(this.workers.values()).map((w) => w.start())
    await Promise.all(promises)
    logger.info('All workers started', { count: this.workers.size })
  }

  /**
   * Stop all workers
   */
  async stopAll(): Promise<void> {
    const promises = Array.from(this.workers.values()).map((w) => w.stop())
    await Promise.all(promises)
    logger.info('All workers stopped', { count: this.workers.size })
  }

  /**
   * Dispatch task to least loaded worker
   */
  dispatch(task: Task, priority: TaskPriority = 'medium'): boolean {
    // Find worker with lowest load
    let targetWorker: TaskWorker | null = null
    let lowestLoad = Infinity

    for (const worker of this.workers.values()) {
      const stats = worker.getStats()
      if (stats.status === 'running' && stats.currentLoad < lowestLoad) {
        lowestLoad = stats.currentLoad
        targetWorker = worker
      }
    }

    if (targetWorker) {
      targetWorker.enqueue(task, priority)
      return true
    }

    logger.warn('No available worker for task', { taskId: task.id })
    return false
  }

  /**
   * Get pool statistics
   */
  getStats(): {
    workers: number
    activeWorkers: number
    totalProcessed: number
    totalSucceeded: number
    totalFailed: number
    avgLoad: number
  } {
    let activeWorkers = 0
    let totalProcessed = 0
    let totalSucceeded = 0
    let totalFailed = 0
    let totalLoad = 0

    for (const worker of this.workers.values()) {
      const stats = worker.getStats()
      if (stats.status === 'running') {
        activeWorkers++
        totalLoad += stats.currentLoad
      }
      totalProcessed += stats.tasksProcessed
      totalSucceeded += stats.tasksSucceeded
      totalFailed += stats.tasksFailed
    }

    return {
      workers: this.workers.size,
      activeWorkers,
      totalProcessed,
      totalSucceeded,
      totalFailed,
      avgLoad: activeWorkers > 0 ? totalLoad / activeWorkers : 0,
    }
  }
}

// Default exports
export function createWorker(
  nodeSelector: (task: Task) => EdgeNode | null,
  taskExecutor: (task: Task, node: EdgeNode) => Promise<unknown>,
  config: Partial<WorkerConfig> = {}
): TaskWorker {
  return new TaskWorker(config, nodeSelector, taskExecutor)
}

export function createWorkerPool(
  nodeSelector: (task: Task) => EdgeNode | null,
  taskExecutor: (task: Task, node: EdgeNode) => Promise<unknown>
): WorkerPool {
  return new WorkerPool(nodeSelector, taskExecutor)
}

